// 書式設定ツールバーのアライメントドロップダウンを初期化する
function initFormatDropdowns() {
  const prefixes = ['ct', 'ag', 'jo', 'ap', 'dbmake'];
  
  prefixes.forEach(pfx => {
    const types = ['align', 'valign', 'wrap'];
    
    types.forEach(type => {
      const dropdown = document.getElementById(`${pfx}-${type}-dropdown`);
      if (!dropdown) return;
      
      const btn = dropdown.querySelector('.format-dropdown-btn');
      const menu = dropdown.querySelector('.format-dropdown-menu');
      const iconSpan = btn ? btn.querySelector('.dropdown-icon') : null;
      
      if (btn && menu) {
        // 開閉トグル
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          
          // 他のドロップダウンをすべて閉じる
          document.querySelectorAll('.format-dropdown').forEach(d => {
            if (d !== dropdown) d.classList.remove('active');
          });
          document.querySelectorAll('.color-picker-dropdown').forEach(d => {
            d.style.display = 'none';
          });
          
          dropdown.classList.toggle('active');
        });
        
        // 子要素のボタンがクリックされたときにメインボタンの表示を更新し、ドロップダウンを閉じる
        menu.querySelectorAll('.toolbar-btn').forEach(subBtn => {
          subBtn.addEventListener('click', () => {
            if (iconSpan) {
              iconSpan.innerHTML = subBtn.innerHTML;
            }
            dropdown.classList.remove('active');
          });

          // activeクラス変更時の親アイコン画像同期
          const observer = new MutationObserver((mutations) => {
            mutations.forEach(mutation => {
              if (mutation.attributeName === 'class' && subBtn.classList.contains('active')) {
                if (iconSpan) {
                  iconSpan.innerHTML = subBtn.innerHTML;
                }
              }
            });
          });
          observer.observe(subBtn, { attributes: true });

          // 初期のactive同期
          if (subBtn.classList.contains('active') && iconSpan) {
            iconSpan.innerHTML = subBtn.innerHTML;
          }
        });
      }
    });
  });
  
  // 外側クリックで閉じる
  document.addEventListener('mousedown', (e) => {
    if (e.target.closest('.format-dropdown')) return;
    document.querySelectorAll('.format-dropdown').forEach(d => {
      d.classList.remove('active');
    });
  }, true);
}

// 連番 (seq) から1対1 (全単射) で衝突のない8桁英数字IDを生成する暗号学的関数 (Format-Preserving Encryption 簡易版)
function encodeSequenceToId(seq) {
  const chars = 'ACEFGHJKMNPQRSTWXY345679';
  const M = 331776; // 24^4
  
  const f = (R, round) => {
    const key = [0x5A827999, 0x6ED9EBA1, 0x8F1BBCDC, 0xCA62C1D6][round];
    let hash = (R ^ key) * 16777619;
    hash = (hash ^ (hash >>> 16)) & 0xFFFFFFFF;
    return Math.abs(hash) % M;
  };

  let l = Math.floor(seq / M) % M;
  let r = seq % M;

  for (let round = 0; round < 4; round++) {
    const nextL = r;
    const nextR = (l + f(r, round)) % M;
    l = nextL;
    r = nextR;
  }

  const Y = l * M + r;

  let temp = Y;
  let id = '';
  for (let i = 0; i < 8; i++) {
    id += chars.charAt(temp % 24);
    temp = Math.floor(temp / 24);
  }
  return id;
}

// 8桁のユニークID生成ヘルパー (シーケンスベースで100%重複なしを保証)
function generate8DigitId() {
  let seq = parseInt(localStorage.getItem(STORAGE_KEYS.ID_SEQUENCE) || '0', 10);
  
  // 初期ダミーデータ（1〜300）との重複を避けるために300からスタート
  if (seq < 300) {
    seq = 300;
  }

  let uniqueId = '';
  let attempts = 0;

  do {
    seq++;
    uniqueId = encodeSequenceToId(seq);
    attempts++;
  } while (
    attempts < 1000 && (
      (state.appointments && state.appointments.some(a => a.id === uniqueId)) ||
      (state.joContracts && state.joContracts.some(j => j.customerPersonalityId === uniqueId || j.customerId === uniqueId)) ||
      (state.apContracts && state.apContracts.some(ap => ap.customerPersonalityId === uniqueId)) ||
      (state.agContracts && state.agContracts.some(ag => ag.customerId === uniqueId)) ||
      (typeof dbmakePartners !== 'undefined' && dbmakePartners && dbmakePartners.some(p => p.id === uniqueId))
    )
  );

  localStorage.setItem(STORAGE_KEYS.ID_SEQUENCE, String(seq));
  return uniqueId;
}

// 重複のない一意な4桁顧客番号を生成するヘルパー（JO情報・申込者情報共通）
function generateUniqueCustomerNumber() {
  let maxNum = 1000;
  if (state.joContracts) {
    state.joContracts.forEach(c => {
      const num = parseInt(c.customerId, 10);
      if (!isNaN(num) && num > maxNum) maxNum = num;
    });
  }
  if (state.apContracts) {
    state.apContracts.forEach(c => {
      const num = parseInt(c.customerId, 10);
      if (!isNaN(num) && num > maxNum) maxNum = num;
    });
  }
  return String(maxNum + 1);
}

/* ============================================================================
   ☁️ Supabase 接続・自動同期エンジン
   ============================================================================ */

// Supabaseクライアントの初期化
// Supabaseクライアントの初期化
let authListenerSubscription = null;

function setupSupabaseAuthListener() {
  if (!supabaseClient) return;
  
  if (authListenerSubscription) {
    if (typeof authListenerSubscription.unsubscribe === 'function') {
      authListenerSubscription.unsubscribe();
    }
  }

  const { data } = supabaseClient.auth.onAuthStateChange(async (event, session) => {
    console.log(`[Supabase Auth] Event: ${event}`);

    // 💡 [管理者バイパス保護] ローカルで owner (既存管理者) としてログインしている場合は、Supabase の状態変化を無視する
    if (state.currentUser && (state.currentUser.id === 'owner' || state.currentUser.role === 'owner')) {
      console.log("[Supabase Auth] Owner bypass session active. Ignoring auth state change.");
      return;
    }
    
    const signupScreen = document.getElementById('signup-screen');
    const loginScreen = document.getElementById('login-screen');

    if (session && session.user) {
      const user = session.user;
      const metadata = user.user_metadata || {};
      const email = user.email;
      const name = metadata.name || email;
      const code = metadata.code || '';
      
      let role = metadata.role || 'sales';
      
      try {
        const { data: userData } = await supabaseClient
          .from('synapse_users')
          .select('role')
          .eq('id', email)
          .single();
        if (userData && userData.role) {
          role = userData.role;
          if (role.startsWith('pending_')) {
            role = role.replace('pending_', '');
          }
        }
      } catch (e) {
        console.warn('[Supabase Auth] Failed to fetch exact user role from public DB:', e);
      }

      // 💻 デバイス識別・検証 (端末認証) の実施
      const isPendingPasswordSetup = (metadata.needs_password_setup === true);
      const isRecovery = (event === 'PASSWORD_RECOVERY');

      if (!isPendingPasswordSetup && !isRecovery) {
        const isDeviceValid = await validateDeviceToken(email);
        
        if (!isDeviceValid) {
          console.log('[Device Auth] Unknown or unregistered device token for:', email);
          
          // 既存のデバイス一覧とユーザー情報を取得
          const { data: dbUser, error: userErr } = await supabaseClient
            .from('synapse_users')
            .select('phone_number')
            .eq('id', email)
            .maybeSingle();

          const { data: dbDevices, error: devErr } = await supabaseClient
            .from('synapse_user_devices')
            .select('device_type')
            .eq('user_id', email);

          if (userErr || devErr) {
            console.error('[Device Auth] Error retrieving device settings:', userErr || devErr);
            showToast('ログインセキュリティ検証中にエラーが発生しました。', 'error');
            await supabaseClient.auth.signOut();
            return;
          }

          const phoneNumber = dbUser ? dbUser.phone_number : '';
          const existingDevices = dbDevices || [];
          const currentType = getDeviceType();

          // 1. 最大登録台数制限の検証 (3台まで)
          if (existingDevices.length >= 3) {
            showToast('信頼されたデバイスの登録数が上限（3台）に達しています。ログインできません。', 'error');
            showAppConfirm(
              '🚫 ログインブロック',
              '信頼されたデバイスの登録数（最大3台）を超えています。\n新しい端末を登録するには、管理者に不要な端末の削除を依頼してください。'
            );
            await supabaseClient.auth.signOut();
            return;
          }

          // 2. デバイス構成パターンの適合検証
          const isCompositionValid = isValidDeviceComposition(existingDevices, currentType);
          if (!isCompositionValid) {
            showToast('許可されていないデバイス構成パターンのため、ログインがブロックされました。', 'error');
            showAppConfirm(
              '🚫 ログインブロック',
              `この端末（${getDeviceName()}）を追加すると、許可されているデバイス構成パターンから外れてしまいます。\n\n【許可される組み合わせ】\n・スマホ1台、タブレット1台、PC1台\n・スマホ2台、PC1台\n・スマホ1台、PC2台\n\n管理者に不要な端末の削除を依頼してください。`
            );
            await supabaseClient.auth.signOut();
            return;
          }

          // 3. 初めてログインする未登録端末では、必ず電話番号宛てのSMS 2段階認証を要求
          if (!phoneNumber) {
            showToast('ご登録電話番号が見つからないため、SMS認証を実行できません。管理者に連絡してください。', 'error');
            await supabaseClient.auth.signOut();
            return;
          }

          showToast('新しい端末を検知しました。ご登録の電話番号宛てにSMS 2段階認証を実行します。', 'info');
          const isVerified = await triggerSmsMfa(phoneNumber, '新しい端末の初回登録');
          
          if (isVerified) {
            // SMS認証に成功：新規デバイスとしてDBに登録
            try {
              const newDeviceToken = crypto.randomUUID ? crypto.randomUUID() : (Math.random().toString(36).substring(2, 15) + '-' + Math.random().toString(36).substring(2, 15));
              const newDeviceName = getDeviceName();

              const { error: insertErr } = await supabaseClient.from('synapse_user_devices').insert({
                user_id: email,
                device_token: newDeviceToken,
                device_name: newDeviceName,
                device_type: currentType,
                last_used_at: new Date().toISOString(),
                created_at: new Date().toISOString()
              });

              if (insertErr) {
                console.error('[Device Auth] Failed to insert new device record:', insertErr);
                showToast('デバイス登録に失敗しました。', 'error');
                await supabaseClient.auth.signOut();
                return;
              }

              localStorage.setItem('synapse_device_token', newDeviceToken);
              showToast('この端末が信頼されたデバイスとして登録されました。', 'success');
            } catch (err) {
              console.error('[Device Auth] Device registration error:', err);
              showToast('システムエラーが発生しました。', 'error');
              await supabaseClient.auth.signOut();
              return;
            }
          } else {
            // SMS認証をキャンセルまたは失敗
            showToast('SMS認証が完了しなかったため、ログインを中止しました。', 'warning');
            await supabaseClient.auth.signOut();
            return;
          }
        }
      }

      state.currentUser = {
        id: email,
        role: role,
        name: name,
        loginId: email,
        code: code
      };
      localStorage.setItem(STORAGE_KEYS.LOGGED_USER, JSON.stringify(state.currentUser));

      if (event === 'PASSWORD_RECOVERY') {
        showLoginScreen(true);
        const modal = document.getElementById('set-password-modal');
        const emailHidden = document.getElementById('set-pwd-email');
        if (modal && emailHidden) {
          emailHidden.value = email;
          
          const lastNameInput = document.getElementById('set-pwd-lastname');
          const firstNameInput = document.getElementById('set-pwd-firstname');
          const birthdayInput = document.getElementById('set-pwd-birthday');
          const genderSelect = document.getElementById('set-pwd-gender');
          const loginIdInput = document.getElementById('set-pwd-loginid');
          const phoneInput = document.getElementById('set-pwd-phone');
          const pwdInput = document.getElementById('set-pwd-input');
          const pwdConfirmInput = document.getElementById('set-pwd-confirm-input');
          
          // 生年月日、性別、ログインID、名前、電話番号入力を非表示にする
          if (birthdayInput && birthdayInput.parentElement && birthdayInput.parentElement.parentElement) birthdayInput.parentElement.parentElement.style.display = 'none';
          if (loginIdInput && loginIdInput.parentElement) loginIdInput.parentElement.style.display = 'none';
          if (phoneInput && phoneInput.parentElement) phoneInput.parentElement.style.display = 'none';
          if (lastNameInput && lastNameInput.parentElement && lastNameInput.parentElement.parentElement) {
            lastNameInput.parentElement.parentElement.style.display = 'none';
          }
          
          const titleEl = modal.querySelector('h3');
          if (titleEl) titleEl.innerHTML = '🔑 パスワードの再設定';
          
          if (pwdInput) pwdInput.value = '';
          if (pwdConfirmInput) pwdConfirmInput.value = '';
          
          modal.style.display = 'flex';
          showToast('パスワード再設定セッションが有効です。新しいパスワードを設定してください。', 'info');
        }
      } else if (metadata.needs_password_setup === true) {
        showLoginScreen(true);
        const modal = document.getElementById('set-password-modal');
        const emailHidden = document.getElementById('set-pwd-email');
        if (modal && emailHidden) {
          emailHidden.value = email;
          
          const lastNameInput = document.getElementById('set-pwd-lastname');
          const firstNameInput = document.getElementById('set-pwd-firstname');
          const birthdayInput = document.getElementById('set-pwd-birthday');
          const genderSelect = document.getElementById('set-pwd-gender');
          const loginIdInput = document.getElementById('set-pwd-loginid');
          const phoneInput = document.getElementById('set-pwd-phone');
          const pwdInput = document.getElementById('set-pwd-input');
          const pwdConfirmInput = document.getElementById('set-pwd-confirm-input');
          
          // 本登録時は全入力項目を表示する
          if (birthdayInput && birthdayInput.parentElement && birthdayInput.parentElement.parentElement) birthdayInput.parentElement.parentElement.style.display = 'flex';
          if (loginIdInput && loginIdInput.parentElement) loginIdInput.parentElement.style.display = 'flex';
          if (phoneInput && phoneInput.parentElement) phoneInput.parentElement.style.display = 'flex';
          if (lastNameInput && lastNameInput.parentElement && lastNameInput.parentElement.parentElement) {
            lastNameInput.parentElement.parentElement.style.display = 'flex';
          }
          
          const titleEl = modal.querySelector('h3');
          if (titleEl) titleEl.innerHTML = '🔑 アカウントの本登録';
          
          if (lastNameInput) lastNameInput.value = metadata.lastName || '';
          if (firstNameInput) firstNameInput.value = metadata.firstName || '';
          if (birthdayInput) birthdayInput.value = metadata.birthday || '';
          if (genderSelect) genderSelect.value = metadata.gender || '';
          if (loginIdInput) loginIdInput.value = metadata.loginId || '';
          if (phoneInput) phoneInput.value = metadata.phone || metadata.phone_number || '';
          if (pwdInput) pwdInput.value = '';
          if (pwdConfirmInput) pwdConfirmInput.value = '';
          
          modal.style.display = 'flex';
          showToast('メール認証に成功しました。プロフィールとパスワードを設定してください。', 'success');
        }
      } else {
        showLoginScreen(false);
        
        const nameEl = document.getElementById('logged-in-user-name');
        const avatarEl = document.getElementById('logged-in-user-avatar');
        if (nameEl) nameEl.textContent = name;
        if (avatarEl) avatarEl.textContent = name.charAt(0);
        
        updateUIForCurrentMode();
        removeRestrictedTabsForRole(role);
        
        // 💡 ログイン成功時の画面遷移
        if (canAccessHomeScreen()) {
          switchView('home-screen');
        } else {
          switchView('mypage-screen');
          if (typeof openMyPage === 'function') openMyPage();
        }
        if (typeof updateServiceUIState === 'function') updateServiceUIState();
        if (typeof checkAndShowUnmergedFormsLoginNotice === 'function') {
          checkAndShowUnmergedFormsLoginNotice();
        }
        
        // ログイン成功時にバックグラウンドで管理者の共有メモをロードする
        loadAdminSharedMemos().catch(err => console.error('[Supabase API] Shared load error on login:', err));
      }
    } else {
      // 💡 [ローカルモックログイン保護] ローカル環境で手動で logged_user を設定している場合（モックセッション中）は、
      // Supabase のセッション無し（null）による自動ログアウトを無視してログイン状態を維持する
      const isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
      const hasMockUser = localStorage.getItem(STORAGE_KEYS.LOGGED_USER);
      
      if (isLocal && hasMockUser) {
        console.log("[Supabase Auth] Session is null, but keeping mock local user session active.");
        if (typeof checkLoginStatus === 'function') {
          checkLoginStatus();
        }
      } else {
        state.decryptedVaultContent = null;
        state.memoUnlockedSecure = false;
        state.lastVaultAccessTime = 0;
        state.currentUser = null;
        localStorage.removeItem(STORAGE_KEYS.LOGGED_USER);
        showLoginScreen(true);
      }
    }
  });
  
  authListenerSubscription = data.subscription || data;
}

