async function fetchNewPartyId(sourceSystem = 'synapse_appoint', isTemporary = true) {
  if (partnerSupabaseClient) {
    try {
      const { data, error } = await partnerSupabaseClient.rpc('generate_party_id', {
        source_system: sourceSystem,
        is_temporary: isTemporary
      });
      if (error) throw error;
      if (data) {
        console.log(`[Party ID] Generated successfully via partner DB: ${data}`);
        // DBで発行されたIDも即座にローカルIDログに登録して同期追跡する
        logLocalPartyId(data, sourceSystem, isTemporary ? 'temporary' : 'active');
        return data;
      }
    } catch (err) {
      console.error('[Party ID] Failed to fetch from partner DB, falling back to local generation:', err);
    }
  } else {
    console.log('[Party ID] Partner DB Supabase client not initialized. Falling back to local generation.');
  }
  
  // フォールバック：ローカルの8桁ID生成ロジックを使用
  const localId = generate8DigitId();
  // ローカルIDログにも即座に記録
  logLocalPartyId(localId, sourceSystem, isTemporary ? 'temporary' : 'active');
  return localId;
}

// === ローカルでのParty ID発行・ステータス履歴の管理 ===
function logLocalPartyId(partyId, source = 'synapse_appoint', status = 'temporary') {
  const key = 'synapse_local_party_ids';
  let localIds = [];
  try {
    const saved = localStorage.getItem(key);
    if (saved) localIds = JSON.parse(saved);
  } catch (e) {}

  const exists = localIds.find(item => item.party_id === partyId);
  if (!exists) {
    localIds.push({
      party_id: partyId,
      seq_value: 1, // 新規ローカル生成IDのシーケンスは初期値の「1」から開始する
      source: source,
      status: status,
      created_at: new Date().toISOString(),
      reset_at: null,
      activated_at: null
    });
    localStorage.setItem(key, JSON.stringify(localIds));
    console.log(`[Local Party ID] Logged new ID: ${partyId} (${status})`);
  }
}

function replaceLocalPartyId(oldId, newId) {
  const key = 'synapse_local_party_ids';
  let localIds = [];
  try {
    const saved = localStorage.getItem(key);
    if (saved) localIds = JSON.parse(saved);
  } catch (e) {}

  const index = localIds.findIndex(item => item.party_id === oldId);
  if (index !== -1) {
    // 重複登録を避ける
    const alreadyExists = localIds.some(item => item.party_id === newId);
    if (alreadyExists) {
      localIds.splice(index, 1);
    } else {
      localIds[index].party_id = newId;
      localIds[index].created_at = new Date().toISOString();
    }
    localStorage.setItem(key, JSON.stringify(localIds));
    console.log(`[Local Party ID] Replaced temporary ID ${oldId} with official ID ${newId}`);
  } else {
    // 古いIDが見つからない場合は新規登録
    logLocalPartyId(newId, 'synapse_appoint', 'temporary');
  }
}

function updateLocalPartyIdStatus(partyId, newStatus, additionalData = {}) {
  const key = 'synapse_local_party_ids';
  let localIds = [];
  try {
    const saved = localStorage.getItem(key);
    if (saved) localIds = JSON.parse(saved);
  } catch (e) {}

  const target = localIds.find(item => item.party_id === partyId);
  if (target) {
    target.status = newStatus;
    if (newStatus === 'reusable') {
      target.reset_at = additionalData.reset_at || new Date().toISOString();
      target.activated_at = null;
    } else if (newStatus === 'active') {
      target.activated_at = additionalData.activated_at || new Date().toISOString();
      target.reset_at = null;
    }
    localStorage.setItem(key, JSON.stringify(localIds));
    console.log(`[Local Party ID] Updated status for ${partyId} to ${newStatus}`);
  } else {
    // 存在しない場合は新規登録して更新
    logLocalPartyId(partyId, 'synapse_appoint', newStatus);
    if (newStatus !== 'temporary') {
      updateLocalPartyIdStatus(partyId, newStatus, additionalData);
    }
  }
}

// === Party ID 管理画面のロジック ===
function getPartyIdStatusInfo(item, now = new Date()) {
  const createdDate = new Date(item.created_at || item.reset_at || now);
  const createdDiffDays = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));
  const isManualReset = !!item.reset_at;
  const isAutoReset = !item.reset_at && createdDiffDays >= 365 * 3;

  if (item.status === 'temporary') {
    return {
      key: 'temporary',
      label: '仮発行 (temporary)',
      badgeHtml: `<span style="background: rgba(245, 158, 11, 0.15); color: #f59e0b; padding: 0.15rem 0.4rem; border-radius: var(--radius-xs); font-weight: 600; font-size: 0.72rem;">仮発行 (temporary)</span>`,
      isResettable: true
    };
  }

  if (item.status === 'active') {
    const isConnectedToContract = 
      (state.apContracts?.some(ap => ap.customerPersonalityId === item.party_id)) ||
      (state.joContracts?.some(jo => jo.customerPersonalityId === item.party_id));
    
    if (isConnectedToContract) {
      return {
        key: 'active',
        label: 'Party ID昇格 (active)',
        badgeHtml: `<span style="background: rgba(16, 185, 129, 0.1); color: #10b981; padding: 0.15rem 0.4rem; border-radius: var(--radius-xs); font-weight: 600; font-size: 0.72rem;">Party ID昇格 (active)</span>`,
        isResettable: false
      };
    } else {
      return {
        key: 'registered',
        label: 'アポイント登録完了 (registered)',
        badgeHtml: `<span style="background: rgba(13, 148, 136, 0.1); color: #0d9488; padding: 0.15rem 0.4rem; border-radius: var(--radius-xs); font-weight: 600; font-size: 0.72rem;">アポイント登録完了 (registered)</span>`,
        isResettable: false
      };
    }
  }

  if (item.status === 'reusable') {
    if (isManualReset || isAutoReset) {
      let remainingDays = 0;
      if (isManualReset) {
        const resetDiffDays = Math.floor((now - new Date(item.reset_at)) / (1000 * 60 * 60 * 24));
        remainingDays = (365 * 3) - resetDiffDays;
      } else {
        remainingDays = (365 * 6) - createdDiffDays;
      }
      return {
        key: 'cooling',
        label: '冷却中 (cooling)',
        badgeHtml: `<span style="background: rgba(107, 114, 128, 0.1); color: #6b7280; padding: 0.15rem 0.4rem; border-radius: var(--radius-xs); font-weight: 600; font-size: 0.72rem;">冷却中 (${remainingDays}日後再利用可)</span>`,
        isResettable: true
      };
    } else {
      return {
        key: 'discarded',
        label: 'アポイント発行後破棄 (discarded)',
        badgeHtml: `<span style="background: rgba(239, 68, 68, 0.08); color: #ef4444; padding: 0.15rem 0.4rem; border-radius: var(--radius-xs); font-weight: 600; font-size: 0.72rem;">アポイント発行後破棄</span>`,
        isResettable: true
      };
    }
  }

  return {
    key: 'unknown',
    label: item.status || '不明',
    badgeHtml: `<span style="background: rgba(107, 114, 128, 0.1); color: #6b7280; padding: 0.15rem 0.4rem; border-radius: var(--radius-xs); font-weight: 600; font-size: 0.72rem;">${item.status || '不明'}</span>`,
    isResettable: false
  };
}

function getSelectedPartyIdStatuses() {
  const cbs = Array.from(document.querySelectorAll('.party-id-status-cb:checked'));
  return cbs.map(cb => cb.value);
}

function updatePartyIdStatusDropdownLabel() {
  const labelEl = document.getElementById('party-id-status-dropdown-label');
  if (!labelEl) return;
  const allCbs = Array.from(document.querySelectorAll('.party-id-status-cb'));
  const checkedCbs = allCbs.filter(cb => cb.checked);
  
  const statusNameMap = {
    temporary: '仮発行',
    registered: 'アポ登録済',
    active: 'Party ID昇格',
    discarded: '破棄',
    cooling: '冷却中'
  };

  if (checkedCbs.length === allCbs.length) {
    labelEl.textContent = `すべて (${allCbs.length})`;
  } else if (checkedCbs.length === 0) {
    labelEl.textContent = '選択なし (0)';
  } else if (checkedCbs.length <= 2) {
    const names = checkedCbs.map(cb => statusNameMap[cb.value] || cb.value);
    labelEl.textContent = `${names.join(', ')} (${checkedCbs.length})`;
  } else {
    const firstTwo = checkedCbs.slice(0, 2).map(cb => statusNameMap[cb.value] || cb.value);
    labelEl.textContent = `${firstTwo.join(', ')} +${checkedCbs.length - 2} (${checkedCbs.length})`;
  }
}

function updatePartyIdSelectionDisplay(tableBody) {
  const countBadge = document.getElementById('party-id-selected-count-badge');
  const countText = document.getElementById('party-id-selected-count-text');
  const countDot = document.getElementById('party-id-selected-count-dot');
  const selectAllCheckbox = document.getElementById('party-id-select-all');
  const bulkResetBtn = document.getElementById('btn-bulk-reset-party-ids');

  const allRowCbs = tableBody ? Array.from(tableBody.querySelectorAll('.party-id-row-checkbox')) : [];
  const checkedCbs = allRowCbs.filter(cb => cb.checked);
  const selectedCount = checkedCbs.length;
  const totalCount = allRowCbs.length;

  if (countText) {
    countText.textContent = `${selectedCount}件を選択中`;
  }
  if (countBadge && countDot) {
    if (selectedCount > 0) {
      countBadge.style.background = 'rgba(59, 130, 246, 0.12)';
      countBadge.style.color = 'var(--primary)';
      countBadge.style.borderColor = 'rgba(59, 130, 246, 0.4)';
      countBadge.style.fontWeight = '700';
      countDot.style.background = 'var(--primary)';
    } else {
      countBadge.style.background = 'var(--bg-surface)';
      countBadge.style.color = 'var(--text-muted)';
      countBadge.style.borderColor = 'var(--border-color)';
      countBadge.style.fontWeight = '500';
      countDot.style.background = '#94a3b8';
    }
  }

  if (selectAllCheckbox) {
    if (totalCount === 0) {
      selectAllCheckbox.checked = false;
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.disabled = true;
      selectAllCheckbox.style.cursor = 'not-allowed';
      selectAllCheckbox.style.opacity = '0.4';
    } else {
      selectAllCheckbox.disabled = false;
      selectAllCheckbox.style.cursor = 'pointer';
      selectAllCheckbox.style.opacity = '1';
      if (selectedCount === totalCount) {
        selectAllCheckbox.checked = true;
        selectAllCheckbox.indeterminate = false;
      } else if (selectedCount > 0) {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = true;
      } else {
        selectAllCheckbox.checked = false;
        selectAllCheckbox.indeterminate = false;
      }
    }
  }

  if (bulkResetBtn) {
    const resettableCheckedCbs = checkedCbs.filter(cb => cb.getAttribute('data-resettable') === 'true');
    const resettableCount = resettableCheckedCbs.length;

    if (selectedCount > 0) {
      if (resettableCount > 0) {
        bulkResetBtn.disabled = false;
        bulkResetBtn.style.opacity = '1';
        bulkResetBtn.style.cursor = 'pointer';
        if (resettableCount === selectedCount) {
          bulkResetBtn.innerHTML = `🔄 選択した ${resettableCount}件のIDを一括リセット`;
        } else {
          bulkResetBtn.innerHTML = `🔄 選択中のリセット対象 ${resettableCount}件を一括リセット`;
        }
      } else {
        bulkResetBtn.disabled = true;
        bulkResetBtn.style.opacity = '0.5';
        bulkResetBtn.style.cursor = 'not-allowed';
        bulkResetBtn.innerHTML = `🔄 選択したIDを一括リセット (対象外)`;
      }
    } else {
      bulkResetBtn.disabled = true;
      bulkResetBtn.style.opacity = '0.5';
      bulkResetBtn.style.cursor = 'not-allowed';
      bulkResetBtn.innerHTML = `🔄 選択したIDを一括リセット`;
    }
  }
}

async function loadPartyIds() {
  const tableBody = document.getElementById('party-id-list-table-body');
  if (!tableBody) return;

  tableBody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-secondary);"><i class="spinner"></i> データを読み込み中...</td></tr>`;
  updatePartyIdSelectionDisplay(null);

  let partyIds = [];
  let isFallback = false;
  let fallbackMessage = '';

  if (partnerSupabaseClient) {
    try {
      // partnerSupabaseClient からデータを全件取得 (ソートはcreated_atの降順)
      const { data, error } = await partnerSupabaseClient
        .from('party_ids')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      partyIds = data || [];
    } catch (err) {
      console.warn('[Supabase Partner] Failed to load party IDs from DB. Falling back to local drafts:', err);
      isFallback = true;
      fallbackMessage = err.message;
    }
  } else {
    isFallback = true;
    fallbackMessage = 'パートナーDBが初期化されていません。';
  }

  // ローカルログをロードしてマージ表示
  let localIds = [];
  try {
    const saved = localStorage.getItem('synapse_local_party_ids');
    if (saved) {
      localIds = JSON.parse(saved);
      let hasChange = false;
      localIds.forEach(item => {
        if (item.seq_value !== 1) {
          item.seq_value = 1;
          hasChange = true;
        }
      });
      if (hasChange) {
        localStorage.setItem('synapse_local_party_ids', JSON.stringify(localIds));
      }
    }
  } catch (e) {}

  // DBデータとローカルデータをマージ（IDをキーにして重複排除、DB側のデータを優先）
  let mergedMap = new Map();
  
  // 先にローカルデータを登録
  localIds.forEach(item => {
    mergedMap.set(item.party_id, { ...item, isLocalOnly: true });
  });

  // DBデータで上書き（DB側のステータスや正確なシーケンス値を優先）
  partyIds.forEach(item => {
    mergedMap.set(item.party_id, { ...item, isLocalOnly: false });
  });

  const mergedList = Array.from(mergedMap.values());
  
  // 作成日時の降順でソート
  mergedList.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

  if (mergedList.length === 0) {
    const emptyMsg = isFallback 
      ? `発行済みのParty IDはありません。<br><span style="font-size: 0.72rem; color: var(--text-muted);">(※パートナーDBの接続エラー: ${fallbackMessage})</span>`
      : '発行済みのParty IDはありません。';
    tableBody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-muted);">${emptyMsg}</td></tr>`;
    updatePartyIdSelectionDisplay(tableBody);
    return;
  }

  // クライアントサイドでのフィルタリングの適用
  const selectedStatuses = getSelectedPartyIdStatuses();
  updatePartyIdStatusDropdownLabel();

  const filterPeriod = document.getElementById('party-id-filter-period')?.value || '';
  const filterSearch = document.getElementById('party-id-filter-search')?.value.trim().toLowerCase() || '';

  const now = new Date();

  const filtered = mergedList.filter(item => {
    // 再利用可能になったID (冷却ロック期間が満了したID) は一覧から削除 (非表示) とする
    if (item.status === 'reusable') {
      const createdDate = new Date(item.created_at || item.reset_at || now);
      const createdDiffDays = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));
      
      if (item.reset_at) {
        // 手動リセットの場合：リセット日から3年経過で冷却満了
        const resetDiffDays = Math.floor((now - new Date(item.reset_at)) / (1000 * 60 * 60 * 24));
        if (resetDiffDays >= 365 * 3) return false;
      } else {
        // 自動リセットの場合：破棄から6年経過 (3年後に自動冷却開始 + 3年冷却) で冷却満了
        if (createdDiffDays >= 365 * 6) return false;
      }
    }

    const statusInfo = getPartyIdStatusInfo(item, now);

    // ステータスフィルター（複数選択）
    if (selectedStatuses.length === 0) {
      return false; // 1つも選択されていない場合は表示しない
    }
    if (!selectedStatuses.includes(statusInfo.key)) {
      return false;
    }

    // 期間フィルター
    if (filterPeriod) {
      const itemDate = new Date(item.status === 'reusable' ? (item.reset_at || item.created_at) : item.created_at);
      const diffMs = now - itemDate;
      const diffDays = diffMs / (1000 * 60 * 60 * 24);

      if (filterPeriod === '3years') {
        if (item.status !== 'reusable') return false;
        const resetDate = new Date(item.reset_at || item.created_at);
        const resetDiffDays = (now - resetDate) / (1000 * 60 * 60 * 24);
        if (resetDiffDays < 365 * 3) return false;
      } else if (filterPeriod === '1year' && diffDays < 365) {
        return false;
      } else if (filterPeriod === '30days' && diffDays < 30) {
        return false;
      }
    }

    // 検索ワードフィルター
    if (filterSearch) {
      const idMatch = item.party_id.toLowerCase().includes(filterSearch);
      const sourceMatch = (item.source || '').toLowerCase().includes(filterSearch);
      if (!idMatch && !sourceMatch) return false;
    }

    return true;
  });

  if (filtered.length === 0) {
    tableBody.innerHTML = `<tr><td colspan="8" style="text-align: center; padding: 2rem; color: var(--text-muted);">該当するデータがありません。</td></tr>`;
    updatePartyIdSelectionDisplay(tableBody);
    return;
  }

  // テーブルの描画
  tableBody.innerHTML = '';
  filtered.forEach(item => {
    const tr = document.createElement('tr');
    tr.style.borderBottom = '1px solid var(--border-color)';
    
    const statusInfo = getPartyIdStatusInfo(item, now);

    // 日時フォーマット
    const formatDate = (isoString) => {
      if (!isoString) return '-';
      const d = new Date(isoString);
      return `${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
    };

    // 操作ボタン (リセット可能ならリセットボタン、不可なら対象外)
    let actionBtn = '';
    if (statusInfo.isResettable) {
      actionBtn = `<button class="btn btn-sm btn-danger btn-reset-party-id" data-id="${item.party_id}" style="padding: 0.25rem 0.5rem; font-size: 0.7rem; font-weight: 600;">🔄 リセット</button>`;
    } else {
      actionBtn = `<button class="btn btn-sm btn-secondary" style="padding: 0.25rem 0.5rem; font-size: 0.7rem; font-weight: 600; opacity: 0.4; cursor: not-allowed;" disabled title="契約中のためリセット不可">対象外</button>`;
    }

    // チェックボックス表示 (どのステータスであっても必ず選択可能)
    const checkboxHtml = `<input type="checkbox" class="party-id-row-checkbox" data-id="${item.party_id}" data-status="${statusInfo.key}" data-resettable="${statusInfo.isResettable ? 'true' : 'false'}" style="cursor: pointer;">`;

    let errorBadge = '';
    if (item.isLocalOnly) {
      errorBadge = `<span style="font-size: 0.65rem; color: #ef4444; border: 1px solid #ef4444; border-radius: 2px; padding: 0 0.15rem; margin-left: 0.35rem; font-weight: bold;" title="DB同期が失敗したためローカルデータを一時表示中">ローカルのみ</span>`;
    }

    tr.innerHTML = `
      <td style="padding: 0.75rem 1rem; text-align: center;">${checkboxHtml}</td>
      <td style="padding: 0.75rem 1rem; font-weight: 600; font-family: monospace; font-size: 0.85rem; color: var(--text-primary);">${item.party_id}${errorBadge}</td>
      <td style="padding: 0.75rem 1rem; color: var(--text-secondary);">${item.seq_value || '-'}</td>
      <td style="padding: 0.75rem 1rem; color: var(--text-secondary);">${item.source || '-'}</td>
      <td style="padding: 0.75rem 1rem;">${statusInfo.badgeHtml}</td>
      <td style="padding: 0.75rem 1rem; color: var(--text-muted);">${formatDate(item.status === 'reusable' ? item.reset_at : item.created_at)}</td>
      <td style="padding: 0.75rem 1rem; color: var(--text-muted);">${formatDate(item.activated_at)}</td>
      <td style="padding: 0.75rem 1rem; text-align: center;">${actionBtn}</td>
    `;

    tableBody.appendChild(tr);
  });

  // リセットボタンにイベントリスナーを貼る
  tableBody.querySelectorAll('.btn-reset-party-id').forEach(btn => {
    btn.addEventListener('click', () => {
      const id = btn.getAttribute('data-id');
      resetPartyId(id);
    });
  });

  // 全選択チェックボックスの制御イベント
  const selectAllCheckbox = document.getElementById('party-id-select-all');
  if (selectAllCheckbox) {
    selectAllCheckbox.checked = false;
    selectAllCheckbox.indeterminate = false;
    selectAllCheckbox.onchange = (e) => {
      const checked = e.target.checked;
      const rowCheckboxes = tableBody.querySelectorAll('.party-id-row-checkbox');
      rowCheckboxes.forEach(cb => {
        cb.checked = checked;
      });
      updatePartyIdSelectionDisplay(tableBody);
    };
  }

  // 個別チェックボックスの制御イベント
  tableBody.querySelectorAll('.party-id-row-checkbox').forEach(cb => {
    cb.onchange = () => {
      updatePartyIdSelectionDisplay(tableBody);
    };
  });

  // 初期値の同期（「0件を選択中」）
  updatePartyIdSelectionDisplay(tableBody);

  // 一括リセットボタンのクリックイベント
  const bulkResetBtn = document.getElementById('btn-bulk-reset-party-ids');
  if (bulkResetBtn) {
    bulkResetBtn.onclick = async () => {
      const checkedResettableCbs = Array.from(tableBody.querySelectorAll('.party-id-row-checkbox:checked'))
        .filter(cb => cb.getAttribute('data-resettable') === 'true');
      const checkedIds = checkedResettableCbs.map(cb => cb.getAttribute('data-id'));
      
      if (checkedIds.length === 0) return;

      const isConfirmed = confirm(`警告: 選択した ${checkedIds.length}件の Party ID を一括で再利用可能（リセット）にします。\nこれらのIDは本日から「さらに3年間」経過するまで再発行はされません。\n実行してよろしいですか？`);
      if (!isConfirmed) return;

      showToast(`選択した ${checkedIds.length}件のIDを一括リセットしています...`, 'info');

      let successCount = 0;
      let failCount = 0;

      for (const partyId of checkedIds) {
        try {
          let dbSuccess = false;
          if (partnerSupabaseClient) {
            const { error } = await partnerSupabaseClient
              .from('party_ids')
              .update({
                status: 'reusable',
                reset_at: new Date().toISOString(),
                activated_at: null
              })
              .eq('party_id', partyId);
            if (!error) dbSuccess = true;
          }
          updateLocalPartyIdStatus(partyId, 'reusable');
          successCount++;
        } catch (err) {
          console.error(`[Party ID] Bulk reset failed for ${partyId}:`, err);
          failCount++;
        }
      }

      if (failCount > 0) {
        showToast(`${successCount}件のリセットに成功しました。${failCount}件に失敗しました。`, 'warning');
      } else {
        showToast(`選択した ${successCount}件の Party ID をリセットしました。冷却ロック（3年間）が開始されます。`, 'success');
      }

      loadPartyIds(); // テーブル再読み込み
    };
  }
}

async function resetPartyId(partyId) {
  const isConfirmed = confirm(`警告: Party ID 「${partyId}」を再利用可能（リセット）にします。\nこのIDはリセット実行日から「さらに3年間」経過するまで再発行はされません。\nよろしいですか？`);
  if (!isConfirmed) return;

  let dbSuccess = false;
  let errorMsg = '';

  if (partnerSupabaseClient) {
    try {
      const { error } = await partnerSupabaseClient
        .from('party_ids')
        .update({
          status: 'reusable',
          reset_at: new Date().toISOString(),
          activated_at: null
        })
        .eq('party_id', partyId);

      if (error) throw error;
      dbSuccess = true;
    } catch (err) {
      console.error('[Supabase Partner] Failed to reset party ID in DB:', err);
      errorMsg = err.message;
    }
  }

  // DBの成否に関わらず、ローカルログ側のステータスを reusable に更新してフェイルセーフにする
  updateLocalPartyIdStatus(partyId, 'reusable');

  if (partnerSupabaseClient && !dbSuccess) {
    showToast(`DB同期は失敗しましたが、ローカル上で ${partyId} をリセットしました (エラー: ${errorMsg})。`, 'warning');
  } else {
    showToast(`Party ID ${partyId} をリセットしました。リセットから3年経過後に自動的に再利用されます。`, 'success');
  }

  loadPartyIds(); // テーブル再読み込み
}

// Supabaseへのデータ送信 (プッシュ)
// 同期ステータスUIの更新
function updateSyncStatusUI() {
  const indicator = document.getElementById('sync-status-indicator');
  const icon = document.getElementById('sync-status-icon');
  const text = document.getElementById('sync-status-text');
  if (!indicator || !icon || !text) return;

  const hasOfflineErrors = state.syncQueue.some(t => t.status === 'error');
  const isSyncingNow = state.syncQueue.some(t => t.status === 'pending');

  if (state.syncQueue.length === 0) {
    icon.textContent = '🟢';
    text.textContent = '同期済み';
    indicator.style.background = 'var(--bg-surface-elevated)';
    indicator.style.color = 'var(--text-secondary)';
    indicator.style.borderColor = 'var(--border-color)';
  } else if (hasOfflineErrors) {
    icon.textContent = '☁️';
    text.textContent = `未同期の変更が ${state.syncQueue.length} 件あります (オフライン)`;
    indicator.style.background = '#fef08a'; // 薄いイエロー
    indicator.style.color = '#854d0e';      // ダークイエロー
    indicator.style.borderColor = '#eab308';
  } else if (isSyncingNow) {
    icon.textContent = '🔄';
    text.textContent = '同期中...';
    indicator.style.background = 'var(--bg-surface-elevated)';
    indicator.style.color = 'var(--text-secondary)';
    indicator.style.borderColor = 'var(--border-color)';
  }
}

// 送信待ちキューの永続化保存
function saveSyncQueueToStorage() {
  originalSetItem('synapse_sync_queue', JSON.stringify(state.syncQueue));
}

// 起動時等のキュー復旧
function loadSyncQueueFromStorage() {
  const saved = localStorage.getItem('synapse_sync_queue');
  if (saved) {
    try {
      state.syncQueue = JSON.parse(saved);
      // 再起動時はステータスを待機状態に戻す
      state.syncQueue.forEach(t => t.status = 'error');
      updateSyncStatusUI();
    } catch (e) {
      console.error("[Supabase] Failed to parse sync queue:", e);
    }
  }
}

// 送信待ちキューのバックグラウンド再送信処理
async function processSyncQueue() {
  if (state.syncQueue.length === 0 || !supabaseClient) return;

  const failedTasks = state.syncQueue.filter(t => t.status === 'error');
  if (failedTasks.length === 0) return;

  console.log(`[Supabase] Retrying ${failedTasks.length} pending sync tasks...`);
  
  for (const task of failedTasks) {
    await syncToSupabase(task.key, task.value);
  }
}

// オンライン復帰時の自動イベントリスナー
window.addEventListener('online', () => {
  console.log("[Network] Connection recovered. Triggering sync queue retry...");
  processSyncQueue();
});

// 定期タイマーによる再試行（30秒おき）
setInterval(() => {
  processSyncQueue();
}, 30000);

// クラウド（Supabase）からユーザー個別設定を取得し、ローカルに適用する
async function loadUserSettingsFromCloud() {
  if (!supabaseClient || !state.currentUser) return;
  
  const userId = state.currentUser.id;
  try {
    const { data, error } = await supabaseClient
      .from('user_profiles')
      .select('*')
      .eq('user_id', userId)
      .maybeSingle();

    if (error) {
      console.error("[Supabase] Failed to load user profiles:", error);
      return;
    }

    if (data) {
      console.log("[Supabase] Applying user profiles from cloud:", data);
      
      state.defaultZoomLevel = data.zoom_level || 100;
      localStorage.setItem(`SYNAPSE_ZOOM_DEFAULT_${userId}`, state.defaultZoomLevel);
      applyZoom(state.defaultZoomLevel);

      const theme = data.ui_theme || 'light';
      localStorage.setItem(`SYNAPSE_THEME_${userId}`, theme);
      applyTheme(theme);

      if (data.background_settings) {
        const hue = data.background_settings.hue ?? 0;
        const sat = data.background_settings.saturation ?? 100;
        localStorage.setItem(`SYNAPSE_HUE_${userId}`, hue);
        localStorage.setItem(`SYNAPSE_SATURATION_${userId}`, sat);
        applyColorTone(hue, sat);
        localStorage.setItem(`SYNAPSE_BG_SETTINGS_${userId}`, JSON.stringify(data.background_settings));
        applyMypageIconOrder();
      }
    }
  } catch (e) {
    console.error("[Supabase] Error loading user profiles:", e);
  }
}

// ストレージキーから対応するテーブル画面IDを特定するヘルパー
function getTableIdFromStorageKey(key) {
  if (!key) return null;
  if (key === STORAGE_KEYS.JO_CONTRACTS || key === STORAGE_KEYS.JO_COLUMNS) return 'jo-info-screen';
  if (key === STORAGE_KEYS.AP_CONTRACTS || key === STORAGE_KEYS.AP_COLUMNS) return 'applicant-info-screen';
  if (key === STORAGE_KEYS.AG_CONTRACTS || key === STORAGE_KEYS.AG_COLUMNS) return 'agency-info-screen';
  if (key === 'synapse_dbmake_partners' || key === STORAGE_KEYS.DBMAKE_COLUMNS) return 'dbmake-screen';
  if (typeof key === 'string' && key.startsWith('custom-table-')) return key;
  if (typeof key === 'string' && key.startsWith('synapse_table_')) return 'custom-table-' + key.replace('synapse_table_', '');
  return null;
}

// Supabaseへのデータ送信 (プッシュ)
async function syncToSupabase(key, value) {
  // 🛡️ テスト実行中およびテスト専用テーブルのSupabase通信を完全遮断（書き込みゼロ保証）
  if (window.__isHandlingTestSubmission) {
    return;
  }
  if (typeof key === 'string' && (key.includes('table_test_') || key.startsWith('synapse_table_table_test_'))) {
    return;
  }
  if (key === STORAGE_KEYS.CUSTOM_TABLES || key === 'synapse_custom_tables') {
    if (Array.isArray(value)) {
      value = value.filter(t => !t || !t.isTestTable);
    }
  }

  // 🛡️ サーバー通信時の編集保護（WRITEガード）
  // オーナー以外の一般ユーザーがテーブルデータを同期しようとした場合、編集ロックおよびアクセス権限を厳格検証
  const targetTableId = getTableIdFromStorageKey(key);
  if (targetTableId && !isOwnerUser()) {
    // 1. テーブル編集ロックの検証（ロック中はサーバーへの書き込みを拒否）
    if (typeof isTableLocked === 'function' && isTableLocked(targetTableId)) {
      console.warn(`[Security/WRITE] Sync blocked for key ${key} (table ${targetTableId}). Table is edit-locked.`);
      state.syncQueue = state.syncQueue.filter(t => t.key !== key);
      saveSyncQueueToStorage();
      updateSyncStatusUI();
      showToast(`【権限制限】シート「${targetTableId}」の編集がロックされているため、サーバーへの保存はブロックされました。`, 'warning');
      return;
    }
    // 2. テーブル自体のアクセス権限の検証（権限なしユーザーの書き込みを拒否）
    if (typeof checkTableAccess === 'function') {
      const tableAccess = checkTableAccess(targetTableId);
      if (!tableAccess.visible) {
        console.warn(`[Security/WRITE] Sync blocked for key ${key} (table ${targetTableId}). User has no access permission.`);
        state.syncQueue = state.syncQueue.filter(t => t.key !== key);
        saveSyncQueueToStorage();
        updateSyncStatusUI();
        showToast(`【権限制限】シート「${targetTableId}」へのアクセス権限がないため、サーバーへの書き込みはブロックされました。`, 'warning');
        return;
      }
    }
  }

  // 同期がオンフライトでない場合はキューを制御
  let task = state.syncQueue.find(t => t.key === key);
  if (!task) {
    task = { key, value, status: 'pending' };
    state.syncQueue.push(task);
  } else {
    task.value = value;
    task.status = 'pending';
  }
  saveSyncQueueToStorage();
  updateSyncStatusUI();

  if (!supabaseClient) {
    console.warn(`[Supabase] Client not initialized. Key ${key} queued.`);
    task.status = 'error';
    saveSyncQueueToStorage();
    updateSyncStatusUI();
    return;
  }

  try {
    const valString = typeof value === 'string' ? value : JSON.stringify(value);
    
    if (key === STORAGE_KEYS.USERS) {
      // 💡 [自動逆同期の制限]
      // ローカルストレージの変更をトリガーにした全ユーザーの一括逆同期（クラウドへの再アップロード）は、
      // データベース側で直接削除したユーザーが勝手に復活する原因となるため、実行を制限します。
      // 新規登録や承認などの個別変更は、各処理のタイミングで個別にDBへ保存されています。
      console.log('[Supabase] Single-source-of-truth bypass: Skip bulk syncing users from localStorage to prevent accidental restoration.');
    } else if (key.startsWith('SYNAPSE_ZOOM_DEFAULT_') || key.startsWith('SYNAPSE_THEME_') || key.startsWith('SYNAPSE_HUE_') || key.startsWith('SYNAPSE_SATURATION_') || key.startsWith('SYNAPSE_BG_SETTINGS_')) {
      // ユーザー設定の同期
      const userId = state.currentUser ? state.currentUser.id : 'guest';
      const zoom = localStorage.getItem(`SYNAPSE_ZOOM_DEFAULT_${userId}`) || '100';
      const theme = localStorage.getItem(`SYNAPSE_THEME_${userId}`) || 'light';
      const hue = localStorage.getItem(`SYNAPSE_HUE_${userId}`) || '0';
      const sat = localStorage.getItem(`SYNAPSE_SATURATION_${userId}`) || '100';

      // 既存の background_settings (iconOrder 等を含む) をマージ
      let bgSettings = { hue: parseInt(hue, 10), saturation: parseInt(sat, 10) };
      try {
        const raw = localStorage.getItem(`SYNAPSE_BG_SETTINGS_${userId}`);
        if (raw) {
          const parsed = JSON.parse(raw);
          bgSettings = { ...parsed, ...bgSettings };
        }
      } catch (e) {
        console.error("[Supabase] Failed to merge background_settings:", e);
      }

      const { error } = await supabaseClient
        .from('user_profiles')
        .upsert({
          user_id: userId,
          zoom_level: parseInt(zoom, 10),
          ui_theme: theme,
          background_settings: bgSettings,
          updated_at: new Date().toISOString()
        });

    } else if (key.startsWith('todo-task-') || key.startsWith('google-task-') || key.startsWith('asana-task-')) {
      // ToDoタスクの同期
      const taskData = typeof value === 'string' ? JSON.parse(value) : value;
      const { error } = await supabaseClient
        .from('synapse_todo_tasks')
        .upsert(taskData);
      if (error) throw error;
    } else {
      let parsedValue;
      try {
        parsedValue = JSON.parse(valString);
      } catch (_) {
        parsedValue = valString;
      }
      
      const { error } = await supabaseClient
        .from('synapse_storage')
        .upsert({ key: key, value: parsedValue, updated_at: new Date().toISOString() });
      
      if (error) {
        throw error;
      }
    }

    // 成功時：キューから削除
    state.syncQueue = state.syncQueue.filter(t => t.key !== key);
    saveSyncQueueToStorage();
    updateSyncStatusUI();
    console.log(`[Supabase] Sync success for key ${key}`);
  } catch (e) {
    console.error(`[Supabase] Error during syncToSupabase for key ${key}:`, e);
    task.status = 'error';
    saveSyncQueueToStorage();
    updateSyncStatusUI();
  }
}

// ToDo専用のオフライン同期キューへの追加ヘルパー
function pushToSyncQueue(table, data) {
  if (table === 'synapse_todo_tasks') {
    syncToSupabase(`todo-task-${data.id}`, data);
  }
}

// Supabaseからのデータ取得 (プル)
function showLoadingIndicator(show) {
  let indicator = document.getElementById('global-loading-indicator');
  if (show) {
    if (!indicator) {
      indicator = document.createElement('div');
      indicator.id = 'global-loading-indicator';
      indicator.style.cssText = 'position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(15, 23, 42, 0.4); backdrop-filter: blur(2px); z-index: 99999; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #ffffff; font-size: 0.9rem; font-weight: 600; font-family: sans-serif; gap: 0.75rem;';
      
      const spinner = document.createElement('div');
      spinner.style.cssText = 'width: 36px; height: 36px; border: 4px solid rgba(255, 255, 255, 0.1); border-top-color: var(--primary, #3b82f6); border-radius: 50%; animation: spin 1s linear infinite;';
      
      if (!document.getElementById('spin-keyframes')) {
        const style = document.createElement('style');
        style.id = 'spin-keyframes';
        style.innerHTML = '@keyframes spin { to { transform: rotate(360deg); } }';
        document.head.appendChild(style);
      }

      const text = document.createElement('div');
      text.textContent = 'データをロード中...';
      text.id = 'global-loading-text';

      indicator.appendChild(spinner);
      indicator.appendChild(text);
      document.body.appendChild(indicator);
    } else {
      indicator.style.display = 'flex';
    }
  } else {
    if (indicator) {
      indicator.style.display = 'none';
    }
  }
}

// クラウド（Supabase）から特定のキーのデータのみをオンデマンド取得してローカルに同期する
async function loadDataFromCloud(key, showSpinner = true) {
  if (!supabaseClient) return null;

  // 🛡️ サーバー通信時の閲覧保護（READガード）
  // 一般ユーザー（またはプレビュー中ユーザー）に該当テーブルの閲覧権限がない場合は、
  // クラウドからのデータ取得・ローカル展開をブロック
  const targetTableId = getTableIdFromStorageKey(key);
  if (targetTableId && !isOwnerUser()) {
    if (typeof checkTableAccess === 'function') {
      const access = checkTableAccess(targetTableId);
      if (!access.visible) {
        console.warn(`[Security/READ] Load blocked for key ${key} (table ${targetTableId}). User has no read permission.`);
        return null;
      }
    }
  }
  
  if (showSpinner) {
    showLoadingIndicator(true);
  }

  try {
    console.log(`[Supabase] Loading data for key: ${key}...`);
    const { data, error } = await supabaseClient
      .from('synapse_storage')
      .select('value')
      .eq('key', key)
      .maybeSingle();

    if (error) {
      console.error(`[Supabase] Load failed for key ${key}:`, error);
      showToast(`データ取得エラー (${key}): ${error.message}`, "error");
      return null;
    }

    if (data && data.value) {
      const valStr = JSON.stringify(data.value);
      localStorage.setItem(key, valStr);
      
      // state 内の該当キーを更新
      loadStateFromLocalStorage([key]);
      return data.value;
    }
    
    return null;
  } catch (e) {
    console.error(`[Supabase] Exception during loadDataFromCloud for key ${key}:`, e);
    return null;
  } finally {
    if (showSpinner) {
      showLoadingIndicator(false);
    }
  }
}

// Supabaseからのデータ取得 (プル)
async function syncFromSupabase(showNotification = false) {
  if (!supabaseClient) return;
  try {
    console.log("[Supabase] Pulling core data from cloud...");
    
    let updatedKeys = [];
    isSyncing = true;
    
    // 1. synapse_permissions（権限データ）をプル
    const { data: permData, error: permError } = await supabaseClient
      .from('synapse_storage')
      .select('*')
      .eq('key', STORAGE_KEYS.PERMISSIONS)
      .maybeSingle();

    if (permError) {
      console.error("[Supabase] Pull permissions failed:", permError);
    } else if (permData && permData.value) {
      const localVal = localStorage.getItem(STORAGE_KEYS.PERMISSIONS);
      const remoteValStr = JSON.stringify(permData.value);
      if (localVal !== remoteValStr) {
        localStorage.setItem(STORAGE_KEYS.PERMISSIONS, remoteValStr);
        state.permissions = permData.value || {};
        if (state.permissions.tableEditLocks) {
          if (!state.tableEditLocks) state.tableEditLocks = {};
          Object.assign(state.tableEditLocks, state.permissions.tableEditLocks);
          localStorage.setItem(STORAGE_KEYS.TABLE_EDIT_LOCKS, JSON.stringify(state.tableEditLocks));
        }
        updatedKeys.push(STORAGE_KEYS.PERMISSIONS);
      }
    }

    // 1-2. synapse_table_edit_locks（テーブル編集ロック）もプル
    const { data: lockData, error: lockError } = await supabaseClient
      .from('synapse_storage')
      .select('*')
      .eq('key', STORAGE_KEYS.TABLE_EDIT_LOCKS)
      .maybeSingle();

    if (!lockError && lockData && lockData.value) {
      const localLockStr = localStorage.getItem(STORAGE_KEYS.TABLE_EDIT_LOCKS);
      const remoteLockStr = JSON.stringify(lockData.value);
      if (localLockStr !== remoteLockStr) {
        localStorage.setItem(STORAGE_KEYS.TABLE_EDIT_LOCKS, remoteLockStr);
        if (!state.tableEditLocks) state.tableEditLocks = {};
        Object.assign(state.tableEditLocks, lockData.value);
      }
    }

    // 2. synapse_users からユーザーデータをプル
    const { data: usersData, error: usersError } = await supabaseClient
      .from('synapse_users')
      .select('*');

    if (usersError) {
      console.error("[Supabase] Pull users failed:", usersError);
      if (showNotification) {
        showToast(`ユーザー同期エラー: ${usersError.message || '接続失敗'}`, "error");
      }
      return;
    }

    try {
      // ユーザーデータの同期 (synapse_users からマッピング)
      if (usersData && Array.isArray(usersData)) {
        // [マイグレーション自動修復] Supabase上に admin または 旧 owner (id === 'owner') が残っている場合はクリーンアップ
        const legacyAdminIdx = usersData.findIndex(u => u.id === 'admin');
        if (legacyAdminIdx !== -1) {
          usersData.splice(legacyAdminIdx, 1);
          supabaseClient.from('synapse_users').delete().eq('id', 'admin').then(() => {
            console.log("[Supabase Migration] Cleaned up legacy admin (id: admin).");
          });
        }

        // 旧 owner (id === 'owner') が残っている場合は確実にSupabaseおよび配列から削除
        for (let i = usersData.length - 1; i >= 0; i--) {
          if (usersData[i].id === 'owner') {
            usersData.splice(i, 1);
          }
        }
        supabaseClient.from('synapse_users').delete().eq('id', 'owner').then(() => {
          console.log("[Supabase Migration] Cleaned up legacy owner (id: owner).");
        });

        // もし owner レコード自体がデータベースにない場合は、owner@synapse.management を強制挿入する
        const dbOwner = usersData.find(u => u.id === 'owner@synapse.management' || u.role === 'owner');
        if (!dbOwner) {
          const newOwner = {
            id: 'owner@synapse.management',
            name: 'オーナー',
            password: 'password',
            role: 'owner',
            email: 'owner@synapse.management',
            code: 'OWNER_SEED_INIT_CODE',
            created_at: new Date().toISOString()
          };
          usersData.unshift(newOwner);
          // 非同期で Supabase に owner を追加しておく
          supabaseClient.from('synapse_users').upsert(newOwner);
        }

        const mappedUsers = usersData.map(user => {
          let mappedRole = user.role || 'sales';
          let mappedStatus = 'active';
          if (mappedRole.startsWith('pending_')) {
            mappedRole = mappedRole.replace('pending_', '');
            mappedStatus = 'pending';
          }
          return {
            id: user.id,
            name: user.name,
            password: user.password,
            role: mappedRole,
            status: mappedStatus,
            email: user.email,
            code: user.code,
            createdAt: user.created_at,
            lastLoginAt: user.last_login_at,
            pwdChangedAt: user.pwd_changed_at
          };
        });

        const localVal = localStorage.getItem(STORAGE_KEYS.USERS);
        
        // 💡 [テスト環境マージ救済措置]
        // ローカルテスト中に作成されたオンボーディングユーザーが
        // DB側の同期によって消去されてしまうのを防ぐ
        const isLocal = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';
        if (isLocal) {
          const localUsers = localVal ? (JSON.parse(localVal) || []) : [];
          const backupUsers = JSON.parse(localStorage.getItem('synapse_test_users_backup') || '[]');
          
          // localVal または backupUsers の両方からテストユーザーをマージする
          const testUsersToKeep = [
            ...localUsers.filter(u => u.id.includes('onboarding_test') || u.id.includes('testuser')),
            ...backupUsers.filter(u => u.id.includes('onboarding_test') || u.id.includes('testuser'))
          ];
          
          // 重複を排除してマージ
          const seen = new Set();
          const uniqueTestUsers = [];
          for (const u of testUsersToKeep) {
            if (!seen.has(u.id.toLowerCase())) {
              seen.add(u.id.toLowerCase());
              uniqueTestUsers.push(u);
            }
          }
          
          uniqueTestUsers.forEach(testUser => {
            const idx = mappedUsers.findIndex(u => u.id.toLowerCase() === testUser.id.toLowerCase());
            if (idx === -1) {
              mappedUsers.push(testUser);
              console.warn('[Supabase Sync] Preserving local test user during remote sync (from backup):', testUser.id);
            } else {
              if (testUser.status === 'pending') {
                mappedUsers[idx].status = 'pending';
                mappedUsers[idx].role = testUser.role;
                console.warn('[Supabase Sync] Overwriting test user status to pending:', testUser.id);
              }
            }
          });
        }

        const remoteValStr = JSON.stringify(mappedUsers);
        if (localVal !== remoteValStr) {
          localStorage.setItem(STORAGE_KEYS.USERS, remoteValStr);
          updatedKeys.push(STORAGE_KEYS.USERS);
        }

        // 3. synapse_custom_tables（カスタムテーブル定義一覧）をプル＆自動キー統一
        try {
          const { data: ctData, error: ctError } = await supabaseClient
            .from('synapse_storage')
            .select('value')
            .eq('key', STORAGE_KEYS.CUSTOM_TABLES)
            .maybeSingle();

          if (!ctError && ctData && Array.isArray(ctData.value)) {
            // 🛡️ ローカルのテスト専用テーブルを退避（クラウド同期による消去を防止）
            const localTestTables = (state.customTables || []).filter(t => t && (t.isTestTable || (t.id && t.id.startsWith('table_test_'))));
            const cleanedTables = ctData.value.map(t => sanitizeAndUnifyTableColumns(t));
            localTestTables.forEach(tt => {
              if (!cleanedTables.some(ct => ct.id === tt.id)) {
                cleanedTables.push(tt);
              }
            });
            state.customTables = cleanedTables;
            if (typeof ensureStandardTablesInState === 'function') {
              ensureStandardTablesInState();
            }
            localStorage.setItem(STORAGE_KEYS.CUSTOM_TABLES, JSON.stringify(state.customTables));
            state.customTables.forEach(t => {
              if (t && t.id) {
                localStorage.setItem(`synapse_table_${t.id}`, JSON.stringify(t));
              }
            });
            updatedKeys.push(STORAGE_KEYS.CUSTOM_TABLES);
            if (typeof renderCustomTableList === 'function') renderCustomTableList();
            if (state.currentView === 'custom-table-screen' && state.activeCustomTableId) {
              renderCustomTable(state.activeCustomTableId);
            }
          }
        } catch (ctErr) {
          console.warn('[Supabase Sync] Pull custom tables failed:', ctErr);
        }
      }
    } finally {
      isSyncing = false;
    }

    // 同時に一般ユーザーの場合は管理者の共有アカウントデータも同期する
    if (state.currentUser && state.currentUser.role !== 'owner') {
      loadAdminSharedMemos().catch(err => console.error('[Supabase API] Shared load error on sync:', err));
    }
    
    if (updatedKeys.length > 0) {
      console.log("[Supabase] LocalStorage updated with remote data:", updatedKeys);
      loadStateFromLocalStorage(updatedKeys);
      if (showNotification) {
        showToast("クラウドから最新データを同期しました。", "success");
      }
    } else {
      if (showNotification) {
        showToast("データは既に最新の状態です。", "info");
      }
    }
  } catch (e) {
    isSyncing = false;
    console.error("[Supabase] Error during syncFromSupabase:", e);
    if (showNotification) showToast("同期処理中にエラーが発生しました。", "error");
  }
}

// ローカルストレージ更新後のメモリ再ロード関数
function loadStateFromLocalStorage(keys) {
  const userId = state.currentUser ? state.currentUser.id : 'guest';
  const dbmakeSuffix = getUserIdSuffix();
  
  keys.forEach(key => {
    if (key === STORAGE_KEYS.CUSTOMERS) {
      state.customers = JSON.parse(localStorage.getItem(STORAGE_KEYS.CUSTOMERS)) || [];
    } else if (key === STORAGE_KEYS.APPOINTMENTS) {
      state.appointments = JSON.parse(localStorage.getItem(STORAGE_KEYS.APPOINTMENTS)) || [];
    } else if (key === STORAGE_KEYS.JO_CONTRACTS) {
      state.joContracts = JSON.parse(localStorage.getItem(STORAGE_KEYS.JO_CONTRACTS)) || [];
    } else if (key === STORAGE_KEYS.AP_CONTRACTS) {
      state.apContracts = JSON.parse(localStorage.getItem(STORAGE_KEYS.AP_CONTRACTS)) || [];
    } else if (key === STORAGE_KEYS.AG_CONTRACTS) {
      state.agContracts = JSON.parse(localStorage.getItem(STORAGE_KEYS.AG_CONTRACTS)) || [];
    } else if (key === 'synapse_dbmake_partners') {
      dbmakePartners = JSON.parse(localStorage.getItem('synapse_dbmake_partners')) || [];
    } else if (key === STORAGE_KEYS.CUSTOM_TABLES) {
      const rawTables = JSON.parse(localStorage.getItem(STORAGE_KEYS.CUSTOM_TABLES)) || [];
      const deletedIds = (typeof getDeletedTableIds === 'function') ? getDeletedTableIds() : [];
      // 🛡️ テスト専用テーブルをローカルストレージや既存stateから保持（消去防止）
      const localTestTables = (state.customTables || []).filter(t => t && (t.isTestTable || (t.id && t.id.startsWith('table_test_'))));
      try {
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k && (k.startsWith('synapse_table_table_test_') || k.startsWith('table_test_'))) {
            const tt = JSON.parse(localStorage.getItem(k));
            if (tt && tt.id && !localTestTables.some(item => item.id === tt.id)) {
              localTestTables.push(tt);
            }
          }
        }
      } catch(e) {}

      state.customTables = rawTables.filter(t => !deletedIds.includes(t.id));
      localTestTables.forEach(tt => {
        if (!state.customTables.some(t => t.id === tt.id)) {
          state.customTables.push(tt);
        }
      });
      if (Array.isArray(state.customTables)) {
        state.customTables.forEach(t => sanitizeAndUnifyTableColumns(t));
      }
      if (typeof ensureStandardTablesInState === 'function') {
        ensureStandardTablesInState();
      }
      if (typeof renderCustomTableList === 'function') {
        renderCustomTableList();
      }
    } else if (typeof key === 'string' && key.startsWith('synapse_table_')) {
      try {
        const singleTbl = JSON.parse(localStorage.getItem(key));
        const deletedIds = (typeof getDeletedTableIds === 'function') ? getDeletedTableIds() : [];
        if (singleTbl && singleTbl.id && !deletedIds.includes(singleTbl.id)) {
          sanitizeAndUnifyTableColumns(singleTbl);
          state.customTables = state.customTables || [];
          const exIdx = state.customTables.findIndex(t => t.id === singleTbl.id);
          if (exIdx >= 0) {
            state.customTables[exIdx] = singleTbl;
          } else {
            state.customTables.push(singleTbl);
          }
        }
      } catch(e) {}
    } else if (key === STORAGE_KEYS.CUSTOM_ACCORDIONS) {
      state.customAccordions = JSON.parse(localStorage.getItem(STORAGE_KEYS.CUSTOM_ACCORDIONS)) || [];
    } else if (key === STORAGE_KEYS.JO_COLUMNS) {
      state.joColumns = JSON.parse(localStorage.getItem(STORAGE_KEYS.JO_COLUMNS));
    } else if (key === STORAGE_KEYS.AP_COLUMNS) {
      state.apColumns = JSON.parse(localStorage.getItem(STORAGE_KEYS.AP_COLUMNS));
    } else if (key === STORAGE_KEYS.AG_COLUMNS) {
      state.agColumns = JSON.parse(localStorage.getItem(STORAGE_KEYS.AG_COLUMNS));
    } else if (key === `SYNAPSE_DBMAKE_COLUMNS${dbmakeSuffix}`) {
      state.dbmakeColumns = JSON.parse(localStorage.getItem(`SYNAPSE_DBMAKE_COLUMNS${dbmakeSuffix}`));
    } else if (key === STORAGE_KEYS.FAVORITES) {
      state.favorites = JSON.parse(localStorage.getItem(STORAGE_KEYS.FAVORITES)) || [];
    }
  });

  // アクティブなビューの強制再描画
  if (state.currentView === 'jo-info-screen') {
    renderJoInfo();
  } else if (state.currentView === 'applicant-info-screen') {
    renderApplicantInfo();
  } else if (state.currentView === 'agency-info-screen') {
    renderAgencyInfo();
  } else if (state.currentView === 'dbmake-screen') {
    renderDbmakePartners();
  } else if (state.currentView.startsWith('custom-table-')) {
    const tableId = state.currentView.replace('custom-table-', '');
    renderCustomTable(tableId);
  }
}

function ensureInitialUsersExist() {
  const defaultUsers = [
    { 
      id: 'owner@synapse.management', 
      name: 'オーナー', 
      email: 'owner@synapse.management',
      password: 'password', 
      role: 'owner',
      code: 'OWNER_SEED_INIT_CODE',
      createdAt: '2025-01-01T10:00:00Z',
      lastLoginAt: new Date().toISOString(),
      pwdChangedAt: '2025-01-01T10:00:00Z' // 半年以上前
    }
  ];

  if (!localStorage.getItem(STORAGE_KEYS.USERS)) {
    localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(defaultUsers));
  } else {
    // 既存のユーザーリストがある場合、欠けているフィールドを自動補完する
    try {
      let users = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS)) || [];
      let updated = false;
      
      let hasOwnerEmail = users.some(u => u.id === 'owner@synapse.management');

      // admin ID が残っていた場合は owner@synapse.management へ移行するロジック
      const adminIdx = users.findIndex(u => u.id === 'admin');
      if (adminIdx !== -1) {
        if (!hasOwnerEmail) {
          users[adminIdx].id = 'owner@synapse.management';
          users[adminIdx].email = 'owner@synapse.management';
          users[adminIdx].name = 'オーナー';
          users[adminIdx].role = 'owner';
          users[adminIdx].code = 'OWNER_SEED_INIT_CODE';
          hasOwnerEmail = true;
        } else {
          users.splice(adminIdx, 1);
        }
        updated = true;
      }
      
      // 旧ID 'owner' の重複アカウントがあった場合は削除・移行して一本化！
      const oldOwnerIdx = users.findIndex(u => u.id === 'owner');
      if (oldOwnerIdx !== -1) {
        if (!hasOwnerEmail) {
          users[oldOwnerIdx].id = 'owner@synapse.management';
          users[oldOwnerIdx].email = 'owner@synapse.management';
          users[oldOwnerIdx].name = 'オーナー';
          users[oldOwnerIdx].role = 'owner';
          users[oldOwnerIdx].code = 'OWNER_SEED_INIT_CODE';
          hasOwnerEmail = true;
        } else {
          users.splice(oldOwnerIdx, 1);
        }
        updated = true;
      }
      
      // もし owner@synapse.management アカウント自体が存在しない場合は追加する
      if (!hasOwnerEmail) {
        users.unshift(defaultUsers[0]);
        updated = true;
      }
      
      users = users.map(u => {
        if (!u.createdAt) { u.createdAt = '2025-01-01T10:00:00Z'; updated = true; }
        if (!u.lastLoginAt) { u.lastLoginAt = new Date().toISOString(); updated = true; }
        if (!u.pwdChangedAt) { u.pwdChangedAt = u.createdAt; updated = true; }
        if (!u.code) { u.code = (u.id === 'owner@synapse.management' ? 'OWNER_SEED_INIT_CODE' : generate8DigitId()); updated = true; }
        return u;
      });
      if (updated) {
        localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(users));
      }
    } catch (e) {
      console.error(e);
    }
  }
}

