// ==========================================
// 形式（オンライン / オフライン）およびオンライン選択肢マスタ管理
// ==========================================

// ==========================================
// 流入経路（オンライン / オフライン）線画アイコン生成ヘルパー
// ==========================================
function getSourceLineIconSvg(type, size = 14) {
  if (type === 'online') {
    // オンライン: 地球儀（Globe）線画アイコン
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: -2px; display: inline-block; flex-shrink: 0;"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg>`;
  } else {
    // オフライン: 同じ地球儀マークに斜線（スラッシュ）が入った線画アイコン
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: -2px; display: inline-block; flex-shrink: 0;"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path><line x1="3" y1="3" x2="21" y2="21" stroke-width="2.2"></line></svg>`;
  }
}

// オンライン種別選択肢のデフォルト初期値（最初は「広告（）」のみ）
const DEFAULT_APPOINT_ONLINE_OPTIONS = ['広告（）'];
// オフライン種別選択肢のデフォルト初期値（最初は「営業」のみ）
const DEFAULT_APPOINT_OFFLINE_OPTIONS = ['営業'];

// オンライン選択肢を取得
function getAppointOnlineOptions() {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.APPOINT_ONLINE_OPTIONS);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    }
  } catch (e) {
    console.error('[Appoint Online Options] Error loading options:', e);
  }
  return [...DEFAULT_APPOINT_ONLINE_OPTIONS];
}

// オンライン選択肢を保存
function saveAppointOnlineOptions(options) {
  if (!Array.isArray(options)) return;
  localStorage.setItem(STORAGE_KEYS.APPOINT_ONLINE_OPTIONS, JSON.stringify(options));
  if (typeof syncToSupabase === 'function') {
    syncToSupabase('synapse_appoint_online_options', options);
  }
}

// オフライン選択肢を取得
function getAppointOfflineOptions() {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.APPOINT_OFFLINE_OPTIONS);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed;
      }
    }
  } catch (e) {
    console.error('[Appoint Offline Options] Error loading options:', e);
  }
  return [...DEFAULT_APPOINT_OFFLINE_OPTIONS];
}

// オフライン選択肢を保存
function saveAppointOfflineOptions(options) {
  if (!Array.isArray(options)) return;
  localStorage.setItem(STORAGE_KEYS.APPOINT_OFFLINE_OPTIONS, JSON.stringify(options));
  if (typeof syncToSupabase === 'function') {
    syncToSupabase('synapse_appoint_offline_options', options);
  }
}

// アポイント詳細候補ドロップダウンの描画（オンラインまたはオフラインに応じて切り替え、常時設置・未選択時はグレーアウト）
function renderAppointSourceCategories(selectedVal) {
  const categorySelect = document.getElementById('appoint-source-category') || document.getElementById('appoint-online-category');
  const sourceType = document.getElementById('appoint-source-type')?.value;
  if (!categorySelect) return;

  const isAdmin = (typeof isUserAdmin === 'function') ? isUserAdmin() : false;

  categorySelect.innerHTML = '';

  // 流入経路が未選択の場合はグレーアウト（非活性）
  if (!sourceType) {
    categorySelect.disabled = true;
    categorySelect.style.background = 'var(--bg-surface-elevated)';
    categorySelect.style.color = 'var(--text-muted)';
    categorySelect.style.opacity = '0.65';
    categorySelect.style.cursor = 'not-allowed';

    const defaultOption = document.createElement('option');
    defaultOption.value = '';
    defaultOption.textContent = '-- 先に流入経路を選択 --';
    categorySelect.appendChild(defaultOption);
    categorySelect.value = '';
    return;
  }

  // 流入経路選択済みの場合は活性化
  categorySelect.disabled = false;
  categorySelect.style.background = 'var(--bg-surface)';
  categorySelect.style.color = 'var(--text-primary)';
  categorySelect.style.opacity = '1';
  categorySelect.style.cursor = 'pointer';

  if (sourceType === 'online') {
    const options = getAppointOnlineOptions();
    const defaultOption = document.createElement('option');
    defaultOption.value = '';
    defaultOption.textContent = '-- オンライン種別を選択 --';
    categorySelect.appendChild(defaultOption);

    options.forEach(opt => {
      const el = document.createElement('option');
      el.value = opt;
      el.textContent = opt;
      categorySelect.appendChild(el);
    });

    const targetVal = selectedVal || '広告（）';
    if (targetVal && targetVal !== '__manage_options__') {
      if (!options.includes(targetVal)) {
        const el = document.createElement('option');
        el.value = targetVal;
        el.textContent = targetVal;
        categorySelect.appendChild(el);
      }
      categorySelect.value = targetVal;
      categorySelect.dataset.lastSelected = targetVal;
    }

    // 管理者の場合、プルダウン末尾に「⚙ 選択肢を編集・追加...」を組み込み
    if (isAdmin) {
      const sep = document.createElement('option');
      sep.disabled = true;
      sep.textContent = '──────────';
      categorySelect.appendChild(sep);

      const manageOpt = document.createElement('option');
      manageOpt.value = '__manage_options__';
      manageOpt.textContent = '⚙ 選択肢を編集・追加...';
      manageOpt.style.color = 'var(--primary)';
      manageOpt.style.fontWeight = 'bold';
      categorySelect.appendChild(manageOpt);
    }
  } else if (sourceType === 'offline') {
    const options = getAppointOfflineOptions();
    const defaultOption = document.createElement('option');
    defaultOption.value = '';
    defaultOption.textContent = '-- オフライン種別を選択 --';
    categorySelect.appendChild(defaultOption);

    options.forEach(opt => {
      const el = document.createElement('option');
      el.value = opt;
      el.textContent = opt;
      categorySelect.appendChild(el);
    });

    const targetVal = selectedVal || '営業';
    if (targetVal && targetVal !== '__manage_options__') {
      if (!options.includes(targetVal)) {
        const el = document.createElement('option');
        el.value = targetVal;
        el.textContent = targetVal;
        categorySelect.appendChild(el);
      }
      categorySelect.value = targetVal;
      categorySelect.dataset.lastSelected = targetVal;
    }

    // 管理者の場合、プルダウン末尾に「⚙ 選択肢を編集・追加...」を組み込み
    if (isAdmin) {
      const sep = document.createElement('option');
      sep.disabled = true;
      sep.textContent = '──────────';
      categorySelect.appendChild(sep);

      const manageOpt = document.createElement('option');
      manageOpt.value = '__manage_options__';
      manageOpt.textContent = '⚙ 選択肢を編集・追加...';
      manageOpt.style.color = 'var(--primary)';
      manageOpt.style.fontWeight = 'bold';
      categorySelect.appendChild(manageOpt);
    }
  }
}

// 後方互換性エイリアス
function renderAppointOnlineOptions(selectedVal) {
  renderAppointSourceCategories(selectedVal);
}

// オンライン選択肢の編集（名称変更）
function editAppointOnlineOption(oldVal, newVal) {
  if (!oldVal || !newVal) return false;
  const trimmed = newVal.trim();
  if (!trimmed) {
    showToast('選択肢名を入力してください。', 'warning');
    return false;
  }
  if (oldVal === trimmed) return true;

  const options = getAppointOnlineOptions();
  const idx = options.indexOf(oldVal);
  if (idx === -1) return false;

  if (options.includes(trimmed)) {
    showToast(`オンライン選択肢「${trimmed}」は既に存在します。`, 'warning');
    return false;
  }

  options[idx] = trimmed;
  saveAppointOnlineOptions(options);

  // 既存のアポイントレコード内の該当カテゴリも一括更新
  let updatedCount = 0;
  if (Array.isArray(state.appointments)) {
    state.appointments.forEach(apt => {
      if (apt && apt.meetingType === 'online' && apt.onlineCategory === oldVal) {
        apt.onlineCategory = trimmed;
        updatedCount++;
      }
    });
    if (updatedCount > 0) {
      localStorage.setItem(STORAGE_KEYS.APPOINTMENTS, JSON.stringify(state.appointments));
      if (typeof syncToSupabase === 'function') {
        syncToSupabase('synapse_appointments', state.appointments);
      }
    }
  }

  // アポイント画面のプルダウン再描画
  if (document.getElementById('appoint-source-type')?.value === 'online') {
    renderAppointSourceCategories(trimmed);
  }
  renderSettingsOnlineOptionsList();
  showToast(`選択肢を「${trimmed}」に変更しました。`, 'success');
  return true;
}

// オフライン選択肢の編集（名称変更）
function editAppointOfflineOption(oldVal, newVal) {
  if (!oldVal || !newVal) return false;
  const trimmed = newVal.trim();
  if (!trimmed) {
    showToast('選択肢名を入力してください。', 'warning');
    return false;
  }
  if (oldVal === trimmed) return true;

  const options = getAppointOfflineOptions();
  const idx = options.indexOf(oldVal);
  if (idx === -1) return false;

  if (options.includes(trimmed)) {
    showToast(`オフライン選択肢「${trimmed}」は既に存在します。`, 'warning');
    return false;
  }

  options[idx] = trimmed;
  saveAppointOfflineOptions(options);

  // 既存のアポイントレコード内の該当カテゴリも一括更新
  let updatedCount = 0;
  if (Array.isArray(state.appointments)) {
    state.appointments.forEach(apt => {
      if (apt && apt.meetingType === 'offline' && apt.onlineCategory === oldVal) {
        apt.onlineCategory = trimmed;
        updatedCount++;
      }
    });
    if (updatedCount > 0) {
      localStorage.setItem(STORAGE_KEYS.APPOINTMENTS, JSON.stringify(state.appointments));
      if (typeof syncToSupabase === 'function') {
        syncToSupabase('synapse_appointments', state.appointments);
      }
    }
  }

  // アポイント画面のプルダウン再描画
  if (document.getElementById('appoint-source-type')?.value === 'offline') {
    renderAppointSourceCategories(trimmed);
  }
  renderSettingsOfflineOptionsList();
  showToast(`選択肢を「${trimmed}」に変更しました。`, 'success');
  return true;
}

// 設定画面（管理者用）のオンライン選択肢一覧の描画（線画アイコン対応・インライン編集対応）
function renderSettingsOnlineOptionsList() {
  const container = document.getElementById('settings-online-options-list');
  if (!container) return;

  const options = getAppointOnlineOptions();
  container.innerHTML = '';

  if (options.length === 0) {
    container.innerHTML = '<div style="font-size: 0.8rem; color: var(--text-muted); padding: 0.5rem; text-align: center;">選択肢が登録されていません</div>';
    return;
  }

  options.forEach(opt => {
    const item = document.createElement('div');
    item.style.display = 'flex';
    item.style.alignItems = 'center';
    item.style.justifyContent = 'space-between';
    item.style.padding = '0.35rem 0.6rem';
    item.style.background = 'var(--bg-surface-elevated)';
    item.style.border = '1px solid var(--border-color)';
    item.style.borderRadius = 'var(--radius-xs)';
    item.style.fontSize = '0.82rem';

    const textSpan = document.createElement('span');
    textSpan.textContent = opt;
    textSpan.style.fontWeight = '600';
    textSpan.style.color = 'var(--text-primary)';
    item.appendChild(textSpan);

    const btnGroup = document.createElement('div');
    btnGroup.style.display = 'flex';
    btnGroup.style.alignItems = 'center';
    btnGroup.style.gap = '0.25rem';

    // 編集ボタン（SVG線画ペンシル）
    const editBtn = document.createElement('button');
    editBtn.type = 'button';
    editBtn.className = 'btn-icon';
    editBtn.innerHTML = '<svg viewBox="0 0 24 24" width="13" height="13" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"></path><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"></path></svg>';
    editBtn.title = '名称を変更';
    editBtn.style.padding = '0.2rem';
    editBtn.style.cursor = 'pointer';
    editBtn.style.background = 'none';
    editBtn.style.border = 'none';
    editBtn.style.color = 'var(--text-secondary)';
    editBtn.onclick = () => {
      // インライン編集モード
      item.innerHTML = '';
      const inputEl = document.createElement('input');
      inputEl.type = 'text';
      inputEl.value = opt;
      inputEl.style.flex = '1';
      inputEl.style.padding = '0.2rem 0.4rem';
      inputEl.style.fontSize = '0.8rem';
      inputEl.style.border = '1px solid var(--primary)';
      inputEl.style.borderRadius = 'var(--radius-xs)';
      inputEl.style.background = 'var(--bg-surface)';
      inputEl.style.color = 'var(--text-primary)';
      inputEl.style.outline = 'none';

      const saveAction = () => {
        const val = inputEl.value.trim();
        if (val && val !== opt) {
          editAppointOnlineOption(opt, val);
        } else {
          renderSettingsOnlineOptionsList();
        }
      };

      inputEl.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          saveAction();
        } else if (e.key === 'Escape') {
          renderSettingsOnlineOptionsList();
        }
      });

      const actionGroup = document.createElement('div');
      actionGroup.style.display = 'flex';
      actionGroup.style.alignItems = 'center';
      actionGroup.style.gap = '0.2rem';

      const saveBtn = document.createElement('button');
      saveBtn.type = 'button';
      saveBtn.className = 'btn-icon';
      saveBtn.innerHTML = '<svg viewBox="0 0 24 24" width="13" height="13" stroke="var(--primary)" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>';
      saveBtn.title = '保存';
      saveBtn.style.padding = '0.2rem';
      saveBtn.style.cursor = 'pointer';
      saveBtn.style.background = 'none';
      saveBtn.style.border = 'none';
      saveBtn.onclick = saveAction;

      const cancelBtn = document.createElement('button');
      cancelBtn.type = 'button';
      cancelBtn.className = 'btn-icon';
      cancelBtn.innerHTML = '<svg viewBox="0 0 24 24" width="13" height="13" stroke="var(--text-muted)" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>';
      cancelBtn.title = 'キャンセル';
      cancelBtn.style.padding = '0.2rem';
      cancelBtn.style.cursor = 'pointer';
      cancelBtn.style.background = 'none';
      cancelBtn.style.border = 'none';
      cancelBtn.onclick = () => renderSettingsOnlineOptionsList();

      actionGroup.appendChild(saveBtn);
      actionGroup.appendChild(cancelBtn);
      item.appendChild(inputEl);
      item.appendChild(actionGroup);
      inputEl.focus();
      inputEl.select();
    };
    btnGroup.appendChild(editBtn);

    // 削除ボタン（SVG線画ゴミ箱）
    const delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'btn-icon';
    delBtn.innerHTML = '<svg viewBox="0 0 24 24" width="13" height="13" stroke="var(--danger)" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>';
    delBtn.title = '削除';
    delBtn.style.padding = '0.2rem';
    delBtn.style.cursor = 'pointer';
    delBtn.style.background = 'none';
    delBtn.style.border = 'none';
    delBtn.onclick = () => {
      if (options.length <= 1) {
        showToast('選択肢は最低1つ登録されている必要があります。', 'warning');
        return;
      }
      if (confirm(`選択肢「${opt}」を削除しますか？`)) {
        const newOpts = options.filter(o => o !== opt);
        saveAppointOnlineOptions(newOpts);
        renderSettingsOnlineOptionsList();
        if (document.getElementById('appoint-source-type')?.value === 'online') {
          renderAppointSourceCategories(document.getElementById('appoint-source-category')?.value);
        }
        showToast(`選択肢「${opt}」を削除しました。`, 'info');
      }
    };
    btnGroup.appendChild(delBtn);

    item.appendChild(btnGroup);
    container.appendChild(item);
  });
}

