function initAppointMeetingTypeUI() {
  const sourceSelect = document.getElementById('appoint-source-type');
  const onlineRadio = document.getElementById('appoint-type-online');
  const offlineRadio = document.getElementById('appoint-type-offline');

  if (sourceSelect) {
    sourceSelect.addEventListener('change', () => {
      setAppointMeetingType(sourceSelect.value);
    });
  }
  if (onlineRadio) {
    onlineRadio.addEventListener('change', () => {
      if (onlineRadio.checked) setAppointMeetingType('online');
    });
  }
  if (offlineRadio) {
    offlineRadio.addEventListener('change', () => {
      if (offlineRadio.checked) setAppointMeetingType('offline');
    });
  }

  // プルダウン内「⚙ 選択肢を編集・追加...」の選択検知（別ボタンを廃止し入力項目欄内に組み込み）
  const categorySelect = document.getElementById('appoint-source-category') || document.getElementById('appoint-online-category');
  const managePanel = document.getElementById('source-option-manage-panel');
  const btnClosePanel = document.getElementById('btn-close-source-manage-panel');
  const inputNewInPanel = document.getElementById('input-new-source-in-panel');
  const btnAddInPanel = document.getElementById('btn-add-source-in-panel');

  if (categorySelect) {
    categorySelect.addEventListener('change', () => {
      if (categorySelect.value === '__manage_options__') {
        // 直前の有効な選択肢に戻す（保存データが壊れないよう保護）
        const fallback = (sourceSelect?.value === 'offline') ? '営業' : '広告（）';
        categorySelect.value = categorySelect.dataset.lastSelected || fallback;

        // 管理パネルを展開
        if (managePanel) {
          managePanel.style.display = 'flex';
          renderSourceManagePanel();
          if (inputNewInPanel) {
            inputNewInPanel.value = '';
            inputNewInPanel.focus();
          }
        }
      } else {
        categorySelect.dataset.lastSelected = categorySelect.value;
        state.isFormDirty = true;
      }
      if (typeof updateSalesIntroducerVisibility === 'function') {
        updateSalesIntroducerVisibility();
      }
    });
  }

  // 初期描画（未選択時はグレーアウト）
  renderAppointSourceCategories(categorySelect?.value || '');
  if (typeof updateSalesIntroducerVisibility === 'function') {
    updateSalesIntroducerVisibility();
  }
  if (typeof initAppointIntroducerSearchEvents === 'function') {
    initAppointIntroducerSearchEvents();
  }

  if (btnClosePanel && managePanel) {
    btnClosePanel.addEventListener('click', () => {
      managePanel.style.display = 'none';
      if (inputNewInPanel) inputNewInPanel.value = '';
    });
  }

  // パネル内での新規選択肢追加アクション
  const handleAddInPanel = () => {
    if (!inputNewInPanel) return;
    const val = inputNewInPanel.value.trim();
    if (!val) {
      showToast('新しい選択肢名を入力してください。', 'warning');
      return;
    }
    const currentType = document.getElementById('appoint-source-type')?.value || 'online';
    if (currentType === 'online') {
      const current = getAppointOnlineOptions();
      if (current.includes(val)) {
        showToast('このオンライン選択肢は既に存在します。', 'warning');
        return;
      }
      current.push(val);
      saveAppointOnlineOptions(current);
      renderAppointSourceCategories(val);
      renderSettingsOnlineOptionsList();
    } else {
      const current = getAppointOfflineOptions();
      if (current.includes(val)) {
        showToast('このオフライン選択肢は既に存在します。', 'warning');
        return;
      }
      current.push(val);
      saveAppointOfflineOptions(current);
      renderAppointSourceCategories(val);
      renderSettingsOfflineOptionsList();
    }

    inputNewInPanel.value = '';
    renderSourceManagePanel();
    state.isFormDirty = true;
    showToast(`選択肢「${val}」を追加しました。`, 'success');
  };

  if (btnAddInPanel) {
    btnAddInPanel.addEventListener('click', handleAddInPanel);
  }
  if (inputNewInPanel) {
    inputNewInPanel.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleAddInPanel();
      } else if (e.key === 'Escape') {
        if (managePanel) managePanel.style.display = 'none';
      }
    });
  }

  // 設定画面側のアドミンオンラインオプション追加ボタン
  const settingsBtnAddOnline = document.getElementById('settings-add-online-option-btn');
  const settingsInputOnline = document.getElementById('settings-new-online-option-input');

  if (settingsBtnAddOnline && settingsInputOnline) {
    const handleSettingsAddOnline = () => {
      const val = settingsInputOnline.value.trim();
      if (!val) {
        showToast('オンライン選択肢名を入力してください。', 'warning');
        return;
      }
      const current = getAppointOnlineOptions();
      if (current.includes(val)) {
        showToast('この選択肢は既に存在します。', 'warning');
        return;
      }
      current.push(val);
      saveAppointOnlineOptions(current);
      renderSettingsOnlineOptionsList();
      if (document.getElementById('appoint-source-type')?.value === 'online') {
        renderAppointSourceCategories(document.getElementById('appoint-source-category')?.value);
      }
      settingsInputOnline.value = '';
      showToast(`オンライン選択肢「${val}」を追加しました。`, 'success');
    };

    settingsBtnAddOnline.addEventListener('click', handleSettingsAddOnline);
    settingsInputOnline.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleSettingsAddOnline();
      }
    });
  }

  // 設定画面側のアドミンオフラインオプション追加ボタン
  const settingsBtnAddOffline = document.getElementById('settings-add-offline-option-btn');
  const settingsInputOffline = document.getElementById('settings-new-offline-option-input');

  if (settingsBtnAddOffline && settingsInputOffline) {
    const handleSettingsAddOffline = () => {
      const val = settingsInputOffline.value.trim();
      if (!val) {
        showToast('オフライン選択肢名を入力してください。', 'warning');
        return;
      }
      const current = getAppointOfflineOptions();
      if (current.includes(val)) {
        showToast('この選択肢は既に存在します。', 'warning');
        return;
      }
      current.push(val);
      saveAppointOfflineOptions(current);
      renderSettingsOfflineOptionsList();
      if (document.getElementById('appoint-source-type')?.value === 'offline') {
        renderAppointSourceCategories(document.getElementById('appoint-source-category')?.value);
      }
      settingsInputOffline.value = '';
      showToast(`オフライン選択肢「${val}」を追加しました。`, 'success');
    };

    settingsBtnAddOffline.addEventListener('click', handleSettingsAddOffline);
    settingsInputOffline.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleSettingsAddOffline();
      }
    });
  }

  // 設定画面タブの切り替えにアポイント設定タブを追加連動
  const settingsTabAppointBtn = document.getElementById('settings-tab-appoint-btn');
  const settingsContentAppoint = document.getElementById('settings-content-appoint');
  if (settingsTabAppointBtn && settingsContentAppoint) {
    settingsTabAppointBtn.addEventListener('click', () => {
      const profileBtn = document.getElementById('settings-tab-profile-btn');
      const devicesBtn = document.getElementById('settings-tab-devices-btn');
      const desktopBtn = document.getElementById('settings-tab-desktop-btn');
      [profileBtn, devicesBtn, desktopBtn].forEach(b => {
        if (b) {
          b.classList.remove('active');
          b.style.color = 'var(--text-secondary)';
          b.style.borderBottomColor = 'transparent';
        }
      });
      const cProfile = document.getElementById('settings-content-profile');
      const cDevices = document.getElementById('settings-content-devices');
      const cDesktop = document.getElementById('settings-content-desktop');
      [cProfile, cDevices, cDesktop].forEach(c => {
        if (c) c.style.display = 'none';
      });

      settingsTabAppointBtn.classList.add('active');
      settingsTabAppointBtn.style.color = 'var(--primary)';
      settingsTabAppointBtn.style.borderBottomColor = 'var(--primary)';
      settingsContentAppoint.style.display = 'flex';
      renderSettingsOnlineOptionsList();
      renderSettingsOfflineOptionsList();
    });

    const profileBtn = document.getElementById('settings-tab-profile-btn');
    const devicesBtn = document.getElementById('settings-tab-devices-btn');
    const desktopBtn = document.getElementById('settings-tab-desktop-btn');
    [profileBtn, devicesBtn, desktopBtn].forEach(b => {
      if (b) {
        b.addEventListener('click', () => {
          settingsTabAppointBtn.classList.remove('active');
          settingsTabAppointBtn.style.color = 'var(--text-secondary)';
          settingsTabAppointBtn.style.borderBottomColor = 'transparent';
          settingsContentAppoint.style.display = 'none';
        });
      }
    });
  }

  updateAppointMeetingTypeRoleVisibility();
}



// 既存顧客選択時のUI処理
function selectCustomer(customer) {
  state.selectedExistingCustomer = customer;
  const banner = document.getElementById('existing-customer-banner');
  const form = document.getElementById('appointment-form');
  const nameGroup = document.getElementById('customer-name-group');
  
  if (customer) {
    document.getElementById('ext-info-name').textContent = `${customer.name} ${customer.furigana ? `(${customer.furigana})` : ''}`;

    // 顧客ID表示（Party ID有無の区別）
    const idEl = document.getElementById('ext-info-id');
    if (idEl) {
      if (customer.hasPartyId !== false && customer.id && customer.id !== '本登録前') {
        idEl.textContent = customer.id;
        idEl.style.color = 'var(--text-primary)';
      } else {
        idEl.innerHTML = '<span class="badge" style="background: rgba(245, 158, 11, 0.15); color: #d97706; border: 1px solid rgba(245, 158, 11, 0.3); font-size: 0.75rem; padding: 0.1rem 0.4rem; font-weight: normal;">未発行（本登録前）</span>';
      }
    }

    document.getElementById('ext-info-phone').textContent = customer.phone || '未登録';
    document.getElementById('ext-info-email').textContent = customer.email || '未登録';
    document.getElementById('ext-info-corp').textContent = customer.corp || '未登録';
    document.getElementById('ext-info-service').textContent = customer.serviceText || customer.service || 'なし';
    
    // 顧客IDに紐付く過去のアポイント履歴を取得して表示（ぶら下がりツリー構造）
    const historyListContainer = document.getElementById('ext-info-history-list');
    historyListContainer.innerHTML = '';
    
    const relatedAppoints = state.appointments.filter(a => {
      if (state.editingAppointId && a.id === state.editingAppointId) return false;
      if (customer.hasPartyId !== false && customer.id && customer.id !== '本登録前') {
        return a.customerId === customer.id;
      } else {
        return (customer.appointIds && customer.appointIds.includes(a.id)) ||
               (a.customerName && a.customerName === customer.name);
      }
    }).sort((a, b) => new Date(b.date || b.datetime || 0) - new Date(a.date || a.datetime || 0));

    document.getElementById('ext-info-history').textContent = `${relatedAppoints.length}件`;

    if (relatedAppoints.length === 0) {
      historyListContainer.innerHTML = '<div style="font-size: 0.8rem; color: var(--text-muted); padding: 0.25rem 0;">└─ 過去のアポイント履歴はありません</div>';
    } else {
      relatedAppoints.forEach(appoint => {
        const dateObj = new Date(appoint.date || appoint.datetime || 0);
        const formattedDate = `${dateObj.getFullYear()}/${dateObj.getMonth() + 1}/${dateObj.getDate()} ${String(dateObj.getHours()).padStart(2, '0')}:${String(dateObj.getMinutes()).padStart(2, '0')}`;
        
        const historyItem = document.createElement('div');
        historyItem.style.marginBottom = '0.5rem';
        historyItem.style.fontSize = '0.85rem';
        
        let statusBadge = '';
        if (appoint.status === 'draft') {
          statusBadge = '<span class="badge badge-draft" style="font-size: 0.65rem; padding: 0.05rem 0.25rem; margin-left: 0.5rem;">下書き</span>';
        } else if (appoint.status === 'cancelled') {
          statusBadge = '<span class="badge" style="font-size: 0.65rem; padding: 0.05rem 0.25rem; margin-left: 0.5rem; background: rgba(239, 68, 68, 0.15); color: var(--danger); border: 1px solid rgba(239, 68, 68, 0.3);">破棄済</span>';
        }

        let meetingBadge = '';
        if (appoint.meetingType === 'online') {
          const detail = appoint.onlineCategory ? ` (${appoint.onlineCategory}${appoint.onlineSubnote ? ` - ${appoint.onlineSubnote}` : ''})` : '';
          meetingBadge = `<span class="badge" style="font-size: 0.65rem; padding: 0.05rem 0.35rem; margin-left: 0.4rem; background: rgba(59, 130, 246, 0.1); color: #2563eb; border: 1px solid rgba(59, 130, 246, 0.3); display: inline-flex; align-items: center; gap: 0.2rem;">${getSourceLineIconSvg('online', 11)}<span>オンライン${detail}</span></span>`;
        } else if (appoint.meetingType === 'offline') {
          const detail = appoint.onlineCategory ? ` (${appoint.onlineCategory}${appoint.onlineSubnote ? ` - ${appoint.onlineSubnote}` : ''})` : '';
          meetingBadge = `<span class="badge" style="font-size: 0.65rem; padding: 0.05rem 0.35rem; margin-left: 0.4rem; background: rgba(107, 114, 128, 0.1); color: #4b5563; border: 1px solid rgba(107, 114, 128, 0.3); display: inline-flex; align-items: center; gap: 0.2rem;">${getSourceLineIconSvg('offline', 11)}<span>オフライン${detail}</span></span>`;
        }

        historyItem.innerHTML = `
          <div style="display: flex; align-items: center; justify-content: space-between;">
            <div>
              <span style="font-family: monospace; color: var(--secondary); font-weight: bold;">└─ ID: ${appoint.id}</span>
              <span style="color: var(--text-secondary); margin-left: 0.5rem;">(${formattedDate})</span>
              ${meetingBadge}
              ${statusBadge}
            </div>
            <button type="button" class="btn-text" style="font-size: 0.75rem; text-decoration: underline; color: var(--primary); padding: 0; border: none; background: transparent; cursor: pointer;" onclick="viewAppointmentDetails('${appoint.id}')">詳細</button>
          </div>
          <div style="margin-left: 1.2rem; color: var(--text-muted); font-size: 0.8rem; border-left: 1px dotted var(--border-color); padding-left: 0.5rem; margin-top: 0.1rem; margin-bottom: 0.3rem;">
            ${appoint.memo || '（メモなし）'}
          </div>
        `;
        historyListContainer.appendChild(historyItem);
      });
    }

    // 🌟 本登録前（Party ID未発行）の場合、過去アポイントIDを自動的に「関連するアポイントID」にセットして連結！
    if (customer.hasPartyId === false && relatedAppoints.length > 0) {
      const autoAppointIds = relatedAppoints.map(a => a.id);
      const linksVal = autoAppointIds.join(', ');
      if (window.renderRelatedAppointIdLinks) {
        window.renderRelatedAppointIdLinks(linksVal, isViewOnly);
      }
      if (state.editingAppointId) {
        const appoint = state.appointments.find(a => a.id === state.editingAppointId);
        if (appoint) {
          appoint.relatedAppointmentIds = linksVal;
          localStorage.setItem(STORAGE_KEYS.APPOINTMENTS, JSON.stringify(state.appointments));
          syncBiDirectionalRelatedAppointmentIds(state.editingAppointId, linksVal);
          relatedAppoints.forEach(pastAp => {
            if (typeof evaluateAppointmentLinking === 'function') {
              evaluateAppointmentLinking(appoint, pastAp.id, () => {});
            }
          });
        }
      }
      showToast(`過去アポイント (${autoAppointIds.length}件) を自動連結しました。`, 'info');
    }
    
    banner.style.display = 'block';
    const placeholder = document.getElementById('existing-customer-placeholder');
    if (placeholder) placeholder.style.display = 'none';

    // 類似データの検索とレンダリングを追加する
    const searchResults = searchRelatedCrossTables(customer);
    renderConnectionPanel(searchResults, false);

    // 相手の名前基本入力欄をプレフィルし、編集不可に
    const nameInput = document.getElementById('customer-name');
    if (nameInput) {
      nameInput.value = customer.name;
      nameInput.readOnly = true;
      nameInput.required = false; // 既存顧客選択時は required を解除
    }
    if (nameGroup) nameGroup.style.display = 'none';
    if (form) form.style.display = 'block';

    // その他関連IDのプリフィル処理 (ポップアップチップ式) (顧客マスタ情報から直接取得)
    const switchToggleContainer = document.getElementById('id-switch-toggle-container');
    const switchMainBtn = document.getElementById('btn-switch-main-id');
    const switchRelatedBtn = document.getElementById('btn-switch-related-id-view');
    
    let relatedId = customer.relatedCustomerId || '';
    
    // 遅延バインドの検知（新規顧客選択時の処理）：
    if (!relatedId && customer.hasPartyId !== false) {
      const originCustomer = state.customers.find(
        c => c.id !== customer.id && c.relatedCustomerId && c.relatedCustomerId.split(',').map(x => x.trim()).includes(customer.id)
      );
      if (originCustomer) {
        relatedId = originCustomer.id;
        customer.relatedCustomerId = relatedId;
        syncBiDirectionalRelatedCustomerId(customer.id, relatedId);
      }
    }
    
    const isViewOnly = state.tabs.find(t => t.id === state.activeTabId)?.appointData?.viewOnly || false;
    if (window.renderRelatedCustomerIdLinks) {
      window.renderRelatedCustomerIdLinks(relatedId, isViewOnly);
    }
    
    if (relatedId && switchToggleContainer) {
      switchToggleContainer.style.display = 'flex';
      switchMainBtn.textContent = `メインID (${customer.id})`;
      switchRelatedBtn.textContent = `関連ID (${relatedId})`;
      switchMainBtn.classList.add('active');
      switchRelatedBtn.classList.remove('active');
    } else {
      if (switchToggleContainer) switchToggleContainer.style.display = 'none';
    }

    // 👤 紹介者の自動事前表記（プリフィル） & 既存顧客紹介者固定
    let foundIntro = null;
    if (customer.introducerId) {
      foundIntro = {
        id: customer.introducerId,
        name: customer.introducerName || customer.introducerId,
        type: customer.introducerType || 'party',
        sub: `ID: ${customer.introducerId}`,
        typeLabel: (customer.introducerType === 'temp') ? '見込み客（仮ID）' : '本登録Party ID'
      };
    } else if (relatedAppoints && relatedAppoints.length > 0) {
      const apWithIntro = relatedAppoints.find(a => a.introducerId);
      if (apWithIntro) {
        foundIntro = {
          id: apWithIntro.introducerId,
          name: apWithIntro.introducerName || apWithIntro.introducerId,
          type: apWithIntro.introducerType || 'party',
          sub: `ID: ${apWithIntro.introducerId}`,
          typeLabel: (apWithIntro.introducerType === 'temp') ? '見込み客（仮ID）' : '本登録Party ID'
        };
      }
    }

    if (foundIntro && typeof selectAppointIntroducer === 'function') {
      selectAppointIntroducer(foundIntro, true);
    } else if (typeof unlockAppointIntroducer === 'function') {
      unlockAppointIntroducer();
    }

    setFormMode('existing');
  } else {
    banner.style.display = 'none';
    const placeholder = document.getElementById('existing-customer-placeholder');
    
    if (typeof unlockAppointIntroducer === 'function') {
      unlockAppointIntroducer();
    }
    
    const nameInput = document.getElementById('customer-name');
    if (state.formMode === 'existing') {
      if (placeholder) placeholder.style.display = 'block';
      if (form) form.style.display = 'none';
      if (nameGroup) nameGroup.style.display = 'none';
      if (nameInput) nameInput.required = false; // 既存時は required を解除
    } else {
      if (placeholder) placeholder.style.display = 'none';
      if (form) form.style.display = 'block';
      if (nameGroup) nameGroup.style.display = 'block';
      if (nameInput) nameInput.required = true; // 新規時は required
    }
    
    if (nameInput) {
      nameInput.value = '';
      nameInput.readOnly = false;
    }
    
    // 関連ID系の表示クリア
    if (window.renderRelatedCustomerIdLinks) {
      window.renderRelatedCustomerIdLinks('', false);
    }
    const switchToggleContainer = document.getElementById('id-switch-toggle-container');
    if (switchToggleContainer) switchToggleContainer.style.display = 'none';
    
    // 関連接続リストと接続データをクリア
    state.connectedLinks = {};
    const connList = document.getElementById('ext-info-connection-list');
    if (connList) connList.innerHTML = '';
  }

  // すでに作成済みのdraftレコードの顧客情報をリアルタイム更新
  if (state.editingAppointId) {
    const appoint = state.appointments.find(a => a.id === state.editingAppointId);
    if (appoint) {
      appoint.customerType = state.formMode;
      appoint.customerId = customer ? customer.id : null;
      appoint.customerName = customer ? customer.name : document.getElementById('customer-name').value.trim();
      localStorage.setItem(STORAGE_KEYS.APPOINTMENTS, JSON.stringify(state.appointments));
    }
    const currentTab = state.tabs.find(t => t.id === state.activeTabId);
    if (currentTab && currentTab.appointData) {
      currentTab.appointData.customerType = state.formMode;
      currentTab.appointData.customerId = customer ? customer.id : null;
      currentTab.appointData.customerName = customer ? customer.name : document.getElementById('customer-name').value.trim();
    }
    if (typeof renderAppointLinkedForms === 'function') {
      renderAppointLinkedForms(appoint || currentTab?.appointData);
    }
  }
}

// 新規・既存モードの設定
function setFormMode(mode) {
  state.formMode = mode;
  const toggleNew = document.getElementById('toggle-cust-new');
  const toggleExist = document.getElementById('toggle-cust-existing');
  const selectArea = document.getElementById('top-customer-select-area');

  if (mode === 'new') {
    toggleNew.classList.add('active');
    toggleExist.classList.remove('active');
    if (selectArea) selectArea.style.display = 'none';
    selectCustomer(null);
  } else {
    toggleNew.classList.remove('active');
    toggleExist.classList.add('active');
    if (selectArea) selectArea.style.display = 'flex';
    if (!state.selectedExistingCustomer) {
      openCustomerSearchModal();
    }
  }
}

// ==========================================
// 7. 顧客検索モーダル処理
// ==========================================
// 全候補リスト生成（Party ID保有顧客 ＋ 本登録前見込み客 ＋ 各種マスタ連携情報）
function getAllCustomerCandidates() {
  const map = new Map();

  // 1. Party ID保有顧客 (state.customers)
  (state.customers || []).forEach(c => {
    const services = [];
    if (state.joContracts && state.joContracts.some(jo => (jo.customerId === c.id || jo.customerPersonalityId === c.id))) {
      services.push('JO契約');
    }
    if (state.apContracts && state.apContracts.some(ap => (ap.customerId === c.id || ap.customerPersonalityId === c.id))) {
      services.push('申込者情報');
    }
    if (state.agContracts && state.agContracts.some(ag => (ag.customerId === c.id || ag.id === c.id))) {
      services.push('代理店');
    }
    const pastAppoints = (state.appointments || []).filter(a => a.customerId === c.id);
    if (pastAppoints.length > 0) {
      services.push(`アポイント (${pastAppoints.length}件)`);
    }
    if (services.length === 0 && c.service) {
      services.push(c.service);
    }

    map.set(`party_${c.id}`, {
      hasPartyId: true,
      id: c.id,
      name: c.name,
      furigana: c.furigana || '',
      phone: c.phone || '',
      email: c.email || '',
      corp: c.corp || '',
      serviceText: services.join(' / ') || '登録済',
      services: services,
      appointIds: pastAppoints.map(a => a.id),
      historyCount: pastAppoints.length
    });
  });

  // 2. 本登録前（Party ID未発行）の見込み客（state.appointments の中から customerId 未設定のアポを人物ごとに集約）
  const prospectMap = new Map();
  (state.appointments || []).forEach(a => {
    if (!a.customerId || a.customerType === 'new') {
      const name = (a.customerName || a.name || '').trim();
      if (!name || name === '名称未設定') return;

      // すでにParty ID持ちの顧客リストに同姓同名で存在する場合はスキップ
      const alreadyHasParty = Array.from(map.values()).some(c => c.name === name);
      if (alreadyHasParty) return;

      if (!prospectMap.has(name)) {
        prospectMap.set(name, {
          name: name,
          furigana: (a.customFields && a.customFields.furigana) || '',
          phone: (a.customFields && a.customFields.phone) || a.phone || '',
          email: (a.customFields && a.customFields.email) || a.email || '',
          corp: (a.customFields && a.customFields.corp_info && a.customFields.corp_info.name) || '',
          appoints: []
        });
      }
      prospectMap.get(name).appoints.push(a);
    }
  });

  prospectMap.forEach((val, name) => {
    map.set(`prospect_${name}`, {
      hasPartyId: false,
      id: '本登録前',
      name: val.name,
      furigana: val.furigana,
      phone: val.phone,
      email: val.email,
      corp: val.corp,
      serviceText: `過去アポイント (${val.appoints.length}件)`,
      services: [`過去アポイント (${val.appoints.length}件)`],
      appointIds: val.appoints.map(a => a.id),
      historyCount: val.appoints.length
    });
  });

  return Array.from(map.values());
}

function openCustomerSearchModal() {
  document.getElementById('customer-search-modal').classList.add('active');
  document.getElementById('modal-search-input').value = '';
  document.getElementById('modal-search-input').focus();
  renderModalCustomerList(getAllCustomerCandidates());
}

function closeModal() {
  document.getElementById('customer-search-modal').classList.remove('active');
}

// モーダル内の顧客リスト描画
function renderModalCustomerList(list) {
  const container = document.getElementById('modal-customer-list');
  container.innerHTML = '';

  if (list.length === 0) {
    container.innerHTML = '<div style="padding: 2.5rem 1rem; text-align: center; color: var(--text-muted); font-size: 0.9rem;">一致する顧客は見つかりませんでした</div>';
    return;
  }

  list.forEach(cust => {
    const item = document.createElement('div');
    item.className = 'search-result-item';
    item.style.padding = '0.75rem 1rem';
    item.style.borderBottom = '1px solid var(--border-color)';
    item.style.cursor = 'pointer';
    item.style.transition = 'background 0.15s ease';

    // 👤 Party ID有無バッジ
    const partyIdBadge = cust.hasPartyId
      ? `<span class="badge" style="font-family: monospace; font-size: 0.73rem; padding: 0.15rem 0.5rem; background: rgba(59, 130, 246, 0.12); color: #2563eb; border: 1px solid rgba(59, 130, 246, 0.3); font-weight: 700;">👤 Party ID: ${cust.id}</span>`
      : `<span class="badge" style="font-size: 0.73rem; padding: 0.15rem 0.5rem; background: rgba(245, 158, 11, 0.12); color: #d97706; border: 1px solid rgba(245, 158, 11, 0.3); font-weight: 700;">⏳ 本登録前</span>`;

    // 📋 何に登録されているかバッジ
    const serviceBadge = cust.hasPartyId
      ? `<span class="badge" style="font-size: 0.73rem; padding: 0.15rem 0.5rem; background: rgba(16, 185, 129, 0.12); color: #059669; border: 1px solid rgba(16, 185, 129, 0.3); font-weight: 600;">契約: ${cust.serviceText}</span>`
      : `<span class="badge" style="font-size: 0.73rem; padding: 0.15rem 0.5rem; background: rgba(107, 114, 128, 0.12); color: #4b5563; border: 1px solid rgba(107, 114, 128, 0.3); font-weight: 600;">登録元: 過去アポ (${cust.historyCount}件)</span>`;

    item.innerHTML = `
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.35rem; flex-wrap: wrap; gap: 0.4rem;">
        <div style="display: flex; align-items: center; gap: 0.5rem;">
          <span style="font-weight: 700; font-size: 0.95rem; color: var(--text-primary);">${cust.name}</span>
          ${cust.furigana ? `<span style="font-size: 0.75rem; color: var(--text-muted);">(${cust.furigana})</span>` : ''}
        </div>
        <div style="display: flex; align-items: center; gap: 0.4rem;">
          ${partyIdBadge}
          ${serviceBadge}
        </div>
      </div>
      <div style="font-size: 0.78rem; color: var(--text-secondary); display: flex; gap: 1.2rem; flex-wrap: wrap;">
        <span>🏢 会社名: ${cust.corp || '未登録'}</span>
        <span>📞 電話: ${cust.phone || '未登録'}</span>
        <span>✉️ メール: ${cust.email || '未登録'}</span>
      </div>
    `;

    item.addEventListener('click', () => {
      if (typeof targetSearchMode !== 'undefined' && targetSearchMode === 'related') {
        const relatedInput = document.getElementById('ext-info-related-id');
        if (relatedInput) {
          relatedInput.value = cust.id;
          relatedInput.readOnly = true;
          const clearBtn = document.getElementById('btn-clear-related-id');
          if (clearBtn) clearBtn.style.display = 'inline-block';
          
          const switchToggleContainer = document.getElementById('id-switch-toggle-container');
          const switchMainBtn = document.getElementById('btn-switch-main-id');
          const switchRelatedBtn = document.getElementById('btn-switch-related-id-view');
          if (switchToggleContainer && state.selectedExistingCustomer) {
            switchToggleContainer.style.display = 'flex';
            switchMainBtn.textContent = `メインID (${state.selectedExistingCustomer.id})`;
            switchRelatedBtn.textContent = `関連ID (${cust.id})`;
            switchMainBtn.classList.add('active');
            switchRelatedBtn.classList.remove('active');
          }
        }
        
        if (state.editingAppointId) {
          const appoint = state.appointments.find(a => a.id === state.editingAppointId);
          if (appoint && appoint.customerId) {
            syncBiDirectionalRelatedCustomerId(appoint.customerId, cust.id);
          }
        }
        targetSearchMode = 'main';
      } else {
        selectCustomer(cust);
      }
      closeModal();
    });
    container.appendChild(item);
  });
}

// モーダル内検索フィルター（Party ID保有者＋本登録前見込み客の横断検索）
function handleModalSearch(e) {
  const query = e.target.value.trim().toLowerCase();
  const allCandidates = getAllCustomerCandidates();

  if (!query) {
    renderModalCustomerList(allCandidates);
    return;
  }

  const filtered = allCandidates.filter(c => {
    return (
      (c.id && c.id.toLowerCase().includes(query)) ||
      (c.name && c.name.toLowerCase().includes(query)) ||
      (c.furigana && c.furigana.toLowerCase().includes(query)) ||
      (c.phone && c.phone.includes(query)) ||
      (c.email && c.email.toLowerCase().includes(query)) ||
      (c.corp && c.corp.toLowerCase().includes(query)) ||
      (c.serviceText && c.serviceText.toLowerCase().includes(query))
    );
  });

  renderModalCustomerList(filtered);
}

