  async function loadCurrentUserProfile() {
    if (!state.currentUser) return;
    const userId = state.currentUser.id;
    
    // デフォルト
    let profile = {
      name: state.currentUser.name || 'オーナー',
      login_id: state.currentUser.loginId || 'owner',
      birthday: '1980/01/01',
      code: state.currentUser.code || '4X9N3K75',
      email: state.currentUser.id === 'owner' ? 'admin@synapse.management' : state.currentUser.id,
      phone_number: state.currentUser.phone_number || '未設定'
    };

    if (supabaseClient && userId !== 'owner') {
      try {
        const { data, error } = await supabaseClient
          .from('synapse_users')
          .select('*')
          .eq('id', userId)
          .maybeSingle();
        if (data) {
          profile = {
            name: data.name || profile.name,
            login_id: data.login_id || profile.login_id,
            birthday: data.birthday || '未設定',
            code: data.code || profile.code,
            email: data.email || profile.email,
            phone_number: data.phone_number || '未設定'
          };
        }
      } catch (err) {
        console.error('[Profile] Failed to fetch profile from Supabase:', err);
      }
    }

    // フルネームから「姓」と「名」を分割
    const nameVal = profile.name || '';
    const nameParts = nameVal.trim().split(/[\s　]+/);
    const lastName = nameParts[0] || '';
    const firstName = nameParts.slice(1).join(' ') || '';

    // 画面のテキストフィールドへセット (編集不可の表示用)
    const lastNameEl = document.getElementById('info-disp-last-name');
    const firstNameEl = document.getElementById('info-disp-first-name');
    const loginidEl = document.getElementById('info-disp-loginid');
    const birthdayEl = document.getElementById('info-disp-birthday');
    const codeEl = document.getElementById('info-disp-code');
    const emailEl = document.getElementById('info-disp-email');
    const phoneEl = document.getElementById('info-disp-phone');

    if (lastNameEl) lastNameEl.value = lastName;
    if (firstNameEl) firstNameEl.value = firstName;
    if (loginidEl) loginidEl.value = profile.login_id;
    if (birthdayEl) birthdayEl.value = profile.birthday;
    if (codeEl) codeEl.value = profile.code;
    if (emailEl) emailEl.value = profile.email;
    if (phoneEl) phoneEl.value = profile.phone_number === '未設定' ? '未設定' : profile.phone_number;
  }

  async function renderMypageDeviceList() {
    const deviceListEl = document.getElementById('screen-info-device-list');
    if (!deviceListEl) return;

    if (!supabaseClient || !state.currentUser) {
      deviceListEl.innerHTML = '<div style="text-align: center; color: var(--text-secondary); font-size: 0.8rem; padding: 1rem 0;">デバイス情報の同期は無効です。</div>';
      return;
    }

    try {
      const searchId = state.currentUser.id === 'owner' ? 'owner@synapse.management' : state.currentUser.id;

      const { data: devices, error } = await supabaseClient
        .from('synapse_user_devices')
        .select('*')
        .eq('user_id', searchId)
        .order('created_at', { ascending: true });

      if (error) throw error;

      const currentToken = localStorage.getItem('synapse_device_token');

      if (!devices || devices.length === 0) {
        // デバイス未登録の場合は現在の端末を認識して一時表示
        const devName = getDeviceName ? getDeviceName() : '現在の端末 (PC)';
        const lastUsed = new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' });
        deviceListEl.innerHTML = `
          <div style="display: flex; justify-content: space-between; align-items: center; background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: var(--radius-sm); padding: 0.6rem 0.75rem; font-size: 0.8rem;">
            <div style="text-align: left;">
              <div style="font-weight: 700; color: var(--text-primary); display: flex; align-items: center; gap: 0.35rem;">
                <span>💻</span>
                <span>${devName}</span>
                <span style="font-size: 0.65rem; background: rgba(16, 185, 129, 0.15); color: #10b981; padding: 0.1rem 0.35rem; border-radius: var(--radius-xs); font-weight: 700; margin-left: 0.5rem;">現在の端末</span>
              </div>
              <div style="font-size: 0.7rem; color: var(--text-secondary); margin-top: 0.2rem;">
                最終利用: ${lastUsed} (ローカル検知)
              </div>
            </div>
          </div>
        `;
        return;
      }

      deviceListEl.innerHTML = devices.map(dev => {
        const isCurrent = dev.device_token === currentToken || (devices.length === 1 && (state.currentUser.id === 'owner' || state.currentUser.id === 'owner@synapse.management' || isOwnerUser()));
        const badge = isCurrent ? '<span style="font-size: 0.65rem; background: rgba(16, 185, 129, 0.15); color: #10b981; padding: 0.1rem 0.35rem; border-radius: var(--radius-xs); font-weight: 700; margin-left: 0.5rem;">現在の端末</span>' : '';
        const lastUsed = new Date(dev.last_used_at).toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' });
        const typeIcon = { smartphone: '📱', tablet: '📟', desktop: '💻' }[dev.device_type] || '💻';
        
        return `
          <div style="display: flex; justify-content: space-between; align-items: center; background: var(--bg-surface); border: 1px solid var(--border-color); border-radius: var(--radius-sm); padding: 0.6rem 0.75rem; font-size: 0.8rem;">
            <div style="text-align: left;">
              <div style="font-weight: 700; color: var(--text-primary); display: flex; align-items: center; gap: 0.35rem;">
                <span>${typeIcon}</span>
                <span>${dev.device_name || '名称不明の端末'}</span>
                ${badge}
              </div>
              <div style="font-size: 0.7rem; color: var(--text-secondary); margin-top: 0.2rem;">
                最終利用: ${lastUsed}
              </div>
            </div>
          </div>
        `;
      }).join('');
    } catch (err) {
      console.error('[Device Auth] Render user devices error:', err);
      deviceListEl.innerHTML = '<div style="text-align: center; color: #ef4444; font-size: 0.8rem; padding: 1rem 0;">エラーが発生しました。</div>';
    }
  }

  // --- メールアドレス編集モーダル関連イベント ---
  const editEmailBtn = document.getElementById('info-edit-email-btn');
  const editEmailModal = document.getElementById('edit-email-modal');
  const editEmailClose = document.getElementById('edit-email-close');
  const editEmailCancel = document.getElementById('edit-email-cancel');
  const editEmailSubmit = document.getElementById('edit-email-submit');

  if (editEmailBtn && editEmailModal) {
    editEmailBtn.addEventListener('click', () => {
      const curEmail = document.getElementById('info-disp-email').value;
      const curEmailLabel = document.getElementById('edit-email-current');
      if (curEmailLabel) curEmailLabel.textContent = curEmail;
      document.getElementById('edit-email-new').value = '';
      document.getElementById('edit-email-confirm').value = '';
      editEmailModal.style.display = 'flex';
    });
  }

  const closeEmailModal = () => {
    if (editEmailModal) editEmailModal.style.display = 'none';
  };
  if (editEmailClose) editEmailClose.addEventListener('click', closeEmailModal);
  if (editEmailCancel) editEmailCancel.addEventListener('click', closeEmailModal);

  if (editEmailSubmit) {
    editEmailSubmit.addEventListener('click', async () => {
      const newEmail = document.getElementById('edit-email-new').value.trim();
      const confirmEmail = document.getElementById('edit-email-confirm').value.trim();

      if (!newEmail || !confirmEmail) {
        showToast('新しいメールアドレスを入力してください。', 'error');
        return;
      }
      if (newEmail !== confirmEmail) {
        showToast('新しいメールアドレスと確認用メールアドレスが一致しません。', 'error');
        return;
      }
      if (!/.+@.+\..+/.test(newEmail)) {
        showToast('メールアドレスの形式が正しくありません。', 'error');
        return;
      }

      editEmailSubmit.disabled = true;
      editEmailSubmit.textContent = '申請中...';

      try {
        if (supabaseClient && state.currentUser.id !== 'owner') {
          const { error } = await supabaseClient.auth.updateUser({ email: newEmail });
          if (error) throw error;
          
          showAppConfirm(
            '✉️ 確認メールを送信しました',
            `変更先のメールアドレス（${newEmail}）宛てに疎通確認メールを送信しました。\nメール内の確認リンクをクリックするまで変更は確定しません。\n変更が承認され次第、新しいメールアドレスが有効になります。`
          );
        } else {
          // デモまたはowner
          state.currentUser.id = newEmail;
          state.currentUser.loginId = newEmail;
          localStorage.setItem(STORAGE_KEYS.LOGGED_USER, JSON.stringify(state.currentUser));
          const emailEl = document.getElementById('info-disp-email');
          if (emailEl) emailEl.value = newEmail;
          
          // マイページのセキュリティ情報表示も更新
          renderMypageSecurityInfo();
          showToast('メールアドレスを更新しました（デモ）。', 'success');
        }
        closeEmailModal();
      } catch (err) {
        console.error('[Email Update] Failure:', err);
        showToast('メールアドレスの変更申請に失敗しました: ' + err.message, 'error');
      } finally {
        editEmailSubmit.disabled = false;
        editEmailSubmit.textContent = '変更を申請する';
      }
    });
  }

