function getFolderMenuPath(accId) {
  const path = [];
  const visited = new Set();
  let current = state.customAccordions.find(a => a.id === accId);
  while (current) {
    if (visited.has(current.id)) {
      console.warn("[Folder Path] Circular reference break:", current.id);
      path.unshift(`[循環:${current.name}]`);
      break;
    }
    visited.add(current.id);
    path.unshift(current.name);
    current = state.customAccordions.find(a => a.id === current.parentMenuId);
  }
  return path.join(' ＞ ');
}

function updateParentSelectDropdowns() {
  const tcSelect = document.getElementById('tc-table-parent');
  const ctSelect = document.getElementById('ct-table-parent-select');
  if (!tcSelect && !ctSelect) return;

  // 標準フォルダーの定義（正規化IDとスマートなアイコン・表示名）
  const standardFolderMap = {
    'root': { value: 'root', text: '🏠 メインメニュー直下（最上位）', icon: '🏠' },
    'agency-accordion': { value: 'agency-accordion', text: '💼 代理店情報', icon: '💼' },
    'jo-accordion': { value: 'jo-accordion', text: '📑 JO情報', icon: '📑' },
    'applicant-accordion': { value: 'applicant-accordion', text: '📋 申込者情報', icon: '📋' },
    'appoint-accordion': { value: 'appoint-accordion', text: '📅 アポイント情報', icon: '📅' },
    'forms-accordion': { value: 'forms-accordion', text: '📝 回答フォーム一覧', icon: '📝' }
  };

  const options = [];
  const addedValues = new Set();

  // 1. ルート（最上位）
  options.push(standardFolderMap['root']);
  addedValues.add('root');

  // 2. 標準フォルダー群（順序良く並べる）
  const stdOrder = ['agency-accordion', 'jo-accordion', 'applicant-accordion', 'appoint-accordion', 'forms-accordion'];
  stdOrder.forEach(id => {
    options.push(standardFolderMap[id]);
    addedValues.add(id);
    // 旧エイリアス（agency-info 等）も重複ガードに追加
    if (id === 'agency-accordion') addedValues.add('agency-info');
    if (id === 'jo-accordion') addedValues.add('jo-info');
    if (id === 'applicant-accordion') addedValues.add('applicant-info');
    if (id === 'appoint-accordion') addedValues.add('appoint');
    if (id === 'forms-accordion') addedValues.add('forms');
  });

  // 3. ユーザー作成カスタムフォルダー（state.customAccordions から重複なく追加）
  if (Array.isArray(state.customAccordions)) {
    state.customAccordions.forEach(acc => {
      const normId = normalizeFolderId(acc.id);
      if (addedValues.has(normId) || addedValues.has(acc.id)) return;
      addedValues.add(acc.id);
      addedValues.add(normId);

      const icon = acc.icon || '📁';
      const pathText = typeof getFolderMenuPath === 'function' ? getFolderMenuPath(acc.id) : (acc.name || acc.id);
      options.push({
        value: normId,
        text: `${icon} ${pathText}`
      });
    });
  }

  const renderOpts = (selectEl) => {
    if (!selectEl) return;
    const rawVal = selectEl.value || selectEl.dataset.selectedVal;
    const currentVal = normalizeFolderId(rawVal);
    selectEl.innerHTML = '';
    options.forEach(opt => {
      const el = document.createElement('option');
      el.value = opt.value;
      el.textContent = opt.text;
      selectEl.appendChild(el);
    });
    if (currentVal && options.some(o => o.value === currentVal)) {
      selectEl.value = currentVal;
    } else {
      selectEl.value = 'root';
    }
  };

  renderOpts(tcSelect);
  renderOpts(ctSelect);
}

function updateAdminFolderAddDropdown() {
  const selectEl = document.getElementById('modal-folder-parent-select');
  if (!selectEl) return;
  const currentVal = normalizeFolderId(selectEl.value);
  selectEl.innerHTML = '<option value="root">🏠 メインメニュー直下（最上位）</option>';

  const standardFolderIds = new Set(['root', 'forms-accordion', 'applicant-accordion', 'jo-accordion', 'agency-accordion', 'appoint-accordion']);

  const stdFolders = [
    { id: 'agency-accordion', name: '💼 代理店情報' },
    { id: 'jo-accordion', name: '📑 JO情報' },
    { id: 'applicant-accordion', name: '📋 申込者情報' },
    { id: 'appoint-accordion', name: '📅 アポイント情報' },
    { id: 'forms-accordion', name: '📝 回答フォーム一覧' }
  ];
  stdFolders.forEach(sf => {
    const el = document.createElement('option');
    el.value = sf.id;
    el.textContent = sf.name;
    selectEl.appendChild(el);
  });

  if (Array.isArray(state.customAccordions)) {
    state.customAccordions.forEach(acc => {
      const normId = normalizeFolderId(acc.id);
      if (standardFolderIds.has(normId) || standardFolderIds.has(acc.id)) return;
      standardFolderIds.add(acc.id);
      standardFolderIds.add(normId);

      const el = document.createElement('option');
      el.value = acc.id;
      el.textContent = (acc.icon ? acc.icon + ' ' : '📁 ') + (typeof getFolderMenuPath === 'function' ? getFolderMenuPath(acc.id) : (acc.name || acc.id));
      selectEl.appendChild(el);
    });
  }
  selectEl.value = currentVal || 'root';
}

function renderAdminPanelFolderList() {
  const tbody = document.getElementById('modal-folder-list-tbody');
  const emptyDiv = document.getElementById('modal-folder-list-empty');
  if (!tbody) return;

  tbody.innerHTML = '';
  
  if (!state.customAccordions || state.customAccordions.length === 0) {
    if (emptyDiv) emptyDiv.style.display = 'block';
    return;
  }
  if (emptyDiv) emptyDiv.style.display = 'none';

  state.customAccordions.forEach(acc => {
    const tr = document.createElement('tr');
    tr.style.borderBottom = '1px solid var(--border-color)';

    // フォルダ名セル
    const tdName = document.createElement('td');
    tdName.style.padding = '0.75rem 0.5rem';
    
    const inputName = document.createElement('input');
    inputName.type = 'text';
    inputName.value = acc.name;
    inputName.style.width = '90%';
    inputName.style.padding = '0.3rem 0.5rem';
    inputName.style.fontSize = '0.85rem';
    inputName.style.border = '1px solid var(--border-color)';
    inputName.style.borderRadius = 'var(--radius-sm)';
    inputName.style.background = 'var(--bg-surface-elevated)';
    inputName.style.color = 'var(--text-primary)';
    inputName.style.outline = 'none';
    
    tdName.appendChild(inputName);

    // 親フォルダセル
    const tdParent = document.createElement('td');
    tdParent.style.padding = '0.75rem 0.5rem';
    
    const selectParent = document.createElement('select');
    selectParent.style.width = '90%';
    selectParent.style.padding = '0.3rem 0.5rem';
    selectParent.style.fontSize = '0.85rem';
    selectParent.style.border = '1px solid var(--border-color)';
    selectParent.style.borderRadius = 'var(--radius-sm)';
    selectParent.style.background = 'var(--bg-surface-elevated)';
    selectParent.style.color = 'var(--text-primary)';
    selectParent.style.cursor = 'pointer';
    selectParent.style.outline = 'none';

    // 選択肢の生成（自身とその子孫を除外）
    const options = [
      { value: 'root', text: 'ルート直下' }
    ];

    // 自身の子孫かどうか判定する関数
    const isDescendant = (parentAccId, childAccId) => {
      let current = state.customAccordions.find(a => a.id === childAccId);
      while (current) {
        if (current.parentMenuId === parentAccId) return true;
        current = state.customAccordions.find(a => a.id === current.parentMenuId);
      }
      return false;
    };

    state.customAccordions.forEach(otherAcc => {
      if (otherAcc.id === acc.id) return; // 自分自身は除外
      if (isDescendant(acc.id, otherAcc.id)) return; // 自分の子孫フォルダは除外（循環参照防止）
      options.push({ value: otherAcc.id, text: getFolderMenuPath(otherAcc.id) });
    });

    options.forEach(opt => {
      const el = document.createElement('option');
      el.value = opt.value;
      el.textContent = opt.text;
      selectParent.appendChild(el);
    });

    selectParent.value = acc.parentMenuId || 'root';
    tdParent.appendChild(selectParent);

    // 操作ボタンセル
    const tdActions = document.createElement('td');
    tdActions.style.padding = '0.75rem 0.5rem';
    tdActions.style.textAlign = 'center';
    
    const saveBtn = document.createElement('button');
    saveBtn.className = 'btn-primary';
    saveBtn.style.padding = '0.3rem 0.6rem';
    saveBtn.style.fontSize = '0.8rem';
    saveBtn.style.marginRight = '0.5rem';
    saveBtn.textContent = '保存';
    saveBtn.title = 'フォルダ名や配置場所の変更を確定して保存';
    saveBtn.addEventListener('click', () => {
      const newName = inputName.value.trim();
      if (!newName) {
        showToast('フォルダ名を入力してください。', 'warning');
        return;
      }
      const newParent = selectParent.value;
      
      // 循環参照の厳格な検証
      if (newParent === acc.id) {
        showToast('自分自身を親フォルダに指定することはできません。', 'warning');
        return;
      }
      if (isDescendant(acc.id, newParent)) {
        showToast('子孫フォルダを親フォルダに指定することはできません。', 'warning');
        return;
      }

      // 名前の変更と配置先の更新
      acc.name = newName;
      acc.parentMenuId = newParent;
      
      saveCustomAccordions();
      renderCustomTableList();
      updateParentSelectDropdowns();
      updateAdminFolderAddDropdown();
      renderAdminPanelFolderList();
      renderModalFolderTree();
      showToast('フォルダ設定を保存しました。', 'success');
    });

    const deleteBtn = document.createElement('button');
    deleteBtn.style.padding = '0.3rem 0.6rem';
    deleteBtn.style.fontSize = '0.8rem';
    deleteBtn.style.border = 'none';
    deleteBtn.style.color = '#fff';
    deleteBtn.style.borderRadius = 'var(--radius-sm)';
    deleteBtn.style.marginLeft = '0.3rem';
    
    if (acc.isSystem) {
      deleteBtn.style.background = 'var(--text-muted)';
      deleteBtn.style.cursor = 'not-allowed';
      deleteBtn.disabled = true;
      deleteBtn.title = 'システム標準フォルダは削除できません';
    } else {
      deleteBtn.style.background = '#ef4444';
      deleteBtn.style.cursor = 'pointer';
      deleteBtn.title = 'このフォルダを削除します';
    }
    
    deleteBtn.textContent = '削除';
    deleteBtn.addEventListener('click', () => {
      if (acc.isSystem) return;
      if (confirm(`フォルダ「${acc.name}」を削除しますか？\n※中のテーブルはルート直下に移動されます。`)) {
        deleteCustomAccordion(acc.id);
      }
    });

    tdActions.appendChild(saveBtn);
    tdActions.appendChild(deleteBtn);

    tr.appendChild(tdName);
    tr.appendChild(tdParent);
    tr.appendChild(tdActions);

    tbody.appendChild(tr);
  });

  // モーダル内のドラッグ＆ドロップ用ツリーを再描画
  renderModalFolderTree();
}

// ================= アプリ内カスタムダイアログ (confirm / prompt の代替) =================
function showAppConfirm(title, message, onOk) {
  const overlay = document.getElementById('custom-dialog-overlay');
  const titleEl = document.getElementById('custom-dialog-title');
  const msgEl = document.getElementById('custom-dialog-message');
  const inputContainer = document.getElementById('custom-dialog-input-container');
  const okBtn = document.getElementById('custom-dialog-ok-btn');
  const cancelBtn = document.getElementById('custom-dialog-cancel-btn');

  if (!overlay) {
    if (confirm(message)) onOk();
    return;
  }

  titleEl.textContent = title || '❓ 確認';
  msgEl.textContent = message || '';
  inputContainer.style.display = 'none';

  overlay.style.display = 'flex';
  overlay.classList.add('active');

  const closeDialog = () => {
    overlay.style.display = 'none';
    overlay.classList.remove('active');
  };

  okBtn.onclick = () => {
    closeDialog();
    if (onOk) onOk();
  };
  cancelBtn.onclick = closeDialog;
}

function showAppPrompt(title, message, defaultValue, onOk) {
  const overlay = document.getElementById('custom-dialog-overlay');
  const titleEl = document.getElementById('custom-dialog-title');
  const msgEl = document.getElementById('custom-dialog-message');
  const inputContainer = document.getElementById('custom-dialog-input-container');
  const inputEl = document.getElementById('custom-dialog-input');
  const okBtn = document.getElementById('custom-dialog-ok-btn');
  const cancelBtn = document.getElementById('custom-dialog-cancel-btn');

  if (!overlay) {
    const res = prompt(message, defaultValue);
    if (res !== null) onOk(res);
    return;
  }

  titleEl.textContent = title || '✏️ 入力';
  msgEl.textContent = message || '';
  inputContainer.style.display = 'block';
  inputEl.value = defaultValue || '';

  overlay.style.display = 'flex';
  overlay.classList.add('active');

  setTimeout(() => {
    inputEl.focus();
    inputEl.select();
  }, 50);

  const closeDialog = () => {
    overlay.style.display = 'none';
    overlay.classList.remove('active');
  };

  const handleOk = () => {
    const val = inputEl.value.trim();
    closeDialog();
    if (val && onOk) onOk(val);
  };

  okBtn.onclick = handleOk;
  cancelBtn.onclick = closeDialog;
  inputEl.onkeydown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleOk();
    }
  };
}

function showAppPasswordPrompt(title, message, onOk) {
  const overlay = document.getElementById('custom-dialog-overlay');
  const titleEl = document.getElementById('custom-dialog-title');
  const msgEl = document.getElementById('custom-dialog-message');
  const inputContainer = document.getElementById('custom-dialog-input-container');
  const inputEl = document.getElementById('custom-dialog-input');
  const okBtn = document.getElementById('custom-dialog-ok-btn');
  const cancelBtn = document.getElementById('custom-dialog-cancel-btn');

  if (!overlay) {
    const res = prompt(message, '');
    if (res !== null) onOk(res);
    return;
  }

  titleEl.textContent = title || '🔒 パスワード確認';
  msgEl.textContent = message || '';
  inputContainer.style.display = 'block';
  inputEl.type = 'password';
  inputEl.value = '';
  inputEl.placeholder = '管理用パスワードを入力';

  overlay.style.display = 'flex';
  overlay.classList.add('active');

  setTimeout(() => {
    inputEl.focus();
  }, 50);

  const closeDialog = () => {
    inputEl.type = 'text';
    inputEl.placeholder = '';
    overlay.style.display = 'none';
    overlay.classList.remove('active');
  };

  const handleOk = () => {
    const val = inputEl.value;
    closeDialog();
    if (onOk) onOk(val);
  };

  okBtn.onclick = handleOk;
  cancelBtn.onclick = closeDialog;
  inputEl.onkeydown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleOk();
    }
  };
}

// 右クリックコンテキストメニューの状態管理
let activeContextMenuTarget = null;

function hideContextMenu() {
  const menu = document.getElementById('folder-context-menu');
  if (menu) menu.style.display = 'none';
  activeContextMenuTarget = null;
}

function showContextMenu(x, y, type, targetObj) {
  const menu = document.getElementById('folder-context-menu');
  if (!menu) return;

  activeContextMenuTarget = { type, targetObj };
  
  // 削除ボタンの可否
  const delBtn = document.getElementById('ctx-delete');
  if (delBtn) {
    if (type === 'folder' && targetObj.isSystem) {
      delBtn.style.display = 'none';
    } else if (type === 'item' && ['agency-info-screen', 'jo-info-screen', 'applicant-info-screen', 'appointment-new', 'appointment-existing', 'drafts-view-screen', 'history-view-screen', 'official-id-link'].includes(targetObj.id)) {
      delBtn.style.display = 'none';
    } else {
      delBtn.style.display = 'flex';
    }
  }

  // 「最上位階層に戻す」ボタンの可否（別の配下に入っている場合のみ表示）
  const moveRootBtn = document.getElementById('ctx-move-root');
  if (moveRootBtn) {
    const parentId = normalizeFolderId(targetObj.parentMenuId || 'root');
    moveRootBtn.style.display = (parentId !== 'root') ? 'flex' : 'none';
  }

  // 画面枠外にはみ出さないように配置
  menu.style.display = 'block';
  const menuWidth = menu.offsetWidth || 160;
  const menuHeight = menu.offsetHeight || 120;
  const posX = (x + menuWidth > window.innerWidth) ? window.innerWidth - menuWidth - 10 : x;
  const posY = (y + menuHeight > window.innerHeight) ? window.innerHeight - menuHeight - 10 : y;

  menu.style.left = `${posX}px`;
  menu.style.top = `${posY}px`;
}

// コンテキストメニューのイベント初期化 (1回のみ)
function initContextMenuEvents() {
  const menu = document.getElementById('folder-context-menu');
  if (!menu || menu.dataset.initialized) return;
  menu.dataset.initialized = 'true';

  document.addEventListener('click', (e) => {
    if (!e.target.closest('#folder-context-menu')) hideContextMenu();
  });

  const renameBtn = document.getElementById('ctx-rename');
  if (renameBtn) {
    renameBtn.addEventListener('click', () => {
      if (!activeContextMenuTarget) return;
      const { type, targetObj } = activeContextMenuTarget;
      hideContextMenu();

      showAppPrompt(
        '名前の変更',
        `新しい${type === 'folder' ? 'フォルダ名' : '名前'}を入力してください:`,
        targetObj.name,
        (newName) => {
          if (newName && newName !== targetObj.name) {
            targetObj.name = newName;
            if (type === 'folder') {
              saveCustomAccordions();
            } else {
              saveCustomTables();
            }
            renderCustomTableList();
            renderModalFolderTree();
            showToast('名前を変更しました。', 'success');
          }
        }
      );
    });
  }

  const moveRootBtn = document.getElementById('ctx-move-root');
  if (moveRootBtn) {
    moveRootBtn.addEventListener('click', () => {
      if (!activeContextMenuTarget) return;
      const { type, targetObj } = activeContextMenuTarget;
      hideContextMenu();

      targetObj.parentMenuId = 'root';
      if (type === 'folder') {
        saveCustomAccordions();
      } else {
        saveCustomTables();
      }
      renderCustomTableList();
      renderModalFolderTree();
      showToast(`「${targetObj.name}」を最上位（親フォルダ階層）に戻しました。`, 'success');
    });
  }

  const delBtn = document.getElementById('ctx-delete');
  if (delBtn) {
    delBtn.addEventListener('click', () => {
      if (!activeContextMenuTarget) return;
      const { type, targetObj } = activeContextMenuTarget;
      hideContextMenu();

      if (type === 'folder') {
        deleteCustomAccordion(targetObj.id);
      } else if (type === 'item') {
        showAppConfirm('削除の確認', `「${targetObj.name}」を削除しますか？`, () => {
          deleteCustomTable(targetObj.id);
        });
      }
    });
  }
}

// ==========================================
// ログイン画面の新規サインアップ処理
// ==========================================
function initSignupEvents() {
  const loginScreen = document.getElementById('login-screen');
  const signupScreen = document.getElementById('signup-screen');
  const goToSignup = document.getElementById('go-to-signup');
  const goToLogin = document.getElementById('go-to-login');
  
  const signupForm = document.getElementById('signup-form');

  // パスワード再設定リンクのアクション登録
  const forgotPasswordLink = document.getElementById('forgot-password-link');
  const resetReqModal = document.getElementById('reset-password-request-modal');
  const resetReqCancel = document.getElementById('reset-pwd-req-cancel-btn');
  const resetReqSubmit = document.getElementById('reset-pwd-req-submit-btn');

  if (forgotPasswordLink && resetReqModal) {
    forgotPasswordLink.addEventListener('click', (e) => {
      e.preventDefault();
      const emailInput = document.getElementById('reset-pwd-req-email');
      const loginIdInput = document.getElementById('login-id');
      if (emailInput) {
        const currentId = loginIdInput ? loginIdInput.value.trim() : '';
        emailInput.value = currentId.includes('@') ? currentId : '';
      }
      resetReqModal.style.display = 'flex';
    });
  }

  if (resetReqCancel && resetReqModal) {
    resetReqCancel.addEventListener('click', () => {
      resetReqModal.style.display = 'none';
    });
  }

  if (resetReqSubmit && resetReqModal) {
    resetReqSubmit.addEventListener('click', async () => {
      const emailInput = document.getElementById('reset-pwd-req-email');
      const targetEmail = emailInput ? emailInput.value.trim() : '';
      if (!targetEmail) {
        showToast('メールアドレスを入力してください。', 'error');
        return;
      }

      const origin = window.location.origin;
      const resetUrl = `${origin}/?action=reset-password&email=${encodeURIComponent(targetEmail)}`;

      showToast('再設定メール送信中...', 'info');

      const sendEmailPromise = window.location.protocol === 'file:' 
        ? Promise.resolve({ success: true, simulated: true })
        : fetch('/api/send-email', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              to: targetEmail,
              subject: '【Synapse】パスワード再設定のご案内',
              html: `
                <div style="font-family: sans-serif; line-height: 1.5; padding: 1.25rem; border: 1px solid #e2e8f0; border-radius: 8px; max-width: 500px; margin: 0 auto; color: #1e293b;">
                  <h2 style="color: #ef4444; margin-top: 0;">パスワード再設定</h2>
                  <p>以下のリンクをクリックして、パスワードの再設定を行ってください：</p>
                  <p style="margin: 1.5rem 0;">
                    <a href="${resetUrl}" style="background: #ef4444; color: #ffffff; padding: 0.6rem 1.2rem; border-radius: 4px; text-decoration: none; font-weight: bold; display: inline-block;">パスワードを再設定する</a>
                  </p>
                  <p style="font-size: 0.8rem; color: #64748b;">
                    ※リンクがクリックできない場合は、以下のURLをブラウザのアドレスバーに直接貼り付けてください：<br>
                    <a href="${resetUrl}" style="color: #ef4444;">${resetUrl}</a>
                  </p>
                </div>
              `
            })
          }).then(res => res.json());

      sendEmailPromise
      .then(data => {
        if (data.success) {
          if (data.simulated) {
            showToast('メール送信をシミュレートしました。', 'success');
            showAppConfirm(
              '📧 パスワード再設定メール（シミュレーション）',
              `（SMTP設定未完了のためシミュレート送信しました）\n「${targetEmail}」宛てのパスワード再設定画面に進みますか？`,
              () => {
                const modal = document.getElementById('set-password-modal');
                const emailHidden = document.getElementById('set-pwd-email');
                if (modal && emailHidden) {
                  emailHidden.value = targetEmail;
                  const pwdInput = document.getElementById('set-pwd-input');
                  const pwdConfirmInput = document.getElementById('set-pwd-confirm-input');
                  if (pwdInput) pwdInput.value = '';
                  if (pwdConfirmInput) pwdConfirmInput.value = '';

                  // 再設定用に入力項目を非表示にする
                  const lastNameInput = document.getElementById('set-pwd-lastname');
                  const firstNameInput = document.getElementById('set-pwd-firstname');
                  const birthdayInput = document.getElementById('set-pwd-birthday');
                  const loginIdInput = document.getElementById('set-pwd-loginid');
                  const phoneInput = document.getElementById('set-pwd-phone');
                  
                  if (birthdayInput && birthdayInput.parentElement) birthdayInput.parentElement.style.display = 'none';
                  if (loginIdInput && loginIdInput.parentElement) loginIdInput.parentElement.style.display = 'none';
                  if (phoneInput && phoneInput.parentElement) phoneInput.parentElement.style.display = 'none';
                  if (lastNameInput && lastNameInput.parentElement && lastNameInput.parentElement.parentElement) {
                    lastNameInput.parentElement.parentElement.style.display = 'none';
                  }
                  
                  const titleEl = modal.querySelector('h3');
                  if (titleEl) titleEl.innerHTML = '🔑 パスワードの再設定';

                  modal.style.display = 'flex';
                }
              }
            );
          } else {
            showToast('パスワード再設定用メールを送信しました。', 'success');
            showAppConfirm(
              '📧 メール送信完了',
              `「${targetEmail}」宛てにパスワード再設定用メールを送信しました。メール内のリンクから再設定を行ってください。`
            );
          }
        } else {
          showToast('メール送信に失敗しました: ' + data.error, 'error');
        }
      })
      .catch(err => {
        console.error('Failed to send reset email:', err);
        showToast('メール送信中に通信エラーが発生しました。', 'error');
      });

      resetReqModal.style.display = 'none';
    });
  }

  // 画面遷移・URL同期ヘルパー関数
  const navigateToAuthView = (view, updateHistory = true) => {
    if (!loginScreen || !signupScreen) return;
    if (view === 'signup') {
      loginScreen.style.display = 'none';
      loginScreen.classList.remove('active');
      signupScreen.style.display = 'flex';
      signupScreen.classList.add('active');
      if (signupForm) signupForm.reset();
      if (updateHistory && window.location.protocol !== 'file:' && window.location.pathname.toLowerCase() !== '/signup') {
        try { history.pushState({ authView: 'signup' }, '', '/signup'); } catch (e) {}
      }
    } else {
      signupScreen.style.display = 'none';
      signupScreen.classList.remove('active');
      loginScreen.style.display = 'flex';
      loginScreen.classList.add('active');
      if (updateHistory && window.location.protocol !== 'file:' && window.location.pathname.toLowerCase() !== '/login' && window.location.pathname !== '/') {
        try { history.pushState({ authView: 'login' }, '', '/login'); } catch (e) {}
      }
    }
  };

  if (goToSignup) {
    goToSignup.addEventListener('click', (e) => {
      e.preventDefault();
      navigateToAuthView('signup');
    });
  }

  if (goToLogin) {
    goToLogin.addEventListener('click', (e) => {
      e.preventDefault();
      navigateToAuthView('login');
    });
  }

  // 初期ロード時のURLパス判定
  const initialPath = window.location.pathname.toLowerCase();
  if (initialPath === '/signup') {
    navigateToAuthView('signup', false);
  } else if (initialPath === '/login') {
    navigateToAuthView('login', false);
  }

  // ブラウザの「戻る」「進む」ボタン操作（popstate）対応
  window.addEventListener('popstate', () => {
    const path = window.location.pathname.toLowerCase();
    if (path === '/signup') {
      navigateToAuthView('signup', false);
    } else if (path === '/login' || path === '/') {
      if (!state.currentUser) {
        navigateToAuthView('login', false);
      }
    }
  });

  if (signupForm) {
    signupForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      
      const lastName = document.getElementById('signup-lastname').value.trim();
      const firstName = document.getElementById('signup-firstname').value.trim();
      const email = document.getElementById('signup-email').value.trim();

      if (!lastName || !firstName) {
        showToast('姓と名を入力してください。', 'error');
        return;
      }

      if (!email) {
        showToast('メールアドレスを入力してください。', 'error');
        return;
      }

      showToast('仮登録処理中...', 'info');

      if (!supabaseClient) {
        showToast('Supabase接続が有効ではありません。', 'error');
        return;
      }

      const fullName = `${lastName} ${firstName}`;
      const userCode = generate8DigitId();
      const tempPassword = "Temp" + generate8DigitId() + "A1!";

      // 1. Supabase Auth でサインアップを実行
      let data = null;
      let error = null;

      const isLocal = window.location.protocol === 'file:' || window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

      if (isLocal) {
        console.warn('[Supabase Auth] Simulating signUp in local/file environment.');
        data = {
          user: {
            id: email,
            email: email,
            created_at: new Date().toISOString(),
            user_metadata: {
              name: fullName,
              lastName: lastName,
              firstName: firstName,
              code: userCode,
              role: 'sales',
              needs_password_setup: true
            }
          }
        };
      } else {
        try {
          const signUpRes = await supabaseClient.auth.signUp({
            email: email,
            password: tempPassword,
            options: {
              data: {
                name: fullName,
                lastName: lastName,
                firstName: firstName,
                code: userCode,
                role: 'sales',
                needs_password_setup: true
              },
              emailRedirectTo: window.location.origin
            }
          });
          data = signUpRes.data;
          error = signUpRes.error;
        } catch (err) {
          error = err;
        }
      }

      if (error) {
        console.error('[Supabase Auth] SignUp failed:', error);
        showToast('仮登録に失敗しました: ' + error.message, 'error');
        return;
      }

      const origin = window.location.origin;
      const setupUrl = `${origin}/?action=set-password&email=${encodeURIComponent(email)}&lastName=${encodeURIComponent(lastName)}&firstName=${encodeURIComponent(firstName)}`;

      showToast(`アカウント「${fullName}」を仮登録しました。メール送信中...`, 'info');

      const sendEmailPromise = window.location.protocol === 'file:' 
        ? Promise.resolve({ success: true, simulated: true })
        : fetch('/api/send-email', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json'
            },
            body: JSON.stringify({
              to: email,
              subject: '【Synapse】アカウント本登録のご案内',
              html: `
                <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; line-height: 1.6; padding: 2rem; max-width: 540px; margin: 0 auto; color: #1e293b; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px;">
                  <div style="text-align: center; margin-bottom: 1.5rem;">
                    <h2 style="color: #4f46e5; margin: 0; font-size: 1.4rem;">Synapse アカウント本登録のご案内</h2>
                  </div>
                  <p><strong>${fullName}</strong> 様</p>
                  <p>この度は「Synapse」に仮登録いただきありがとうございます。</p>
                  <p style="background: #f8fafc; border-left: 4px solid #4f46e5; padding: 0.75rem 1rem; margin: 1.5rem 0; font-size: 0.9rem; color: #334155;">
                    ⚠️ まだアカウント登録は完了しておりません。<br>
                    以下のボタンをクリックしてプロフィール・パスワードを設定し、本登録を完了してください。
                  </p>
                  <div style="text-align: center; margin: 2rem 0;">
                    <a href="${setupUrl}" style="background: #4f46e5; color: #ffffff; padding: 0.75rem 1.75rem; border-radius: 6px; text-decoration: none; font-weight: bold; font-size: 1rem; display: inline-block; box-shadow: 0 4px 6px -1px rgba(79, 70, 229, 0.2);">本登録を完了する</a>
                  </div>
                  <p style="font-size: 0.8rem; color: #94a3b8; margin-top: 2.5rem; border-top: 1px solid #e2e8f0; padding-top: 1rem; line-height: 1.5;">
                    ※ボタンがクリックできない場合は、以下のURLをコピーしてブラウザのアドレスバーに直接貼り付けてアクセスしてください：<br>
                    <a href="${setupUrl}" style="color: #4f46e5; word-break: break-all;">${setupUrl}</a>
                  </p>
                </div>
              `
            })
          }).then(res => res.json());

      sendEmailPromise
      .then(data => {
        if (data.success) {
          if (data.simulated) {
            showToast('メール送信をシミュレートしました。', 'success');
            showAppConfirm(
              '📧 アカウント本登録メール（シミュレーション）',
              `（SMTP設定未完了のためシミュレート送信しました）\n「${email}」宛てのアカウント本登録画面に進みますか？`,
              () => {
                const modal = document.getElementById('set-password-modal');
                const emailHidden = document.getElementById('set-pwd-email');
                if (modal && emailHidden) {
                  emailHidden.value = email;
                  const pwdInput = document.getElementById('set-pwd-input');
                  const pwdConfirmInput = document.getElementById('set-pwd-confirm-input');
                  if (pwdInput) pwdInput.value = '';
                  if (pwdConfirmInput) pwdConfirmInput.value = '';

                  // 本登録用のフィールド表示と初期値設定を行う
                  const lastNameInput = document.getElementById('set-pwd-lastname');
                  const firstNameInput = document.getElementById('set-pwd-firstname');
                  const birthdayInput = document.getElementById('set-pwd-birthday');
                  const loginIdInput = document.getElementById('set-pwd-loginid');
                  const phoneInput = document.getElementById('set-pwd-phone');
                  
                  if (lastNameInput) lastNameInput.value = lastName || '';
                  if (firstNameInput) firstNameInput.value = firstName || '';
                  if (phoneInput) phoneInput.value = '';
                  if (birthdayInput) birthdayInput.value = '';
                  const genderSelect = document.getElementById('set-pwd-gender');
                  if (genderSelect) genderSelect.value = '';
                  if (loginIdInput) loginIdInput.value = '';
                  
                  if (birthdayInput && birthdayInput.parentElement && birthdayInput.parentElement.parentElement) {
                    birthdayInput.parentElement.parentElement.style.display = 'flex';
                  }
                  if (loginIdInput && loginIdInput.parentElement) loginIdInput.parentElement.style.display = 'flex';
                  if (phoneInput && phoneInput.parentElement) phoneInput.parentElement.style.display = 'flex';
                  if (lastNameInput && lastNameInput.parentElement && lastNameInput.parentElement.parentElement) {
                    lastNameInput.parentElement.parentElement.style.display = 'flex';
                  }
                  
                  const titleEl = modal.querySelector('h3');
                  if (titleEl) titleEl.innerHTML = '🔑 アカウントの本登録';

                  modal.style.display = 'flex';
                }
              }
            );
          } else {
            showToast('パスワード設定用のメールを送信しました。受信トレイをご確認ください。', 'success');
            showAppConfirm(
              '📧 メール送信完了',
              `「${email}」宛てにパスワード設定メールを送信しました。メール内のリンクから設定を行ってください。`
            );
          }
        } else {
          showToast('メール送信に失敗しました: ' + data.error, 'error');
        }
      })
      .catch(err => {
        console.error('Failed to send signup email:', err);
        showToast('メール送信中に通信エラーが発生しました。', 'error');
      });

      signupForm.reset();
      
      if (signupScreen && loginScreen) {
        signupScreen.style.display = 'none';
        signupScreen.classList.remove('active');
        loginScreen.style.display = 'flex';
        loginScreen.classList.add('active');
      }
    });
  }

  // 🔐 パスワード設定モーダルの制御
  const setPwdModal = document.getElementById('set-password-modal');
  const setPwdCancelBtn = document.getElementById('set-pwd-cancel-btn');
  const setPwdSubmit = document.getElementById('set-pwd-submit-btn');

  if (setPwdCancelBtn && setPwdModal) {
    setPwdCancelBtn.addEventListener('click', () => {
      setPwdModal.style.display = 'none';
      // ログイン画面へ切り替え
      if (signupScreen && loginScreen) {
        signupScreen.style.display = 'none';
        signupScreen.classList.remove('active');
        loginScreen.style.display = 'flex';
        loginScreen.classList.add('active');
      }
      showToast('パスワード設定がキャンセルされました。', 'info');
    });
  }

  // 🎂 生年月日の自動変換・フォーマット関数
  const parseAndFormatBirthday = (input) => {
    if (!input) return null;
    let str = input.trim();
    // 全角英数記号を半角に変換
    str = str.replace(/[Ａ-Ｚａ-ｚ０-９]/g, s => String.fromCharCode(s.charCodeAt(0) - 0xFEE0));
    str = str.replace(/[／．－ー―]/g, '/');

    // 実在するカレンダー日付かどうかの検証関数
    const isValidCalendarDate = (y, m, d) => {
      const year = parseInt(y, 10);
      const month = parseInt(m, 10);
      const day = parseInt(d, 10);
      if (year < 1900 || year > 2100 || month < 1 || month > 12 || day < 1 || day > 31) return false;
      const date = new Date(year, month - 1, day);
      return date.getFullYear() === year && (date.getMonth() + 1) === month && date.getDate() === day;
    };

    // 和暦 (令和/平成/昭和/大正/明治, R/H/S/T/M) の変換 (区切り文字必須)
    const eraMatch = str.match(/^(令和|平成|昭和|大正|明治|[RHSTM])\s*([0-9元]+)[\/年\.\-]\s*([0-9]+)[\/月\.\-]?\s*([0-9]+)日?$/i);
    if (eraMatch) {
      const era = eraMatch[1].toUpperCase();
      let eraYear = eraMatch[2] === '元' ? 1 : parseInt(eraMatch[2], 10);
      const month = parseInt(eraMatch[3], 10);
      const day = parseInt(eraMatch[4], 10);
      let baseYear = 1988;
      if (era === '令和' || era === 'R') baseYear = 2018;
      else if (era === '平成' || era === 'H') baseYear = 1988;
      else if (era === '昭和' || era === 'S') baseYear = 1925;
      else if (era === '大正' || era === 'T') baseYear = 1911;
      else if (era === '明治' || era === 'M') baseYear = 1867;

      const fullYear = baseYear + eraYear;
      if (isValidCalendarDate(fullYear, month, day)) {
        return `${fullYear}/${String(month).padStart(2, '0')}/${String(day).padStart(2, '0')}`;
      }
    }

    // 漢字区切り (1990年1月1日)
    const kanjiMatch = str.match(/^(\d{4})年\s*(\d{1,2})月\s*(\d{1,2})日?$/);
    if (kanjiMatch) {
      const y = kanjiMatch[1];
      const m = kanjiMatch[2];
      const d = kanjiMatch[3];
      if (isValidCalendarDate(y, m, d)) {
        return `${y}/${String(m).padStart(2, '0')}/${String(d).padStart(2, '0')}`;
      }
    }

    // 記号区切り (1990/1/1, 1990-1-1, 1990.1.1)
    const splitMatch = str.match(/^(\d{4})[\/\-\.](\d{1,2})[\/\-\.](\d{1,2})$/);
    if (splitMatch) {
      const y = splitMatch[1];
      const m = splitMatch[2];
      const d = splitMatch[3];
      if (isValidCalendarDate(y, m, d)) {
        return `${y}/${String(m).padStart(2, '0')}/${String(d).padStart(2, '0')}`;
      }
    }

    // 連続数字は厳格に【8桁 (YYYYMMDD)】のみ許可 (6桁 199111 や 7桁 1990111 など曖昧なものは変換せず除外)
    const num8Match = str.match(/^(\d{4})(\d{2})(\d{2})$/);
    if (num8Match) {
      const y = num8Match[1];
      const m = num8Match[2];
      const d = num8Match[3];
      if (isValidCalendarDate(y, m, d)) {
        return `${y}/${m}/${d}`;
      }
    }

    // 曖昧な連続数字（6桁や7桁など）や不完全な形式は絶対に推測変換せず弾く
    return null;
  };

  // 📱 電話番号の自動変換・正規化関数
  const parseAndFormatPhone = (input) => {
    if (!input) return '';
    let str = input.trim();
    // 全角数字を半角に変換
    str = str.replace(/[０-９]/g, s => String.fromCharCode(s.charCodeAt(0) - 0xFEE0));
    // ハイフンやカッコ、スペースを除去
    str = str.replace(/[-\s\(\)ー－]/g, '');
    return str;
  };

  // 入力フィールドの blur 時に自動変換を適用＆カレンダーピッカー同期
  const birthdayInputEl = document.getElementById('set-pwd-birthday');
  const birthdayPickerEl = document.getElementById('set-pwd-birthday-picker');
  const birthdayCalBtnEl = document.getElementById('set-pwd-birthday-cal-btn');

  if (birthdayInputEl) {
    birthdayInputEl.addEventListener('blur', () => {
      const formatted = parseAndFormatBirthday(birthdayInputEl.value);
      if (formatted) {
        birthdayInputEl.value = formatted;
        if (birthdayPickerEl) {
          try { birthdayPickerEl.value = formatted.replace(/\//g, '-'); } catch (e) {}
        }
      }
    });
  }

  if (birthdayPickerEl && birthdayInputEl) {
    birthdayPickerEl.addEventListener('change', () => {
      if (birthdayPickerEl.value) {
        const [y, m, d] = birthdayPickerEl.value.split('-');
        birthdayInputEl.value = `${y}/${m}/${d}`;
      }
    });

    if (birthdayCalBtnEl) {
      birthdayCalBtnEl.style.pointerEvents = 'auto';
      birthdayCalBtnEl.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (typeof birthdayPickerEl.showPicker === 'function') {
          birthdayPickerEl.showPicker();
        } else {
          birthdayPickerEl.click();
        }
      });
    }
  }

  const phoneInputEl = document.getElementById('set-pwd-phone');
  if (phoneInputEl) {
    phoneInputEl.addEventListener('blur', () => {
      const normalized = parseAndFormatPhone(phoneInputEl.value);
      if (normalized) {
        phoneInputEl.value = normalized;
      }
    });
  }

  if (setPwdSubmit && setPwdModal) {
    setPwdSubmit.addEventListener('click', async () => {
      const email = document.getElementById('set-pwd-email').value;
      const lastName = document.getElementById('set-pwd-lastname') ? document.getElementById('set-pwd-lastname').value.trim() : '';
      const firstName = document.getElementById('set-pwd-firstname') ? document.getElementById('set-pwd-firstname').value.trim() : '';
      const birthday = document.getElementById('set-pwd-birthday') ? document.getElementById('set-pwd-birthday').value.trim() : '';
      const gender = document.getElementById('set-pwd-gender') ? document.getElementById('set-pwd-gender').value : '';
      const loginId = document.getElementById('set-pwd-loginid') ? document.getElementById('set-pwd-loginid').value.trim() : '';
      const phone = document.getElementById('set-pwd-phone') ? document.getElementById('set-pwd-phone').value.trim() : '';
      const pwd = document.getElementById('set-pwd-input').value.trim();
      const pwdConfirm = document.getElementById('set-pwd-confirm-input').value.trim();

      const birthdayInput = document.getElementById('set-pwd-birthday');
      const isRecovery = birthdayInput && birthdayInput.parentElement && birthdayInput.parentElement.parentElement && birthdayInput.parentElement.parentElement.style.display === 'none';

      let resolvedLoginId = loginId;
      let resolvedBirthday = birthday;
      let resolvedPhone = phone;
      let resolvedFullName = (lastName && firstName) ? `${lastName} ${firstName}` : '';

      if (isRecovery) {
        // パスワードバリデーションのみ実行 (8文字以上、大・小・数字必須)
        if (!pwd) {
          showToast('パスワードを入力してください。', 'error');
          return;
        }
        if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[a-zA-Z0-9]{8,}$/.test(pwd)) {
          showToast('パスワードは半角英数字8文字以上で、大文字、小文字、数字をすべて含めてください。', 'error');
          return;
        }
        if (pwd !== pwdConfirm) {
          showToast('パスワードと確認用パスワードが一致しません。', 'error');
          return;
        }

        showToast('パスワード再設定中...', 'info');

        if (!supabaseClient) {
          showToast('Supabase接続が有効ではありません。', 'error');
          return;
        }

        // 既存のユーザー情報をDBから取得してマージする
        const { data: existingUser } = await supabaseClient
          .from('synapse_users')
          .select('name, login_id, birthday, phone_number, gender')
          .eq('id', email)
          .maybeSingle();
        
        if (existingUser) {
          resolvedFullName = existingUser.name || email;
          resolvedLoginId = existingUser.login_id || '';
          resolvedBirthday = existingUser.birthday || '';
          resolvedPhone = existingUser.phone_number || '';
        }
      } else {
        // 0. 姓名バリデーション
        if (!lastName || !firstName) {
          showToast('姓と名を入力してください。', 'error');
          return;
        }
        resolvedFullName = `${lastName} ${firstName}`;

        // 1. 生年月日バリデーション (自動変換)
        const formattedBirthday = parseAndFormatBirthday(birthday);
        if (!formattedBirthday) {
          showToast('有効な生年月日を入力してください（例: 1990/01/01, 19900101, 平成2年1月1日）。', 'error');
          return;
        }
        resolvedBirthday = formattedBirthday;
        if (birthdayInput) birthdayInput.value = formattedBirthday;

        // 2. ログインIDバリデーション
        if (!loginId) {
          showToast('ログインIDを入力してください。', 'error');
          return;
        }
        // 半角英数字6文字以上、大文字不可、記号は-_ .のみ可、記号のみ不可
        if (!/^(?=.*[a-z0-9])[a-z0-9\-_\.]{6,}$/.test(loginId)) {
          showToast('ログインIDは半角英数字（小文字のみ）および記号（-_ .）を含む6文字以上で入力してください（記号のみは不可）。', 'error');
          return;
        }

        // 2.5 電話番号バリデーション (自動正規化)
        const normalizedPhone = parseAndFormatPhone(phone);
        if (!normalizedPhone || !/^0\d{9,10}$/.test(normalizedPhone)) {
          showToast('有効な電話番号（例: 090-1234-5678）を入力してください。', 'error');
          return;
        }
        resolvedPhone = normalizedPhone;
        const phoneInputField = document.getElementById('set-pwd-phone');
        if (phoneInputField) phoneInputField.value = normalizedPhone;

        // 3. パスワードバリデーション
        if (!pwd) {
          showToast('パスワードを入力してください。', 'error');
          return;
        }
        // 半角英数字8文字以上、大文字、小文字、数字すべて必須
        if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[a-zA-Z0-9]{8,}$/.test(pwd)) {
          showToast('パスワードは半角英数字8文字以上で、大文字、小文字、数字をすべて含めてください。', 'error');
          return;
        }

        if (pwd !== pwdConfirm) {
          showToast('パスワードと確認用パスワードが一致しません。', 'error');
          return;
        }

        showToast('本登録処理中...', 'info');

        if (!supabaseClient) {
          showToast('Supabase接続が有効ではありません。', 'error');
          return;
        }

        // 4. 重複チェック：同じログインIDが既に登録されていないか？
        const { data: duplicateUser, error: dupError } = await supabaseClient
          .from('synapse_users')
          .select('id')
          .eq('login_id', loginId)
          .maybeSingle();

        if (dupError) {
          console.error('[Supabase DB] Duplicate login ID check failed:', dupError);
        }
        if (duplicateUser && duplicateUser.id !== email) {
          showToast('入力されたログインIDは既に登録されています。別のログインIDを使用してください。', 'error');
          return;
        }
      }

      // 5. Supabase Auth でパスワードを更新し、メタデータを更新
      const updateData = { needs_password_setup: false };
      if (!isRecovery) {
        updateData.lastName = lastName;
        updateData.firstName = firstName;
        updateData.name = resolvedFullName;
        updateData.gender = gender;
        updateData.birthday = resolvedBirthday;
        updateData.loginId = resolvedLoginId;
        updateData.phone = resolvedPhone;
        updateData.phone_number = resolvedPhone;
      }
      const { data, error } = await supabaseClient.auth.updateUser({
        password: pwd,
        data: updateData
      });

      let user = data ? data.user : null;
      let metadata = user ? (user.user_metadata || {}) : {};

      if (error) {
        console.warn('[Supabase Auth] Password update warning (proceeding with database synchronization):', error);
        user = {
          created_at: new Date().toISOString()
        };
        metadata = {
          name: resolvedFullName || email.split('@')[0],
          lastName: lastName,
          firstName: firstName,
          role: '',
          code: 'TEMP_CODE'
        };
      }

      // 6. synapse_users テーブルにプロフィール情報を同期
      let dbError = null;
      const isLocalEnv = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1' || window.location.protocol === 'file:';

      if (isLocalEnv) {
        console.warn('[Supabase DB] Simulating profile upsert in local/file environment.');
      } else {
        const payload = {
          id: email,
          name: resolvedFullName || metadata.name || email,
          password: pwd,
          role: metadata.role || 'sales',
          email: email,
          code: metadata.code || '',
          login_id: resolvedLoginId,
          birthday: resolvedBirthday,
          phone_number: resolvedPhone,
          created_at: (user && user.created_at) ? user.created_at : new Date().toISOString(),
          last_login_at: new Date().toISOString(),
          pwd_changed_at: new Date().toISOString()
        };

        if (gender) {
          payload.gender = gender;
        }

        let res = await supabaseClient.from('synapse_users').upsert(payload);
        if (res.error && res.error.message && res.error.message.includes('gender')) {
          console.warn('[Supabase DB] gender column does not exist in synapse_users. Retrying without gender column.');
          delete payload.gender;
          res = await supabaseClient.from('synapse_users').upsert(payload);
        }
        dbError = res.error;
      }

      if (dbError) {
        console.error('[Supabase DB] Profile upsert failed:', dbError);
        showToast('同期に失敗しました: ' + dbError.message, 'error');
        return;
      }

      // 7. ローカルの currentUser 情報を同期
      state.currentUser = {
        id: email,
        role: metadata.role || '',
        name: resolvedFullName || metadata.name || email,
        lastName: lastName,
        firstName: firstName,
        gender: gender,
        birthday: resolvedBirthday,
        loginId: resolvedLoginId,
        password: pwd,
        code: metadata.code || '',
        phone_number: resolvedPhone
      };
      localStorage.setItem(STORAGE_KEYS.LOGGED_USER, JSON.stringify(state.currentUser));

      // 7.5 新規登録された端末（1台目）を自動的に信頼されたデバイスとして登録
      try {
        const deviceToken = crypto.randomUUID ? crypto.randomUUID() : (Math.random().toString(36).substring(2, 15) + '-' + Math.random().toString(36).substring(2, 15));
        const deviceName = getDeviceName();
        const deviceType = getDeviceType();
        
        let devError = null;
        if (isLocalEnv) {
          console.warn('[Device Auth] Simulating auto-registration of first device in local/file environment.');
        } else {
          const { error } = await supabaseClient.from('synapse_user_devices').insert({
            user_id: email,
            device_token: deviceToken,
            device_name: deviceName,
            device_type: deviceType,
            last_used_at: new Date().toISOString(),
            created_at: new Date().toISOString()
          });
          devError = error;
        }

        if (!devError) {
          localStorage.setItem('synapse_device_token', deviceToken);
          console.log('[Device Auth] Auto-registered first device:', deviceName);
        } else {
          console.error('[Device Auth] Failed to auto-register first device:', devError);
        }
      } catch (err) {
        console.error('[Device Auth] Auto-register error:', err);
      }

      // システム状態の初期化
      initDatabase();
      renderJoInfo();
      renderJoColumnSelector();

      const nameEl = document.getElementById('logged-in-user-name');
      const avatarEl = document.getElementById('logged-in-user-avatar');
      if (nameEl) nameEl.textContent = state.currentUser.name;
      if (avatarEl) avatarEl.textContent = state.currentUser.name.charAt(0);

      state.tabs = [];
      state.activeTabId = null;

      const sidebarEl = document.getElementById('app-sidebar');
      const toggleBtn = document.getElementById('sidebar-toggle-btn');
      if (sidebarEl) sidebarEl.classList.remove('collapsed');
      if (toggleBtn) {
        toggleBtn.textContent = '‹';
        toggleBtn.title = 'サイドバーを折りたたむ';
      }

      updateUIForCurrentMode();
      removeRestrictedTabsForRole(state.currentUser.role);

      setPwdModal.style.display = 'none';
      if (signupScreen) {
        signupScreen.style.display = 'none';
        signupScreen.classList.remove('active');
      }

      showToast('パスワードを設定し、本登録が完了しました。', 'success');

      if (!state.currentUser.role) {
        if (typeof showBusinessRoleSelectionModal === 'function') {
          showBusinessRoleSelectionModal(state.currentUser);
        } else {
          showLoginScreen(false);
          switchView('mypage-screen');
          openMyPage();
        }
      } else {
        showLoginScreen(false);
        switchView('mypage-screen');
        openMyPage();
      }
    });
  }
}

// ==========================================
// ユーザーアカウント管理（システム管理者専用）
// ==========================================
function initUserManagerEvents() {
  const panelBtn = document.getElementById('admin-panel-user-register-btn');
  const form = document.getElementById('tab-user-register-form');
  const generateBtn = document.getElementById('tab-reg-password-generate-btn');
  // パスワード変更リマインダー即時実行
  const reminderRunBtn = document.getElementById('user-pwd-reminder-run-btn');

  // 管理者パネルボタンからタブを開く
  if (panelBtn) {
    panelBtn.addEventListener('click', () => {
      if (!checkAdminIconAccess('admin-panel-user-register-btn')) {
        showToast('この機能を利用する権限がありません。', 'error');
        return;
      }
      const searchInputEl = document.getElementById('tab-user-search-input');
      if (searchInputEl) searchInputEl.value = '';
      const filterRoleEl = document.getElementById('tab-user-filter-role');
      if (filterRoleEl) filterRoleEl.value = 'all';
      const sortDateEl = document.getElementById('tab-user-sort-date');
      if (sortDateEl) sortDateEl.value = 'desc';

      openTab('user-manager-screen', 'user-manager-screen', '👥 ユーザー登録・管理');
      renderUserManagerList();
    });
  }

  // パスワード自動生成 (6文字以上、大・小・数字それぞれ1字以上、記号なし)
  if (generateBtn) {
    generateBtn.addEventListener('click', () => {
      const uppers = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
      const lowers = 'abcdefghijklmnopqrstuvwxyz';
      const numbers = '0123456789';
      
      // 最低1文字ずつ含める
      let pwd = '';
      pwd += uppers.charAt(Math.floor(Math.random() * uppers.length));
      pwd += lowers.charAt(Math.floor(Math.random() * lowers.length));
      pwd += numbers.charAt(Math.floor(Math.random() * numbers.length));
      
      // 残りをランダムに埋めて10文字にする
      const allChars = uppers + lowers + numbers;
      for (let i = 0; i < 7; i++) {
        pwd += allChars.charAt(Math.floor(Math.random() * allChars.length));
      }
      
      // シャッフル
      pwd = pwd.split('').sort(() => 0.5 - Math.random()).join('');

      const pwdInput = document.getElementById('tab-reg-user-password');
      const pwdConfirmInput = document.getElementById('tab-reg-user-password-confirm');
      if (pwdInput) pwdInput.value = pwd;
      if (pwdConfirmInput) pwdConfirmInput.value = pwd;
      
      showToast('ルール適合パスワードを自動生成しました。', 'success');
    });
  }

  // パスワード変更リマインダー即時実行
  if (reminderRunBtn) {
    reminderRunBtn.addEventListener('click', () => {
      const toggle = document.getElementById('user-pwd-reminder-toggle');
      if (toggle && !toggle.checked) {
        showToast('リマインダー自動送信設定がOFFのため、実行できません。', 'error');
        return;
      }

      ensureInitialUsersExist();
      const users = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS)) || [];
      const halfYearMs = 180 * 24 * 60 * 60 * 1000;
      const now = Date.now();
      let sentCount = 0;

      users.forEach(user => {
        const changedTime = user.pwdChangedAt ? new Date(user.pwdChangedAt).getTime() : new Date(user.createdAt || '2025-01-01').getTime();
        if (now - changedTime >= halfYearMs) {
          sentCount++;
          // モックメール送信演出＆操作ログ記録
          addAuditLog(`SYSTEM`, `USER_PWD_REMINDER`, `ユーザー「${user.name} (ID: ${user.id})」宛てにパスワード期限リマインダーメールを自動シミュレート送信しました。`);
          showToast(`📧 ${user.name} 様へパスワード変更促しメールを送信しました。`, 'info');
        }
      });

      if (sentCount > 0) {
        showToast(`パスワード期限切れの ${sentCount} 名にリマインダーメールを送信しました。`, 'success');
      } else {
        showToast('現在、パスワード変更期限（半年）を迎えている登録ユーザーはいません。', 'success');
      }
    });
  }

  if (form) {
    const newForm = form.cloneNode(true);
    form.parentNode.replaceChild(newForm, form);

    newForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const regLastName = document.getElementById('tab-reg-user-lastname').value.trim();
      const regFirstName = document.getElementById('tab-reg-user-firstname').value.trim();
      const regEmail = document.getElementById('tab-reg-user-email').value.trim();
      const regId = regEmail; // ユーザー名は不要で、メールアドレスをそのままログインID（id）とする
      const regPassword = document.getElementById('tab-reg-user-password').value.trim();
      const regPasswordConfirm = document.getElementById('tab-reg-user-password-confirm').value.trim();

      if (!regLastName || !regFirstName) {
        showToast('姓と名を入力してください。', 'error');
        return;
      }

      if (!regEmail) {
        showToast('メールアドレスを入力してください。', 'error');
        return;
      }

      // パスワードバリデーション: 英大文字・英小文字・数字必須、記号不可、6文字以上
      if (!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[a-zA-Z0-9]{6,}$/.test(regPassword)) {
        showToast('パスワードは6文字以上で、英大文字、英小文字、数字をそれぞれ1文字以上組み合わせてください（記号不可）。', 'error');
        return;
      }

      if (regPassword !== regPasswordConfirm) {
        showToast('パスワードと確認用パスワードが一致しません。', 'error');
        return;
      }

      showToast('ユーザー登録中...', 'info');

      if (!supabaseClient) {
        showToast('Supabase接続が有効ではありません。', 'error');
        return;
      }

      const regFullName = `${regLastName} ${regFirstName}`;
      const nowIso = new Date().toISOString();
      const userCode = generate8DigitId(); // 一意のユーザーコードを生成

      // 1. Supabase の synapse_users テーブルに直接挿入する（管理者権限による先行登録）
      const { error: dbError } = await supabaseClient.from('synapse_users').upsert({
        id: regId,
        name: regFullName,
        password: regPassword,
        role: 'sales', // 初期割り当てロール（必要に応じて変更可能）
        email: regEmail,
        code: userCode,
        created_at: nowIso
      });

      if (dbError) {
        console.error('[Supabase DB] Failed to pre-register user:', dbError);
        showToast('ユーザー登録に失敗しました: ' + dbError.message, 'error');
        return;
      }

      // 2. クラウドデータを再同期してUIを最新化
      await syncFromSupabase(false);
      window._presenceUsersFetched = false;
      if (typeof window.initPresenceUserSelector === 'function') {
        window.initPresenceUserSelector();
      }

      showToast(`ユーザー「${regFullName}」を正常に登録しました。`, 'success');
      newForm.reset();
      
      const searchInputEl = document.getElementById('tab-user-search-input');
      if (searchInputEl) searchInputEl.value = '';
      const filterRoleEl = document.getElementById('tab-user-filter-role');
      if (filterRoleEl) filterRoleEl.value = 'all';
      const sortDateEl = document.getElementById('tab-user-sort-date');
      if (sortDateEl) sortDateEl.value = 'desc';

      renderUserManagerList();
    });
  }

  const filterRole = document.getElementById('tab-user-filter-role');
  const sortDate = document.getElementById('tab-user-sort-date');
  const searchInput = document.getElementById('tab-user-search-input');
  if (filterRole) {
    filterRole.addEventListener('change', () => renderUserManagerList());
  }
  if (sortDate) {
    sortDate.addEventListener('change', () => renderUserManagerList());
  }
  if (searchInput) {
    searchInput.addEventListener('input', () => renderUserManagerList());
  }
}

function renderUserManagerList() {
  const container = document.getElementById('tab-user-list-container');
  const countBadge = document.getElementById('tab-user-count-badge');
  if (!container) return;

  ensureInitialUsersExist();
  let users = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS)) || [];

  // ロールフィルター適用
  const filterRoleEl = document.getElementById('tab-user-filter-role');
  const selectedRole = filterRoleEl ? filterRoleEl.value : 'all';
  if (selectedRole !== 'all') {
    users = users.filter(u => u.role === selectedRole);
  }

  // 検索入力フィルター適用（名前、ID、コード、メールアドレスを対象に部分一致）
  const searchInputEl = document.getElementById('tab-user-search-input');
  const searchQuery = searchInputEl ? searchInputEl.value.trim().toLowerCase() : '';
  if (searchQuery !== '') {
    users = users.filter(u => {
      const name = (u.name || '').toLowerCase();
      const id = (u.id || '').toLowerCase();
      const code = (u.code || '').toLowerCase();
      const email = (u.email || '').toLowerCase();
      return name.includes(searchQuery) || id.includes(searchQuery) || code.includes(searchQuery) || email.includes(searchQuery);
    });
  }

  // 登録日ソート適用
  const sortDateEl = document.getElementById('tab-user-sort-date');
  const selectedSort = sortDateEl ? sortDateEl.value : 'desc';
  users.sort((a, b) => {
    const timeA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
    const timeB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
    if (selectedSort === 'asc') {
      return timeA - timeB; // 古い順 (昇順)
    } else {
      return timeB - timeA; // 新しい順 (降順)
    }
  });

  if (countBadge) countBadge.textContent = `${users.length}件`;

  container.innerHTML = '';

  if (users.length === 0) {
    container.innerHTML = `<div style="text-align: center; color: var(--text-muted); font-size: 0.8rem; padding: 1.5rem 0;">該当する登録アカウントはありません。</div>`;
    return;
  }

  const ninetyDaysMs = 90 * 24 * 60 * 60 * 1000;
  const now = Date.now();

  users.forEach(user => {
    const card = document.createElement('div');
    card.style.cssText = 'display: flex; justify-content: space-between; align-items: center; padding: 0.35rem 0.65rem; border: 1px solid var(--border-color); border-radius: var(--radius-sm); background: var(--bg-surface); transition: background-color 0.2s; flex-wrap: wrap; gap: 0.35rem;';
    
    // ロールごとのバッジ
    let roleBadgeColor = 'var(--text-muted)';
    let roleLabel = getRoleJpName(user.role);
    if (user.role === 'owner' || user.role === 'admin') {
      roleBadgeColor = '#8b5cf6'; // オーナーは高級感ある紫
    } else if (user.role === 'sales') {
      roleBadgeColor = 'var(--primary)'; // 営業はプライマリブルー
    } else if (user.role === 'setup-support' || user.role === 'support') {
      roleBadgeColor = 'var(--secondary)'; // サポートはセカンダリグリーン
    } else if (user.role === 'store-patrol') {
      roleBadgeColor = '#f59e0b'; // 店舗パトロールはオレンジ
    } else if (user.role === 'back-office') {
      roleBadgeColor = '#10b981'; // バックオフィスはエメラルドグリーン
    }

    // 最終ログインから3ヶ月(90日)経過しているか検知
    const lastLoginTime = user.lastLoginAt ? new Date(user.lastLoginAt).getTime() : 0;
    const isInactive = (now - lastLoginTime) >= ninetyDaysMs;

    const info = document.createElement('div');
    info.style.cssText = 'display: flex; flex-direction: column; gap: 0.1rem; flex: 1; min-width: 200px;';
    
    let lastLoginStr = '未ログイン';
    if (user.lastLoginAt) {
      const d = new Date(user.lastLoginAt);
      lastLoginStr = `${d.getFullYear()}/${d.getMonth()+1}/${d.getDate()} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
    }

    info.innerHTML = `
      <div style="display: flex; align-items: center; gap: 0.35rem; font-size: 0.8rem; font-weight: 700; color: var(--text-primary); flex-wrap: wrap;">
        <span>${user.name}</span>
        <span style="font-size: 0.62rem; font-weight: 600; padding: 0.02rem 0.25rem; border-radius: var(--radius-sm); color: #ffffff; background: ${roleBadgeColor};">${roleLabel}</span>
        ${isInactive ? `<span style="font-size: 0.62rem; font-weight: 700; padding: 0.02rem 0.25rem; border-radius: var(--radius-sm); color: #ffffff; background: #eab308; animation: statusPulse 2s infinite;">⚠️ 長期未ログイン (3ヶ月以上)</span>` : ''}
      </div>
      <div style="font-size: 0.68rem; color: var(--text-secondary); display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 0.05rem;">
        <span>コード: <code style="background: var(--bg-surface-elevated); padding: 0.02rem 0.15rem; border-radius: var(--radius-xs); color: var(--text-primary); font-family: monospace;">${user.code || 'N/A'}</code></span>
        <span>ID: <code style="background: var(--bg-surface-elevated); padding: 0.02rem 0.15rem; border-radius: var(--radius-xs); color: var(--text-primary); font-family: monospace;">${user.id}</code></span>
        <span>Pass: <code style="background: var(--bg-surface-elevated); padding: 0.02rem 0.15rem; border-radius: var(--radius-xs); color: var(--text-primary); font-family: monospace;">${user.password}</code></span>
        <span>最終ログイン: <span style="font-weight: 600;">${lastLoginStr}</span></span>
      </div>
    `;

    const action = document.createElement('div');
    action.style.cssText = 'display: flex; align-items: center; gap: 0.4rem;';

    // 3ヶ月以上未ログインの場合に確認メール送信ボタンを配置
    if (isInactive) {
      const emailBtn = document.createElement('button');
      emailBtn.className = 'btn-secondary';
      emailBtn.innerHTML = '📧 確認メール';
      emailBtn.style.cssText = 'font-size: 0.65rem; padding: 0.1rem 0.3rem; font-weight: 600; border-radius: var(--radius-xs); cursor: pointer;';
      emailBtn.addEventListener('click', () => {
        emailBtn.disabled = true;
        emailBtn.innerHTML = '送信中...';
        setTimeout(() => {
          showToast(`📧 「${user.name}」様へ長期間ログインのないことに対する状況確認メールをシミュレート送信しました。`, 'success');
          addAuditLog(`SYSTEM`, `INACTIVE_USER_EMAIL`, `長期未ログインユーザー「${user.name} (ID: ${user.id})」へ確認メールを送信しました。`);
          emailBtn.disabled = false;
          emailBtn.innerHTML = '📧 確認メール';
        }, 1000);
      });
      action.appendChild(emailBtn);
    }

    const delBtn = document.createElement('button');
    delBtn.className = 'btn-text';
    delBtn.innerHTML = '🗑️ 削除';
    delBtn.style.cssText = 'color: #ef4444; font-size: 0.68rem; font-weight: 600; cursor: pointer; border: none; background: none; padding: 0.1rem 0.2rem;';
    
    const isSelf = state.currentUser && state.currentUser.loginId === user.id;
    const isDefaultAdmin = user.id === 'admin';
    if (isSelf || isDefaultAdmin) {
      delBtn.disabled = true;
      delBtn.style.opacity = '0.35';
      delBtn.style.cursor = 'not-allowed';
      delBtn.title = isSelf ? 'ログイン中の自分自身のアカウントは削除できません。' : 'デフォルト管理者アカウントは削除できません。';
    } else {
      delBtn.addEventListener('click', () => {
        showAppConfirm('アカウントの削除', `アカウント「${user.name}（ID: ${user.id}）」を削除しますか？`, async () => {
          if (!supabaseClient) {
            showToast('Supabase接続が有効ではありません。', 'error');
            return;
          }
          showToast('ユーザー削除中...', 'info');
          const { error: dbError } = await supabaseClient
            .from('synapse_users')
            .delete()
            .eq('id', user.id);

          if (dbError) {
            console.error('[Supabase DB] Failed to delete user:', dbError);
            showToast('ユーザーの削除に失敗しました: ' + dbError.message, 'error');
            return;
          }

          // クラウドデータを再同期してUIを最新化
          await syncFromSupabase(false);
          window._presenceUsersFetched = false;
          if (typeof window.initPresenceUserSelector === 'function') {
            window.initPresenceUserSelector();
          }
          showToast(`ユーザー「${user.name}」を削除しました。`, 'success');
          renderUserManagerList();
        });
      });
    }

    // 📱 端末管理ボタンの追加
    const deviceBtn = document.createElement('button');
    deviceBtn.className = 'btn-secondary';
    deviceBtn.innerHTML = '📱 端末';
    deviceBtn.style.cssText = 'font-size: 0.65rem; padding: 0.15rem 0.35rem; font-weight: 600; border-radius: var(--radius-xs); cursor: pointer; border: 1px solid var(--border-color); background: var(--bg-surface); color: var(--text-primary); margin-right: 0.2rem;';
    deviceBtn.addEventListener('click', () => {
      openAdminDeviceModal(user.id);
    });
    action.appendChild(deviceBtn);

    action.appendChild(delBtn);
    card.appendChild(info);
    card.appendChild(action);
    container.appendChild(card);
  });
}

function renderModalFolderTree() {
  const container = document.getElementById('modal-folder-tree-container');
  const rootDropzone = document.getElementById('modal-tree-root-dropzone');
  if (!container) return;

  ensureStandardAccordionsInState();
  ensureStandardTablesInState();
  initContextMenuEvents();

  container.innerHTML = '';

  // 検索フィルターバインド
  const searchInput = document.getElementById('modal-folder-search-input');
  const searchTerm = searchInput ? searchInput.value.trim().toLowerCase() : '';
  if (searchInput && !searchInput.dataset.bound) {
    searchInput.dataset.bound = 'true';
    searchInput.addEventListener('input', () => {
      renderModalFolderTree();
    });
  }

  // 1. ルートドロップゾーンのイベント設定
  if (rootDropzone) {
    rootDropzone.innerHTML = '📥 ここにドラッグ＆ドロップして 🏠 最上位（親フォルダ階層）へ取り出す';
    rootDropzone.addEventListener('dragover', (e) => {
      e.preventDefault();
      rootDropzone.style.borderColor = 'var(--primary)';
      rootDropzone.style.background = 'rgba(var(--primary-rgb), 0.1)';
      rootDropzone.style.color = 'var(--primary)';
    });
    rootDropzone.addEventListener('dragleave', () => {
      rootDropzone.style.borderColor = 'var(--border-color)';
      rootDropzone.style.background = 'var(--bg-surface-elevated)';
      rootDropzone.style.color = 'var(--text-primary)';
    });
    rootDropzone.addEventListener('drop', (e) => {
      e.preventDefault();
      rootDropzone.style.borderColor = 'var(--border-color)';
      rootDropzone.style.background = 'var(--bg-surface-elevated)';
      rootDropzone.style.color = 'var(--text-primary)';

      const dragSourceId = e.dataTransfer.getData('text/plain');
      const dragType = e.dataTransfer.getData('application/cos-type');
      if (!dragSourceId) return;

      if (dragType === 'folder') {
        const acc = state.customAccordions.find(a => a.id === dragSourceId);
        if (acc) {
          acc.parentMenuId = 'root';
          saveCustomAccordions();
          showToast(`フォルダ「${acc.name}」を最上位（親フォルダ階層）に取り出しました。`, 'success');
        }
      } else if (dragType === 'table') {
        const tbl = state.customTables.find(t => t.id === dragSourceId);
        if (tbl) {
          tbl.parentMenuId = 'root';
          saveCustomTables();
          showToast(`「${tbl.name}」を最上位（親フォルダ階層）に取り出しました。`, 'success');
        }
      }

      renderCustomTableList();
      renderModalFolderTree();
    });
  }

  // 2. 再帰的ツリーノードレンダラー (開閉トグル ＋ 右クリックメニュー ＋ 検索フィルタ)
  const renderTreeNode = (parentId, indentLevel, targetContainer) => {
    const targetParentId = normalizeFolderId(parentId);

    // フォルダの抽出
    let childFolders = state.customAccordions.filter(acc => normalizeFolderId(acc.parentMenuId || 'root') === targetParentId);
    
    childFolders.forEach(acc => {
      // 検索一致判定（子要素に検索語が含まれるかも含む）
      if (searchTerm && !acc.name.toLowerCase().includes(searchTerm)) {
        const hasMatchingChild = state.customTables.some(t => normalizeFolderId(t.parentMenuId) === acc.id && t.name.toLowerCase().includes(searchTerm)) ||
                                 state.customAccordions.some(a => normalizeFolderId(a.parentMenuId) === acc.id && a.name.toLowerCase().includes(searchTerm));
        if (!hasMatchingChild) return;
      }

      const folderNode = document.createElement('div');
      folderNode.className = 'tree-node-item';
      folderNode.style.marginLeft = `${indentLevel * 1.1}rem`;
      folderNode.style.padding = '0.35rem 0.6rem';
      folderNode.style.margin = '0.2rem 0';
      folderNode.style.borderRadius = 'var(--radius-sm)';
      folderNode.style.border = '1px solid var(--border-color)';
      folderNode.style.background = 'var(--bg-surface)';
      folderNode.style.cursor = 'grab';
      folderNode.style.display = 'flex';
      folderNode.style.alignItems = 'center';
      folderNode.style.gap = '0.4rem';
      folderNode.style.fontSize = '0.83rem';
      folderNode.style.fontWeight = '600';
      folderNode.style.transition = 'all 0.15s ease';
      
      // 開閉トグル矢印ボタン (検索語がある時以外は初期は親フォルダのみ見せて配下は閉じる ▶)
      const toggleArrow = document.createElement('span');
      toggleArrow.textContent = searchTerm ? '▼' : '▶';
      toggleArrow.style.cssText = 'cursor: pointer; font-size: 0.65rem; color: var(--text-muted); width: 14px; text-align: center; display: inline-block; user-select: none;';
      
      // サイドバーと完全に同期したカスタムアイコン（デフォルト: 🎯, 📑, 💼, 📅, 📁等）を取得
      const defaultFolderIcon = acc.id === 'appoint-accordion' ? '📅' :
                                acc.id === 'agency-accordion' ? '💼' :
                                acc.id === 'jo-accordion' ? '📑' :
                                acc.id === 'applicant-accordion' ? '🎯' : '📁';
      const folderIconHtml = getUserItemIconHtml(acc.id, defaultFolderIcon);

      const folderLabel = document.createElement('span');
      folderLabel.innerHTML = `${folderIconHtml} <span>${acc.name}</span>`;
      folderLabel.style.cursor = 'pointer';
      folderLabel.style.display = 'flex';
      folderLabel.style.alignItems = 'center';
      folderLabel.style.gap = '0.35rem';

      folderNode.appendChild(toggleArrow);
      folderNode.appendChild(folderLabel);

      // 右クリック（コンテキスト）メニュー
      folderNode.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        e.stopPropagation();
        showContextMenu(e.clientX, e.clientY, 'folder', acc);
      });

      // ドラッグ属性
      folderNode.draggable = true;
      folderNode.addEventListener('dragstart', (e) => {
        e.stopPropagation();
        e.dataTransfer.setData('text/plain', acc.id);
        e.dataTransfer.setData('application/cos-type', 'folder');
        folderNode.style.opacity = '0.5';
      });
      folderNode.addEventListener('dragend', () => {
        folderNode.style.opacity = '1';
      });

      // ドロップゾーン（フォルダの上にドロップして配属する）
      folderNode.addEventListener('dragover', (e) => {
        e.preventDefault();
        e.stopPropagation();

        const dragSourceId = e.dataTransfer.getData('text/plain');
        const dragType = e.dataTransfer.getData('application/cos-type');
        
        if (dragSourceId === acc.id) return;
        
        if (dragType === 'folder') {
          const isDescendant = (parentAccId, childAccId) => {
            let current = state.customAccordions.find(a => a.id === childAccId);
            while (current) {
              if (current.parentMenuId === parentAccId) return true;
              current = state.customAccordions.find(a => a.id === current.parentMenuId);
            }
            return false;
          };
          if (isDescendant(dragSourceId, acc.id)) return;
        }

        folderNode.style.background = 'rgba(var(--primary-rgb), 0.15)';
        folderNode.style.borderColor = 'var(--primary)';
      });
      folderNode.addEventListener('dragleave', () => {
        folderNode.style.background = 'var(--bg-surface)';
        folderNode.style.borderColor = 'var(--border-color)';
      });
      folderNode.addEventListener('drop', (e) => {
        e.preventDefault();
        e.stopPropagation();
        folderNode.style.background = 'var(--bg-surface)';
        folderNode.style.borderColor = 'var(--border-color)';

        const dragSourceId = e.dataTransfer.getData('text/plain');
        const dragType = e.dataTransfer.getData('application/cos-type');
        
        if (!dragSourceId || dragSourceId === acc.id) return;

        if (dragType === 'folder') {
          const srcAcc = state.customAccordions.find(a => a.id === dragSourceId);
          if (srcAcc) {
            srcAcc.parentMenuId = acc.id;
            saveCustomAccordions();
            showToast(`フォルダ「${srcAcc.name}」を「${acc.name}」配下に配置しました。`, 'success');
          }
        } else if (dragType === 'table') {
          const srcTbl = state.customTables.find(t => t.id === dragSourceId);
          if (srcTbl) {
            srcTbl.parentMenuId = acc.id;
            saveCustomTables();
            showToast(`「${srcTbl.name}」を「${acc.name}」配下に配置しました。`, 'success');
          }
        }

        renderCustomTableList();
        renderModalFolderTree();
      });

      targetContainer.appendChild(folderNode);

      // 配下の子要素を格納するコンテナ (検索語がある時以外は初期状態は非表示 none で親のみ表示)
      const childContainer = document.createElement('div');
      childContainer.className = 'modal-tree-child-container';
      childContainer.style.display = searchTerm ? 'block' : 'none';
      targetContainer.appendChild(childContainer);

      // 開閉クリックイベントの設定
      const toggleExpand = (e) => {
        if (e) e.stopPropagation();
        const isHidden = childContainer.style.display === 'none';
        childContainer.style.display = isHidden ? 'block' : 'none';
        toggleArrow.textContent = isHidden ? '▼' : '▶';
      };

      toggleArrow.addEventListener('click', toggleExpand);
      folderLabel.addEventListener('click', toggleExpand);

      // 子要素（子フォルダ・所属テーブル・サブメニュー項目）を再帰的描画
      renderTreeNode(acc.id, indentLevel + 1, childContainer);
    });

    // 所属テーブル・サブメニュー項目の抽出
    let childTables = state.customTables.filter(t => normalizeFolderId(t.parentMenuId || 'root') === targetParentId);

    childTables.forEach(tbl => {
      if (searchTerm && !tbl.name.toLowerCase().includes(searchTerm)) return;

      const tableNode = document.createElement('div');
      tableNode.className = 'tree-node-item';
      tableNode.style.marginLeft = `${indentLevel * 1.1}rem`;
      tableNode.style.padding = '0.3rem 0.5rem';
      tableNode.style.margin = '0.15rem 0';
      tableNode.style.borderRadius = 'var(--radius-sm)';
      tableNode.style.border = '1px solid rgba(var(--border-color-rgb), 0.6)';
      tableNode.style.background = 'var(--bg-surface)';
      tableNode.style.cursor = 'grab';
      tableNode.style.display = 'flex';
      tableNode.style.alignItems = 'center';
      tableNode.style.gap = '0.35rem';
      tableNode.style.fontSize = '0.8rem';
      tableNode.style.transition = 'all 0.15s ease';
      
      // サイドバーおよびテーブル一覧と同期したカスタムアイコンを取得
      const isSub = ['appointment-new', 'appointment-existing', 'drafts-view-screen', 'history-view-screen', 'official-id-link'].includes(tbl.id);
      const defaultTableIcon = isSub ? '📝' : '📊';
      const tableIconHtml = getUserItemIconHtml(tbl.id, defaultTableIcon);

      tableNode.innerHTML = `${tableIconHtml} <span>${tbl.name}</span>`;

      // 右クリック（コンテキスト）メニュー
      tableNode.addEventListener('contextmenu', (e) => {
        e.preventDefault();
        e.stopPropagation();
        showContextMenu(e.clientX, e.clientY, 'item', tbl);
      });

      // テーブルはドラッグのみ可能
      tableNode.draggable = true;
      tableNode.addEventListener('dragstart', (e) => {
        e.stopPropagation();
        e.dataTransfer.setData('text/plain', tbl.id);
        e.dataTransfer.setData('application/cos-type', 'table');
        tableNode.style.opacity = '0.5';
      });
      tableNode.addEventListener('dragend', () => {
        tableNode.style.opacity = '1';
      });

      targetContainer.appendChild(tableNode);
    });
  };

  // ルートからツリー構築を開始
  renderTreeNode('root', 0, container);
}

function renderPermissionTree() {
  const treeContainer = document.getElementById('permission-tree');
  if (!treeContainer) return;
  treeContainer.innerHTML = '';

  const createTreeItem = (label, type, targetId, children = [], extra = {}) => {
    const item = document.createElement('div');
    item.className = 'tree-item';
    item.style.paddingLeft = '0.75rem';
    item.style.marginTop = '0.25rem';

    const header = document.createElement('div');
    header.className = 'tree-header';
    header.style.display = 'flex';
    header.style.alignItems = 'center';
    header.style.cursor = 'pointer';
    header.style.padding = '0.3rem 0.5rem';
    header.style.borderRadius = 'var(--radius-sm)';
    header.style.fontSize = '0.85rem';
    header.style.color = 'var(--text-secondary)';
    header.style.transition = 'background 0.2s';
    
    header.addEventListener('mouseenter', () => header.style.background = 'var(--bg-surface-elevated)');
    header.addEventListener('mouseleave', () => {
      if (state.activePermissionTarget?.targetId !== targetId) {
        header.style.background = 'none';
      }
    });

    header.addEventListener('click', () => {
      treeContainer.querySelectorAll('.tree-header').forEach(h => {
        h.style.background = 'none';
        h.style.color = 'var(--text-secondary)';
      });
      header.style.background = 'rgba(26, 115, 232, 0.15)';
      header.style.color = 'var(--primary)';

      state.activePermissionTarget = { type, targetId, label, extra };
      
      if (type === 'folder') {
        switchPermissionTab('folder-tab');
      } else if (type === 'table') {
        switchPermissionTab('table-tab');
      } else if (type === 'column') {
        switchPermissionTab('column-tab');
      }
      renderPermissionSettingsDetails();
    });

    const icon = document.createElement('span');
    icon.style.marginRight = '0.4rem';
    if (type === 'folder') icon.textContent = '📁';
    else if (type === 'table') icon.textContent = '📋';
    else if (type === 'column') icon.textContent = '🧱';
    header.appendChild(icon);

    const span = document.createElement('span');
    span.textContent = label;
    header.appendChild(span);
    item.appendChild(header);

    if (children.length > 0) {
      const childContainer = document.createElement('div');
      childContainer.className = 'tree-children';
      childContainer.style.paddingLeft = '0.75rem';
      childContainer.style.borderLeft = '1px dashed var(--border-color)';
      childContainer.style.marginLeft = '0.6rem';
      children.forEach(child => childContainer.appendChild(child));
      item.appendChild(childContainer);
    }

    return item;
  };

  const folders = [
    {
      id: 'appoint-accordion',
      name: 'アポイント情報',
      tables: []
    },
    {
      id: 'agency-accordion',
      name: '代理店情報',
      tables: [
        { id: 'agency-info-screen', name: '📊 基本マスタ', columns: state.agColumns }
      ]
    },
    {
      id: 'jo-accordion',
      name: 'JO情報',
      tables: [
        { id: 'jo-info-screen', name: '📊 基本マスタ', columns: state.joColumns }
      ]
    },
    {
      id: 'applicant-accordion',
      name: '申込者情報',
      tables: [
        { id: 'applicant-info-screen', name: '📊 基本マスタ', columns: state.apColumns }
      ]
    },
  ];

  state.customAccordions.forEach(acc => {
    folders.push({
      id: acc.id,
      name: `カスタムフォルダ: ${getFolderMenuPath(acc.id)}`,
      tables: state.customTables.filter(t => t.parentMenuId === acc.id)
    });
  });

  const rootTables = state.customTables.filter(t => !t.parentMenuId || t.parentMenuId === 'root' || t.parentMenuId === 'custom-tables');
  if (rootTables.length > 0) {
    folders.push({
      id: 'root-folder-pseudo',
      name: 'ルート直下テーブル',
      tables: rootTables
    });
  }

  folders.forEach(f => {
    const tableNodes = [];
    f.tables.forEach(t => {
      const colNodes = [];
      const cols = t.columns || [];
      cols.forEach(c => {
        colNodes.push(createTreeItem(c.label || c.name, 'column', `${t.id}::${c.id}`, [], { tableId: t.id, columnId: c.id }));
      });
      tableNodes.push(createTreeItem(t.name, 'table', t.id, colNodes));
    });
    
    treeContainer.appendChild(createTreeItem(f.name, 'folder', f.id, tableNodes));
  });
}

function switchPermissionTab(tabId) {
  const screen = document.getElementById('permission-settings-screen');
  if (!screen) return;
  screen.querySelectorAll('.tab-btn').forEach(btn => {
    if (btn.dataset.tab === tabId) btn.classList.add('active');
    else btn.classList.remove('active');
  });

  screen.querySelectorAll('.tab-pane').forEach(pane => {
    if (pane.id === tabId) pane.classList.add('active');
    else pane.classList.remove('active');
  });
}

function renderPermissionSettingsDetails() {
  const target = state.activePermissionTarget;
  if (!target) {
    showPermissionEmptyState();
    return;
  }

  if (target.type === 'folder') {
    const pane = document.getElementById('folder-tab');
    pane.innerHTML = `
      <h3>📁 フォルダー閲覧権限設定</h3>
      <p style="color:var(--text-muted); font-size:0.85rem; margin-bottom:1rem;">対象フォルダー: <strong>${target.label}</strong></p>
      <div class="permission-checkbox-list" style="display:flex; flex-direction:column; gap:0.5rem; background:rgba(255,255,255,0.02); padding:1rem; border-radius:var(--radius-sm); border:1px solid var(--border-color);">
        ${ALL_ACCOUNTS.map(acc => {
          const allowed = state.permissions.folders[target.targetId] || [];
          const checked = allowed.includes(acc.id) ? 'checked' : '';
          return `
            <label style="display:flex; align-items:center; gap:0.5rem; cursor:pointer;">
              <input type="checkbox" class="folder-perm-cb" data-user-id="${acc.id}" ${checked}>
              <span>${acc.name}</span>
            </label>
          `;
        }).join('')}
      </div>
      <button class="btn-primary" id="save-folder-perm-btn" style="margin-top:1rem; padding:0.5rem 1rem;">設定を保存</button>
    `;

    document.getElementById('save-folder-perm-btn').addEventListener('click', () => {
      const allowed = [];
      pane.querySelectorAll('.folder-perm-cb').forEach(cb => {
        if (cb.checked) allowed.push(cb.dataset.userId);
      });
      state.permissions.folders[target.targetId] = allowed;
      savePermissions();
      renderCustomTableList();
      showToast('フォルダー権限を保存しました。', 'success');
    });
  }

  if (target.type === 'table') {
    const pane = document.getElementById('table-tab');
    pane.innerHTML = `
      <h3>📋 テーブル閲覧権限設定</h3>
      <p style="color:var(--text-muted); font-size:0.85rem; margin-bottom:1rem;">対象テーブル: <strong>${target.label}</strong></p>
      <div class="permission-checkbox-list" style="display:flex; flex-direction:column; gap:0.5rem; background:rgba(255,255,255,0.02); padding:1rem; border-radius:var(--radius-sm); border:1px solid var(--border-color);">
        ${ALL_ACCOUNTS.map(acc => {
          const allowed = state.permissions.tables[target.targetId] || [];
          const checked = allowed.includes(acc.id) ? 'checked' : '';
          return `
            <label style="display:flex; align-items:center; gap:0.5rem; cursor:pointer;">
              <input type="checkbox" class="table-perm-cb" data-user-id="${acc.id}" ${checked}>
              <span>${acc.name}</span>
            </label>
          `;
        }).join('')}
      </div>
      <button class="btn-primary" id="save-table-perm-btn" style="margin-top:1rem; padding:0.5rem 1rem;">設定を保存</button>
    `;

    document.getElementById('save-table-perm-btn').addEventListener('click', () => {
      const allowed = [];
      pane.querySelectorAll('.table-perm-cb').forEach(cb => {
        if (cb.checked) allowed.push(cb.dataset.userId);
      });
      state.permissions.tables[target.targetId] = allowed;
      savePermissions();
      renderCustomTableList();
      showToast('テーブル権限を保存しました。', 'success');
    });

    renderRowFilterSettings(target.targetId);
  }

  if (target.type === 'column') {
    const pane = document.getElementById('column-tab');
    const tableId = target.extra.tableId;
    const colId = target.extra.columnId;

    pane.innerHTML = `
      <h3>🧱 カラム閲覧権限設定</h3>
      <p style="color:var(--text-muted); font-size:0.85rem; margin-bottom:1rem;">対象カラム: <strong>${target.label}</strong> (テーブル ID: ${tableId})</p>
      <div class="permission-checkbox-list" style="display:flex; flex-direction:column; gap:0.5rem; background:rgba(255,255,255,0.02); padding:1rem; border-radius:var(--radius-sm); border:1px solid var(--border-color);">
        ${ALL_ACCOUNTS.map(acc => {
          const tableCols = state.permissions.columns[tableId] || {};
          const allowed = tableCols[colId] || [];
          const isSetup = Object.keys(tableCols).includes(colId);
          const checked = (!isSetup || allowed.includes(acc.id)) ? 'checked' : '';
          
          return `
            <label style="display:flex; align-items:center; gap:0.5rem; cursor:pointer;">
              <input type="checkbox" class="col-perm-cb" data-user-id="${acc.id}" ${checked}>
              <span>${acc.name}</span>
            </label>
          `;
        }).join('')}
      </div>
      <button class="btn-primary" id="save-col-perm-btn" style="margin-top:1rem; padding:0.5rem 1rem;">設定を保存</button>
    `;

    document.getElementById('save-col-perm-btn').addEventListener('click', () => {
      const allowed = [];
      pane.querySelectorAll('.col-perm-cb').forEach(cb => {
        if (cb.checked) allowed.push(cb.dataset.userId);
      });
      if (!state.permissions.columns[tableId]) state.permissions.columns[tableId] = {};
      state.permissions.columns[tableId][colId] = allowed;
      savePermissions();
      renderCustomTableList();
      showToast('カラム権限を保存しました。', 'success');
    });
  }
}

function showPermissionEmptyState() {
  const panes = ['folder-tab', 'table-tab', 'column-tab', 'row-filter-tab'];
  panes.forEach(pid => {
    const pane = document.getElementById(pid);
    if (pane) {
      pane.innerHTML = `
        <div style="text-align:center; padding:3rem; color:var(--text-muted);">
          <p style="font-size:1.5rem; margin-bottom:0.5rem;">👈 ターゲット未選択</p>
          <p>左側の権限ツリーから、設定したいフォルダ、テーブル、またはカラムを選択してください。</p>
        </div>
      `;
    }
  });
}

function renderRowFilterSettings(tableId) {
  const pane = document.getElementById('row-filter-tab');
  if (!pane) return;

  let columns = [];
  if (tableId === 'agency-info-screen') columns = state.agColumns;
  else if (tableId === 'jo-info-screen') columns = state.joColumns;
  else if (tableId === 'applicant-info-screen') columns = state.apColumns;
  else {
    const tbl = state.customTables.find(t => t.id === tableId || `custom-table-${t.id}` === tableId);
    if (tbl) columns = tbl.columns;
  }

  pane.innerHTML = `
    <h3>🔍 行表示ワード制限設定（関連ワード制限）</h3>
    <p style="color:var(--text-muted); font-size:0.85rem; margin-bottom:1rem;">対象テーブルに対するユーザーごとの表示抽出フィルタを設定します。</p>
    
    <div id="row-filter-users-accordion" style="display:flex; flex-direction:column; gap:1rem;">
      ${ALL_ACCOUNTS.map(acc => {
        const filterSetting = (state.permissions.rowFilters[tableId] || {})[acc.id] || { matchType: 'OR', rules: [] };
        return `
          <div class="user-filter-card" style="border:1px solid var(--border-color); border-radius:var(--radius-sm); padding:1rem; background:rgba(255,255,255,0.01);">
            <h4 style="margin-bottom:0.75rem; border-bottom:1px solid var(--border-color); padding-bottom:0.25rem; color:var(--text-primary);">${acc.name}</h4>
            
            <div style="display:flex; align-items:center; gap:1rem; margin-bottom:1rem;">
              <span style="font-size:0.85rem;">結合条件:</span>
              <label style="display:inline-flex; align-items:center; gap:0.25rem; cursor:pointer;">
                <input type="radio" name="matchtype-${acc.id}" value="OR" ${filterSetting.matchType === 'OR' ? 'checked' : ''}>
                <span>いずれかに一致 (OR)</span>
              </label>
              <label style="display:inline-flex; align-items:center; gap:0.25rem; cursor:pointer;">
                <input type="radio" name="matchtype-${acc.id}" value="AND" ${filterSetting.matchType === 'AND' ? 'checked' : ''}>
                <span>すべてに一致 (AND)</span>
              </label>
            </div>

            <div class="rules-list" id="rules-list-${acc.id}" style="display:flex; flex-direction:column; gap:0.5rem; margin-bottom:0.75rem;">
            </div>

            <button class="btn-secondary add-rule-row-btn" data-user-id="${acc.id}" style="padding:0.25rem 0.5rem; font-size:0.8rem;">＋ 条件を追加</button>
          </div>
        `;
      }).join('')}
    </div>
    <button class="btn-primary" id="save-row-filter-btn" style="margin-top:1.5rem; padding:0.5rem 1.2rem;">行フィルタ設定を保存</button>
  `;

  ALL_ACCOUNTS.forEach(acc => {
    const listContainer = document.getElementById(`rules-list-${acc.id}`);
    const filterSetting = (state.permissions.rowFilters[tableId] || {})[acc.id] || { matchType: 'OR', rules: [] };
    
    const addRuleRow = (ruleData = { columnId: '', word: '' }) => {
      const row = document.createElement('div');
      row.className = 'rule-row';
      row.style.display = 'flex';
      row.style.alignItems = 'center';
      row.style.gap = '0.5rem';

      const select = document.createElement('select');
      select.className = 'rule-col-select';
      select.style.padding = '0.25rem';
      select.style.fontSize = '0.85rem';
      columns.forEach(col => {
        const opt = document.createElement('option');
        opt.value = col.id;
        opt.textContent = col.label || col.name;
        if (col.id === ruleData.columnId) opt.selected = true;
        select.appendChild(opt);
      });

      const opSpan = document.createElement('span');
      opSpan.textContent = 'が';
      opSpan.style.fontSize = '0.85rem';

      const valInput = document.createElement('input');
      valInput.type = 'text';
      valInput.className = 'rule-word-input';
      valInput.value = ruleData.word || '';
      valInput.placeholder = 'キーワード';
      valInput.style.padding = '0.25rem';
      valInput.style.fontSize = '0.85rem';
      valInput.style.flex = '1';

      const endSpan = document.createElement('span');
      endSpan.textContent = 'を含む';
      endSpan.style.fontSize = '0.85rem';

      const removeBtn = document.createElement('button');
      removeBtn.className = 'btn-danger';
      removeBtn.innerHTML = '<svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: -2px;"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path></svg>';
      removeBtn.style.padding = '0.2' + 'rem 0.4rem';
      removeBtn.style.fontSize = '0.8rem';
      removeBtn.addEventListener('click', () => row.remove());

      row.appendChild(select);
      row.appendChild(opSpan);
      row.appendChild(valInput);
      row.appendChild(endSpan);
      row.appendChild(removeBtn);
      listContainer.appendChild(row);
    };

    if (filterSetting.rules && filterSetting.rules.length > 0) {
      filterSetting.rules.forEach(r => addRuleRow(r));
    }

    const addBtn = pane.querySelector(`.add-rule-row-btn[data-user-id="${acc.id}"]`);
    addBtn.addEventListener('click', () => {
      addRuleRow();
    });
  });

  document.getElementById('save-row-filter-btn').addEventListener('click', () => {
    if (!state.permissions.rowFilters[tableId]) state.permissions.rowFilters[tableId] = {};

    ALL_ACCOUNTS.forEach(acc => {
      const container = document.getElementById(`rules-list-${acc.id}`);
      const matchType = pane.querySelector(`input[name="matchtype-${acc.id}"]:checked`).value;
      const rules = [];

      container.querySelectorAll('.rule-row').forEach(row => {
        const columnId = row.querySelector('.rule-col-select').value;
        const word = row.querySelector('.rule-word-input').value.trim();
        if (columnId && word) {
          rules.push({ columnId, word });
        }
      });

      if (rules.length > 0) {
        state.permissions.rowFilters[tableId][acc.id] = { matchType, rules };
      } else {
        delete state.permissions.rowFilters[tableId][acc.id];
      }
    });

    savePermissions();
    renderCustomTableList();
    showToast('行フィルタ設定を保存しました。', 'success');
  });
}

function renderPermissionSummary() {
  const pane = document.getElementById('summary-tab');
  if (!pane) return;

  const tables = [
    { id: 'appoint-accordion', name: 'アポイント情報（フォルダ）', type: 'folder' },
    { id: 'agency-accordion', name: '代理店情報（フォルダ）', type: 'folder' },
    { id: 'agency-info-screen', name: '🏢 代理店・基本マスタ', type: 'table' },
    { id: 'jo-accordion', name: 'JO情報（フォルダ）', type: 'folder' },
    { id: 'jo-info-screen', name: '💼 JO・基本マスタ', type: 'table' },
    { id: 'applicant-accordion', name: '申込者情報（フォルダ）', type: 'folder' },
    { id: 'applicant-info-screen', name: '👥 申込者・基本マスタ', type: 'table' },

  ];

  state.customAccordions.forEach(acc => {
    tables.push({ id: acc.id, name: `📁 ${getFolderMenuPath(acc.id)}（フォルダ）`, type: 'folder' });
  });

  state.customTables.forEach(t => {
    tables.push({ id: t.id, name: `📋 ${t.name}`, type: 'table' });
  });

  pane.innerHTML = `
    <h3>📊 権限設定サマリー</h3>
    <p style="color:var(--text-muted); font-size:0.85rem; margin-bottom:1rem;">各ユーザーに付与されている詳細権限を一元的に確認・管理できます。</p>
    
    <div style="overflow-x:auto; background:var(--bg-surface); border:1px solid var(--border-color); border-radius:var(--radius-md);">
      <table style="width:100%; border-collapse:collapse; text-align:left; font-size:0.85rem;">
        <thead>
          <tr style="background:var(--bg-surface-elevated); border-bottom:2px solid var(--border-color);">
            <th style="padding:0.75rem 1rem;">対象要素</th>
            <th style="padding:0.75rem 1rem;">種別</th>
            ${ALL_ACCOUNTS.map(acc => `<th style="padding:0.75rem 1rem; text-align:center;">${acc.name}</th>`).join('')}
          </tr>
        </thead>
        <tbody>
          ${tables.map(t => {
            return `
              <tr style="border-bottom:1px solid var(--border-color);">
                <td style="padding:0.6rem 1rem; font-weight:bold; color:var(--text-primary);">${t.name}</td>
                <td style="padding:0.6rem 1rem; color:var(--text-secondary);">${t.type === 'folder' ? '📂 フォルダ' : '📄 テーブル'}</td>
                ${ALL_ACCOUNTS.map(acc => {
                  let hasAccess = false;
                  let detailText = '';

                  if (t.type === 'folder') {
                    const allowed = state.permissions.folders[t.id] || [];
                    hasAccess = allowed.includes(acc.id);
                  } else {
                    const allowed = state.permissions.tables[t.id] || [];
                    hasAccess = allowed.includes(acc.id);

                    if (hasAccess) {
                      const rowF = (state.permissions.rowFilters[t.id] || {})[acc.id];
                      if (rowF && rowF.rules && rowF.rules.length > 0) {
                        detailText = `<div style="font-size:0.75rem; color:var(--secondary); margin-top:2px;">🔍 行制限: ${rowF.rules.length}件 (${rowF.matchType})</div>`;
                      }

                      const colP = state.permissions.columns[t.id];
                      if (colP) {
                        const colsNotAllowed = Object.keys(colP).filter(cid => !colP[cid].includes(acc.id));
                        if (colsNotAllowed.length > 0) {
                          detailText += `<div style="font-size:0.75rem; color:var(--primary); margin-top:2px;">🧱 カラム非表示: ${colsNotAllowed.length}列</div>`;
                        }
                      }
                    }
                  }

                  return `
                    <td style="padding:0.6rem 1rem; text-align:center;">
                      ${hasAccess ? '<span style="color:#10b981; font-weight:bold;">🟢 閲覧可</span>' : '<span style="color:#ef4444;">🔴 閲覧不可</span>'}
                      ${detailText}
                    </td>
                  `;
                }).join('')}
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;
}

function startImpersonationPreview(targetUserId, mode) {
  state.prePreviewView = state.currentView;
  state.previewUserId = targetUserId;
  state.previewMode = mode;

  // プレビュー開始時の権限スナップショットを記録（元に戻す・全復元用）
  state.initialPreviewPermissions = JSON.parse(JSON.stringify(state.permissions || {}));
  state.permissionHistory = [];
  updatePreviewUndoButtons();
  
  const bar = document.getElementById('impersonate-preview-bar');
  if (bar) {
    const userLabel = ALL_ACCOUNTS.find(a => a.id === targetUserId)?.name || targetUserId;
    const modeLabel = (mode === 'grayout' || mode === 'simulate') ? 'デバッグ（グレー表示）' : '完全再現（非表示）';
    
    const userEl = document.getElementById('previewing-user-name');
    if (userEl) userEl.textContent = userLabel;
    
    const modeEl = document.getElementById('previewing-mode-name');
    if (modeEl) modeEl.textContent = modeLabel;
    
    const modeSelect = document.getElementById('preview-mode-select');
    if (modeSelect) {
      modeSelect.value = (mode === 'grayout' || mode === 'simulate') ? 'simulate' : 'actual';
    }
    
    bar.style.display = 'flex';
  }
  document.body.classList.add('in-preview-mode');

  renderCustomTableList();
  
  // 実際のユーザーが見られるログイン後の画面（マイページ画面）へ遷移
  switchView('mypage-screen');

  updateUIForCurrentMode();

  if (state.currentView === 'jo-info-screen') renderJoInfo();
  else if (state.currentView === 'applicant-info-screen') renderApplicantInfo();
  else if (state.currentView === 'agency-info-screen') renderAgencyInfo();
  else if (state.currentView === 'custom-table-screen' && state.activeCustomTableId) {
    renderCustomTable(state.activeCustomTableId);
  }

  showToast(`なりすましプレビューを開始しました：${targetUserId}`, 'info');
}

function endImpersonationPreview() {
  state.previewUserId = null;
  state.previewMode = null;
  state.initialPreviewPermissions = null;
  state.permissionHistory = [];
  updatePreviewUndoButtons();

  const bar = document.getElementById('impersonate-preview-bar');
  if (bar) {
    bar.style.display = 'none';
  }
  document.body.classList.remove('in-preview-mode');

  renderCustomTableList();
  updateUIForCurrentMode();

  // 元の画面に戻る
  if (state.prePreviewView) {
    switchView(state.prePreviewView);
  } else {
    switchView('mypage-screen');
  }

  if (state.currentView === 'jo-info-screen') renderJoInfo();
  else if (state.currentView === 'applicant-info-screen') renderApplicantInfo();
  else if (state.currentView === 'agency-info-screen') renderAgencyInfo();
  else if (state.currentView === 'custom-table-screen' && state.activeCustomTableId) {
    renderCustomTable(state.activeCustomTableId);
  }

  showToast('プレビューを終了し、通常の管理者ビューに戻りました。', 'success');
}

document.addEventListener('DOMContentLoaded', () => {
  const quitBtn = document.getElementById('preview-quit-btn');
  if (quitBtn) {
    quitBtn.addEventListener('click', () => {
      endImpersonationPreview();
    });
  }

  const undoBtn = document.getElementById('preview-undo-btn');
  if (undoBtn) {
    undoBtn.addEventListener('click', () => {
      undoLastPermissionChange();
    });
  }

  const resetAllBtn = document.getElementById('preview-reset-all-btn');
  if (resetAllBtn) {
    resetAllBtn.addEventListener('click', () => {
      resetPreviewPermissions();
    });
  }

  const modeSelect = document.getElementById('preview-mode-select');
  if (modeSelect) {
    modeSelect.addEventListener('change', () => {
      state.previewMode = modeSelect.value;
      const modeLabel = state.previewMode === 'simulate' ? 'デバッグ（グレー表示）' : '完全再現（非表示）';
      const modeEl = document.getElementById('previewing-mode-name');
      if (modeEl) modeEl.textContent = modeLabel;

      if (typeof renderCustomTableList === 'function') renderCustomTableList();

      if (state.currentView === 'jo-info-screen') renderJoInfo();
      else if (state.currentView === 'applicant-info-screen') renderApplicantInfo();
      else if (state.currentView === 'agency-info-screen') renderAgencyInfo();
      else if (state.currentView === 'custom-table-screen' && state.activeCustomTableId) {
        renderCustomTable(state.activeCustomTableId);
      }
    });
  }
});

function initPermissionSettingsScreen() {
  const runBtn = document.getElementById('run-impersonation-preview-btn');
  if (runBtn) {
    const newRunBtn = runBtn.cloneNode(true);
    runBtn.parentNode.replaceChild(newRunBtn, runBtn);

    newRunBtn.addEventListener('click', () => {
      const userSelect = document.getElementById('impersonation-user-select');
      const modeSelect = document.getElementById('impersonation-mode-select');
      if (!userSelect || !modeSelect) return;
      
      const targetUser = userSelect.value;
      const mode = modeSelect.value;
      
      if (!targetUser) {
        showToast('対象ユーザーを選択してください。', 'warning');
        return;
      }

      startImpersonationPreview(targetUser, mode);
    });
  }

  const screen = document.getElementById('permission-settings-screen');
  if (screen) {
    screen.querySelectorAll('.tab-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        const tabId = btn.dataset.tab;
        switchPermissionTab(tabId);
        if (tabId === 'summary-tab') {
          renderPermissionSummary();
        } else {
          renderPermissionSettingsDetails();
        }
      });
    });
  }

  // 💡 権限画面モード切り替えリスナーのバインド
  const modeTreeBtn = document.getElementById('perm-mode-tree-btn');
  const modeMatrixBtn = document.getElementById('perm-mode-matrix-btn');
  const modeUserBtn = document.getElementById('perm-mode-user-btn');

  const containerTree = document.getElementById('perm-view-tree-container');
  const containerMatrix = document.getElementById('perm-view-matrix-container');
  const containerUser = document.getElementById('perm-view-user-container');

  const switchPermMode = (mode) => {
    [modeTreeBtn, modeMatrixBtn, modeUserBtn].forEach(btn => {
      if (btn) btn.classList.remove('active');
    });
    [containerTree, containerMatrix, containerUser].forEach(c => {
      if (c) c.style.display = 'none';
    });

    if (mode === 'tree') {
      if (modeTreeBtn) modeTreeBtn.classList.add('active');
      if (containerTree) containerTree.style.display = 'flex';
      renderPermissionTree();
      showPermissionEmptyState();
    } else if (mode === 'matrix') {
      if (modeMatrixBtn) modeMatrixBtn.classList.add('active');
      if (containerMatrix) containerMatrix.style.display = 'block';
      renderPermissionMatrix();
    } else if (mode === 'user') {
      if (modeUserBtn) modeUserBtn.classList.add('active');
      if (containerUser) containerUser.style.display = 'flex';
      renderUserBasedPermissionList();
    }
  };

  if (modeTreeBtn) modeTreeBtn.addEventListener('click', () => switchPermMode('tree'));
  if (modeMatrixBtn) modeMatrixBtn.addEventListener('click', () => switchPermMode('matrix'));
  if (modeUserBtn) modeUserBtn.addEventListener('click', () => switchPermMode('user'));

  // デフォルト起動時はデータツリー別設定
  switchPermMode('tree');
}

// 🔑 全フォルダ・テーブル情報収集用共通ヘルパー
function getAllFoldersAndTables() {
  const list = [
    { type: 'folder', id: 'appoint-accordion', name: '📁 アポイント情報（フォルダ）' },
    { type: 'folder', id: 'agency-accordion', name: '📁 代理店情報（フォルダ）' },
    { type: 'table', id: 'agency-info-screen', name: '📋 代理店 基本マスタ（テーブル）', parentId: 'agency-accordion' },
    { type: 'folder', id: 'jo-accordion', name: '📁 JO情報（フォルダ）' },
    { type: 'table', id: 'jo-info-screen', name: '📋 JO 基本マスタ（テーブル）', parentId: 'jo-accordion' },
    { type: 'folder', id: 'applicant-accordion', name: '📁 申込者情報（フォルダ）' },
    { type: 'table', id: 'applicant-info-screen', name: '📋 申込者 基本マスタ（テーブル）', parentId: 'applicant-accordion' }
  ];

  state.customAccordions.forEach(acc => {
    list.push({ type: 'folder', id: acc.id, name: `📁 カスタム: ${getFolderMenuPath(acc.id)}（フォルダ）` });
  });

  state.customTables.forEach(t => {
    list.push({ type: 'table', id: t.id, name: `📋 カスタム: ${t.name}（テーブル）`, parentId: t.parentMenuId || 'root', columns: t.columns || [] });
  });

  return list;
}

// 🔑 テーブル別アクセス制御行列 (マトリクス) の描画
function renderPermissionMatrix() {
  const table = document.getElementById('perm-matrix-grid-table');
  const tbody = document.getElementById('perm-matrix-grid-tbody');
  if (!table || !tbody) return;

  // 横軸ヘッダー生成 (全アカウント)
  const thead = table.querySelector('thead') || document.createElement('thead');
  thead.innerHTML = '';
  const trHead = document.createElement('tr');
  
  const thTarget = document.createElement('th');
  thTarget.textContent = '対象フォルダ / テーブル';
  trHead.appendChild(thTarget);

  ALL_ACCOUNTS.forEach(acc => {
    const th = document.createElement('th');
    th.textContent = acc.name;
    th.style.textAlign = 'center';
    th.style.fontSize = '0.8rem';
    trHead.appendChild(th);
  });
  thead.appendChild(trHead);
  if (!table.querySelector('thead')) {
    table.appendChild(thead);
  }

  // 縦軸ボディ生成
  tbody.innerHTML = '';
  const items = getAllFoldersAndTables();

  items.forEach(item => {
    const tr = document.createElement('tr');
    tr.style.borderBottom = '1px solid var(--border-color)';

    const tdName = document.createElement('td');
    tdName.textContent = item.name;
    tdName.style.padding = '0.4rem 0.5rem';
    tdName.style.fontSize = '0.8rem';
    if (item.type === 'folder') {
      tdName.style.fontWeight = 'bold';
      tdName.style.color = 'var(--text-primary)';
      tr.style.background = 'rgba(255,255,255,0.015)';
    } else {
      tdName.style.paddingLeft = '1.5rem';
      tdName.style.color = 'var(--text-secondary)';
    }
    tr.appendChild(tdName);

    ALL_ACCOUNTS.forEach(acc => {
      const td = document.createElement('td');
      td.style.textAlign = 'center';
      td.style.padding = '0.4rem';

      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.className = `matrix-cb-${item.type}`;
      cb.dataset.itemId = item.id;
      cb.dataset.userId = acc.id;

      if (item.type === 'folder') {
        const allowed = state.permissions.folders[item.id] || [];
        cb.checked = allowed.includes(acc.id);
      } else {
        const allowed = state.permissions.tables[item.id] || [];
        cb.checked = allowed.includes(acc.id);
      }

      td.appendChild(cb);
      tr.appendChild(td);
    });

    tbody.appendChild(tr);
  });

  // 保存ボタン
  const saveBtn = document.getElementById('save-perm-matrix-btn');
  if (saveBtn) {
    const newSaveBtn = saveBtn.cloneNode(true);
    saveBtn.parentNode.replaceChild(newSaveBtn, saveBtn);
    newSaveBtn.addEventListener('click', () => {
      const newFoldersPerm = {};
      const newTablesPerm = {};

      tbody.querySelectorAll('.matrix-cb-folder').forEach(cb => {
        if (cb.checked) {
          if (!newFoldersPerm[cb.dataset.itemId]) newFoldersPerm[cb.dataset.itemId] = [];
          newFoldersPerm[cb.dataset.itemId].push(cb.dataset.userId);
        }
      });

      tbody.querySelectorAll('.matrix-cb-table').forEach(cb => {
        if (cb.checked) {
          if (!newTablesPerm[cb.dataset.itemId]) newTablesPerm[cb.dataset.itemId] = [];
          newTablesPerm[cb.dataset.itemId].push(cb.dataset.userId);
        }
      });

      items.forEach(item => {
        if (item.type === 'folder') {
          state.permissions.folders[item.id] = newFoldersPerm[item.id] || [];
        } else {
          state.permissions.tables[item.id] = newTablesPerm[item.id] || [];
        }
      });

      savePermissions();
      renderCustomTableList();
      showToast('行列のアクセス権限を保存しました。', 'success');
      renderPermissionMatrix();
    });
  }
}

// 🔑 ユーザー別一括設定の描画
function renderUserBasedPermissionList(activeUserId = null) {
  const userListContainer = document.getElementById('perm-user-list-select');
  const selectedTitle = document.getElementById('perm-user-selected-title');
  const configArea = document.getElementById('perm-user-config-area');
  const saveBtn = document.getElementById('save-user-based-perm-btn');
  
  if (!userListContainer || !configArea || !selectedTitle) return;

  userListContainer.innerHTML = '';
  ALL_ACCOUNTS.forEach(acc => {
    const btn = document.createElement('button');
    btn.className = 'btn btn-secondary';
    btn.style.width = '100%';
    btn.style.textAlign = 'left';
    btn.style.padding = '0.4rem 0.6rem';
    btn.style.fontSize = '0.8rem';
    btn.style.marginBottom = '0.2rem';
    btn.textContent = `👤 ${acc.name} (${acc.id})`;
    
    if (activeUserId === acc.id) {
      btn.style.background = 'rgba(26, 115, 232, 0.15)';
      btn.style.borderColor = 'var(--primary)';
      btn.style.color = 'var(--primary)';
    }

    btn.addEventListener('click', () => {
      renderUserBasedPermissionList(acc.id);
    });

    userListContainer.appendChild(btn);
  });

  if (!activeUserId) {
    selectedTitle.textContent = 'ユーザーを選択してください';
    configArea.style.display = 'none';
    if (saveBtn) saveBtn.style.display = 'none';
    return;
  }

  const activeUser = ALL_ACCOUNTS.find(a => a.id === activeUserId);
  selectedTitle.textContent = `👤 ユーザー設定: ${activeUser.name} (${activeUser.id})`;
  configArea.style.display = 'flex';
  if (saveBtn) saveBtn.style.display = 'block';

  const items = getAllFoldersAndTables();

  // A. フォルダ・テーブル閲覧チェックボックス群の描画
  const tablesContainer = document.getElementById('perm-user-tables-checkboxes');
  tablesContainer.innerHTML = '';
  items.forEach(item => {
    const label = document.createElement('label');
    label.style.display = 'flex';
    label.style.alignItems = 'center';
    label.style.gap = '0.4rem';
    label.style.cursor = 'pointer';
    label.style.padding = '0.2rem';
    
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.className = `user-view-cb-${item.type}`;
    cb.dataset.itemId = item.id;

    if (item.type === 'folder') {
      const allowed = state.permissions.folders[item.id] || [];
      cb.checked = allowed.includes(activeUserId);
    } else {
      const allowed = state.permissions.tables[item.id] || [];
      cb.checked = allowed.includes(activeUserId);
    }

    const span = document.createElement('span');
    span.textContent = item.name;
    span.style.fontSize = '0.75rem';
    if (item.type === 'folder') {
      span.style.fontWeight = 'bold';
    }

    label.appendChild(cb);
    label.appendChild(span);
    tablesContainer.appendChild(label);
  });

  // B. 表示カラム権限の描画
  const columnsContainer = document.getElementById('perm-user-columns-container');
  columnsContainer.innerHTML = '';

  const tables = items.filter(i => i.type === 'table');
  tables.forEach(t => {
    let cols = [];
    if (t.id === 'agency-info-screen') cols = state.agColumns;
    else if (t.id === 'jo-info-screen') cols = state.joColumns;
    else if (t.id === 'applicant-info-screen') cols = state.apColumns;
    else {
      cols = t.columns || [];
    }

    if (cols.length === 0) return;

    const divTable = document.createElement('div');
    divTable.style.border = '1px solid var(--border-color)';
    divTable.style.borderRadius = 'var(--radius-sm)';
    divTable.style.padding = '0.5rem 0.75rem';
    divTable.style.background = 'rgba(255,255,255,0.005)';

    const h4 = document.createElement('h4');
    h4.textContent = t.name;
    h4.style.fontSize = '0.8rem';
    h4.style.margin = '0 0 0.4rem 0';
    h4.style.color = 'var(--text-secondary)';
    divTable.appendChild(h4);

    const divCols = document.createElement('div');
    divCols.style.display = 'grid';
    divCols.style.gridTemplateColumns = 'repeat(auto-fill, minmax(180px, 1fr))';
    divCols.style.gap = '0.4rem';

    cols.forEach(c => {
      const label = document.createElement('label');
      label.style.display = 'flex';
      label.style.alignItems = 'center';
      label.style.gap = '0.35rem';
      label.style.cursor = 'pointer';

      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.className = `user-col-cb-${t.id}`;
      cb.dataset.colId = c.id;

      const tableCols = state.permissions.columns[t.id] || {};
      const allowed = tableCols[c.id] || [];
      const isSetup = Object.keys(tableCols).includes(c.id);
      cb.checked = (!isSetup || allowed.includes(activeUserId));

      const span = document.createElement('span');
      span.textContent = c.label || c.name;
      span.style.fontSize = '0.75rem';

      label.appendChild(cb);
      label.appendChild(span);
      divCols.appendChild(label);
    });

    divTable.appendChild(divCols);
    columnsContainer.appendChild(divTable);
  });

  // C. 行フィルタ条件の描画
  const filtersContainer = document.getElementById('perm-user-filters-container');
  filtersContainer.innerHTML = '';

  tables.forEach(t => {
    const divFilter = document.createElement('div');
    divFilter.style.display = 'flex';
    divFilter.style.alignItems = 'center';
    divFilter.style.gap = '0.75rem';
    divFilter.style.border = '1px solid var(--border-color)';
    divFilter.style.borderRadius = 'var(--radius-sm)';
    divFilter.style.padding = '0.4rem 0.6rem';
    divFilter.style.background = 'rgba(255,255,255,0.005)';

    const span = document.createElement('span');
    span.textContent = t.name;
    span.style.fontSize = '0.75rem';
    span.style.width = '240px';
    span.style.overflow = 'hidden';
    span.style.textOverflow = 'ellipsis';
    span.style.whiteSpace = 'nowrap';
    span.style.color = 'var(--text-secondary)';
    divFilter.appendChild(span);

    const input = document.createElement('input');
    input.type = 'text';
    input.className = `user-filter-input-${t.id}`;
    input.placeholder = '制限ワードを入力（カンマ区切り。例: 運営中, 一時停止）';
    input.style.flex = '1';
    input.style.padding = '0.25rem 0.5rem';
    input.style.fontSize = '0.75rem';
    input.style.border = '1px solid var(--border-color)';
    input.style.borderRadius = 'var(--radius-sm)';
    input.style.background = 'var(--bg-surface)';
    input.style.color = 'var(--text-primary)';
    input.style.outline = 'none';

    const tableFilters = state.permissions.rowFilters[t.id] || {};
    input.value = tableFilters[activeUserId] || '';

    divFilter.appendChild(input);
    filtersContainer.appendChild(divFilter);
  });

  // 保存処理
  if (saveBtn) {
    const newSaveBtn = saveBtn.cloneNode(true);
    saveBtn.parentNode.replaceChild(newSaveBtn, saveBtn);
    newSaveBtn.addEventListener('click', () => {
      // 閲覧権限の更新
      items.forEach(item => {
        const cb = tablesContainer.querySelector(`.user-view-cb-${item.type}[data-item-id="${item.id}"]`);
        if (cb) {
          const allowed = (item.type === 'folder' ? state.permissions.folders[item.id] : state.permissions.tables[item.id]) || [];
          const index = allowed.indexOf(activeUserId);
          
          if (cb.checked) {
            if (index === -1) allowed.push(activeUserId);
          } else {
            if (index !== -1) allowed.splice(index, 1);
          }

          if (item.type === 'folder') {
            state.permissions.folders[item.id] = allowed;
          } else {
            state.permissions.tables[item.id] = allowed;
          }
        }
      });

      // 表示カラムの更新
      tables.forEach(t => {
        const cbs = columnsContainer.querySelectorAll(`.user-col-cb-${t.id}`);
        if (cbs.length > 0) {
          if (!state.permissions.columns[t.id]) state.permissions.columns[t.id] = {};
          
          cbs.forEach(cb => {
            const colId = cb.dataset.colId;
            const allowed = state.permissions.columns[t.id][colId] || [];
            const index = allowed.indexOf(activeUserId);

            if (cb.checked) {
              const isSetup = Object.keys(state.permissions.columns[t.id]).includes(colId);
              if (isSetup && index === -1) {
                allowed.push(activeUserId);
              }
            } else {
              const isSetup = Object.keys(state.permissions.columns[t.id]).includes(colId);
              if (!isSetup) {
                const defaultAllowed = ALL_ACCOUNTS.map(a => a.id).filter(uid => uid !== activeUserId);
                state.permissions.columns[t.id][colId] = defaultAllowed;
              } else {
                if (index !== -1) {
                  allowed.splice(index, 1);
                }
              }
            }
          });
        }
      });

      // 行フィルタの更新
      tables.forEach(t => {
        const input = filtersContainer.querySelector(`.user-filter-input-${t.id}`);
        if (input) {
          if (!state.permissions.rowFilters[t.id]) state.permissions.rowFilters[t.id] = {};
          const val = input.value.trim();
          if (val) {
            state.permissions.rowFilters[t.id][activeUserId] = val;
          } else {
            delete state.permissions.rowFilters[t.id][activeUserId];
          }
        }
      });

      savePermissions();
      renderCustomTableList();
      showToast(`${activeUser.name} の権限設定を一括保存しました。`, 'success');
      renderUserBasedPermissionList(activeUserId);
    });
  }
}

// ============================================================================
// ⏪ TimeCell Recovery & 操作ログ履歴 エンジン
// ============================================================================

let auditFilterState = {
  types: ['ALL'], // 'ALL' or array of 'EDIT', 'DELETE', 'RESTORE'
  users: [],      // empty = all users
  dateMode: 'range', // 'range' | 'single' | 'multi'
  dateFrom: '',
  dateTo: '',
  singleDate: '',
  multiDates: [],
  table: '',
  word: '',
  expandedGroupIds: new Set()
};
if (typeof window !== 'undefined') {
  window.auditFilterState = auditFilterState;
}

// ログの自動グループ化（同一ユーザー × 同一テーブル × 10分以内の連続操作・スマートセッションバッチ）
function groupAuditLogs(logs) {
  if (!logs || logs.length === 0) return [];
  const groups = [];
  const GAP_MS = 10 * 60 * 1000; // 10分

  logs.forEach(log => {
    const logTime = new Date(log.timestamp).getTime();
    
    // 直近のグループの中から、同一ユーザー × 同一テーブル かつ 時間差が10分以内のものを検索
    const matchingGroup = groups.find(g => 
      g.userId === log.userId && 
      g.tableId === log.tableId && 
      Math.abs(g.lastTime - logTime) <= GAP_MS
    );

    if (matchingGroup) {
      matchingGroup.logs.push(log);
      matchingGroup.lastTime = Math.min(matchingGroup.lastTime, logTime);
      matchingGroup.startTime = new Date(Math.max(new Date(matchingGroup.startTime).getTime(), logTime)).toISOString();
      if (!matchingGroup.types.includes(log.type || 'EDIT')) {
        matchingGroup.types.push(log.type || 'EDIT');
      }
    } else {
      groups.push({
        id: `grp_${log.id}`,
        userId: log.userId,
        userName: log.userName || log.userId,
        tableId: log.tableId,
        tableName: log.tableName || log.tableId,
        startTime: log.timestamp,
        lastTime: logTime,
        types: [log.type || 'EDIT'],
        logs: [log]
      });
    }
  });

  return groups;
}

// TimeCell Recovery 復元実行エンジン（管理者専用権限ガード）
function executeTimeCellRecovery(targetLogs, confirmMsg = null) {
  // 1. 厳格な管理者権限チェック
  const isMasterAdmin = isOwnerUser() || (state.currentUser && (state.currentUser.role === 'admin' || state.currentUser.role === 'owner' || state.currentUser.id === 'admin'));
  if (!isMasterAdmin) {
    showToast('TimeCell Recovery を実行する管理者権限がありません。', 'error');
    console.error('[Security] Unauthorized attempt to execute TimeCell Recovery.');
    return;
  }

  if (!targetLogs || targetLogs.length === 0) {
    showToast('復元対象の操作ログがありません。', 'warning');
    return;
  }

  const promptText = confirmMsg || `選択した ${targetLogs.length} 件のセル変更を、変更前の過去データへ復元（TimeCell Recovery）します。\n他のユーザーの入力は一切変更されません。よろしいですか？`;
  if (!confirm(promptText)) return;

  // 2. 最新の操作から順に巻き戻すため「降順（新しい順）」にソート
  const sortedLogs = [...targetLogs].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

  // 3. テーブルごとにグループ化してコミット
  const groupedByTable = {};
  sortedLogs.forEach(log => {
    if (!groupedByTable[log.tableId]) groupedByTable[log.tableId] = [];
    groupedByTable[log.tableId].push(log);
  });

  const currentUser = state.currentUser ? (state.currentUser.name || state.currentUser.id) : '管理者';
  let restoredCount = 0;

  Object.keys(groupedByTable).forEach(tableId => {
    let normId = tableId;
    if (tableId.startsWith('custom-table-')) normId = tableId.replace('custom-table-', '');
    if (tableId === 'dbmake-partners' || tableId === 'dbmake-screen') normId = 'dbmake';
    if (tableId === 'jo-contracts' || tableId === 'jo-info-screen') normId = 'jo';
    if (tableId === 'ap-contracts' || tableId === 'applicant-info-screen') normId = 'ap';
    if (tableId === 'ag-contracts' || tableId === 'agency-info-screen') normId = 'ag';

    const meta = getTableMeta(normId);
    if (!meta || !meta.rows) return;

    groupedByTable[tableId].forEach(log => {
      const row = meta.rows.find(r => (r.id === log.rowId || r.customerId === log.rowId || r.customerPersonalityId === log.rowId));
      if (row) {
        const currentVal = row[log.columnId] !== undefined ? row[log.columnId] : '';
        const restoreVal = log.oldValue !== undefined ? log.oldValue : '';

        // 対象セルの値を復元
        row[log.columnId] = restoreVal;
        restoredCount++;

        // 🌟 復元ログ（RESTORE）の新規記録（トレーサビリティの永久保持）
        const restoreLog = {
          id: `log_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
          type: 'RESTORE',
          timestamp: new Date().toISOString(),
          userId: state.currentUser ? (state.currentUser.loginId || state.currentUser.id) : 'admin',
          userName: currentUser,
          tableId: tableId,
          tableName: log.tableName,
          rowId: log.rowId,
          columnId: log.columnId,
          columnName: log.columnName,
          oldValue: currentVal,
          newValue: restoreVal,
          restoredFrom: {
            targetLogId: log.id,
            originalTimestamp: log.timestamp,
            originalUser: log.userName || log.userId,
            originalType: log.type || 'EDIT'
          }
        };
        state.auditLogs.unshift(restoreLog);
      }
    });

    if (typeof meta.save === 'function') meta.save();
    if (typeof meta.render === 'function') meta.render();
  });

  saveAuditLogs();
  renderAuditLogs();
  showToast(`${restoredCount} 件のデータを TimeCell Recovery で復元しました。`, 'success');
}

function initAuditLogScreen() {
  // アイコン描画
  const headerIcon = document.getElementById('audit-log-header-icon');
  if (headerIcon && window.SYNAPSE_LINE_ICONS) {
    headerIcon.innerHTML = SYNAPSE_LINE_ICONS.clock(22);
  }
  const bulkBtnIcon = document.getElementById('timecell-bulk-btn-icon');
  if (bulkBtnIcon && window.SYNAPSE_LINE_ICONS) {
    bulkBtnIcon.innerHTML = SYNAPSE_LINE_ICONS.rewind(15);
  }
  const clearBtnIcon = document.getElementById('audit-clear-btn-icon');
  if (clearBtnIcon && window.SYNAPSE_LINE_ICONS) {
    clearBtnIcon.innerHTML = SYNAPSE_LINE_ICONS.trash(15);
  }
  const userFilterIcon = document.getElementById('icon-user-filter');
  if (userFilterIcon && window.SYNAPSE_LINE_ICONS) {
    userFilterIcon.innerHTML = SYNAPSE_LINE_ICONS.user(14);
  }
  const userChevronIcon = document.getElementById('icon-user-chevron');
  if (userChevronIcon && window.SYNAPSE_LINE_ICONS) {
    userChevronIcon.innerHTML = SYNAPSE_LINE_ICONS.chevronDown(13);
  }
  const clockFilterIcon = document.getElementById('icon-clock-filter');
  if (clockFilterIcon && window.SYNAPSE_LINE_ICONS) {
    clockFilterIcon.innerHTML = SYNAPSE_LINE_ICONS.calendar(14);
  }

  // 1. 操作種別チップのイベント
  document.querySelectorAll('.audit-type-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      const type = chip.dataset.type;
      if (type === 'ALL') {
        auditFilterState.types = ['ALL'];
        document.querySelectorAll('.audit-type-chip').forEach(c => c.classList.remove('active'));
        chip.classList.add('active');
      } else {
        // ALLを解除
        const allChip = document.querySelector('.audit-type-chip[data-type="ALL"]');
        if (allChip) allChip.classList.remove('active');
        if (auditFilterState.types.includes('ALL')) auditFilterState.types = [];

        if (auditFilterState.types.includes(type)) {
          auditFilterState.types = auditFilterState.types.filter(t => t !== type);
          chip.classList.remove('active');
        } else {
          auditFilterState.types.push(type);
          chip.classList.add('active');
        }

        if (auditFilterState.types.length === 0) {
          auditFilterState.types = ['ALL'];
          if (allChip) allChip.classList.add('active');
        }
      }
      renderAuditLogs();
    });
  });

  // 2. クイック期間ボタンのイベント
  document.querySelectorAll('.audit-quick-date-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const range = btn.dataset.range;
      const now = new Date();
      const dateModeSelect = document.getElementById('audit-date-mode-select');
      const fromInput = document.getElementById('audit-filter-date-from');
      const toInput = document.getElementById('audit-filter-date-to');

      if (dateModeSelect) dateModeSelect.value = 'range';
      toggleAuditDateMode('range');

      if (range === 'all') {
        auditFilterState.dateFrom = '';
        auditFilterState.dateTo = '';
        if (fromInput) fromInput.value = '';
        if (toInput) toInput.value = '';
      } else if (range === '1h') {
        const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);
        auditFilterState.dateFrom = oneHourAgo.toISOString().slice(0, 16);
        auditFilterState.dateTo = now.toISOString().slice(0, 16);
        if (fromInput) fromInput.value = auditFilterState.dateFrom;
        if (toInput) toInput.value = auditFilterState.dateTo;
      } else if (range === '24h') {
        const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
        auditFilterState.dateFrom = oneDayAgo.toISOString().slice(0, 16);
        auditFilterState.dateTo = now.toISOString().slice(0, 16);
        if (fromInput) fromInput.value = auditFilterState.dateFrom;
        if (toInput) toInput.value = auditFilterState.dateTo;
      } else if (range === 'today') {
        const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 0, 0, 0);
        auditFilterState.dateFrom = todayStart.toISOString().slice(0, 16);
        auditFilterState.dateTo = now.toISOString().slice(0, 16);
        if (fromInput) fromInput.value = auditFilterState.dateFrom;
        if (toInput) toInput.value = auditFilterState.dateTo;
      } else if (range === 'yesterday') {
        const yStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 0, 0, 0);
        const yEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1, 23, 59, 59);
        auditFilterState.dateFrom = yStart.toISOString().slice(0, 16);
        auditFilterState.dateTo = yEnd.toISOString().slice(0, 16);
        if (fromInput) fromInput.value = auditFilterState.dateFrom;
        if (toInput) toInput.value = auditFilterState.dateTo;
      }
      renderAuditLogs();
    });
  });

  // 3. ユーザーマルチセレクトドロップダウン
  const userBtn = document.getElementById('audit-user-multiselect-btn');
  const userDropdown = document.getElementById('audit-user-dropdown');
  if (userBtn && userDropdown) {
    userBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      userDropdown.style.display = userDropdown.style.display === 'none' ? 'block' : 'none';
      renderAuditUserDropdown();
    });
    document.addEventListener('click', (e) => {
      if (!userBtn.contains(e.target) && !userDropdown.contains(e.target)) {
        userDropdown.style.display = 'none';
      }
    });
  }

  // 4. 日時モードセレクト
  const dateModeSelect = document.getElementById('audit-date-mode-select');
  if (dateModeSelect) {
    dateModeSelect.addEventListener('change', (e) => {
      toggleAuditDateMode(e.target.value);
      renderAuditLogs();
    });
  }

  const fromInput = document.getElementById('audit-filter-date-from');
  const toInput = document.getElementById('audit-filter-date-to');
  if (fromInput) fromInput.addEventListener('change', (e) => { auditFilterState.dateFrom = e.target.value; renderAuditLogs(); });
  if (toInput) toInput.addEventListener('change', (e) => { auditFilterState.dateTo = e.target.value; renderAuditLogs(); });

  const singleInput = document.getElementById('audit-filter-date-single');
  if (singleInput) singleInput.addEventListener('change', (e) => { auditFilterState.singleDate = e.target.value; renderAuditLogs(); });

  const multiAddBtn = document.getElementById('audit-date-multi-add-btn');
  const multiInput = document.getElementById('audit-filter-date-multi-input');
  if (multiAddBtn && multiInput) {
    multiAddBtn.addEventListener('click', () => {
      const val = multiInput.value;
      if (val && !auditFilterState.multiDates.includes(val)) {
        auditFilterState.multiDates.push(val);
        renderMultiDateChips();
        renderAuditLogs();
      }
    });
  }

  // テーブル・ワード検索
  const tableInput = document.getElementById('audit-log-filter-table');
  if (tableInput) tableInput.addEventListener('input', (e) => { auditFilterState.table = e.target.value; renderAuditLogs(); });

  const wordInput = document.getElementById('audit-log-filter-word');
  if (wordInput) wordInput.addEventListener('input', (e) => { auditFilterState.word = e.target.value; renderAuditLogs(); });

  // リセットボタン
  const resetBtn = document.getElementById('audit-log-reset-btn');
  if (resetBtn) {
    resetBtn.addEventListener('click', () => {
      auditFilterState = {
        types: ['ALL'],
        users: [],
        dateMode: 'range',
        dateFrom: '',
        dateTo: '',
        singleDate: '',
        multiDates: [],
        table: '',
        word: '',
        expandedGroupIds: new Set()
      };
      if (tableInput) tableInput.value = '';
      if (wordInput) wordInput.value = '';
      if (fromInput) fromInput.value = '';
      if (toInput) toInput.value = '';
      if (singleInput) singleInput.value = '';
      if (dateModeSelect) dateModeSelect.value = 'range';
      toggleAuditDateMode('range');
      document.querySelectorAll('.audit-type-chip').forEach(c => {
        if (c.dataset.type === 'ALL') c.classList.add('active');
        else c.classList.remove('active');
      });
      renderAuditLogs();
    });
  }

  // 展開・折りたたみボタン
  const expandAllBtn = document.getElementById('audit-expand-all-btn');
  const collapseAllBtn = document.getElementById('audit-collapse-all-btn');
  if (expandAllBtn) {
    expandAllBtn.addEventListener('click', () => {
      document.querySelectorAll('.audit-group-item').forEach(el => {
        el.classList.add('expanded');
        const rows = el.querySelector('.audit-group-rows');
        if (rows) rows.style.display = 'block';
        const chevron = el.querySelector('.audit-group-chevron');
        if (chevron && window.SYNAPSE_LINE_ICONS) chevron.innerHTML = SYNAPSE_LINE_ICONS.chevronDown(14);
      });
    });
  }
  if (collapseAllBtn) {
    collapseAllBtn.addEventListener('click', () => {
      document.querySelectorAll('.audit-group-item').forEach(el => {
        el.classList.remove('expanded');
        const rows = el.querySelector('.audit-group-rows');
        if (rows) rows.style.display = 'none';
        const chevron = el.querySelector('.audit-group-chevron');
        if (chevron && window.SYNAPSE_LINE_ICONS) chevron.innerHTML = SYNAPSE_LINE_ICONS.chevronRight(14);
      });
    });
  }

  // 履歴クリアボタン
  const clearBtn = document.getElementById('audit-log-clear-btn');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      const isMasterAdmin = isOwnerUser() || (state.currentUser && (state.currentUser.role === 'admin' || state.currentUser.role === 'owner' || state.currentUser.id === 'admin'));
      if (!isMasterAdmin) {
        showToast('操作ログをクリアする権限がありません。', 'error');
        return;
      }
      if (confirm('すべての操作ログ履歴を完全に消去しますか？（この操作は元に戻せません）')) {
        state.auditLogs = [];
        saveAuditLogs();
        renderAuditLogs();
        showToast('操作ログ履歴をクリアしました。', 'info');
      }
    });
  }

  renderAuditLogs();
}

function toggleAuditDateMode(mode) {
  auditFilterState.dateMode = mode;
  const rangeBox = document.getElementById('audit-date-range-box');
  const singleBox = document.getElementById('audit-date-single-box');
  const multiBox = document.getElementById('audit-date-multi-box');
  if (rangeBox) rangeBox.style.display = mode === 'range' ? 'flex' : 'none';
  if (singleBox) singleBox.style.display = mode === 'single' ? 'flex' : 'none';
  if (multiBox) multiBox.style.display = mode === 'multi' ? 'flex' : 'none';
}

function renderMultiDateChips() {
  const container = document.getElementById('audit-date-multi-chips');
  if (!container) return;
  container.innerHTML = '';
  auditFilterState.multiDates.forEach(d => {
    const chip = document.createElement('span');
    chip.style.cssText = 'background: #e0f2fe; color: #0369a1; border: 1px solid #bae6fd; padding: 0.1rem 0.4rem; border-radius: 4px; font-size: 0.72rem; display: flex; align-items: center; gap: 0.25rem;';
    chip.innerHTML = `<span>${d}</span> <span style="cursor: pointer; font-weight: bold;">&times;</span>`;
    chip.querySelector('span:last-child').addEventListener('click', () => {
      auditFilterState.multiDates = auditFilterState.multiDates.filter(item => item !== d);
      renderMultiDateChips();
      renderAuditLogs();
    });
    container.appendChild(chip);
  });
}

function renderAuditUserDropdown() {
  const dropdown = document.getElementById('audit-user-dropdown');
  if (!dropdown) return;
  dropdown.innerHTML = '';

  const uniqueUsers = Array.from(new Set(state.auditLogs.map(l => l.userId || 'system'))).filter(Boolean);
  if (uniqueUsers.length === 0) {
    dropdown.innerHTML = '<div style="font-size:0.75rem; color:var(--text-muted); padding:0.4rem;">ユーザーがいません</div>';
    return;
  }

  const allLabel = document.createElement('label');
  allLabel.style.cssText = 'display: flex; align-items: center; gap: 0.4rem; padding: 0.25rem 0.4rem; font-size: 0.78rem; cursor: pointer; border-bottom: 1px solid var(--border-color); margin-bottom: 0.25rem; font-weight: 600;';
  allLabel.innerHTML = `<input type="checkbox" id="audit-user-all-cb" ${auditFilterState.users.length === 0 ? 'checked' : ''} /> <span>すべて選択</span>`;
  allLabel.querySelector('input').addEventListener('change', (e) => {
    if (e.target.checked) {
      auditFilterState.users = [];
      dropdown.querySelectorAll('.audit-user-item-cb').forEach(cb => cb.checked = false);
    }
    updateAuditUserLabel();
    renderAuditLogs();
  });
  dropdown.appendChild(allLabel);

  uniqueUsers.forEach(uId => {
    const logItem = state.auditLogs.find(l => l.userId === uId);
    const uName = logItem ? logItem.userName || uId : uId;
    const isChecked = auditFilterState.users.includes(uId);

    const itemLabel = document.createElement('label');
    itemLabel.style.cssText = 'display: flex; align-items: center; gap: 0.4rem; padding: 0.25rem 0.4rem; font-size: 0.78rem; cursor: pointer; border-radius: 4px;';
    itemLabel.innerHTML = `<input type="checkbox" class="audit-user-item-cb" value="${uId}" ${isChecked ? 'checked' : ''} /> <span>${uName} <small style="color:var(--text-muted);">(${uId})</small></span>`;
    
    itemLabel.querySelector('input').addEventListener('change', (e) => {
      const allCb = document.getElementById('audit-user-all-cb');
      if (allCb) allCb.checked = false;

      if (e.target.checked) {
        if (!auditFilterState.users.includes(uId)) auditFilterState.users.push(uId);
      } else {
        auditFilterState.users = auditFilterState.users.filter(id => id !== uId);
      }
      if (auditFilterState.users.length === 0 && allCb) allCb.checked = true;

      updateAuditUserLabel();
      renderAuditLogs();
    });
    dropdown.appendChild(itemLabel);
  });
}

function updateAuditUserLabel() {
  const label = document.getElementById('audit-user-selected-label');
  if (!label) return;
  if (auditFilterState.users.length === 0) {
    label.textContent = 'すべての操作者';
  } else if (auditFilterState.users.length === 1) {
    const u = auditFilterState.users[0];
    const logItem = state.auditLogs.find(l => l.userId === u);
    label.textContent = logItem ? (logItem.userName || u) : u;
  } else {
    label.textContent = `${auditFilterState.users.length} 名を選択中`;
  }
}

// 🌟 複合フィルターの評価エンジン
function filterAuditLogs(logs = (state.auditLogs || [])) {
  if (!logs || logs.length === 0) return [];
  return logs.filter(log => {
    // 1. 操作種別フィルター
    if (auditFilterState.types && !auditFilterState.types.includes('ALL')) {
      const logType = log.type || 'EDIT';
      if (!auditFilterState.types.includes(logType)) return false;
    }

    // 2. ユーザーフィルター（複数指定対応）
    if (auditFilterState.users && auditFilterState.users.length > 0) {
      if (!auditFilterState.users.includes(log.userId)) return false;
    }

    // 3. 日時フィルター（3モード対応）
    const logDate = new Date(log.timestamp);
    if (auditFilterState.dateMode === 'range') {
      if (auditFilterState.dateFrom && new Date(log.timestamp) < new Date(auditFilterState.dateFrom)) return false;
      if (auditFilterState.dateTo && new Date(log.timestamp) > new Date(auditFilterState.dateTo)) return false;
    } else if (auditFilterState.dateMode === 'single') {
      if (auditFilterState.singleDate) {
        const logDateStr = logDate.toISOString().slice(0, 10);
        if (logDateStr !== auditFilterState.singleDate) return false;
      }
    } else if (auditFilterState.dateMode === 'multi') {
      if (auditFilterState.multiDates && auditFilterState.multiDates.length > 0) {
        const logDateStr = logDate.toISOString().slice(0, 10);
        if (!auditFilterState.multiDates.includes(logDateStr)) return false;
      }
    }

    // 4. テーブルフィルター
    if (auditFilterState.table && !String(log.tableName || '').toLowerCase().includes(auditFilterState.table.toLowerCase())) return false;

    // 5. ワード検索
    if (auditFilterState.word) {
      const w = auditFilterState.word.toLowerCase();
      const matchWord = 
        String(log.oldValue || '').toLowerCase().includes(w) ||
        String(log.newValue || '').toLowerCase().includes(w) ||
        String(log.columnName || '').toLowerCase().includes(w);
      if (!matchWord) return false;
    }

    return true;
  });
}

function renderAuditLogs() {
  const container = document.getElementById('audit-groups-container');
  const emptyNotice = document.getElementById('audit-log-empty');
  const groupCountEl = document.getElementById('audit-group-count');
  const totalCountEl = document.getElementById('audit-total-log-count');
  const bulkBtn = document.getElementById('timecell-recovery-bulk-btn');
  const bulkCountSpan = document.getElementById('timecell-selected-count');
  if (!container) return;

  container.innerHTML = '';
  if (!state.auditLogs) state.auditLogs = [];

  const isMasterAdmin = isOwnerUser() || (state.currentUser && (state.currentUser.role === 'admin' || state.currentUser.role === 'owner' || state.currentUser.id === 'admin'));

  // 🌟 複合フィルターの評価
  const filtered = filterAuditLogs(state.auditLogs);

  if (groupCountEl) groupCountEl.textContent = '0';
  if (totalCountEl) totalCountEl.textContent = filtered.length;

  // 管理者専用 TimeCell 一括復元ボタンの表示制御
  if (bulkBtn) {
    if (isMasterAdmin && filtered.length > 0) {
      bulkBtn.style.display = 'flex';
      if (bulkCountSpan) bulkCountSpan.textContent = filtered.length;
      bulkBtn.onclick = () => {
        executeTimeCellRecovery(filtered, `現在絞り込まれている ${filtered.length} 件の操作をすべて一括復元（TimeCell Recovery）します。\n他のユーザーの入力は一切破壊されません。よろしいですか？`);
      };
    } else {
      bulkBtn.style.display = 'none';
    }
  }

  if (filtered.length === 0) {
    if (emptyNotice) emptyNotice.style.display = 'block';
    return;
  }
  if (emptyNotice) emptyNotice.style.display = 'none';

  // 🌟 Googleスプレッドシート風 連続操作の自動グループ化
  const groups = groupAuditLogs(filtered);
  if (groupCountEl) groupCountEl.textContent = groups.length;

  const formatDate = (ts) => {
    if (!ts) return '';
    const d = new Date(ts);
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const h = String(d.getHours()).padStart(2, '0');
    const min = String(d.getMinutes()).padStart(2, '0');
    const s = String(d.getSeconds()).padStart(2, '0');
    return `${m}/${day} ${h}:${min}:${s}`;
  };

  const getActionBadgeHtml = (type) => {
    if (type === 'DELETE') {
      return `<span style="display:inline-flex; align-items:center; gap:0.25rem; background:#fee2e2; color:#b91c1c; border:1px solid #fecaca; padding:0.1rem 0.45rem; border-radius:4px; font-size:0.72rem; font-weight:700;">${SYNAPSE_LINE_ICONS.trash(12)} 削除</span>`;
    } else if (type === 'RESTORE') {
      return `<span style="display:inline-flex; align-items:center; gap:0.25rem; background:#f3e8ff; color:#7e22ce; border:1px solid #e9d5ff; padding:0.1rem 0.45rem; border-radius:4px; font-size:0.72rem; font-weight:700;">${SYNAPSE_LINE_ICONS.rewind(12)} 復元</span>`;
    } else {
      return `<span style="display:inline-flex; align-items:center; gap:0.25rem; background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; padding:0.1rem 0.45rem; border-radius:4px; font-size:0.72rem; font-weight:700;">${SYNAPSE_LINE_ICONS.edit(12)} 編集</span>`;
    }
  };

  groups.forEach(grp => {
    const groupCard = document.createElement('div');
    groupCard.className = 'audit-group-item';
    groupCard.style.cssText = 'border-bottom: 1px solid var(--border-color); background: var(--bg-surface);';

    const isExpanded = auditFilterState.expandedGroupIds.has(grp.id);

    // グループヘッダー
    const header = document.createElement('div');
    header.style.cssText = 'display: flex; justify-content: space-between; align-items: center; padding: 0.65rem 1rem; cursor: pointer; background: var(--bg-surface-elevated); border-bottom: 1px solid rgba(0,0,0,0.05); user-select: none;';
    
    header.innerHTML = `
      <div style="display: flex; align-items: center; gap: 0.6rem; flex-wrap: wrap;">
        <span class="audit-group-chevron" style="color: var(--text-secondary); display: flex; align-items: center;">
          ${isExpanded ? SYNAPSE_LINE_ICONS.chevronDown(14) : SYNAPSE_LINE_ICONS.chevronRight(14)}
        </span>
        <span style="font-size: 0.85rem; font-weight: 700; color: var(--text-primary); font-family: monospace;">
          ${formatDate(grp.startTime)} ${grp.startTime !== grp.lastTime ? '〜 ' + formatDate(grp.lastTime) : ''}
        </span>
        <span style="display: inline-flex; align-items: center; gap: 0.3rem; background: var(--bg-surface); border: 1px solid var(--border-color); padding: 0.1rem 0.5rem; border-radius: 12px; font-size: 0.75rem; font-weight: 600;">
          ${SYNAPSE_LINE_ICONS.user(12)} ${grp.userName}
        </span>
        <span style="color: var(--text-secondary); font-size: 0.8rem;">${grp.tableName}</span>
        <span style="background: rgba(59, 130, 246, 0.1); color: #2563eb; border: 1px solid rgba(59, 130, 246, 0.2); padding: 0.05rem 0.45rem; border-radius: 10px; font-size: 0.72rem; font-weight: 700;">
          ${grp.logs.length} 件の操作
        </span>
        <div style="display: flex; gap: 0.25rem;">
          ${grp.types.map(t => getActionBadgeHtml(t)).join(' ')}
        </div>
      </div>
      <div style="display: flex; align-items: center; gap: 0.5rem;">
        ${isMasterAdmin ? `
          <button type="button" class="btn btn-secondary audit-group-restore-btn" style="padding: 0.2rem 0.55rem; font-size: 0.75rem; display: flex; align-items: center; gap: 0.3rem; color: #0284c7; border-color: #bae6fd;">
            ${SYNAPSE_LINE_ICONS.rewind(13)} <span>このグループを一括復元</span>
          </button>
        ` : ''}
      </div>
    `;

    // グループ開閉制御
    header.addEventListener('click', (e) => {
      if (e.target.closest('.audit-group-restore-btn')) return;
      const rowsBox = groupCard.querySelector('.audit-group-rows');
      const chevron = groupCard.querySelector('.audit-group-chevron');
      if (rowsBox.style.display === 'none') {
        rowsBox.style.display = 'block';
        chevron.innerHTML = SYNAPSE_LINE_ICONS.chevronDown(14);
        auditFilterState.expandedGroupIds.add(grp.id);
      } else {
        rowsBox.style.display = 'none';
        chevron.innerHTML = SYNAPSE_LINE_ICONS.chevronRight(14);
        auditFilterState.expandedGroupIds.delete(grp.id);
      }
    });

    // グループ一括復元ボタン
    const grpRestoreBtn = header.querySelector('.audit-group-restore-btn');
    if (grpRestoreBtn) {
      grpRestoreBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        executeTimeCellRecovery(grp.logs, `このグループ（${grp.logs.length} 件の操作）をすべて変更前の値へ復元します。\nよろしいですか？`);
      });
    }

    // グループ詳細行テーブル
    const rowsBox = document.createElement('div');
    rowsBox.className = 'audit-group-rows';
    rowsBox.style.display = isExpanded ? 'block' : 'none';

    const table = document.createElement('table');
    table.style.cssText = 'width: 100%; border-collapse: collapse; font-size: 0.8rem; background: var(--bg-surface);';
    table.innerHTML = `
      <thead>
        <tr style="background: rgba(0,0,0,0.02); border-bottom: 1px solid var(--border-color); color: var(--text-secondary); text-align: left;">
          <th style="padding: 0.4rem 1rem; width: 140px;">日時</th>
          <th style="padding: 0.4rem 0.75rem; width: 90px;">種別</th>
          <th style="padding: 0.4rem 0.75rem; width: 140px;">カラム名</th>
          <th style="padding: 0.4rem 0.75rem; width: 100px;">対象ID</th>
          <th style="padding: 0.4rem 0.75rem;">変更前</th>
          <th style="padding: 0.4rem 0.75rem;">変更後</th>
          <th style="padding: 0.4rem 0.75rem; width: 160px;">復元元情報</th>
          ${isMasterAdmin ? '<th style="padding: 0.4rem 0.75rem; width: 70px; text-align: center;">操作</th>' : ''}
        </tr>
      </thead>
      <tbody></tbody>
    `;

    const tbody = table.querySelector('tbody');
    grp.logs.forEach(log => {
      const tr = document.createElement('tr');
      tr.style.cssText = 'border-bottom: 1px solid var(--border-color); transition: background 0.15s;';
      tr.onmouseenter = () => tr.style.background = 'rgba(0,0,0,0.02)';
      tr.onmouseleave = () => tr.style.background = 'transparent';

      const restoreInfoHtml = log.restoredFrom 
        ? `<span style="font-size:0.72rem; color:#7e22ce;" title="復元元ログ: ${log.restoredFrom.targetLogId}">↪ ${formatDate(log.restoredFrom.originalTimestamp)} (${log.restoredFrom.originalUser})</span>`
        : '<span style="color:var(--text-muted); font-size:0.72rem;">-</span>';

      tr.innerHTML = `
        <td style="padding:0.4rem 1rem; color:var(--text-muted); font-family:monospace; font-size:0.75rem;">${formatDate(log.timestamp)}</td>
        <td style="padding:0.4rem 0.75rem;">${getActionBadgeHtml(log.type || 'EDIT')}</td>
        <td style="padding:0.4rem 0.75rem; font-weight:600; color:var(--text-primary);">${log.columnName || log.columnId}</td>
        <td style="padding:0.4rem 0.75rem; color:var(--text-secondary); font-family:monospace; font-size:0.75rem;">${log.rowId}</td>
        <td style="padding:0.4rem 0.75rem; color:var(--text-secondary); background:rgba(239, 68, 68, 0.04); text-decoration:line-through; font-family:monospace; max-width:180px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${log.oldValue}">${log.oldValue || '(空)'}</td>
        <td style="padding:0.4rem 0.75rem; color:var(--text-primary); background:rgba(16, 185, 129, 0.04); font-weight:bold; font-family:monospace; max-width:180px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${log.newValue}">${log.newValue || '(空)'}</td>
        <td style="padding:0.4rem 0.75rem;">${restoreInfoHtml}</td>
        ${isMasterAdmin ? `
          <td style="padding:0.4rem 0.75rem; text-align:center;">
            <button type="button" class="btn btn-secondary audit-single-restore-btn" style="padding:0.15rem 0.45rem; font-size:0.72rem; display:inline-flex; align-items:center; gap:0.2rem;" title="このセル変更のみを元に戻す">
              ${SYNAPSE_LINE_ICONS.rewind(12)} <span>復元</span>
            </button>
          </td>
        ` : ''}
      `;

      // 個別セル復元ボタン
      const singleRestoreBtn = tr.querySelector('.audit-single-restore-btn');
      if (singleRestoreBtn) {
        singleRestoreBtn.addEventListener('click', () => {
          executeTimeCellRecovery([log], `このセル（${log.columnName}）の値を「${log.newValue}」から変更前の「${log.oldValue || '(空)'}」へ復元します。\nよろしいですか？`);
        });
      }

      tbody.appendChild(tr);
    });

    rowsBox.appendChild(table);
    groupCard.appendChild(header);
    groupCard.appendChild(rowsBox);
    container.appendChild(groupCard);
  });
}

/* ============================================================================
   🏷️ ドロップダウン (データの入力規則) 設定サイドバー制御
   ============================================================================ */

const VALIDATION_PALETTE_COLORS = [
  '#64748b', // グレー (slate)
  '#3b82f6', // ブルー
  '#10b981', // グリーン
  '#eab308', // イエロー
  '#f97316', // オレンジ
  '#ef4444', // レッド
  '#8b5cf6', // パープル
  '#ec4899', // ピンク
  '#06b6d4', // ティール
  '#6366f1', // インディゴ
  '#0284c7', // スカイブルー
  '#84cc16'  // ライム
];

let activeValidationState = {
  tbl: null,
  colId: null,
  choices: []
};

function hexToRgba(hex, alpha) {
  hex = (hex || '#64748b').replace('#', '');
  if (hex.length === 3) {
    hex = hex.split('').map(x => x + x).join('');
  }
  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
window.hexToRgba = hexToRgba;

function normalizeColChoices(col) {
  if (!col.choices) {
    col.choices = [];
  }
  col.choices = col.choices.map((c, idx) => {
    if (typeof c === 'string') {
      return {
        value: c,
        color: VALIDATION_PALETTE_COLORS[idx % VALIDATION_PALETTE_COLORS.length],
        textColor: '#ffffff'
      };
    }
    if (c && typeof c === 'object') {
      return {
        value: c.value || '',
        color: c.color || VALIDATION_PALETTE_COLORS[idx % VALIDATION_PALETTE_COLORS.length],
        textColor: c.textColor || '#ffffff'
      };
    }
    return { value: '', color: '#64748b', textColor: '#ffffff' };
  });
  
  if (!col.dropdownStyle) {
    col.dropdownStyle = 'chip-outline';
  }
}
window.normalizeColChoices = normalizeColChoices;

function openValidationSidebar(tbl, colId) {
  if (window.logToDebugPanel) window.logToDebugPanel(`openValidationSidebar called: tbl=${tbl.id}, colId=${colId}`, '#00ff00');
  const sidebar = document.getElementById('validation-sidebar');
  if (!sidebar) {
    if (window.logToDebugPanel) window.logToDebugPanel('ERR: validation-sidebar DOM element not found', '#ff4444');
    return;
  }

  const col = tbl.columns.find(c => c.id === colId);
  if (!col) {
    if (window.logToDebugPanel) window.logToDebugPanel(`ERR: colId=${colId} not found in columns of tbl=${tbl.id}`, '#ff4444');
    return;
  }

  // 既存データから選択肢（チップ）を自動抽出してプリセット
  if (!col.choices || col.choices.length === 0) {
    const uniqueVals = new Set();
    if (tbl.rows && tbl.rows.length > 0) {
      tbl.rows.forEach(row => {
        const val = String(row[colId] || '').trim();
        if (val && val !== 'ー' && val !== '-' && val !== 'undefined' && val !== 'null') {
          uniqueVals.add(val);
        }
      });
    }

    if (uniqueVals.size > 0) {
      col.choices = Array.from(uniqueVals).map((val, idx) => {
        // 代表的なステータス値に基づく自動着色
        let color = VALIDATION_PALETTE_COLORS[idx % VALIDATION_PALETTE_COLORS.length];
        if (val.includes('申請中') || val.includes('ACTIVE') || val.includes('有効') || val.includes('承認中')) {
          color = '#3b82f6'; // 青 (Blue)
        } else if (val.includes('一時停止') || val.includes('INACTIVE') || val.includes('無効') || val.includes('停止') || val.includes('保留')) {
          color = '#f97316'; // オレンジ (Orange)
        } else if (val.includes('運営中') || val.includes('完了') || val.includes('確定') || val.includes('正常') || val.includes('アクティブ')) {
          color = '#10b981'; // 緑 (Green)
        } else if (val.includes('削除') || val.includes('却下') || val.includes('非承認') || val.includes('エラー') || val.includes('異常')) {
          color = '#ef4444'; // 赤 (Red)
        }
        return { value: val, color: color, textColor: '#ffffff' };
      });

      // 既存データが存在する場合は、基準を「リスト（ドロップダウン）」にし、スタイルを「チップ」に自動切り替え
      col.type = 'select';
      col.dropdownStyle = 'chip-outline';
    }
  }

  normalizeColChoices(col);

  activeValidationState.tbl = tbl;
  activeValidationState.colId = colId;
  activeValidationState.choices = col.choices.map(c => ({ ...c }));

  const rangeInput = document.getElementById('validation-range-input');
  if (rangeInput) {
    rangeInput.value = `${tbl.name}!${col.label}`;
  }

  // 基準（コラムタイプ）のセット
  const criteriaSelect = document.getElementById('validation-criteria-select');
  if (criteriaSelect) {
    let typeVal = 'text';
    if (col.type === 'select') typeVal = 'list';
    else if (col.type === 'date') typeVal = 'date';
    else if (col.type === 'number') typeVal = 'number';
    criteriaSelect.value = typeVal;
    updateValidationSidebarUi(typeVal);
  }

  // 日付表示形式のセット
  const dateFormatSelect = document.getElementById('validation-date-format-select');
  const customDateFormatInput = document.getElementById('validation-custom-date-format');
  if (col.type === 'date') {
    if (dateFormatSelect) {
      dateFormatSelect.value = col.dateFormat || 'YYYY/MM/DD';
      if (customDateFormatInput) {
        customDateFormatInput.value = col.customDateFormat || '';
        customDateFormatInput.style.display = dateFormatSelect.value === 'custom' ? 'block' : 'none';
      }
    }
  }

  const styleVal = col.dropdownStyle === 'arrow' ? 'arrow' : 'chip';
  const styleRadio = document.getElementById(`validation-style-${styleVal}`);
  if (styleRadio) styleRadio.checked = true;

  const chipTypeVal = col.dropdownStyle === 'chip-fill' ? 'fill' : 'outline';
  const chipTypeRadio = document.getElementById(`validation-chip-${chipTypeVal}`);
  if (chipTypeRadio) chipTypeRadio.checked = true;

  const chipContainer = document.getElementById('validation-chip-type-container');
  if (chipContainer) {
    chipContainer.style.display = styleVal === 'chip' ? 'block' : 'none';
  }

  const advContent = document.getElementById('validation-advanced-content');
  const advToggle = document.getElementById('validation-advanced-toggle');
  if (advContent) advContent.style.display = 'none';
  if (advToggle) {
    const arrow = advToggle.querySelector('.toggle-arrow');
    if (arrow) arrow.textContent = '▶';
  }

  renderValidationChoices();

  sidebar.style.display = 'flex';
  sidebar.offsetHeight; // 強制リフロー（アニメーションおよび初期描画の競合バグ防止）
  sidebar.style.transform = 'translateX(0)';

  if (window.logToDebugPanel) {
    const computed = window.getComputedStyle(sidebar);
    const rect = sidebar.getBoundingClientRect();
    window.logToDebugPanel(`Sidebar STATE: display=${sidebar.style.display}, transform=${sidebar.style.transform}, computedDisplay=${computed.display}, computedTransform=${computed.transform}, computedZIndex=${computed.zIndex}, visibility=${computed.visibility}, rect=[x:${Math.round(rect.left)},y:${Math.round(rect.top)},w:${Math.round(rect.width)},h:${Math.round(rect.height)}]`, '#00ff00');
  }

  const contextMenu = document.getElementById('ct-context-menu');
  if (contextMenu) contextMenu.style.display = 'none';
}

function updateValidationSidebarUi(criteria) {
  const optionsSection = document.getElementById('validation-options-section');
  const advancedSection = document.getElementById('validation-advanced-section');
  const dateFormatSection = document.getElementById('validation-date-format-section');

  if (criteria === 'list') {
    if (optionsSection) optionsSection.style.display = 'block';
    if (advancedSection) advancedSection.style.display = 'block';
    if (dateFormatSection) dateFormatSection.style.display = 'none';
  } else if (criteria === 'date') {
    if (optionsSection) optionsSection.style.display = 'none';
    if (advancedSection) advancedSection.style.display = 'none';
    if (dateFormatSection) dateFormatSection.style.display = 'block';
  } else {
    if (optionsSection) optionsSection.style.display = 'none';
    if (advancedSection) advancedSection.style.display = 'none';
    if (dateFormatSection) dateFormatSection.style.display = 'none';
  }
}

function closeValidationSidebar() {
  const sidebar = document.getElementById('validation-sidebar');
  if (sidebar) {
    sidebar.style.transform = 'translateX(100%)';
    setTimeout(() => {
      sidebar.style.display = 'none';
    }, 300);
  }
  const palette = document.getElementById('validation-color-palette');
  if (palette) palette.style.display = 'none';
}

function renderValidationChoices() {
  const container = document.getElementById('validation-choices-list');
  if (!container) return;
  container.innerHTML = '';

  activeValidationState.choices.forEach((choice, idx) => {
    const itemDiv = document.createElement('div');
    itemDiv.className = 'validation-choice-item';
    itemDiv.setAttribute('data-index', idx);

    const dragIcon = document.createElement('div');
    dragIcon.className = 'validation-choice-drag';
    dragIcon.textContent = '⋮⋮';
    itemDiv.appendChild(dragIcon);

    const colorBtn = document.createElement('div');
    colorBtn.className = 'validation-choice-color-btn';
    colorBtn.style.backgroundColor = choice.color || '#6366f1';
    colorBtn.title = '背景色';
    colorBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      showColorPalette(colorBtn, idx, 'color');
    });
    itemDiv.appendChild(colorBtn);

    const textColorBtn = document.createElement('div');
    textColorBtn.className = 'validation-choice-color-btn';
    textColorBtn.style.backgroundColor = choice.textColor || '#ffffff';
    textColorBtn.style.border = '1px solid var(--border-color)';
    textColorBtn.style.color = '#333333';
    textColorBtn.style.display = 'flex';
    textColorBtn.style.alignItems = 'center';
    textColorBtn.style.justifyContent = 'center';
    textColorBtn.style.fontSize = '10px';
    textColorBtn.style.fontWeight = 'bold';
    textColorBtn.style.marginLeft = '4px';
    textColorBtn.textContent = 'A';
    textColorBtn.title = '文字色';
    textColorBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      showColorPalette(textColorBtn, idx, 'textColor');
    });
    itemDiv.appendChild(textColorBtn);

    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'validation-choice-input';
    input.value = choice.value;
    input.placeholder = 'オプション名を入力';
    input.addEventListener('input', (e) => {
      activeValidationState.choices[idx].value = e.target.value;
    });
    itemDiv.appendChild(input);

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'validation-choice-remove';
    removeBtn.innerHTML = '&times;';
    removeBtn.addEventListener('click', () => {
      activeValidationState.choices.splice(idx, 1);
      renderValidationChoices();
    });
    itemDiv.appendChild(removeBtn);

    container.appendChild(itemDiv);
  });
}

function showColorPalette(targetBtn, choiceIndex, colorProperty = 'color') {
  const palette = document.getElementById('validation-color-palette');
  if (!palette) return;

  palette.innerHTML = '';
  // 文字色選択の場合は白と黒をパレットの先頭に追加して選択しやすくする
  const colors = colorProperty === 'textColor' 
    ? ['#ffffff', '#000000', ...VALIDATION_PALETTE_COLORS]
    : VALIDATION_PALETTE_COLORS;

  colors.forEach(color => {
    const circle = document.createElement('div');
    circle.className = 'palette-color-circle';
    circle.style.backgroundColor = color;
    circle.style.border = color === '#ffffff' ? '1px solid #ccc' : 'none';
    circle.addEventListener('click', () => {
      activeValidationState.choices[choiceIndex][colorProperty] = color;
      targetBtn.style.backgroundColor = color;
      palette.style.display = 'none';
    });
    palette.appendChild(circle);
  });

  const rect = targetBtn.getBoundingClientRect();
  palette.style.top = `${rect.bottom + window.scrollY + 4}px`;
  palette.style.left = `${rect.left + window.scrollX - 45}px`;
  palette.style.display = 'grid';

  const closePalette = (e) => {
    if (!palette.contains(e.target) && e.target !== targetBtn) {
      palette.style.display = 'none';
      document.removeEventListener('mousedown', closePalette, true);
    }
  };
  setTimeout(() => {
    document.addEventListener('mousedown', closePalette, true);
  }, 0);
}

function saveAndRenderValidation(tbl) {
  const tableId = tbl.id;
  const suffix = getUserIdSuffix();
  
  if (tableId === 'jo-info-screen') {
    localStorage.setItem(STORAGE_KEYS.JO_COLUMNS, JSON.stringify(state.joColumns));
    renderJoInfo();
  } else if (tableId === 'applicant-info-screen') {
    localStorage.setItem(STORAGE_KEYS.AP_COLUMNS, JSON.stringify(state.apColumns));
    renderApplicantInfo();
  } else if (tableId === 'agency-info-screen') {
    localStorage.setItem(STORAGE_KEYS.AG_COLUMNS, JSON.stringify(state.agColumns));
    renderAgencyInfo();
  } else if (tableId === 'dbmake') {
    localStorage.setItem(`SYNAPSE_DBMAKE_COLUMNS${suffix}`, JSON.stringify(state.dbmakeColumns));
    renderDbmakePartners();
  } else {
    saveCustomTables();
    renderCustomTable(tableId);
  }
}

function setupValidationSidebarEvents() {
  document.getElementById('validation-sidebar-close-btn')?.addEventListener('click', closeValidationSidebar);

  // 基準（コラムタイプ）切り替えイベント
  document.getElementById('validation-criteria-select')?.addEventListener('change', (e) => {
    updateValidationSidebarUi(e.target.value);
  });

  // 日付の表示形式切り替えイベント
  document.getElementById('validation-date-format-select')?.addEventListener('change', (e) => {
    const customInput = document.getElementById('validation-custom-date-format');
    if (customInput) {
      customInput.style.display = e.target.value === 'custom' ? 'block' : 'none';
    }
  });

  document.getElementById('validation-submit-btn')?.addEventListener('click', () => {
    if (!activeValidationState.tbl || !activeValidationState.colId) return;

    const tbl = activeValidationState.tbl;
    const col = tbl.columns.find(c => c.id === activeValidationState.colId);
    if (!col) return;

    const criteria = document.getElementById('validation-criteria-select')?.value;

    if (criteria === 'list') {
      col.type = 'select';
      col.choices = activeValidationState.choices
        .filter(c => c.value.trim() !== '')
        .map(c => ({ value: c.value.trim(), color: c.color, textColor: c.textColor || '#ffffff' }));

      const styleVal = document.querySelector('input[name="validation-display-style"]:checked')?.value;
      if (styleVal === 'arrow') {
        col.dropdownStyle = 'arrow';
      } else {
        const chipType = document.querySelector('input[name="validation-chip-type"]:checked')?.value;
        col.dropdownStyle = chipType === 'fill' ? 'chip-fill' : 'chip-outline';
      }
    } else if (criteria === 'date') {
      col.type = 'date';
      col.dateFormat = document.getElementById('validation-date-format-select')?.value || 'YYYY/MM/DD';
      if (col.dateFormat === 'custom') {
        col.customDateFormat = document.getElementById('validation-custom-date-format')?.value.trim() || 'YYYY-MM-DD';
      } else {
        col.customDateFormat = '';
      }
      col.choices = [];
    } else if (criteria === 'number') {
      col.type = 'number';
      col.choices = [];
    } else {
      col.type = 'text';
      col.choices = [];
    }

    saveAndRenderValidation(tbl);
    closeValidationSidebar();
    showToast('列の入力規則を更新しました。', 'success');
  });

  document.getElementById('validation-remove-btn')?.addEventListener('click', () => {
    if (!activeValidationState.tbl || !activeValidationState.colId) return;

    const tbl = activeValidationState.tbl;
    const col = tbl.columns.find(c => c.id === activeValidationState.colId);
    if (!col) return;

    // タイプを text に戻す（規則削除＝初期状態のテキストタイプ）
    col.type = 'text';
    col.choices = [];
    col.dropdownStyle = 'chip-outline';
    col.dateFormat = '';
    col.customDateFormat = '';

    saveAndRenderValidation(tbl);
    closeValidationSidebar();
    showToast('入力規則を削除しました。', 'success');
  });

  document.getElementById('validation-add-choice-btn')?.addEventListener('click', () => {
    const nextColor = VALIDATION_PALETTE_COLORS[activeValidationState.choices.length % VALIDATION_PALETTE_COLORS.length];
    activeValidationState.choices.push({
      value: '',
      color: nextColor
    });
    renderValidationChoices();
  });

  const advToggle = document.getElementById('validation-advanced-toggle');
  const advContent = document.getElementById('validation-advanced-content');
  if (advToggle && advContent) {
    advToggle.addEventListener('click', () => {
      const isHidden = advContent.style.display === 'none';
      advContent.style.display = isHidden ? 'block' : 'none';
      const arrow = advToggle.querySelector('.toggle-arrow');
      if (arrow) {
        arrow.textContent = isHidden ? '▼' : '▶';
      }
    });
  }

  const styleRadios = document.querySelectorAll('input[name="validation-display-style"]');
  const chipContainer = document.getElementById('validation-chip-type-container');
  styleRadios.forEach(radio => {
    radio.addEventListener('change', (e) => {
      if (chipContainer) {
        chipContainer.style.display = e.target.value === 'chip' ? 'block' : 'none';
      }
    });
  });
}

// マイページアイコンのドラッグ＆ドロップ制御（PCマウス・スマホタッチ両対応）
function setupMypageDragAndDrop() {
  const container = document.getElementById('mypage-icon-container');
  if (!container) return;

  let dragSource = null;
  const cards = container.querySelectorAll('.admin-app-icon');

  cards.forEach(card => {
    // --- PCマウスドラッグ用 ---
    card.addEventListener('dragstart', (e) => {
      dragSource = card;
      card.style.opacity = '0.4';
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', card.getAttribute('data-id'));
    });

    card.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';

      if (dragSource !== card) {
        const rect = card.getBoundingClientRect();
        const next = (e.clientY - rect.top) / (rect.bottom - rect.top) > 0.5 ||
                     (e.clientX - rect.left) / (rect.right - rect.left) > 0.5;
        
        container.insertBefore(dragSource, next ? card.nextSibling : card);
      }
    });

    card.addEventListener('dragend', () => {
      card.style.opacity = '1';
      saveMypageIconOrder();
    });

    // --- スマホ・タブレットタッチ用 ---
    let touchStartEl = null;

    card.addEventListener('touchstart', (e) => {
      touchStartEl = card;
      card.style.opacity = '0.5';
    }, { passive: true });

    card.addEventListener('touchmove', (e) => {
      if (!touchStartEl) return;

      const touch = e.touches[0];
      const x = touch.clientX;
      const y = touch.clientY;

      const elementNode = document.elementFromPoint(x, y);
      if (!elementNode) return;

      const targetCard = elementNode.closest('.admin-app-icon');
      if (targetCard && targetCard !== touchStartEl && targetCard.parentNode === container) {
        const rect = targetCard.getBoundingClientRect();
        const next = (y - rect.top) / (rect.bottom - rect.top) > 0.5 ||
                     (x - rect.left) / (rect.right - rect.left) > 0.5;
        
        container.insertBefore(touchStartEl, next ? targetCard.nextSibling : targetCard);
      }
    });

    card.addEventListener('touchend', () => {
      if (touchStartEl) {
        touchStartEl.style.opacity = '1';
        touchStartEl = null;
        saveMypageIconOrder();
      }
    });
  });
}

// マイページの現在のアイコン順序をローカルおよびクラウドへ保存
function saveMypageIconOrder() {
  const container = document.getElementById('mypage-icon-container');
  if (!container) return;

  const currentOrder = Array.from(container.querySelectorAll('.admin-app-icon')).map(card => {
    return card.getAttribute('data-id');
  });

  const userId = state.currentUser ? state.currentUser.id : 'guest';
  const storageKey = `SYNAPSE_MYPAGE_ICON_ORDER_${userId}`;
  localStorage.setItem(storageKey, JSON.stringify(currentOrder));

  // 既存の background_settings とマージして保存
  const settingsKey = `SYNAPSE_BG_SETTINGS_${userId}`;
  let bgSettings = {};
  try {
    const raw = localStorage.getItem(settingsKey);
    if (raw) bgSettings = JSON.parse(raw);
  } catch (e) {
    console.error("[Settings] Failed to parse existing bg settings:", e);
  }

  bgSettings.iconOrder = currentOrder;
  localStorage.setItem(settingsKey, JSON.stringify(bgSettings));
  console.log("[Mypage] Saved icon order:", currentOrder);
}

// マイページのアイコン順序を適用（DOM要素の再配置）
function applyMypageIconOrder() {
  const container = document.getElementById('mypage-icon-container');
  if (!container) return;

  const userId = state.currentUser ? state.currentUser.id : 'guest';
  let order = null;
  const orderKey = `SYNAPSE_MYPAGE_ICON_ORDER_${userId}`;
  const settingsKey = `SYNAPSE_BG_SETTINGS_${userId}`;
  
  try {
    const bgRaw = localStorage.getItem(settingsKey);
    if (bgRaw) {
      const bgSettings = JSON.parse(bgRaw);
      if (bgSettings && bgSettings.iconOrder) {
        order = bgSettings.iconOrder;
      }
    }
    if (!order) {
      const orderRaw = localStorage.getItem(orderKey);
      if (orderRaw) order = JSON.parse(orderRaw);
    }
  } catch (e) {
    console.error("[Mypage] Failed to load icon order settings:", e);
  }

  if (!order || !Array.isArray(order)) return;

  const cardMap = {};
  const cards = container.querySelectorAll('.admin-app-icon');
  cards.forEach(card => {
    const id = card.getAttribute('data-id');
    if (id) cardMap[id] = card;
  });

  order.forEach(id => {
    const card = cardMap[id];
    if (card) {
      container.appendChild(card);
      delete cardMap[id];
    }
  });

  Object.values(cardMap).forEach(card => {
    container.appendChild(card);
  });
}

