        renderLeftSidebarMembers();
        renderDefaultShareMemberList();
        renderFormShareMemberList();
        
        // カレンダー表示も更新（予定フィルタリングを再適用）
        renderMypageCalendar();
        
        // モーダルを閉じる
        if (shareModal) shareModal.style.display = 'none';
