  // 3. 左サイドバーのメンバーリストを描画
  function renderLeftSidebarMembers() {
    const listContainer = document.getElementById('calendar-filter-member-list');
    if (!listContainer) return;
    
    listContainer.innerHTML = '';
    
    synapseMembers.forEach(member => {
      const isMe = state.currentUser && member.id === state.currentUser.id;
      const isAllowed = isMe || (state.calendarAllowedShareMembers && state.calendarAllowedShareMembers.includes(member.id));
      if (!isAllowed) return;

      const isChecked = calendarFilteredMembers.includes(member.id);
      
      const item = document.createElement('div');
      item.className = 'calendar-member-item';
      item.onclick = () => {
        toggleMemberFilter(member.id);
      };
      
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = isChecked;
      checkbox.style.margin = '0';
      checkbox.style.cursor = 'pointer';
      checkbox.onclick = (e) => e.stopPropagation();
      checkbox.onchange = () => toggleMemberFilter(member.id);
      
      const avatar = document.createElement('div');
      avatar.className = 'calendar-member-avatar';
      avatar.style.background = member.color;
      avatar.textContent = member.name.charAt(0);
      
      const name = document.createElement('span');
      name.className = 'calendar-member-name';
      name.textContent = member.name;
      
      // Google連携マークの付与（ログインユーザー本人が実際に連携中の場合のみ表示）
      if (member.id === (state.currentUser ? state.currentUser.id : 'guest') && isGoogleLinked) {
        name.innerHTML += ' <span style="font-size: 0.62rem; background: rgba(66, 133, 244, 0.1); color: #4285F4; padding: 1px 4px; border-radius: 4px; font-weight: bold; margin-left: 4px;">Google</span>';
      }
      
      item.appendChild(checkbox);
      item.appendChild(avatar);
      item.appendChild(name);
      
      listContainer.appendChild(item);
    });
  }

  // メンバー表示フィルターのオンオフ
  function toggleMemberFilter(memberId) {
    const idx = calendarFilteredMembers.indexOf(memberId);
    if (idx === -1) {
      calendarFilteredMembers.push(memberId);
    } else {
      calendarFilteredMembers.splice(idx, 1);
    }
    updateMemberFilterUI();
    renderMypageCalendar();
  }

  function updateMemberFilterUI() {
    renderLeftSidebarMembers();
  }

  // 4. マンスリーカレンダーの描画
  function renderMypageCalendar() {
    const daysGrid = document.getElementById('calendar-days-grid');
    const monthYearTitle = document.getElementById('calendar-month-year');
    const weekHeader = document.getElementById('calendar-week-days-header');
    const timelineContainer = document.getElementById('calendar-timeline-container');
    if (!daysGrid || !monthYearTitle) return;

    daysGrid.innerHTML = '';
    if (timelineContainer) timelineContainer.innerHTML = '';
    
    const year = calendarCurrentDate.getFullYear();
    const month = calendarCurrentDate.getMonth();
    
    const dayNames = ['日', '月', '火', '水', '木', '金', '土'];
    
    if (state.calendarViewMode === 'day') {
      if (weekHeader) weekHeader.style.display = 'none';
      daysGrid.style.display = 'none';
      if (timelineContainer) timelineContainer.style.display = 'block';
      
      const dayJp = dayNames[calendarCurrentDate.getDay()];
      monthYearTitle.textContent = `${year}年 ${month + 1}月 ${calendarCurrentDate.getDate()}日 (${dayJp})`;
      
      // 予定データ（全件）を取り込む
      const visibleEvents = getVisibleEventsForMonth(year, month);
      const dayEvents = visibleEvents.filter(ev => {
        const evStart = new Date(ev.start_time);
        return evStart.getDate() === calendarCurrentDate.getDate() && 
               evStart.getMonth() === calendarCurrentDate.getMonth() && 
               evStart.getFullYear() === calendarCurrentDate.getFullYear();
      });
      
      if (timelineContainer) {
        const timelineWrapper = document.createElement('div');
        timelineWrapper.style.display = 'flex';
        timelineWrapper.style.position = 'relative';
        timelineWrapper.style.height = '1440px'; // 24時間 * 60px
        timelineWrapper.style.width = '100%';
        
        const leftAxis = document.createElement('div');
        leftAxis.style.width = '60px';
        leftAxis.style.minWidth = '60px';
        leftAxis.style.borderRight = '1px solid var(--border-color)';
        leftAxis.style.position = 'relative';
        leftAxis.style.background = 'rgba(var(--bg-surface-rgb), 0.5)';
        
        const rightCanvas = document.createElement('div');
        rightCanvas.style.flex = '1';
        rightCanvas.style.position = 'relative';
        rightCanvas.style.height = '1440px';
        
        // 24時間スロット生成
        for (let h = 0; h < 24; h++) {
          const timeLabel = document.createElement('div');
          timeLabel.style.position = 'absolute';
          timeLabel.style.top = `${h * 60}px`;
          timeLabel.style.width = '100%';
          timeLabel.style.height = '60px';
          timeLabel.style.fontSize = '0.72rem';
          timeLabel.style.color = 'var(--text-secondary)';
          timeLabel.style.textAlign = 'right';
          timeLabel.style.paddingRight = '8px';
          timeLabel.style.paddingTop = '4px';
          timeLabel.style.boxSizing = 'border-box';
          timeLabel.textContent = `${h}:00`;
          leftAxis.appendChild(timeLabel);
          
          const hourGridLine = document.createElement('div');
          hourGridLine.style.position = 'absolute';
          hourGridLine.style.top = `${h * 60}px`;
          hourGridLine.style.left = '0';
          hourGridLine.style.right = '0';
          hourGridLine.style.height = '60px';
          hourGridLine.style.borderBottom = '1px dashed var(--border-color)';
          hourGridLine.style.boxSizing = 'border-box';
          rightCanvas.appendChild(hourGridLine);
        }
        
        timelineWrapper.appendChild(leftAxis);
        timelineWrapper.appendChild(rightCanvas);
        timelineContainer.appendChild(timelineWrapper);
        
        // 重なり合い（コンフリクト）の調整
        const processedEvents = dayEvents.map(ev => {
          const start = new Date(ev.start_time);
          const end = new Date(ev.end_time);
          
          const startMin = start.getHours() * 60 + start.getMinutes();
          const endMin = end.getHours() * 60 + end.getMinutes();
          const duration = Math.max(30, endMin - startMin); // 最小30分
          
          return {
            event: ev,
            start: startMin,
            end: startMin + duration,
            col: 0,
            maxCols: 1
          };
        });
        
        processedEvents.sort((a, b) => a.start - b.start);
        
        for (let i = 0; i < processedEvents.length; i++) {
          const current = processedEvents[i];
          const overlaps = [];
          for (let j = 0; j < i; j++) {
            const prev = processedEvents[j];
            if (current.start < prev.end && current.end > prev.start) {
              overlaps.push(prev);
            }
          }
          
          if (overlaps.length > 0) {
            const usedCols = overlaps.map(o => o.col);
            let myCol = 0;
            while (usedCols.includes(myCol)) {
              myCol++;
            }
            current.col = myCol;
            
            const totalGroup = overlaps.concat(current);
            const neededCols = Math.max(...totalGroup.map(o => o.col)) + 1;
            
            totalGroup.forEach(g => {
              g.maxCols = Math.max(g.maxCols, neededCols);
            });
            
            overlaps.forEach(o => {
              processedEvents.forEach(p => {
                if (p !== o && p !== current && (p.start < o.end && p.end > o.start)) {
                  p.maxCols = Math.max(p.maxCols, neededCols);
                }
              });
            });
          }
        }
        
        processedEvents.forEach(p => {
          const ev = p.event;
          const card = document.createElement('div');
          card.className = 'timeline-event-card';
          if (ev.is_google_event) {
            card.classList.add('google-event');
          } else if (ev.id && ev.id.startsWith('google-task-')) {
            // Google To-Do スタイル
            card.style.backgroundColor = ev.status === 'completed' ? 'var(--bg-hover)' : 'rgba(59, 130, 246, 0.08)';
            card.style.color = ev.status === 'completed' ? 'var(--text-muted)' : 'var(--primary)';
            card.style.borderLeft = `4px solid var(--primary)`;
            card.style.borderTop = '1px solid rgba(59, 130, 246, 0.15)';
            card.style.borderRight = '1px solid rgba(59, 130, 246, 0.15)';
            card.style.borderBottom = '1px solid rgba(59, 130, 246, 0.15)';
            if (ev.status === 'completed') card.style.textDecoration = 'line-through';
          } else if (ev.id && ev.id.startsWith('asana-')) {
            // Asana スタイル
            card.style.backgroundColor = ev.status === 'completed' ? 'var(--bg-hover)' : 'rgba(224, 79, 95, 0.08)';
            card.style.color = ev.status === 'completed' ? 'var(--text-muted)' : '#e04f5f';
            card.style.borderLeft = `4px solid #e04f5f`;
            card.style.borderTop = '1px solid rgba(224, 79, 95, 0.15)';
            card.style.borderRight = '1px solid rgba(224, 79, 95, 0.15)';
            card.style.borderBottom = '1px solid rgba(224, 79, 95, 0.15)';
            if (ev.status === 'completed') card.style.textDecoration = 'line-through';
          } else {
            card.style.backgroundColor = ev.color || '#3b82f6';
            card.style.color = 'white';
          }
          
          const top = p.start;
          const height = p.end - p.start;
          const widthPercent = 100 / p.maxCols;
          const leftPercent = p.col * widthPercent;
          
          card.style.top = `${top}px`;
          card.style.height = `${height}px`;
          card.style.width = `calc(${widthPercent}% - 6px)`;
          card.style.left = `calc(${leftPercent}% + 3px)`;
          
          const titleEl = document.createElement('div');
          titleEl.className = 'card-title';
          titleEl.textContent = ev.is_google_event ? `G: ${ev.title}` : ev.title;
          
          const timeEl = document.createElement('div');
          timeEl.className = 'card-time';
          const start = new Date(ev.start_time);
          const end = new Date(ev.end_time);
          const formatTime = (d) => String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
          timeEl.textContent = `${formatTime(start)} - ${formatTime(end)}`;
          
          card.appendChild(titleEl);
          card.appendChild(timeEl);
          
          if (!ev.is_google_event && ev.user_name) {
            const metaEl = document.createElement('div');
            metaEl.className = 'card-meta';
            metaEl.textContent = `${ev.category} / ${ev.user_name}`;
            card.appendChild(metaEl);
          }
          
          const isMine = !ev.is_google_event ? (ev.user_id === me) : (ev.category !== '祝日');
          if (isMine) {
            card.style.cursor = 'grab';
            
            card.onmousedown = (e) => {
              let isDragging = false;
              const startY = e.clientY;
              const startTop = top;
              const duration = p.end - p.start;
              
              card.style.cursor = 'grabbing';
              card.style.zIndex = '1000';
              card.style.opacity = '0.8';
              
              const onMouseMove = (moveEvent) => {
                isDragging = true;
                const deltaY = moveEvent.clientY - startY;
                let newTop = startTop + deltaY;
                
                // 15分(15px)単位にスナップ
                newTop = Math.round(newTop / 15) * 15;
                
                // 範囲制限 (0 〜 1440 - duration)
                newTop = Math.max(0, Math.min(1440 - duration, newTop));
                
                card.style.top = `${newTop}px`;
                
                // ドラッグ中のプレビュー時刻を一時表示
                const tempStartHour = Math.floor(newTop / 60);
                const tempStartMin = newTop % 60;
                const tempEndHour = Math.floor((newTop + duration) / 60);
                const tempEndMin = (newTop + duration) % 60;
                const formatNum = (n) => String(n).padStart(2, '0');
                timeEl.textContent = `${formatNum(tempStartHour)}:${formatNum(tempStartMin)} - ${formatNum(tempEndHour)}:${formatNum(tempEndMin)} (移動中)`;
              };
              
              const onMouseUp = async (upEvent) => {
                document.removeEventListener('mousemove', onMouseMove);
                document.removeEventListener('mouseup', onMouseUp);
                
                card.style.cursor = 'grab';
                card.style.zIndex = '';
                card.style.opacity = '';
                
                if (!isDragging) {
                  // ドラッグされなかった場合は通常のクリック（編集フォーム読み込み）
                  calendarSelectedDate = start;
                  updateSelectedDateLabel();
                  loadEventsForSelectedDate();
                  selectEventForEdit(ev);
                  return;
                }
                
                // ドラッグ終了時の位置から最終時間を決定
                let finalTop = parseInt(card.style.top);
                const newStartHour = Math.floor(finalTop / 60);
                const newStartMin = finalTop % 60;
                const newEndTotal = finalTop + duration;
                const newEndHour = Math.floor(newEndTotal / 60);
                const newEndMin = newEndTotal % 60;
                
                // 重複チェック
                let hasConflict = false;
                
                // 同日の他のすべての表示予定（自分自身を除く）
                const otherEvents = dayEvents.filter(other => other.id !== ev.id);
                for (const other of otherEvents) {
                  const oStart = new Date(other.start_time);
                  const oEnd = new Date(other.end_time);
                  const oStartMin = oStart.getHours() * 60 + oStart.getMinutes();
                  const oEndMin = oEnd.getHours() * 60 + oEnd.getMinutes();
                  
                  // 重複しているか
                  if (oStartMin < newEndTotal && oEndMin > finalTop) {
                    hasConflict = true;
                    break;
                  }
                }
                
                if (hasConflict) {
                  showToast('他の予定と時間が重複するため移動できません。', 'warning');
                  // 元の位置に戻す
                  card.style.top = `${startTop}px`;
                  const originalStart = new Date(ev.start_time);
                  const originalEnd = new Date(ev.end_time);
                  timeEl.textContent = `${formatTime(originalStart)} - ${formatTime(originalEnd)}`;
                  return;
                }
                
                // 時間を変更して保存
                const newStart = new Date(start);
                newStart.setHours(newStartHour, newStartMin, 0, 0);
                const newEnd = new Date(end);
                newEnd.setHours(newEndHour, newEndMin, 0, 0);
                
                ev.start_time = newStart.toISOString();
                ev.end_time = newEnd.toISOString();
                
                // DB更新処理
                if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
                  try {
                    if (ev.is_google_event) {
                      const googleEventId = ev.id.replace('google-', '');
                      await updateGoogleCalendarEventTime(googleEventId, ev.title, ev.start_time, ev.end_time);
                    } else {
                      await partnerSupabaseClient
                        .from('synapse_calendar_events')
                        .update({
                          start_time: ev.start_time,
                          end_time: ev.end_time
                        })
                        .eq('id', ev.id);
                    }
                  } catch (e) {
                    console.error("Failed to save dragged event:", e);
                    showToast('予定の保存に失敗しました。', 'error');
                  }
                }
                
                // メモリ・ローカルストレージ更新
                localStorage.setItem(`SYNAPSE_USER_CALENDAR_EVENTS_${me}`, JSON.stringify(state.calendarEvents));
                showToast('予定を移動しました。', 'success');
                
                renderMypageCalendar();
                loadEventsForSelectedDate();
              };
              
              document.addEventListener('mousemove', onMouseMove);
              document.addEventListener('mouseup', onMouseUp);
            };
          } else {
            // 他人の予定の場合はクリック閲覧のみ
            card.onclick = (e) => {
              e.stopPropagation();
              calendarSelectedDate = start;
              updateSelectedDateLabel();
              loadEventsForSelectedDate();
              selectEventForEdit(ev);
            };
          }
          
          rightCanvas.appendChild(card);
        });
        
        // 朝8時に自動スクロール
        setTimeout(() => {
          timelineContainer.scrollTop = 480;
        }, 100);
      }
      return;
    }

    // 月・週表示の時は曜日ヘッダーとグリッドを表示
    if (weekHeader) weekHeader.style.display = 'grid';
    daysGrid.style.display = 'grid';
    if (timelineContainer) timelineContainer.style.display = 'none';

    let totalGridCount = 42;
    let startDate = null;
    
    if (state.calendarViewMode === 'week') {
      daysGrid.classList.add('week-view');
      totalGridCount = 7;
      
      const current = new Date(calendarCurrentDate);
      const currentDay = current.getDay();
      startDate = new Date(current);
      startDate.setDate(current.getDate() - currentDay);
      
      const endOfWeek = new Date(startDate);
      endOfWeek.setDate(startDate.getDate() + 6);
      
      const startStr = `${startDate.getMonth() + 1}/${startDate.getDate()}`;
      const endStr = `${endOfWeek.getMonth() + 1}/${endOfWeek.getDate()}`;
      monthYearTitle.textContent = `${startDate.getFullYear()}年 ${startDate.getMonth() + 1}月 (${startStr}〜${endStr})`;
    } else {
      daysGrid.classList.remove('week-view');
      totalGridCount = 42;
      
      const firstDayIndex = new Date(year, month, 1).getDay();
      startDate = new Date(year, month, 1 - firstDayIndex);
      
      monthYearTitle.textContent = `${year}年 ${month + 1}月`;
    }
    
    const visibleEvents = getVisibleEventsForMonth(year, month);
    
    for (let i = 0; i < totalGridCount; i++) {
      const cellDate = new Date(startDate);
      cellDate.setDate(startDate.getDate() + i);
      const dayNum = cellDate.getDate();
      
      const cell = document.createElement('div');
      cell.className = 'calendar-day-cell';
      
      if (state.calendarViewMode === 'month' && cellDate.getMonth() !== month) {
        cell.classList.add('other-month');
      }
      
      const today = new Date();
      if (cellDate.getDate() === today.getDate() && cellDate.getMonth() === today.getMonth() && cellDate.getFullYear() === today.getFullYear()) {
        cell.classList.add('today');
      }
      
      if (cellDate.getDate() === calendarSelectedDate.getDate() && cellDate.getMonth() === calendarSelectedDate.getMonth() && cellDate.getFullYear() === calendarSelectedDate.getFullYear()) {
        cell.classList.add('selected');
      }
      
      const dayNumberEl = document.createElement('span');
      dayNumberEl.className = 'day-number';
      if (state.calendarViewMode === 'week') {
        dayNumberEl.textContent = `${cellDate.getMonth() + 1}/${dayNum}`;
      } else {
        dayNumberEl.textContent = dayNum;
      }
      cell.appendChild(dayNumberEl);
      
      const eventContainer = document.createElement('div');
      eventContainer.className = 'calendar-cell-events';
      
      const dayEvents = visibleEvents.filter(ev => {
        const evStart = new Date(ev.start_time);
        return evStart.getDate() === cellDate.getDate() && 
               evStart.getMonth() === cellDate.getMonth() && 
               evStart.getFullYear() === cellDate.getFullYear();
      });

      dayEvents.sort((a, b) => new Date(a.start_time) - new Date(b.start_time));

      const maxDisplay = state.calendarViewMode === 'week' ? 8 : 3;
      dayEvents.slice(0, maxDisplay).forEach(ev => {
        const evMicro = document.createElement('div');
        evMicro.className = 'calendar-event-micro';
        
        if (state.calendarViewMode === 'week') {
          const evStart = new Date(ev.start_time);
          const evEnd = new Date(ev.end_time);
          const formatTime = (d) => String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
          evMicro.setAttribute('data-time', `${formatTime(evStart)} - ${formatTime(evEnd)}`);
        }
        
        if (ev.is_google_event) {
          evMicro.classList.add('google-event');
          evMicro.textContent = `G: ${ev.title}`;
          evMicro.title = `[Google] ${ev.title}`;
        } else {
          evMicro.textContent = ev.title;
          
          if (ev.id && ev.id.startsWith('google-task-')) {
            // Google To-Do スタイル (薄い青背景、濃い青文字、左端太い青線)
            if (ev.status === 'completed') {
              evMicro.style.backgroundColor = 'var(--bg-hover)';
              evMicro.style.color = 'var(--text-muted)';
              evMicro.style.borderLeft = '3px solid var(--text-muted)';
              evMicro.style.textDecoration = 'line-through';
            } else {
              evMicro.style.backgroundColor = 'rgba(59, 130, 246, 0.08)';
              evMicro.style.color = 'var(--primary)';
              evMicro.style.border = '1px solid rgba(59, 130, 246, 0.15)';
              evMicro.style.borderLeft = '3px solid var(--primary)';
            }
            evMicro.title = `[Google To-Do] ${ev.title}`;
          } else if (ev.id && ev.id.startsWith('asana-')) {
            // Asana スタイル (薄い赤背景、濃い赤文字、左端太い赤線)
            if (ev.status === 'completed') {
              evMicro.style.backgroundColor = 'var(--bg-hover)';
              evMicro.style.color = 'var(--text-muted)';
              evMicro.style.borderLeft = '3px solid var(--text-muted)';
              evMicro.style.textDecoration = 'line-through';
            } else {
              evMicro.style.backgroundColor = 'rgba(224, 79, 95, 0.08)';
              evMicro.style.color = '#e04f5f';
              evMicro.style.border = '1px solid rgba(224, 79, 95, 0.15)';
              evMicro.style.borderLeft = '3px solid #e04f5f';
            }
            evMicro.title = `[Asana] ${ev.title}`;
          } else {
            // 通常予定
            evMicro.style.backgroundColor = ev.color || '#3b82f6';
            evMicro.style.color = 'white';
            evMicro.style.borderLeft = 'none';
            evMicro.title = `[${ev.category}] ${ev.title} (${ev.user_name || '不明'})`;
          }
        }
        
        // クリック時に予定編集フォームを開く
        evMicro.onclick = (e) => {
          e.stopPropagation();
          selectEventForEdit(ev);
        };
        
        eventContainer.appendChild(evMicro);
      });

      if (dayEvents.length > maxDisplay) {
        const moreBadge = document.createElement('div');
        moreBadge.style.fontSize = '0.62rem';
        moreBadge.style.color = 'var(--text-secondary)';
        moreBadge.style.textAlign = 'right';
        moreBadge.style.fontWeight = 'bold';
        moreBadge.style.paddingRight = '2px';
        moreBadge.textContent = `他 +${dayEvents.length - maxDisplay}件`;
        eventContainer.appendChild(moreBadge);
      }
      
      cell.appendChild(eventContainer);
      
      // セルクリック時のイベント (自動的に「日表示」へ切り替えるズームイン連動)
      cell.onclick = () => {
        calendarSelectedDate = cellDate;
        calendarCurrentDate = cellDate; // 日表示の基準日も合わせる
        state.calendarViewMode = 'day';
        
        const vMonth = document.getElementById('calendar-view-month');
        const vWeek = document.getElementById('calendar-view-week');
        const vDay = document.getElementById('calendar-view-day');
        if (vMonth && vWeek && vDay) {
          vDay.classList.add('active');
          vMonth.classList.remove('active');
          vWeek.classList.remove('active');
          vDay.style.background = 'var(--primary)';
          vDay.style.color = 'white';
          vMonth.style.background = 'transparent';
          vMonth.style.color = 'var(--text-secondary)';
          vWeek.style.background = 'transparent';
          vWeek.style.color = 'var(--text-secondary)';
        }
        
        renderMypageCalendar();
        updateSelectedDateLabel();
        loadEventsForSelectedDate();
        resetEventForm();
      };

      daysGrid.appendChild(cell);
    }
  }

  // 指定年月かつフィルターに合致する予定を取得（Google予定も含む）
  function getVisibleEventsForMonth(year, month) {
    let events = [];
    const me = state.currentUser ? state.currentUser.id.toLowerCase() : 'guest';
    const isMeAllowed = isOwnerUser() || me === 'owner' || me === 'owner@synapse.management' || (state.calendarAllowedShareMembers && state.calendarAllowedShareMembers.map(m => m.toLowerCase()).includes(me));
    
    // 通常予定（ローカル/Supabase）のフィルタリング
    if (state.calendarEvents) {
      events = state.calendarEvents.filter(ev => {
        // デモ用モック予定は完全に除外する（IDが 'dummy-' で始まる、またはダミーユーザーの予定）
        if (ev.id && ev.id.startsWith('dummy-')) return false;
        if (ev.user_id === 'sales_01@synapse.management' || ev.user_id === 'sales_02@synapse.management') return false;

        // Google予定ではないこと
        if (ev.is_google_event) return false;
        
        // 独自タスク（ToDoカテゴリ）は以下の独立したマッピングで描画するため、ここからは一旦除外する
        if (ev.category === 'ToDo' && ev.id && ev.id.startsWith('task-')) return false;
        
        const isOwner = ev.user_id && ev.user_id.toLowerCase() === me;
        
        // 作成者がオーナーからカレンダー共有を許可されていること（本人は常に表示）
        const isCreatorAllowed = (ev.user_id && ev.user_id.toLowerCase() === me) || (state.calendarAllowedShareMembers && state.calendarAllowedShareMembers.map(m => m.toLowerCase()).includes(ev.user_id.toLowerCase()));
        if (!isCreatorAllowed) return false;
        
        // ログインユーザー自身がオーナーから共有許可されていない場合、他人の予定は一切見えない
        if (!isMeAllowed && !isOwner) return false;

        // 作成者が表示対象 of メンバーに含まれていること（自分自身の予定は常に表示）
        if (!isOwner && !calendarFilteredMembers.map(m => m.toLowerCase()).includes(ev.user_id.toLowerCase())) return false;
        
        // ログインユーザーの閲覧権限があるか（RLSと同様のフロントエンドでの検算）
        const isSharedAll = ev.shared_with && ev.shared_with.includes('*');
        const isSharedMe = ev.shared_with && ev.shared_with.map(m => m.toLowerCase()).includes(me);
        
        return isOwner || isSharedAll || isSharedMe;
      });
    }

    // 本物のGoogleカレンダー予定（同期データ）のフィルタリングとマージ
    if (state.calendarEvents) {
      const realGoogleEvents = state.calendarEvents.filter(ev => {
        if (!ev.is_google_event) return false;

        // 日本の祝日は常に表示する
        if (ev.category === '祝日') return true;

        // ログインユーザー自身のGoogle予定（user_id === me）は、無条件で常に表示する
        if (ev.user_id && ev.user_id.toLowerCase() === me) return true;

        // 連携中のGoogleアカウントの予定のみを無条件で常に描画する
        if (isGoogleLinked && googleLinkedEmail && ev.user_name && ev.user_name.toLowerCase() === googleLinkedEmail.toLowerCase()) {
          return true;
        }

        // 他人のGoogle予定は、表示フィルター（チェックボックス）でチェックが入っているメンバーのもののみを描画
        const isUserChecked = calendarFilteredMembers.some(m => ev.user_id && m.toLowerCase() === ev.user_id.toLowerCase());
        return isUserChecked;
      });
      events = events.concat(realGoogleEvents);
    }

    // Googleカレンダー予定（ダミーのモックデータ）のフィルタリングとマージ
    synapseMembers.forEach(member => {
      const isOwner = member.id === me;
      const isMemberAllowed = isOwner || (state.calendarAllowedShareMembers && state.calendarAllowedShareMembers.includes(member.id));
      if (!isMemberAllowed) return;

      if (!isMeAllowed && !isOwner) return;

      // フィルターでチェックが入っているメンバーのみGoogle同期イベントを描画
      if (calendarFilteredMembers.includes(member.id)) {
        const dummyGoogle = getGoogleDummyEventsForMember(member.id);
        events = events.concat(dummyGoogle);
      }
    });

    // --- 📋 ToDoタスク（Google Tasks ＆ 独自タスク）の制御・マージ ---
    if (state.calendarShowTasks !== false) {
      // 1. Synapse独自タスクの抽出とカレンダーイベントへのマッピング
      if (typeof todoTasks !== 'undefined' && todoTasks.length > 0) {
        todoTasks.forEach(task => {
          if (!task.due || task.show_on_calendar === false) return;

          // 共有権限チェック
          const isOwner = task.user_id === me;
          const isSharedAll = task.shared_with && task.shared_with.includes('*');
          const isSharedMe = task.shared_with && task.shared_with.map(m => m.toLowerCase()).includes(me);

          if (!isOwner && !isSharedAll && !isSharedMe) return;

          // 表示フィルター（チェックボックス）のチェック状態を確認（他人のタスクの場合）
          if (!isOwner && !calendarFilteredMembers.map(m => m.toLowerCase()).includes(task.user_id.toLowerCase())) return;

          let label = task.status === 'completed' ? '✓ ' : '○ ';
          if (task.id.startsWith('google-task-')) {
            label += '🔹 ';
          } else if (task.id.startsWith('asana-')) {
            label += '🔺 ';
          }

          events.push({
            id: task.id,
            title: label + task.title,
            start_time: task.due + 'T00:00:00',
            end_time: task.due + 'T23:59:59',
            all_day: true,
            category: 'ToDo',
            notes: task.notes,
            status: task.status,
            user_id: task.user_id,
            user_name: task.user_name || task.user_id,
            is_todo_task: true,
            color: task.status === 'completed' ? '#94a3b8' : '#f59e0b' // 完了はグレー、未完了はアンバー
          });
        });
      }
    } else {
      // タスク非表示（トグルOFF）の場合：すべてのタスク（Google TasksおよびカテゴリToDo）をカレンダーから除外
      events = events.filter(ev => {
        const isGoogleTask = ev.id && ev.id.startsWith('google-task-');
        const isTodoCategory = ev.category === 'ToDo';
        return !isGoogleTask && !isTodoCategory;
      });
    }

    // ★ カレンダー表示対象フィルター（10択）の適用 ★
    const displayFilter = state.calendarDisplayFilter || 'all-events';
    if (displayFilter !== 'all-events') {
      events = events.filter(ev => {
        // 日本の祝日は常に表示する
        if (ev.category === '祝日') return true;

        const isTodo = ev.is_todo_task === true || ev.category === 'ToDo' || (ev.id && (ev.id.startsWith('task-') || ev.id.startsWith('google-task-')));
        const isAsana = ev.id && ev.id.startsWith('asana-');
        const isEvent = !isTodo && !isAsana; // 一般予定

        const isMyItem = ev.user_id && (ev.user_id.toLowerCase() === me || (googleLinkedEmail && ev.user_id.toLowerCase() === googleLinkedEmail.toLowerCase()));

        switch (displayFilter) {
          case 'my-events-only': // 自分の予定のみ反映
            return isEvent && isMyItem;

          case 'shared-members-only': // 共有しているメンバーのみ反映
            return isEvent && !isMyItem;

          case 'shared-with-me': // 自分と共有しているメンバーの反映
            if (!isEvent || isMyItem) return false;
            // 共有先に自分が含まれている、または全員共有 '*'
            const isSharedAll = ev.shared_with && ev.shared_with.includes('*');
            const isSharedMe = ev.shared_with && ev.shared_with.map(m => m.toLowerCase()).includes(me);
            return isSharedAll || isSharedMe;

          case 'todo-only': // ToDo リストのみ反映
            return isTodo;

          case 'my-events-and-todo': // 自分の予定と自分のToDoリストの反映
            return (isEvent && isMyItem) || (isTodo && isMyItem);

          case 'asana-only': // Asana のみ反映
            return isAsana;

          case 'my-events-and-asana': // 自分の予定とAsanaの反映
            return (isEvent && isMyItem) || (isAsana && isMyItem);

          case 'asana-and-todo': // AsanaとTodoの反映
            return isAsana || isTodo;

          case 'my-events-asana-todo': // 自分の予定とAsanaとTodoの反映
            return (isEvent && isMyItem) || (isAsana && isMyItem) || (isTodo && isMyItem);

          case 'shared-members-asana': // 共有しているメンバーのAsanaの反映
            return isAsana && !isMyItem;

          default:
            return true;
        }
      });
    }

    console.log(`[Calendar Debug] Total raw events: ${state.calendarEvents ? state.calendarEvents.length : 0}, filtered visible events for ${year}/${month + 1}: ${events.length}`);
    if (events.length > 0) {
      console.log(`[Calendar Debug] Sample Event 0 details:`, {
        id: events[0].id,
        title: events[0].title,
        start_time: events[0].start_time,
        parsed_date: new Date(events[0].start_time).toString(),
        is_google_event: events[0].is_google_event,
        user_id: events[0].user_id,
        user_name: events[0].user_name
      });
      const matches = events.filter(ev => {
        const d = new Date(ev.start_time);
        return d.getFullYear() === year && d.getMonth() === month;
      });
      console.log(`[Calendar Debug] Of the visible events, ${matches.length} matches the target month ${year}/${month + 1}`);
    }
    return events;
  }

