  // 5. 予定のCRUDアクション

  // 新規追加用にフォームをリセット
  function resetEventForm() {
    const eventIdInput = document.getElementById('calendar-form-event-id');
    if (!eventIdInput) return; // UIがDOMにない場合はスキップ

    eventIdInput.value = '';
    document.getElementById('calendar-form-title').value = '';
    document.getElementById('calendar-form-start-time').value = '09:00';
    document.getElementById('calendar-form-end-time').value = '10:00';
    document.getElementById('calendar-form-category').value = '一般';
    document.getElementById('calendar-form-color').value = '#3b82f6';
    document.getElementById('calendar-form-location').value = '';
    document.getElementById('calendar-form-desc').value = '';
    
    const shareTypeSelect = document.getElementById('calendar-form-share-type');
    if (shareTypeSelect) {
      const me = state.currentUser ? state.currentUser.id : 'guest';
      const defaultShareType = localStorage.getItem(`SYNAPSE_CALENDAR_DEFAULT_SHARE_TYPE_${me}`) || 'private';
      shareTypeSelect.value = defaultShareType;
      shareTypeSelect.dispatchEvent(new Event('change'));
      
      if (defaultShareType === 'select') {
        const defaultMembersData = localStorage.getItem(`SYNAPSE_CALENDAR_DEFAULT_SHARE_MEMBERS_${me}`);
        const defaultMembers = defaultMembersData ? JSON.parse(defaultMembersData) : [];
        setTimeout(() => {
          const listContainer = document.getElementById('calendar-form-share-members-list');
          if (listContainer) {
            const inputs = listContainer.querySelectorAll('input[type="checkbox"]');
            inputs.forEach(input => {
              input.checked = defaultMembers.includes(input.value);
            });
          }
        }, 50);
      }
    }

    // 新規登録のため全フィールドを有効化し、削除ボタンを非表示にする
    enableFormFields(true);
    const deleteBtn = document.getElementById('calendar-event-delete-btn');
    if (deleteBtn) deleteBtn.style.display = 'none';
  }

  // 既存予定をフォームに読み込む
  function selectEventForEdit(event) {
    const me = state.currentUser ? state.currentUser.id : 'guest';
    const isGoogle = event.is_google_event;
    const isMine = !isGoogle ? (event.user_id === me) : (event.category !== '祝日');

    document.getElementById('calendar-form-event-id').value = event.id;
    document.getElementById('calendar-form-title').value = event.title;
    
    const start = new Date(event.start_time);
    const end = new Date(event.end_time);
    const formatTime = (date) => date.toTimeString().slice(0, 5);
    
    document.getElementById('calendar-form-start-time').value = formatTime(start);
    document.getElementById('calendar-form-end-time').value = formatTime(end);
    document.getElementById('calendar-form-category').value = event.category || '一般';
    document.getElementById('calendar-form-color').value = event.color || '#3b82f6';
    document.getElementById('calendar-form-location').value = event.location || '';
    document.getElementById('calendar-form-desc').value = event.description || '';

    const shareTypeSelect = document.getElementById('calendar-form-share-type');
    
    // 共有範囲の復元
    if (shareTypeSelect) {
      if (!event.shared_with || event.shared_with.includes('*')) {
        shareTypeSelect.value = 'all';
      } else if (event.shared_with.length === 1 && event.shared_with.includes(event.user_id)) {
        shareTypeSelect.value = 'private';
      } else {
        shareTypeSelect.value = 'select';
      }
      shareTypeSelect.dispatchEvent(new Event('change'));

      // 個別選択メンバーの復元
      if (shareTypeSelect.value === 'select' && event.shared_with) {
        setTimeout(() => {
          const listContainer = document.getElementById('calendar-form-share-members-list');
          if (listContainer) {
            const inputs = listContainer.querySelectorAll('input[type="checkbox"]');
            inputs.forEach(input => {
              input.checked = event.shared_with.includes(input.value);
            });
          }
        }, 50);
      }
    }

    const deleteBtn = document.getElementById('calendar-event-delete-btn');

    if (isMine) {
      // 自分の予定なら編集・削除を許可（Google予定であっても、自身のアカウントの予定であれば削除を許可する）
      enableFormFields(true);
      if (deleteBtn) deleteBtn.style.display = 'block';
    } else {
      // 他人の予定なら「閲覧専用」にする
      enableFormFields(false);
      if (deleteBtn) deleteBtn.style.display = 'none';
    }
  }

  // フォームフィールドの有効・無効切り替え
  function enableFormFields(enable) {
    const fields = [
      'calendar-form-title', 'calendar-form-start-time', 'calendar-form-end-time',
      'calendar-form-category', 'calendar-form-color', 'calendar-form-location',
      'calendar-form-desc', 'calendar-form-share-type'
    ];
    
    fields.forEach(id => {
      const el = document.getElementById(id);
      if (el) el.disabled = !enable;
    });

    const shareMembersContainer = document.getElementById('calendar-form-share-members-list');
    if (shareMembersContainer) {
      const checkboxes = shareMembersContainer.querySelectorAll('input');
      checkboxes.forEach(cb => cb.disabled = !enable);
    }

    const saveBtn = document.getElementById('calendar-event-save-btn');
    if (saveBtn) {
      saveBtn.style.display = enable ? 'block' : 'none';
    }
  }

  // フォーム内の共有用メンバーチェックリストを描画
  function renderFormShareMemberList() {
    const listContainer = document.getElementById('calendar-form-share-members-list');
    if (!listContainer) return;

    listContainer.innerHTML = '';
    const me = state.currentUser ? state.currentUser.id : 'guest';

    // 自分以外のメンバーを共有候補としてリスト
    synapseMembers.forEach(member => {
      if (member.id === me) return;

      const isAllowed = state.calendarAllowedShareMembers && state.calendarAllowedShareMembers.includes(member.id);
      if (!isAllowed) return;

      const item = document.createElement('div');
      item.style.display = 'flex';
      item.style.alignItems = 'center';
      item.style.gap = '0.35rem';
      item.style.fontSize = '0.75rem';

      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.value = member.id;
      checkbox.id = `share-member-cb-${member.id}`;
      checkbox.style.cursor = 'pointer';

      const label = document.createElement('label');
      label.htmlFor = `share-member-cb-${member.id}`;
      label.textContent = member.name;
      label.style.cursor = 'pointer';
      label.style.flex = '1';

      item.appendChild(checkbox);
      item.appendChild(label);
      listContainer.appendChild(item);
    });
  }

  // 予定の保存処理 (INSERT / UPDATE)
  async function saveCalendarEvent() {
    const id = document.getElementById('calendar-form-event-id').value;
    const title = document.getElementById('calendar-form-title').value.trim();
    const startTimeStr = document.getElementById('calendar-form-start-time').value;
    const endTimeStr = document.getElementById('calendar-form-end-time').value;
    const category = document.getElementById('calendar-form-category').value;
    const color = document.getElementById('calendar-form-color').value;
    const location = document.getElementById('calendar-form-location').value.trim();
    const description = document.getElementById('calendar-form-desc').value.trim();
    const shareType = document.getElementById('calendar-form-share-type').value;

    if (!title) {
      showToast('予定のタイトルを入力してください。', 'error');
      return;
    }

    const me = state.currentUser ? state.currentUser.id.toLowerCase() : 'guest';
    const myName = state.currentUser ? (state.currentUser.name || state.currentUser.id) : '自分';

    // 開始日時・終了日時のDateオブジェクト作成
    const getFullDateISO = (timeStr) => {
      const [hours, mins] = timeStr.split(':');
      const d = new Date(calendarSelectedDate);
      d.setHours(parseInt(hours, 10), parseInt(mins, 10), 0, 0);
      return d.toISOString();
    };

    const start_time = getFullDateISO(startTimeStr);
    const end_time = getFullDateISO(endTimeStr);

    if (new Date(start_time) >= new Date(end_time)) {
      showToast('終了時刻は開始時刻より後に設定してください。', 'error');
      return;
    }

    // 共有範囲の作成
    let shared_with = [me]; // 自分は常に共有
    if (shareType === 'private') {
      shared_with = [me];
    } else if (shareType === 'select') {
      const checkboxes = document.querySelectorAll('#calendar-form-share-members-list input[type="checkbox"]:checked');
      checkboxes.forEach(cb => {
        const isAllowed = state.calendarAllowedShareMembers && state.calendarAllowedShareMembers.includes(cb.value);
        if (isAllowed) {
          shared_with.push(cb.value);
        }
      });
    }

    const isGoogle = id && id.startsWith('google-');

    const eventData = {
      id: id || generateUUID(),
      user_id: me,
      user_name: myName,
      title: title,
      start_time: start_time,
      end_time: end_time,
      location: location,
      description: description,
      category: category,
      color: color,
      shared_with: shared_with,
      is_google_event: isGoogle
    };

    // Google予定の編集の場合、GoogleカレンダーAPIの更新も走らせる
    if (isGoogle) {
      const googleEventId = id.replace('google-', '');
      await updateGoogleCalendarEventTime(googleEventId, title, start_time, end_time);
    }

    // DBへの同期保存を試みる
    let success = false;
    if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
      try {
        const { error } = await partnerSupabaseClient
          .from('synapse_calendar_events')
          .upsert(eventData);
        if (!error) {
          success = true;
        } else {
          console.error("Supabase upsert error:", error.message);
        }
      } catch (e) {
        console.error("Supabase connection error during save:", e);
      }
    }

    // ローカルストレージでの保存・更新 (フォールバック ＆ 即座の描画反映)
    const idx = state.calendarEvents.findIndex(ev => ev.id === eventData.id);
    if (idx !== -1) {
      state.calendarEvents[idx] = eventData;
    } else {
      state.calendarEvents.push(eventData);
    }
    localStorage.setItem(`SYNAPSE_USER_CALENDAR_EVENTS_${me}`, JSON.stringify(state.calendarEvents));
    
    showToast(id ? '予定を更新しました。' : '予定を新規作成しました！', 'success');
    
    // カレンダー再描画とフォームリセット
    renderMypageCalendar();
    loadEventsForSelectedDate();
    resetEventForm();
  }

  // 予定の削除処理
  async function deleteCalendarEvent() {
    const id = document.getElementById('calendar-form-event-id').value;
    if (!id) return;

    if (!confirm('この予定を削除しますか？')) return;

    const me = state.currentUser ? state.currentUser.id : 'guest';

    // Googleカレンダー予定の場合、Google APIからも削除
    if (id.startsWith('google-')) {
      const googleEventId = id.replace('google-', '');
      try {
        await deleteEventFromGoogleCalendar(googleEventId);
      } catch (e) {
        console.error("[Google Calendar API] deleteEventFromGoogleCalendar failed:", e);
      }
    }

    // DBからの削除を試みる
    if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
      try {
        let query = partnerSupabaseClient
          .from('synapse_calendar_events')
          .delete()
          .eq('id', id);
        
        // 通常の予定のみ user_id で制限する（Google予定は一意のIDで確実にクリーンアップ）
        if (!id.startsWith('google-')) {
          query = query.eq('user_id', me);
        }

        const { error } = await query;
        if (error) {
          console.error("Supabase event delete error:", error.message);
        }
      } catch (e) {
        console.error("Supabase event delete failed:", e);
      }
    }

    // メモリ上の状態から削除
    state.calendarEvents = state.calendarEvents.filter(ev => ev.id !== id);

    // ローカルストレージ（自分・ゲスト両方）からも完全に削除して同期
    localStorage.setItem(`SYNAPSE_USER_CALENDAR_EVENTS_${me}`, JSON.stringify(state.calendarEvents));
    localStorage.setItem('SYNAPSE_USER_CALENDAR_EVENTS_guest', JSON.stringify(state.calendarEvents.filter(ev => ev.id !== id)));

    showToast('予定を削除しました。', 'info');

    // カレンダー再描画とフォームリセット
    renderMypageCalendar();
    loadEventsForSelectedDate();
    resetEventForm();
  }

  // UUID生成ヘルパー
  function generateUUID() {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
      const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
      return v.toString(16);
    });
  }

  // 日付ラベル更新
  function updateSelectedDateLabel() {
    const label = document.getElementById('calendar-selected-date-label');
    if (!label) return;
    
    const year = calendarSelectedDate.getFullYear();
    const month = calendarSelectedDate.getMonth() + 1;
    const day = calendarSelectedDate.getDate();
    const dayName = ['日', '月', '火', '水', '木', '金', '土'][calendarSelectedDate.getDay()];
    
    label.textContent = `選択日: ${month}月${day}日(${dayName})`;
  }

  function renderTodoList() {
    try {
      const activeList = document.getElementById('todo-active-list');
      const doneList = document.getElementById('todo-done-list');
      const uncompletedCount = document.getElementById('todo-uncompleted-count');
      const completedCount = document.getElementById('todo-completed-count');

      if (!activeList || !doneList) return;

      activeList.innerHTML = '';
      doneList.innerHTML = '';

      const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
      const me = rawUserId.toLowerCase();

      // 期限日判定用の今日
      const todayStr = new Date().toISOString().slice(0, 10);

      // サービスフィルターの適用
      const currentServiceFilter = state.todoServiceFilter || 'all';
      let filteredTasks = Array.isArray(todoTasks) ? [...todoTasks] : [];

      if (currentServiceFilter === 'google') {
        filteredTasks = filteredTasks.filter(t => t && t.id && t.id.startsWith('google-task-'));
      } else if (currentServiceFilter === 'asana') {
        filteredTasks = filteredTasks.filter(t => t && t.id && t.id.startsWith('asana-'));
      }

      // ソート順の適用
      const currentSortMode = state.todoSortMode || 'due';
      if (currentSortMode === 'due') {
        // 日付順（期限日 due 順）にソート (期限があるものを昇順で先に並べ、期限なしは最後に)
        filteredTasks.sort((a, b) => {
          const dueA = a.due || '';
          const dueB = b.due || '';
          if (dueA && dueB) {
            return dueA.localeCompare(dueB);
          }
          if (dueA) return -1;
          if (dueB) return 1;
          return 0;
        });
      } else {
        // 登録順（作成日時 created_at の降順：新しいものが上）
        filteredTasks.sort((a, b) => {
          const timeA = (a && a.created_at) ? new Date(a.created_at).getTime() : 0;
          const timeB = (b && b.created_at) ? new Date(b.created_at).getTime() : 0;
          if (timeA !== timeB) {
            return timeB - timeA;
          }
          const idA = (a && a.id) || '';
          const idB = (b && b.id) || '';
          return idB.localeCompare(idA);
        });
      }

      const activeTasks = filteredTasks.filter(t => t.status !== 'completed');
      const doneTasks = filteredTasks.filter(t => t.status === 'completed');

      if (uncompletedCount) uncompletedCount.textContent = activeTasks.length.toString();
      if (completedCount) completedCount.textContent = doneTasks.length.toString();

      // 未完了タスクの描画
      function renderGroupedTasks(tasks, listContainer, isCompletedList) {
        if (!tasks || tasks.length === 0) {
          listContainer.innerHTML = `<p style="font-size: 0.8rem; color: var(--text-secondary); text-align: center; padding: 1rem 0;">${isCompletedList ? '完了済みのタスクはありません' : '未完了のタスクはありません'}</p>`;
          return;
        }

        if (state.todoGroupMode === 'project') {
          // プロジェクトごとにグループ分け
          const groups = {};
          tasks.forEach(task => {
            let projName = 'Synapse タスク';
            const tid = (task && task.id) || '';
            if (tid.startsWith('asana-')) {
              let wsName = task.workspace_name || '';
              let prjName = task.project_name || '';
              if (!wsName && !prjName && task.notes) {
                const match = task.notes.match(/^【Asana帰属: ([^＞】]+)(?: ＞ ([^】\()]+))?/);
                if (match) {
                  prjName = match[2] ? match[2].trim() : '';
                }
              }
              projName = prjName ? `Asana: ${prjName}` : 'Asana (プロジェクトなし)';
            } else if (tid.startsWith('google-')) {
              let listName = '';
              if (task.notes) {
                const match = task.notes.match(/^【Google To-Do帰属: ([^】]+)】/);
                if (match) {
                  listName = match[1] ? match[1].trim() : '';
                }
              }
              projName = listName ? `Google To-Do: ${listName}` : 'Google To-Do (リストなし)';
            }

            if (!groups[projName]) {
              groups[projName] = [];
            }
            groups[projName].push(task);
          });

          // グループごとにアコーディオン (details/summary) を作成して描画
          Object.keys(groups).sort().forEach(groupKey => {
            const groupTasks = groups[groupKey];
            
            const details = document.createElement('details');
            details.className = 'todo-project-details';
            details.open = true; // デフォルトで展開
            details.style.marginBottom = '0.75rem';
            details.style.border = '1px solid var(--border-color)';
            details.style.borderRadius = 'var(--radius-md)';
            details.style.background = 'var(--bg-surface)';
            details.style.overflow = 'hidden';
            details.style.boxShadow = 'var(--shadow-sm)';

            const summary = document.createElement('summary');
            summary.className = 'todo-project-summary';
            summary.style.display = 'flex';
            summary.style.alignItems = 'center';
            summary.style.justifyContent = 'space-between';
            summary.style.padding = '0.65rem 0.85rem';
            summary.style.fontSize = '0.8rem';
            summary.style.fontWeight = '700';
            summary.style.color = 'var(--text-primary)';
            summary.style.background = 'var(--bg-surface-elevated)';
            summary.style.cursor = 'pointer';
            summary.style.userSelect = 'none';

            // summary の左側（タイトルとアイコン）
            const leftArea = document.createElement('div');
            leftArea.style.display = 'flex';
            leftArea.style.alignItems = 'center';
            leftArea.style.gap = '0.45rem';
            
            // アイコン色の判定 (▲マーク)
            let iconColor = 'var(--primary)';
            if (groupKey.startsWith('Asana:')) {
              iconColor = '#e04f5f'; // Asanaカラー
            } else if (groupKey.startsWith('Google To-Do')) {
              iconColor = '#3b82f6'; // Googleカラー
            }
            
            leftArea.innerHTML = `<span style="color: ${iconColor}; font-size: 0.65rem; display: inline-flex; align-items: center; justify-content: center; margin-right: 0.2rem;">▲</span> <span>${groupKey}</span>`;

            // summary の右側（件数バッジと矢印）
            const rightArea = document.createElement('div');
            rightArea.style.display = 'flex';
            rightArea.style.alignItems = 'center';
            rightArea.style.gap = '0.5rem';

            const countBadge = document.createElement('span');
            countBadge.style.fontSize = '0.7rem';
            countBadge.style.background = 'rgba(0, 0, 0, 0.04)';
            countBadge.style.border = '1px solid var(--border-color)';
            countBadge.style.color = 'var(--text-secondary)';
            countBadge.style.padding = '2px 8px';
            countBadge.style.borderRadius = '12px';
            countBadge.textContent = groupTasks.length;

            // アコーディオンの矢印アイコン
            const arrowIcon = document.createElement('span');
            arrowIcon.className = 'details-arrow-icon';
            arrowIcon.innerHTML = '▼';
            arrowIcon.style.fontSize = '0.6rem';
            arrowIcon.style.transition = 'transform 0.2s';
            arrowIcon.style.color = 'var(--text-secondary)';

            rightArea.appendChild(countBadge);
            rightArea.appendChild(arrowIcon);

            summary.appendChild(leftArea);
            summary.appendChild(rightArea);

            // 開閉に合わせて矢印を回転させる処理
            details.ontoggle = () => {
              arrowIcon.style.transform = details.open ? 'rotate(0deg)' : 'rotate(-90deg)';
            };

            const contentDiv = document.createElement('div');
            contentDiv.style.display = 'flex';
            contentDiv.style.flexDirection = 'column';
            contentDiv.style.gap = '0.5rem';
            contentDiv.style.padding = '0.5rem';
            contentDiv.style.background = 'var(--bg-surface)';
            contentDiv.style.borderTop = '1px solid var(--border-color)';

            groupTasks.forEach(task => {
              const item = createTodoDomItem(task, todayStr, me);
              contentDiv.appendChild(item);
            });

            details.appendChild(summary);
            details.appendChild(contentDiv);
            listContainer.appendChild(details);
          });

        } else {
          // 通常のフラット描画
          tasks.forEach(task => {
            const item = createTodoDomItem(task, todayStr, me);
            listContainer.appendChild(item);
          });
        }
      }

      renderGroupedTasks(activeTasks, activeList, false);
      renderGroupedTasks(doneTasks, doneList, true);
    } catch (renderErr) {
      console.error("[ToDo Render Error] Failed to render todo list:", renderErr);
    }
  }

  // 6. 本物の Google Calendar API 連携処理

  // 6-A. ポップアップ起動による Google OAuth 認証
  function startRealGoogleAuth(clientId, apiKey) {
    if (typeof google === 'undefined' || !google.accounts || !google.accounts.oauth2) {
      showToast('Google API ライブラリがロードされていません。リロードしてください。', 'error');
      return;
    }

    showToast('Google公式サインイン画面を起動します...', 'info');

    try {
      const me = state.currentUser ? state.currentUser.id.toLowerCase() : 'guest';
      
      // Google GIS token client の初期化（毎回生成して最新のスコープ設定を確実に反映）
      googleTokenClient = google.accounts.oauth2.initTokenClient({
        client_id: clientId,
        scope: 'https://www.googleapis.com/auth/calendar.events https://www.googleapis.com/auth/calendar.readonly https://www.googleapis.com/auth/userinfo.email https://www.googleapis.com/auth/tasks',
        callback: async (tokenResponse) => {
          if (tokenResponse && tokenResponse.access_token) {
            googleAccessToken = tokenResponse.access_token;
            
            // 有効期限 (ミリ秒) を計算して保存
            const expiresAt = Date.now() + (tokenResponse.expires_in || 3600) * 1000;
            localStorage.setItem(`SYNAPSE_GOOGLE_ACCESS_TOKEN_${me}`, googleAccessToken);
            localStorage.setItem(`SYNAPSE_GOOGLE_TOKEN_EXPIRES_${me}`, expiresAt.toString());
            
            console.log("[Google Calendar API] Token client callback success!");
            
            let email = me; // ログイン中ユーザーIDを初期値
            try {
              // userinfo エンドポイントからメールアドレスを取得
              const res = await fetch('https://www.googleapis.com/oauth2/v3/userinfo', {
                headers: { 'Authorization': `Bearer ${googleAccessToken}` }
              });
              const info = await res.json();
              if (info && info.email) {
                email = info.email;
              } else {
                // userinfo がダメな場合は tokeninfo から取得を試みる
                const tokenRes = await fetch(`https://www.googleapis.com/oauth2/v3/tokeninfo?access_token=${googleAccessToken}`);
                const tokenInfo = await tokenRes.json();
                if (tokenInfo && tokenInfo.email) email = tokenInfo.email;
              }
            } catch (e) {
              console.warn("OAuth email resolution failed, using active user id instead.", e);
            }

            linkGoogleCalendar(email);
          } else {
            const err = (tokenResponse && tokenResponse.error) ? tokenResponse.error : '認証が完了しなかったか、トークンを取得できませんでした。';
            showToast(`Google認証エラー: ${err}`, 'error');
            console.error("[Google Calendar API] GIS Token Callback error:", tokenResponse);
          }
        }
      });
      
      // 初回はプロンプトを表示してユーザーの承認とトークン取得を行う
      googleTokenClient.requestAccessToken();
    } catch (err) {
      console.error("[Google Calendar API] GIS Authorization failed:", err);
      showToast('Google認証の起動に失敗しました。', 'error');
    }
  }

  async function linkGoogleCalendar(email) {
    const me = state.currentUser ? state.currentUser.id.toLowerCase() : 'guest';
    
    // ★ 同一アカウント制限のバリデーション ★
    // GoogleカレンダーとGoogle Tasks (ToDo) は、どちらか先に連携している場合のみ、同一アカウントであることを確認
    const isCalendarLinked = isGoogleLinked || (localStorage.getItem(`SYNAPSE_GOOGLE_LINKED_${me}`) === 'true');
    const isTasksLinked = state.googleLinkTasks === true;
    const existingGoogleEmail = localStorage.getItem(`SYNAPSE_GOOGLE_EMAIL_${me}`) || '';

    if ((isCalendarLinked || isTasksLinked) && existingGoogleEmail) {
      if (email.toLowerCase() !== existingGoogleEmail.toLowerCase()) {
        showToast(`既に連携されているGoogleアカウント (${existingGoogleEmail}) と異なるアカウント (${email}) は連携できません。`, 'error');
        setGoogleLinkState(isCalendarLinked, existingGoogleEmail);
        updateGoogleStatusUI();
        const warningText = document.getElementById('task-sync-warning-text');
        if (warningText) {
          warningText.textContent = `⚠️ 既に連携されているGoogleアカウント (${existingGoogleEmail}) と同一のアカウントをご利用ください。`;
          warningText.style.display = 'block';
        }
        return;
      }
    }

    setGoogleLinkState(true, email);
    
    localStorage.setItem(`SYNAPSE_GOOGLE_LINKED_${me}`, 'true');
    localStorage.setItem(`SYNAPSE_GOOGLE_EMAIL_${me}`, email);
    
    // synapse_storage に連携メールアドレスを保存（他ユーザーから参照できるようにするため）
    if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient && me !== 'guest') {
      try {
        await partnerSupabaseClient
          .from('synapse_storage')
          .upsert({
            key: `synapse_google_linked_email_${me}`,
            value: email
          });
      } catch (e) {
        console.warn("[Google Calendar API] Failed to share email on synapse_storage:", e);
      }
    }
    
    updateGoogleStatusUI();
    
    // タスク画面側のUI更新
    const labelGoogleEmail = document.getElementById('task-sync-google-email');
    const btnGoogleConnect = document.getElementById('task-sync-google-btn');
    const labelGoogleReflect = document.getElementById('task-sync-google-calendar-reflect-label');
    if (labelGoogleEmail && btnGoogleConnect) {
      labelGoogleEmail.textContent = email;
      btnGoogleConnect.textContent = '連携解除';
      btnGoogleConnect.className = 'btn btn-danger';
    }
    if (labelGoogleReflect) {
      labelGoogleReflect.style.display = 'flex';
    }
    if (typeof updateCalendarDisplayFilterOptions === 'function') {
      updateCalendarDisplayFilterOptions();
    }

    // 警告をクリア
    const warningText = document.getElementById('task-sync-warning-text');
    if (warningText) warningText.style.display = 'none';

    showToast('Googleカレンダーと連携されました！', 'success');
    
    // カレンダー一覧を取得してセレクトボックスを初期化
    await fetchAndRenderGoogleCalendars();
    
    syncWithGoogleCalendar();
  }

  async function unlinkGoogleCalendar() {
    const me = state.currentUser ? state.currentUser.id.toLowerCase() : 'guest';
    
    if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
      try {
        await partnerSupabaseClient
          .from('synapse_calendar_events')
          .delete()
          .eq('user_id', me)
          .eq('is_google_event', true);

        // synapse_todo_tasks テーブルからもGoogle同期タスクを完全に削除
        await partnerSupabaseClient
          .from('synapse_todo_tasks')
          .delete()
          .eq('user_id', me)
          .like('id', 'google-task-%');
          
        // synapse_storage から連携メールアドレス情報を削除
        if (me !== 'guest') {
          await partnerSupabaseClient
            .from('synapse_storage')
            .delete()
            .eq('key', `synapse_google_linked_email_${me}`);
        }
      } catch (e) {
        console.warn("Failed to clear DB Google cache events or storage:", e);
      }
    }

    state.calendarEvents = state.calendarEvents.filter(ev => !(ev.user_id === me && ev.is_google_event));
    localStorage.setItem(`SYNAPSE_USER_CALENDAR_EVENTS_${me}`, JSON.stringify(state.calendarEvents));

    // メモリおよびローカルストレージからもGoogle同期タスクを即時削除
    todoTasks = todoTasks.filter(t => !t.id.startsWith('google-task-'));
    localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));

    setGoogleLinkState(false, '');
    googleAccessToken = null;
    googleTokenClient = null;
    
    localStorage.setItem(`SYNAPSE_GOOGLE_LINKED_${me}`, 'false');
    localStorage.setItem(`SYNAPSE_GOOGLE_EMAIL_${me}`, '');
    localStorage.removeItem(`SYNAPSE_GOOGLE_ACCESS_TOKEN_${me}`);
    localStorage.removeItem(`SYNAPSE_GOOGLE_TOKEN_EXPIRES_${me}`);
    localStorage.removeItem(`SYNAPSE_GOOGLE_SELECTED_CALENDAR_ID_${me}`);
    
    updateGoogleStatusUI();
    
    // Google Tasks カレンダー反映トグルの表示リセット
    state.googleTasksShowOnCalendar = true;
    localStorage.setItem(`SYNAPSE_GOOGLE_TASKS_SHOW_ON_CALENDAR_${me}`, 'true');
    const chkGoogleReflect = document.getElementById('task-sync-google-calendar-reflect');
    const labelGoogleReflect = document.getElementById('task-sync-google-calendar-reflect-label');
    if (chkGoogleReflect) chkGoogleReflect.checked = true;
    if (labelGoogleReflect) labelGoogleReflect.style.display = 'none';

    if (typeof updateCalendarDisplayFilterOptions === 'function') {
      updateCalendarDisplayFilterOptions();
    }

    showToast('Googleカレンダーの連携を解除しました。', 'info');
    
    // セレクトボックスを隠す
    const selectContainer = document.getElementById('google-calendar-select-container');
    if (selectContainer) selectContainer.style.display = 'none';
    
    renderLeftSidebarMembers();
    renderMypageCalendar();
    loadEventsForSelectedDate();
  }

  // 連携中の Google カレンダー一覧を取得してセレクトボックスに描画
  async function fetchAndRenderGoogleCalendars() {
    const selectContainer = document.getElementById('google-calendar-select-container');
    const select = document.getElementById('google-calendar-select');
    if (!selectContainer || !select) return;

    if (!isGoogleLinked || !googleAccessToken) {
      selectContainer.style.display = 'none';
      return;
    }

    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const apiKey = state.googleApiKey || getLocalStorageGoogleItem('SYNAPSE_GOOGLE_API_KEY', rawUserId);

    try {
      let calendarListUrl = `https://www.googleapis.com/calendar/v3/users/me/calendarList`;
      let response = await fetch(calendarListUrl, {
        headers: { 'Authorization': `Bearer ${googleAccessToken}` }
      });
      
      if (!response.ok && apiKey) {
        calendarListUrl = `https://www.googleapis.com/calendar/v3/users/me/calendarList?key=${apiKey}`;
        response = await fetch(calendarListUrl, {
          headers: { 'Authorization': `Bearer ${googleAccessToken}` }
        });
      }

      if (response.ok) {
        const listData = await response.json();
        if (listData && listData.items) {
          select.innerHTML = '';
          
          // プライマリ・本人のカレンダーのみに絞り込む（家族カレンダーなどを非表示にする）
          const mainCals = listData.items.filter(cal => 
            cal.id === 'primary' || 
            (googleLinkedEmail && cal.id.toLowerCase() === googleLinkedEmail.toLowerCase())
          );

          mainCals.forEach(cal => {
            const opt = document.createElement('option');
            opt.value = cal.id;
            opt.textContent = cal.summary + (cal.primary ? ' (プライマリ)' : '');
            select.appendChild(opt);
          });

          // 保存された選択の復元
          const savedCalId = localStorage.getItem(`SYNAPSE_GOOGLE_SELECTED_CALENDAR_ID_${me}`) || 'primary';
          select.value = savedCalId;
          
          // 選択されたものがなければプライマリ（または最初のもの）
          if (!select.value && select.options.length > 0) {
            select.selectedIndex = 0;
            localStorage.setItem(`SYNAPSE_GOOGLE_SELECTED_CALENDAR_ID_${me}`, select.value);
          }

          selectContainer.style.display = 'flex';
        }
      } else {
        console.warn("[Google Calendar API] Failed to fetch calendar list for select dropdown");
        selectContainer.style.display = 'none';
      }
    } catch (e) {
      console.warn("[Google Calendar API] Error fetching calendar list for select:", e);
      selectContainer.style.display = 'none';
    }
  }

  // 設定ロード完了後に外部から呼び出すためのブリッジ関数
  window.triggerGoogleSyncIfLinked = function(clientId, apiKey) {
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const isLinked = getLocalStorageGoogleItem('SYNAPSE_GOOGLE_LINKED', rawUserId) === 'true';
    if (isLinked && clientId && apiKey) {
      console.log("[Google Calendar API] Auto-triggering Google Sync after config load...");
      silentGoogleSync(clientId, apiKey);
    }
  };

  async function silentGoogleSync(clientId, apiKey) {
    console.log("[Google Calendar API] Linked account auto-sync triggered.");
    
    const me = state.currentUser ? state.currentUser.id.toLowerCase() : 'guest';
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const cachedToken = getLocalStorageGoogleItem('SYNAPSE_GOOGLE_ACCESS_TOKEN', rawUserId);
    const expiresStr = getLocalStorageGoogleItem('SYNAPSE_GOOGLE_TOKEN_EXPIRES', rawUserId);
    const expiresAt = expiresStr ? parseInt(expiresStr, 10) : 0;
    
    // 現在の連携メールアドレスをロード
    googleLinkedEmail = getLocalStorageGoogleItem('SYNAPSE_GOOGLE_EMAIL', rawUserId) || '';

    // トークンが残っており、有効期限の5分前より先であれば再利用する
    if (cachedToken && expiresAt && (expiresAt - Date.now() > 5 * 60 * 1000)) {
      googleAccessToken = cachedToken;
      console.log("[Google Calendar API] Reusing valid cached access token.");
      fetchAndRenderGoogleCalendars();
      syncWithGoogleCalendar();
      return;
    }

    // トークンが無い、または期限切れの場合はサイレント更新 (prompt: 'none') を実行
    if (typeof google !== 'undefined' && google.accounts && google.accounts.oauth2) {
      try {
        console.log("[Google Calendar API] Token expired or missing. Refreshing token silently with hint:", googleLinkedEmail);
        
        googleTokenClient = google.accounts.oauth2.initTokenClient({
          client_id: clientId,
          scope: 'https://www.googleapis.com/auth/calendar.events https://www.googleapis.com/auth/calendar.readonly https://www.googleapis.com/auth/userinfo.email https://www.googleapis.com/auth/tasks',
          prompt: 'none', // 画面にポップアップを出さずに裏で再取得
          callback: async (tokenResponse) => {
            if (tokenResponse && tokenResponse.access_token) {
              googleAccessToken = tokenResponse.access_token;
              
              const newExpiresAt = Date.now() + (tokenResponse.expires_in || 3600) * 1000;
              localStorage.setItem(`SYNAPSE_GOOGLE_ACCESS_TOKEN_${me}`, googleAccessToken);
              localStorage.setItem(`SYNAPSE_GOOGLE_TOKEN_EXPIRES_${me}`, newExpiresAt.toString());
              
              console.log("[Google Calendar API] Silent token refresh success!");
              fetchAndRenderGoogleCalendars();
              syncWithGoogleCalendar();
            } else {
              console.warn("[Google Calendar API] Silent token refresh returned empty token or error:", tokenResponse ? tokenResponse.error : 'unknown');
              
              // サイレント認証がセキュリティ等の理由でブロックされた場合の安全なフォールバック
              // ユーザーに連携解除はせず、前回のキャッシュを描画したままにする
              if (tokenResponse && (tokenResponse.error === 'interaction_required' || tokenResponse.error === 'consent_required')) {
                console.log("[Google Calendar API] Silent token refresh requires interaction. Cache will be preserved.");
              }
            }
          }
        });
        
        // hint を設定して Google に対象アカウントを明示する（超重要！）
        googleTokenClient.requestAccessToken({ prompt: 'none', hint: googleLinkedEmail });
      } catch (e) {
        console.warn("[Google Calendar API] Silent token refresh failed:", e);
      }
    } else {
      console.warn("[Google Calendar API] Google GIS library not fully loaded for silent sync.");
    }
  }

  // 6-B. Google Calendar API からのイベント取得 ＆ 同期保存
  async function syncWithGoogleCalendar() {
    if (!isGoogleLinked || !googleAccessToken) {
      console.log("[Google Calendar API] No active OAuth token available.");
      return;
    }

    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const apiKey = state.googleApiKey || getLocalStorageGoogleItem('SYNAPSE_GOOGLE_API_KEY', rawUserId);

    showToast('Googleカレンダーから予定を同期中...', 'info');

    try {
      // 1. カレンダーリスト（マイカレンダー一覧）の取得
      // 【二段構え】まずはAPIキーなし（推奨）で試行し、エラーならAPIキー付きでリトライ
      let calendarListUrl = `https://www.googleapis.com/calendar/v3/users/me/calendarList`;
      let listResponse = await fetch(calendarListUrl, {
        headers: { 'Authorization': `Bearer ${googleAccessToken}` }
      });
      
      if (!listResponse.ok && apiKey) {
        console.log("[Google Calendar API] Fetching calendar list without API Key failed. Retrying with API Key...");
        calendarListUrl = `https://www.googleapis.com/calendar/v3/users/me/calendarList?key=${apiKey}`;
        listResponse = await fetch(calendarListUrl, {
          headers: { 'Authorization': `Bearer ${googleAccessToken}` }
        });
      }

      // ドロップダウンで選択されている連携カレンダーIDを取得して適用
      const savedCalId = localStorage.getItem(`SYNAPSE_GOOGLE_SELECTED_CALENDAR_ID_${me}`) || 'primary';
      let calendarIds = [savedCalId];

      // 過去の大量の予定で maxResults が埋め尽くされ、現在の予定が取得できなくなるのを防ぐため、
      // 期間を「本日の3ヶ月前」から「本日の1年後」の計15ヶ月間に絞り、かつ最大取得件数を 1000 件に増やす
      const timeMin = new Date();
      timeMin.setMonth(timeMin.getMonth() - 3);
      const timeMax = new Date();
      timeMax.setMonth(timeMax.getMonth() + 12);

      let allGoogleEvents = [];

      // 2. 各カレンダーから予定を取得してマージ (カレンダー連携がONの場合のみ)
      if (state.googleLinkCalendar !== false) {
        for (const calendarId of calendarIds) {
          const isHolidayCal = calendarId.includes('holiday') || calendarId.includes('group.v.calendar.google.com');
          
          // 【二段構え】まずはAPIキーなし（推奨）で試行
          let url = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendarId)}/events` + 
                    `?timeMin=${timeMin.toISOString()}&timeMax=${timeMax.toISOString()}&singleEvents=true&orderBy=startTime&maxResults=1000`;
          
          try {
            let response = await fetch(url, {
              headers: { 'Authorization': `Bearer ${googleAccessToken}` }
            });
            
            if (!response.ok && apiKey) {
              console.log(`[Google Calendar API] Fetch events for ${calendarId} without API Key failed. Retrying with API Key...`);
              url = `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendarId)}/events` + 
                    `?timeMin=${timeMin.toISOString()}&timeMax=${timeMax.toISOString()}&singleEvents=true&orderBy=startTime&maxResults=1000&key=${apiKey}`;
              response = await fetch(url, {
                headers: { 'Authorization': `Bearer ${googleAccessToken}` }
              });
            }
            
            if (!response.ok) {
              let errMsg = "Unknown Error";
              try {
                const errData = await response.json();
                if (errData && errData.error) {
                  errMsg = `[Code: ${errData.error.code}] ${errData.error.message}`;
                }
              } catch (_) {}
              console.error(`[Google Calendar API] Fetch failed for calendar ${calendarId}:`, errMsg);
              showToast(`Google同期エラー: ${errMsg}`, 'error');
              continue;
            }
            
            const data = await response.json();
            if (data && data.items) {
              const validItems = data.items.filter(event => {
                if (event.status === 'cancelled') return false;
                if (!event.start || !event.end) return false;
                if (!event.start.dateTime && !event.start.date) return false;
                if (!event.end.dateTime && !event.end.date) return false;
                return true;
              });
              const events = validItems.map(event => {
                return {
                  id: `google-${event.id}`,
                  user_id: me,
                  user_name: googleLinkedEmail,
                  title: event.summary || '予定なし',
                  start_time: event.start.dateTime || event.start.date + 'T00:00:00Z',
                  end_time: event.end.dateTime || event.end.date + 'T23:59:59Z',
                  location: event.location || '',
                  description: event.description || '',
                  category: isHolidayCal ? '祝日' : '一般',
                  color: isHolidayCal ? '#f43f5e' : '#4285F4',
                  shared_with: ['*'],
                  is_google_event: true
                };
              });
              allGoogleEvents = allGoogleEvents.concat(events);
            }
          } catch (err) {
            console.error(`[Google Calendar API] Error fetching events for calendar ${calendarId}:`, err);
          }
        }
      }

      // Google Tasks および Asana のタスク同期を連動して実行
      if (state.googleLinkTasks) {
        await syncWithGoogleTasks(me);
      }
      if (state.asanaLinkTasks) {
        await syncWithAsanaTasks(me);
      }

      // 3. Supabase DB へのキャッシュ保存とメモリ更新
      if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
        try {
          const { error: delError } = await partnerSupabaseClient
            .from('synapse_calendar_events')
            .delete()
            .eq('user_id', me)
            .eq('is_google_event', true);
          if (delError) {
            console.error("Supabase DB Google cache delete error:", delError.message);
          }
          
          if (allGoogleEvents.length > 0) {
            // DB用にIDを除外し、descriptionにGoogleIDを埋め込んだクローンを作成
            const dbEvents = allGoogleEvents.map(ev => {
              const clone = { ...ev };
              delete clone.id; // UUID制約エラー回避のためIDを除外（Supabase側で自動生成）
              
              const rawGoogleId = ev.id.replace('google-task-', '').replace('google-', '');
              const marker = ev.id.startsWith('google-task-') ? '__GOOGLE_TASK_ID__' : '__GOOGLE_ID__';
              clone.description = (clone.description || '') + `\n\n${marker}:${rawGoogleId}`;
              
              return clone;
            });

            const { error: insError } = await partnerSupabaseClient
              .from('synapse_calendar_events')
              .insert(dbEvents);
            if (insError) {
              console.error("Supabase DB Google cache insert error:", insError.message, insError.details, insError.hint);
            }
          }
        } catch (e) {
          console.error("Supabase DB Google cache sync failed:", e);
        }
      }

      state.calendarEvents = state.calendarEvents.filter(ev => !(ev.user_id === me && ev.is_google_event));
      state.calendarEvents = state.calendarEvents.concat(allGoogleEvents);
      localStorage.setItem(`SYNAPSE_USER_CALENDAR_EVENTS_${me}`, JSON.stringify(state.calendarEvents));

      const normalCount = allGoogleEvents.filter(ev => ev.category !== '祝日').length;
      const holidayCount = allGoogleEvents.filter(ev => ev.category === '祝日').length;
      showToast(`Google同期完了: 一般 ${normalCount}件 / 祝日 ${holidayCount}件 を同期しました！`, 'success');

      renderMypageCalendar();
      loadEventsForSelectedDate();
      if (typeof renderTodoList === 'function') renderTodoList();
    } catch (error) {
      console.error("[Google Calendar API] Sync error:", error);
      showToast('Googleカレンダーの同期中にエラーが発生しました。', 'error');
    }
  }

  // 6-C. Googleカレンダーに予定を書き込む (POST)
  async function addEventToGoogleCalendar(event) {
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const apiKey = getLocalStorageGoogleItem('SYNAPSE_GOOGLE_API_KEY', rawUserId);

    const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?key=${apiKey}`;

    const body = {
      summary: event.title,
      location: event.location,
      description: event.description,
      start: { dateTime: event.start_time },
      end: { dateTime: event.end_time }
    };

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${googleAccessToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
      });
      const data = await response.json();
      if (data && data.id) {
        event.google_event_id = data.id;
        if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
          await partnerSupabaseClient
            .from('synapse_calendar_events')
            .update({ google_event_id: data.id })
            .eq('id', event.id);
        }
        const idx = state.calendarEvents.findIndex(ev => ev.id === event.id);
        if (idx !== -1) {
          state.calendarEvents[idx].google_event_id = data.id;
          localStorage.setItem(`SYNAPSE_USER_CALENDAR_EVENTS_${me}`, JSON.stringify(state.calendarEvents));
        }
        console.log("[Google Calendar API] Event created on Google Calendar:", data.id);
      }
    } catch (e) {
      console.error("[Google Calendar API] Post event failed:", e);
    }
  }

  // 6-D. Googleカレンダーの予定を削除する (DELETE)
  async function deleteEventFromGoogleCalendar(googleEventId) {
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const apiKey = getLocalStorageGoogleItem('SYNAPSE_GOOGLE_API_KEY', rawUserId);

    const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events/${googleEventId}?key=${apiKey}`;

    try {
      await fetch(url, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${googleAccessToken}`
        }
      });
      console.log("[Google Calendar API] Event deleted on Google Calendar:", googleEventId);
    } catch (e) {
      console.error("[Google Calendar API] Delete event failed:", e);
    }
  }

  // 6-E. Googleカレンダーの予定の時間を更新する (PATCH)
  async function updateGoogleCalendarEventTime(googleEventId, title, startTime, endTime) {
    const me = state.currentUser ? state.currentUser.id : 'guest';
    const apiKey = state.googleApiKey || localStorage.getItem(`SYNAPSE_GOOGLE_API_KEY_${me}`);

    const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events/${googleEventId}?key=${apiKey}`;

    const body = {
      summary: title,
      start: { dateTime: startTime },
      end: { dateTime: endTime }
    };

    try {
      const response = await fetch(url, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${googleAccessToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
      });
      if (response.ok) {
        console.log("[Google Calendar API] Event time updated on Google Calendar:", googleEventId);
      } else {
        const err = await response.json();
        console.error("[Google Calendar API] Update event failed:", err);
      }
    } catch (e) {
      console.error("[Google Calendar API] Update event failed:", e);
    }
  }

  // Google連携のカレンダーリストを取得してドロップダウンにロードする
  async function fetchAndRenderGoogleCalendars() {
    const select = document.getElementById('google-calendar-select');
    const container = document.getElementById('google-calendar-select-container');
    if (!select || !container) return;

    if (!isGoogleLinked || !googleAccessToken) {
      container.style.display = 'none';
      return;
    }

    const me = state.currentUser ? state.currentUser.id.toLowerCase() : 'guest';
    const savedCalId = localStorage.getItem(`SYNAPSE_GOOGLE_SELECTED_CALENDAR_ID_${me}`) || 'primary';

    try {
      const apiKey = state.googleApiKey || getLocalStorageGoogleItem('SYNAPSE_GOOGLE_API_KEY', me);
      let url = `https://www.googleapis.com/calendar/v3/users/me/calendarList`;
      let response = await fetch(url, {
        headers: { 'Authorization': `Bearer ${googleAccessToken}` }
      });
      if (!response.ok && apiKey) {
        url = `https://www.googleapis.com/calendar/v3/users/me/calendarList?key=${apiKey}`;
        response = await fetch(url, {
          headers: { 'Authorization': `Bearer ${googleAccessToken}` }
        });
      }

      if (response.ok) {
        const data = await response.json();
        if (data && data.items) {
          // プライマリ・本人のカレンダーのみに絞り込む（家族カレンダーなどを非表示にする）
          const writeableCals = data.items.filter(cal => 
            cal.id === 'primary' || 
            (googleLinkedEmail && cal.id.toLowerCase() === googleLinkedEmail.toLowerCase())
          );

          select.innerHTML = '';
          writeableCals.forEach(cal => {
            const opt = document.createElement('option');
            opt.value = cal.id;
            opt.textContent = cal.summary + (cal.id === 'primary' ? ' (プライマリ)' : '');
            if (cal.id === savedCalId) opt.selected = true;
            select.appendChild(opt);
          });

          container.style.display = 'flex';
        }
      }
    } catch (e) {
      console.warn("[Google Calendar API] Failed to fetch calendar list for dropdown:", e);
    }
  }

  function updateGoogleStatusUI() {
    const dot = document.getElementById('google-calendar-status-dot');
    const text = document.getElementById('google-calendar-status-text');
    const btn = document.getElementById('google-calendar-connect-btn');
    const btnCalendar = document.getElementById('mypage-btn-calendar');

    if (!dot || !text || !btn) return;

    if (isGoogleLinked) {
      dot.style.backgroundColor = '#10b981';
      text.textContent = `Google連携中: ${googleLinkedEmail}`;
      btn.textContent = '連携解除';
      btn.className = 'btn btn-secondary';
      
      if (btnCalendar) {
        btnCalendar.style.background = 'rgba(66, 133, 244, 0.08)';
        btnCalendar.style.borderColor = '#4285F4';
        const titleSpan = btnCalendar.querySelector('span:nth-of-type(1)');
        const descSpan = btnCalendar.querySelector('span:nth-of-type(2)');
        if (titleSpan) titleSpan.innerText = 'カレンダーを開く';
        if (descSpan) descSpan.innerText = `連携中: ${googleLinkedEmail}`;
      }

      // タスク外部連携設定のGoogle Tasks連携側も接続中にする
      const labelGoogleEmail = document.getElementById('task-sync-google-email');
      const btnGoogleConnect = document.getElementById('task-sync-google-btn');
      if (labelGoogleEmail && btnGoogleConnect) {
        labelGoogleEmail.textContent = googleLinkedEmail;
        btnGoogleConnect.textContent = '連携解除';
        btnGoogleConnect.className = 'btn btn-danger';
      }

      fetchAndRenderGoogleCalendars();
    } else {
      dot.style.backgroundColor = '#ef4444';
      text.textContent = 'Google未連携';
      btn.textContent = '連携する';
      btn.className = 'btn btn-primary';
      btn.style.background = '#4285F4';
      
      if (btnCalendar) {
        btnCalendar.style.background = 'var(--bg-surface)';
        btnCalendar.style.borderColor = 'var(--border-color)';
        const titleSpan = btnCalendar.querySelector('span:nth-of-type(1)');
        const descSpan = btnCalendar.querySelector('span:nth-of-type(2)');
        if (titleSpan) titleSpan.innerText = 'カレンダー';
        if (descSpan) descSpan.innerText = '個人・共有の予定管理とGoogleカレンダーの同期連携を行います';
      }

      // タスク外部連携設定のGoogle Tasks連携側を未接続にする
      const labelGoogleEmail = document.getElementById('task-sync-google-email');
      const btnGoogleConnect = document.getElementById('task-sync-google-btn');
      if (labelGoogleEmail && btnGoogleConnect) {
        labelGoogleEmail.textContent = '未接続';
        btnGoogleConnect.textContent = 'アカウント接続';
        btnGoogleConnect.className = 'btn btn-secondary';
      }

      const selectContainer = document.getElementById('google-calendar-select-container');
      if (selectContainer) selectContainer.style.display = 'none';
    }
  }

  // 外部からのタブ活性化時の再描画用ブリッジ
  function refreshCalendarView() {
    fetchCalendarEvents().then(() => {
      renderMypageCalendar();
      updateSelectedDateLabel();
      loadEventsForSelectedDate();
      resetEventForm();
    });
  }

  // ============================================================================
  // 📋 Synapse ToDoリスト (タスク管理) ロジック
  // ============================================================================
  let todoTasks = [];
  let editingTodoId = null;

  window.initMypageTasks = function() {
    console.log("[Tasks App] Initializing Tasks Screen...");
    editingTodoId = null;

    // 画面ビューの初期状態リセットおよび遷移イベントバインド
    const todoMainView = document.getElementById('todo-main-view');
    const todoSyncSettingsView = document.getElementById('todo-sync-settings-view');
    const toggleSettingsBtn = document.getElementById('task-sync-settings-toggle-btn');
    const backToTasksBtn = document.getElementById('task-sync-settings-back-btn');

    if (todoMainView) todoMainView.style.display = 'flex';
    if (todoSyncSettingsView) todoSyncSettingsView.style.display = 'none';
    if (toggleSettingsBtn) toggleSettingsBtn.style.display = 'inline-flex';

    if (toggleSettingsBtn) {
      toggleSettingsBtn.onclick = () => {
        if (todoMainView) todoMainView.style.display = 'none';
        if (todoSyncSettingsView) todoSyncSettingsView.style.display = 'flex';
        toggleSettingsBtn.style.display = 'none';
      };
    }

    if (backToTasksBtn) {
      backToTasksBtn.onclick = () => {
        if (todoSyncSettingsView) todoSyncSettingsView.style.display = 'none';
        if (todoMainView) todoMainView.style.display = 'flex';
        if (toggleSettingsBtn) toggleSettingsBtn.style.display = 'inline-flex';
      };
    }

    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();

    // Google連携情報の初期復元（カレンダー画面をロードする前にタスク画面を開いた場合のケア）
    const isLinkedVal = localStorage.getItem(`SYNAPSE_GOOGLE_LINKED_${me}`) === 'true';
    const emailVal = localStorage.getItem(`SYNAPSE_GOOGLE_EMAIL_${me}`) || '';
    setGoogleLinkState(isLinkedVal, emailVal);
    if (!googleAccessToken) {
      const cachedToken = localStorage.getItem(`SYNAPSE_GOOGLE_ACCESS_TOKEN_${me}`);
      const expiresStr = localStorage.getItem(`SYNAPSE_GOOGLE_TOKEN_EXPIRES_${me}`);
      const expiresAt = expiresStr ? parseInt(expiresStr, 10) : 0;
      if (cachedToken && expiresAt && (expiresAt - Date.now() > 5 * 60 * 1000)) {
        googleAccessToken = cachedToken;
      }
    }

    // DOM要素
    const btnNewTodo = document.getElementById('task-new-btn');
    const todoFormTitleText = document.getElementById('todo-form-title-text');
    const inputTitle = document.getElementById('todo-form-title');
    const inputDue = document.getElementById('todo-form-due');
    const inputNotes = document.getElementById('todo-form-notes');
    const chkShowOnCalendar = document.getElementById('todo-form-show-on-calendar');
    const chkShared = document.getElementById('todo-form-shared');
    const shareMembersContainer = document.getElementById('todo-form-share-members-container');
    const shareMembersList = document.getElementById('todo-form-share-members-list');
    const saveTodoBtn = document.getElementById('todo-form-save-btn');
    const deleteTodoBtn = document.getElementById('todo-form-delete-btn');

    // 新規タスクボタン
    if (btnNewTodo) {
      btnNewTodo.onclick = () => {
        resetTodoForm();
      };
    }

    // グループ分けオプションの復元とバインド（デフォルト: project）
    const groupSelect = document.getElementById('todo-group-select');
    state.todoGroupMode = localStorage.getItem(`SYNAPSE_TODO_GROUP_MODE_${me}`) || 'project';

    function updateGroupFilterButtonsState() {
      if (!groupSelect) return;
      groupSelect.value = state.todoGroupMode;
    }

    if (groupSelect) {
      groupSelect.onchange = (e) => {
        state.todoGroupMode = e.target.value;
        localStorage.setItem(`SYNAPSE_TODO_GROUP_MODE_${me}`, e.target.value);
        renderTodoList();
      };
    }

    updateGroupFilterButtonsState();

    // 並び順オプションの復元とバインド
    const sortSelect = document.getElementById('todo-sort-select');
    state.todoSortMode = localStorage.getItem(`SYNAPSE_TODO_SORT_MODE_${me}`) || 'due';

    function updateSortFilterButtonsState() {
      if (!sortSelect) return;
      sortSelect.value = state.todoSortMode;
    }

    if (sortSelect) {
      sortSelect.onchange = (e) => {
        state.todoSortMode = e.target.value;
        localStorage.setItem(`SYNAPSE_TODO_SORT_MODE_${me}`, e.target.value);
        renderTodoList();
      };
    }

    updateSortFilterButtonsState();

    // Asana フォーム要素
    const asanaSyncToggleContainer = document.getElementById('todo-form-asana-sync-toggle-container');
    const asanaSyncCheckbox = document.getElementById('todo-form-asana-sync');
    const asanaFieldsContainer = document.getElementById('todo-form-asana-fields');
    
    const selectAsanaWorkspace = document.getElementById('todo-form-asana-workspace');
    const selectAsanaProject = document.getElementById('todo-form-asana-project');
    const selectAsanaSection = document.getElementById('todo-form-asana-section');
    const selectAsanaAssignee = document.getElementById('todo-form-asana-assignee');

    const btnAsanaNewProject = document.getElementById('todo-form-asana-new-project-btn');
    const btnAsanaNewSection = document.getElementById('todo-form-asana-new-section-btn');

    // Google Tasks 連携フォーム要素
    const googleSyncToggleContainer = document.getElementById('todo-form-google-sync-toggle-container');
    const googleSyncCheckbox = document.getElementById('todo-form-google-sync');
    const googleFieldsContainer = document.getElementById('todo-form-google-fields');

    // Google/Asana連携が有効化されているかどうか
    const asanaLinked = localStorage.getItem(`SYNAPSE_ASANA_LINK_TASKS_${me}`) === 'true';
    const asanaToken = localStorage.getItem(`SYNAPSE_ASANA_PAT_${me}`) || '';
    const googleLinked = isGoogleLinked && (localStorage.getItem(`SYNAPSE_GOOGLE_LINK_TASKS_${me}`) === 'true');

    if (asanaLinked && asanaToken) {
      if (asanaSyncToggleContainer) asanaSyncToggleContainer.style.display = 'flex';
    } else {
      if (asanaSyncToggleContainer) asanaSyncToggleContainer.style.display = 'none';
    }

    if (googleLinked) {
      if (googleSyncToggleContainer) googleSyncToggleContainer.style.display = 'flex';
    } else {
      if (googleSyncToggleContainer) googleSyncToggleContainer.style.display = 'none';
    }

    // トグルの連動（排他制御）
    if (googleSyncCheckbox) {
      googleSyncCheckbox.onchange = async () => {
        if (googleSyncCheckbox.checked) {
          if (googleFieldsContainer) googleFieldsContainer.style.display = 'flex';
          if (asanaSyncCheckbox) {
            asanaSyncCheckbox.checked = false;
            if (asanaFieldsContainer) asanaFieldsContainer.style.display = 'none';
          }
          await updateGoogleTaskListDropdown();
        } else {
          if (googleFieldsContainer) googleFieldsContainer.style.display = 'none';
        }
      };
    }

    if (asanaSyncCheckbox) {
      asanaSyncCheckbox.onchange = async () => {
        if (asanaSyncCheckbox.checked) {
          if (asanaFieldsContainer) asanaFieldsContainer.style.display = 'flex';
          if (googleSyncCheckbox) {
            googleSyncCheckbox.checked = false;
            if (googleFieldsContainer) googleFieldsContainer.style.display = 'none';
          }
          // ワークスペース一覧のロード
          await populateAsanaWorkspaces();
        } else {
          if (asanaFieldsContainer) asanaFieldsContainer.style.display = 'none';
        }
      };
    }

    // ワークスペース変更時の連動
    if (selectAsanaWorkspace) {
      selectAsanaWorkspace.onchange = async () => {
        const workspaceGid = selectAsanaWorkspace.value;
        if (workspaceGid) {
          await populateAsanaProjects(workspaceGid);
          await populateAsanaAssignees(workspaceGid);
        }
      };
    }

    // プロジェクト変更時の連動
    if (selectAsanaProject) {
      selectAsanaProject.onchange = async () => {
        const projectGid = selectAsanaProject.value;
        await populateAsanaSections(projectGid);
      };
    }

    // 新規プロジェクト（フォルダ）作成
    if (btnAsanaNewProject) {
      btnAsanaNewProject.onclick = async (e) => {
        e.preventDefault();
        const workspaceGid = selectAsanaWorkspace.value;
        if (!workspaceGid) {
          showToast("ワークスペースを選択してください。", "error");
          return;
        }
        const name = prompt("新規プロジェクト（フォルダ）の名前を入力してください:");
        if (!name || !name.trim()) return;

        try {
          btnAsanaNewProject.disabled = true;
          btnAsanaNewProject.textContent = "作成中...";
          const prj = await createAsanaProject(asanaToken, workspaceGid, name.trim());
          showToast(`プロジェクト「${prj.name}」を作成しました。`, "success");
          
          // 再読み込み＆自動選択
          await populateAsanaProjects(workspaceGid, prj.gid);
        } catch (err) {
          showToast("プロジェクトの作成に失敗しました: " + err.message, "error");
        } finally {
          btnAsanaNewProject.disabled = false;
          btnAsanaNewProject.textContent = "📁 新規作成";
        }
      };
    }

    // 新規セクション作成
    if (btnAsanaNewSection) {
      btnAsanaNewSection.onclick = async (e) => {
        e.preventDefault();
        const projectGid = selectAsanaProject.value;
        if (!projectGid) {
          showToast("プロジェクトを選択してください。", "error");
          return;
        }
        const name = prompt("新規セクションの名前を入力してください:");
        if (!name || !name.trim()) return;

        try {
          btnAsanaNewSection.disabled = true;
          btnAsanaNewSection.textContent = "作成中...";
          const sec = await createAsanaSection(asanaToken, projectGid, name.trim());
          showToast(`セクション「${sec.name}」を作成しました。`, "success");
          
          // 再読み込み＆自動選択
          await populateAsanaSections(projectGid, sec.gid);
        } catch (err) {
          showToast("セクションの作成に失敗しました: " + err.message, "error");
        } finally {
          btnAsanaNewSection.disabled = false;
          btnAsanaNewSection.textContent = "📂 新規作成";
        }
      };
    }

    // 各種セレクトボックスの読み込み補助関数群
    window.populateAsanaWorkspaces = async function(selectedGid = '') {
      if (!selectAsanaWorkspace) return;
      selectAsanaWorkspace.innerHTML = '<option value="">読み込み中...</option>';
      const workspaces = await fetchAsanaWorkspaces(asanaToken);
      selectAsanaWorkspace.innerHTML = '';
      
      if (workspaces.length === 0) {
        selectAsanaWorkspace.innerHTML = '<option value="">(ワークスペースがありません)</option>';
        return;
      }

      workspaces.forEach(ws => {
        const opt = document.createElement('option');
        opt.value = ws.gid;
        opt.textContent = ws.name;
        if (selectedGid && ws.gid === selectedGid) opt.selected = true;
        selectAsanaWorkspace.appendChild(opt);
      });

      // 最初のワークスペースに基づきプロジェクトとメンバーを自動ロード
      const activeWsGid = selectAsanaWorkspace.value;
      if (activeWsGid) {
        await populateAsanaProjects(activeWsGid);
        await populateAsanaAssignees(activeWsGid);
      }
    };

    window.populateAsanaProjects = async function(workspaceGid, selectedGid = '') {
      if (!selectAsanaProject) return;
      selectAsanaProject.innerHTML = '<option value="">読み込み中...</option>';
      const projects = await fetchAsanaProjects(asanaToken, workspaceGid);
      selectAsanaProject.innerHTML = '<option value="">(プロジェクトなし)</option>';

      projects.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p.gid;
        opt.textContent = p.name;
        if (selectedGid && p.gid === selectedGid) opt.selected = true;
        selectAsanaProject.appendChild(opt);
      });

      // セクションも連動ロード
      const activePrjGid = selectAsanaProject.value;
      await populateAsanaSections(activePrjGid);
    };

    window.populateAsanaSections = async function(projectGid, selectedGid = '') {
      if (!selectAsanaSection) return;
      if (!projectGid) {
        selectAsanaSection.innerHTML = '<option value="">(プロジェクトが未選択です)</option>';
        return;
      }
      selectAsanaSection.innerHTML = '<option value="">読み込み中...</option>';
      const sections = await fetchAsanaSections(asanaToken, projectGid);
      selectAsanaSection.innerHTML = '<option value="">(セクションなし)</option>';

      sections.forEach(s => {
        const opt = document.createElement('option');
        opt.value = s.gid;
        opt.textContent = s.name;
        if (selectedGid && s.gid === selectedGid) opt.selected = true;
        selectAsanaSection.appendChild(opt);
      });
    };

    window.populateAsanaAssignees = async function(workspaceGid, selectedGid = '') {
      if (!selectAsanaAssignee) return;
      selectAsanaAssignee.innerHTML = '<option value="">読み込み中...</option>';
      const users = await fetchAsanaWorkspaceUsers(asanaToken, workspaceGid);
      selectAsanaAssignee.innerHTML = '<option value="">(未割り当て)</option>';

      users.forEach(u => {
        const opt = document.createElement('option');
        opt.value = u.gid;
        opt.textContent = u.name + (u.email ? ` (${u.email})` : '');
        if (selectedGid && u.gid === selectedGid) opt.selected = true;
        selectAsanaAssignee.appendChild(opt);
      });
    };

    // 共有トグルの連動
    if (chkShared) {
      chkShared.onchange = () => {
        if (chkShared.checked) {
          shareMembersContainer.style.display = 'flex';
          renderTodoShareMembersList();
        } else {
          shareMembersContainer.style.display = 'none';
        }
      };
    }

    // 保存ボタン
    if (saveTodoBtn) {
      saveTodoBtn.onclick = async () => {
        await saveTodoItem();
      };
    }

    // 削除ボタン
    if (deleteTodoBtn) {
      deleteTodoBtn.onclick = async () => {
        await deleteTodoItem();
      };
    }

    // === 📋 ToDo タブ切り替えロジック ===
    const tabActive = document.getElementById('todo-tab-active');
    const tabDone = document.getElementById('todo-tab-done');
    const containerActive = document.getElementById('todo-active-list-container');
    const containerDone = document.getElementById('todo-done-list-container');

    function switchTodoTab(tabType) {
      if (tabType === 'done') {
        // 完了済みタブを有効化
        if (tabActive) {
          tabActive.style.color = 'var(--text-secondary)';
          tabActive.style.borderBottomColor = 'transparent';
          tabActive.classList.remove('active');
        }
        if (tabDone) {
          tabDone.style.color = 'var(--primary)';
          tabDone.style.borderBottomColor = 'var(--primary)';
          tabDone.classList.add('active');
        }
        if (containerActive) containerActive.style.display = 'none';
        if (containerDone) containerDone.style.display = 'block';
        localStorage.setItem(`SYNAPSE_TODO_ACTIVE_TAB_${me}`, 'done');
      } else {
        // 未完了タブを有効化 (デフォルト)
        if (tabActive) {
          tabActive.style.color = 'var(--primary)';
          tabActive.style.borderBottomColor = 'var(--primary)';
          tabActive.classList.add('active');
        }
        if (tabDone) {
          tabDone.style.color = 'var(--text-secondary)';
          tabDone.style.borderBottomColor = 'transparent';
          tabDone.classList.remove('active');
        }
        if (containerActive) containerActive.style.display = 'block';
        if (containerDone) containerDone.style.display = 'none';
        localStorage.setItem(`SYNAPSE_TODO_ACTIVE_TAB_${me}`, 'active');
      }
    }

    if (tabActive) {
      tabActive.onclick = () => switchTodoTab('active');
    }
    if (tabDone) {
      tabDone.onclick = () => switchTodoTab('done');
    }

    // 初回ロード時のタブ状態の復元
    const savedTab = localStorage.getItem(`SYNAPSE_TODO_ACTIVE_TAB_${me}`) || 'active';
    switchTodoTab(savedTab);

    // === 📋 ToDo サービス別フィルター切り替えロジック ===
    const filterServiceSelect = document.getElementById('todo-filter-service-select');
    const filterGoogleOpt = document.getElementById('todo-filter-service-google-opt');
    const filterAsanaOpt = document.getElementById('todo-filter-service-asana-opt');

    function switchTodoServiceFilter(filterType) {
      state.todoServiceFilter = filterType;
      localStorage.setItem(`SYNAPSE_TODO_SERVICE_FILTER_${me}`, filterType);

      if (filterServiceSelect) {
        filterServiceSelect.value = filterType;
      }

      // 再描画
      renderTodoList();
    }

    function updateTodoServiceFilterButtonsState() {
      const isGoogleLinkedState = isGoogleLinked || (localStorage.getItem(`SYNAPSE_GOOGLE_LINKED_${me}`) === 'true');
      const hasAsanaPat = !!localStorage.getItem(`SYNAPSE_ASANA_PAT_${me}`);

      if (filterGoogleOpt) {
        if (!isGoogleLinkedState) {
          filterGoogleOpt.disabled = true;
          if (state.todoServiceFilter === 'google') {
            switchTodoServiceFilter('all');
          }
        } else {
          filterGoogleOpt.disabled = false;
        }
      }

      if (filterAsanaOpt) {
        if (!hasAsanaPat) {
          filterAsanaOpt.disabled = true;
          if (state.todoServiceFilter === 'asana') {
            switchTodoServiceFilter('all');
          }
        } else {
          filterAsanaOpt.disabled = false;
        }
      }
    }
    window.updateTodoServiceFilterButtonsState = updateTodoServiceFilterButtonsState;

    if (filterServiceSelect) {
      filterServiceSelect.onchange = (e) => {
        const val = e.target.value;
        if (val === 'google' && filterGoogleOpt && filterGoogleOpt.disabled) {
          filterServiceSelect.value = state.todoServiceFilter;
          return;
        }
        if (val === 'asana' && filterAsanaOpt && filterAsanaOpt.disabled) {
          filterServiceSelect.value = state.todoServiceFilter;
          return;
        }
        switchTodoServiceFilter(val);
      };
    }

    // サービスフィルターの初期復元
    const savedServiceFilter = localStorage.getItem(`SYNAPSE_TODO_SERVICE_FILTER_${me}`) || 'all';
    state.todoServiceFilter = savedServiceFilter;
    switchTodoServiceFilter(savedServiceFilter);
    updateTodoServiceFilterButtonsState();

    // 🔌 タスク外部連携設定のバインド
    initTaskSyncSettings(me);

    // Google連携中の場合、トークンのサイレント復元・更新を走らせて自動同期を実行
    const clientId = localStorage.getItem(`SYNAPSE_GOOGLE_CLIENT_ID_${me}`) || '';
    const apiKey = localStorage.getItem(`SYNAPSE_GOOGLE_API_KEY_${me}`) || '';
    if (isGoogleLinked && clientId && apiKey) {
      silentGoogleSync(clientId, apiKey);
    }

    // 初期ロード
    loadTodoTasks().then(() => {
      renderTodoList();
      resetTodoForm();
    });
  };

  // フォームリセット
  function resetTodoForm() {
    editingTodoId = null;
    document.getElementById('todo-form-title-text').textContent = '新規タスクの作成';
    document.getElementById('todo-form-title').value = '';
    document.getElementById('todo-form-due').value = '';
    document.getElementById('todo-form-notes').value = '';
    document.getElementById('todo-form-show-on-calendar').checked = true;
    
    const chkShared = document.getElementById('todo-form-shared');
    chkShared.checked = false;
    chkShared.disabled = false;
    document.getElementById('todo-form-share-members-container').style.display = 'none';
    
    document.getElementById('todo-form-delete-btn').style.display = 'none';
    
    // 保存ボタンの有効化
    const saveTodoBtn = document.getElementById('todo-form-save-btn');
    if (saveTodoBtn) {
      saveTodoBtn.disabled = false;
      saveTodoBtn.textContent = '保存する';
    }

    // Asana/Google 連携フォーム状態のリセット
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const asanaSyncToggleContainer = document.getElementById('todo-form-asana-sync-toggle-container');
    const asanaSyncCheckbox = document.getElementById('todo-form-asana-sync');
    const asanaFieldsContainer = document.getElementById('todo-form-asana-fields');
    
    const selectAsanaWorkspace = document.getElementById('todo-form-asana-workspace');
    const selectAsanaProject = document.getElementById('todo-form-asana-project');
    const selectAsanaSection = document.getElementById('todo-form-asana-section');
    const selectAsanaAssignee = document.getElementById('todo-form-asana-assignee');

    const googleSyncToggleContainer = document.getElementById('todo-form-google-sync-toggle-container');
    const googleSyncCheckbox = document.getElementById('todo-form-google-sync');
    const googleFieldsContainer = document.getElementById('todo-form-google-fields');
    const selectGoogleList = document.getElementById('todo-form-google-list');

    const asanaLinked = localStorage.getItem(`SYNAPSE_ASANA_LINK_TASKS_${me}`) === 'true';
    if (asanaSyncCheckbox) {
      asanaSyncCheckbox.checked = false;
      asanaSyncCheckbox.disabled = false;
    }
    if (asanaFieldsContainer) asanaFieldsContainer.style.display = 'none';
    
    if (asanaLinked) {
      if (asanaSyncToggleContainer) asanaSyncToggleContainer.style.display = 'flex';
    } else {
      if (asanaSyncToggleContainer) asanaSyncToggleContainer.style.display = 'none';
    }

    if (selectAsanaWorkspace) selectAsanaWorkspace.innerHTML = '';
    if (selectAsanaProject) selectAsanaProject.innerHTML = '<option value="">(プロジェクトなし)</option>';
    if (selectAsanaSection) selectAsanaSection.innerHTML = '<option value="">(セクションなし)</option>';
    if (selectAsanaAssignee) selectAsanaAssignee.innerHTML = '<option value="">(未割り当て)</option>';

    const googleLinked = isGoogleLinked && (localStorage.getItem(`SYNAPSE_GOOGLE_LINK_TASKS_${me}`) === 'true');
    if (googleSyncCheckbox) {
      googleSyncCheckbox.checked = false;
      googleSyncCheckbox.disabled = false;
    }
    if (googleFieldsContainer) googleFieldsContainer.style.display = 'none';

    if (googleLinked) {
      if (googleSyncToggleContainer) googleSyncToggleContainer.style.display = 'flex';
      updateGoogleTaskListDropdown();
    } else {
      if (googleSyncToggleContainer) googleSyncToggleContainer.style.display = 'none';
    }
  }

  // 共有メンバーリストの描画 (独自タスク用)
  function renderTodoShareMembersList() {
    const listEl = document.getElementById('todo-form-share-members-list');
    if (!listEl) return;
    listEl.innerHTML = '';

    // システムに存在する他のメンバー一覧を取得 (カレンダー共有候補と同様)
    const members = getCalendarAllowedMembers();
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();

    members.forEach(member => {
      const memberId = member.user_id.toLowerCase();
      if (memberId === me) return; // 自分自身は除外

      const label = document.createElement('label');
      label.style.display = 'flex';
      label.style.alignItems = 'center';
      label.style.gap = '0.3rem';
      label.style.fontSize = '0.72rem';
      label.style.cursor = 'pointer';
      label.style.userSelect = 'none';

      const input = document.createElement('input');
      input.type = 'checkbox';
      input.value = member.user_id;
      input.className = 'todo-share-member-checkbox';
      input.style.width = '12px';
      input.style.height = '12px';

      label.appendChild(input);
      label.appendChild(document.createTextNode(member.full_name || member.user_id));
      listEl.appendChild(label);
    });
  }

  // ToDoタスクのロード (Supabase DB または localStorage)
  async function loadTodoTasks() {
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();

    if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
      try {
        // supabase-jsのURL生成バグを回避するため、.contains() や .or() などの
        // 記号を含む配列フィルタを避け、DBから全件取得してクライアント側でフィルタリングする
        const { data, error } = await partnerSupabaseClient
          .from('synapse_todo_tasks')
          .select('*');

        if (error) throw error;

        if (data) {
          const rawUserIdLower = rawUserId.toLowerCase();
          todoTasks = data.filter(t => {
            // 自分のタスク
            if (t.user_id && t.user_id.toLowerCase() === me) return true;
            // 共有メンバーに自分が含まれているか、全員共有('*')か
            if (t.shared_with && Array.isArray(t.shared_with)) {
              const sharedLower = t.shared_with.map(s => s.toLowerCase());
              if (sharedLower.includes(rawUserIdLower) || sharedLower.includes('*')) {
                return true;
              }
            }
            return false;
          });

          localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));
          return;
        }
      } catch (err) {
        console.warn("[ToDo DB] Load failed, falling back to local storage:", err);
      }
    }

    // フォールバック: ローカルストレージ
    const saved = localStorage.getItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`);
    todoTasks = saved ? JSON.parse(saved) : [];
  }

  // ToDoタスクの保存 (DB & localStorage & Asana)
  async function saveTodoItem() {
    const titleInput = document.getElementById('todo-form-title');
    const title = titleInput.value.trim();
    if (!title) {
      showToast("タスク名を入力してください。", "error");
      return;
    }

    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const myName = state.currentUser ? state.currentUser.full_name : 'Guest';

    const saveTodoBtn = document.getElementById('todo-form-save-btn');
    if (saveTodoBtn) {
      saveTodoBtn.disabled = true;
      saveTodoBtn.textContent = '保存中...';
    }

    try {
      const due = document.getElementById('todo-form-due').value;
      const notes = document.getElementById('todo-form-notes').value.trim();
      const showOnCalendar = document.getElementById('todo-form-show-on-calendar').checked;
      const isShared = document.getElementById('todo-form-shared').checked;

      let sharedWith = [];
      if (isShared) {
        const checkedBoxes = document.querySelectorAll('.todo-share-member-checkbox:checked');
        checkedBoxes.forEach(box => sharedWith.push(box.value));
        if (sharedWith.length === 0) {
          sharedWith = ['*']; // 指定なしの場合は全員共有
        }
      }

      const isNew = !editingTodoId;
      let taskId = isNew ? `task-${generate8DigitId()}` : editingTodoId;

      // もし他人の共有タスクを編集しようとした場合はガード
      if (!isNew) {
        const existing = todoTasks.find(t => t.id === taskId);
        if (existing && existing.user_id !== me) {
          showToast("他人のタスクは編集できません。", "error");
          if (saveTodoBtn) {
            saveTodoBtn.disabled = false;
            saveTodoBtn.textContent = '変更を保存';
          }
          return;
        }
      }

      // Asana 同期関連の処理
      const asanaSyncCheckbox = document.getElementById('todo-form-asana-sync');
      const asanaLinked = localStorage.getItem(`SYNAPSE_ASANA_LINK_TASKS_${me}`) === 'true';
      const asanaToken = localStorage.getItem(`SYNAPSE_ASANA_PAT_${me}`) || '';

      const selectAsanaWorkspace = document.getElementById('todo-form-asana-workspace');
      const selectAsanaProject = document.getElementById('todo-form-asana-project');
      const selectAsanaSection = document.getElementById('todo-form-asana-section');
      const selectAsanaAssignee = document.getElementById('todo-form-asana-assignee');

      let workspaceName = '';
      let projectName = '';
      let sectionName = '';

      if (asanaSyncCheckbox && asanaSyncCheckbox.checked && asanaLinked && asanaToken) {
        const workspaceGid = selectAsanaWorkspace ? selectAsanaWorkspace.value : '';
        const projectGid = selectAsanaProject ? selectAsanaProject.value : '';
        const sectionGid = selectAsanaSection ? selectAsanaSection.value : '';
        const assigneeGid = selectAsanaAssignee ? selectAsanaAssignee.value : '';

        if (!workspaceGid) {
          showToast("Asanaのワークスペースを選択してください。", "error");
          if (saveTodoBtn) {
            saveTodoBtn.disabled = false;
            saveTodoBtn.textContent = isNew ? '保存する' : '変更を保存';
          }
          return;
        }

        workspaceName = selectAsanaWorkspace.options[selectAsanaWorkspace.selectedIndex]?.text || '';
        projectName = (selectAsanaProject && selectAsanaProject.selectedIndex >= 0) ? selectAsanaProject.options[selectAsanaProject.selectedIndex].text : '';
        if (projectName === '(プロジェクトなし)') projectName = '';
        sectionName = (selectAsanaSection && selectAsanaSection.selectedIndex >= 0) ? selectAsanaSection.options[selectAsanaSection.selectedIndex].text : '';
        if (sectionName === '(セクションなし)') sectionName = '';

        if (isNew) {
          // Asana に新規タスク作成
          const asanaReqBody = {
            data: {
              name: title,
              notes: notes,
              workspace: workspaceGid,
              projects: projectGid ? [projectGid] : [],
              assignee: assigneeGid || null
            }
          };
          if (due) {
            asanaReqBody.data.due_on = due;
          }
          const asanaRes = await fetch('https://app.asana.com/api/1.0/tasks', {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${asanaToken}`,
              'Content-Type': 'application/json',
              'Accept': 'application/json'
            },
            body: JSON.stringify(asanaReqBody)
          });
          if (!asanaRes.ok) throw new Error("Asanaタスクの作成に失敗しました。");
          const asanaResJson = await asanaRes.json();
          const newAsanaTask = asanaResJson.data;
          
          taskId = `asana-${newAsanaTask.gid}`;

          // セクションがある場合は、そのセクションへ移動
          if (projectGid && sectionGid) {
            await fetch(`https://app.asana.com/api/1.0/sections/${sectionGid}/addTask`, {
              method: 'POST',
              headers: {
                'Authorization': `Bearer ${asanaToken}`,
                'Content-Type': 'application/json',
                'Accept': 'application/json'
              },
              body: JSON.stringify({ data: { task: newAsanaTask.gid } })
            });
          }
        } else if (taskId.startsWith('asana-')) {
          // Asanaの既存タスク更新
          const taskGid = taskId.replace('asana-', '');
          const asanaReqBody = {
            data: {
              name: title,
              notes: notes,
              assignee: assigneeGid || null,
              due_on: due || null
            }
          };
          const asanaRes = await fetch(`https://app.asana.com/api/1.0/tasks/${taskGid}`, {
            method: 'PUT',
            headers: {
              'Authorization': `Bearer ${asanaToken}`,
              'Content-Type': 'application/json',
              'Accept': 'application/json'
            },
            body: JSON.stringify(asanaReqBody)
          });
          if (!asanaRes.ok) throw new Error("Asanaタスクの更新に失敗しました。");

          // プロジェクト・セクションの移動
          if (projectGid) {
            const addProjectBody = {
              data: {
                project: projectGid
              }
            };
            if (sectionGid) {
              addProjectBody.data.section = sectionGid;
            }
            await fetch(`https://app.asana.com/api/1.0/tasks/${taskGid}/addProject`, {
              method: 'POST',
              headers: {
                'Authorization': `Bearer ${asanaToken}`,
                'Content-Type': 'application/json',
                'Accept': 'application/json'
              },
              body: JSON.stringify(addProjectBody)
            });
          }
        }
      }

      // Google Tasks 同期関連の処理
      const googleSyncCheckbox = document.getElementById('todo-form-google-sync');
      const selectGoogleList = document.getElementById('todo-form-google-list');
      const googleLinked = isGoogleLinked && (localStorage.getItem(`SYNAPSE_GOOGLE_LINK_TASKS_${me}`) === 'true');

      let googleListName = '';

      if (googleSyncCheckbox && googleSyncCheckbox.checked && googleLinked && googleAccessToken) {
        const googleListId = selectGoogleList ? selectGoogleList.value : '';
        if (!googleListId) {
          showToast("Google To-Doの保存先リストを選択してください。", "error");
          if (saveTodoBtn) {
            saveTodoBtn.disabled = false;
            saveTodoBtn.textContent = isNew ? '保存する' : '変更を保存';
          }
          return;
        }

        googleListName = selectGoogleList.options[selectGoogleList.selectedIndex]?.text || '';

        if (isNew) {
          // Google に新規タスク作成
          const googleTask = await createGoogleTask(googleListId, {
            title: title,
            notes: notes,
            due: due,
            status: 'needsAction'
          });
          taskId = `google-task-${googleTask.id}`;
        } else if (taskId.startsWith('google-task-')) {
          const googleTaskId = taskId.replace('google-task-', '');
          let oldListName = '';
          const existing = todoTasks.find(t => t.id === taskId);
          if (existing && existing.notes) {
            const match = existing.notes.match(/^【Google To-Do帰属: ([^】]+)】/);
            if (match) {
              oldListName = match[1] ? match[1].trim() : '';
            }
          }

          if (oldListName && oldListName !== googleListName) {
            // リスト移動が発生した場合：元のリストからタスクを削除し、新しいリストに再作成
            const oldList = (state.googleTaskLists || []).find(l => l.title === oldListName);
            if (oldList) {
              await deleteGoogleTask(oldList.id, googleTaskId);
            }
            const googleTask = await createGoogleTask(googleListId, {
              title: title,
              notes: notes,
              due: due,
              status: existing ? existing.status : 'needsAction'
            });
            // DBにある古いIDを削除しておく
            if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
              try {
                await partnerSupabaseClient
                  .from('synapse_todo_tasks')
                  .delete()
                  .eq('id', taskId);
              } catch (delErr) {
                console.warn("[Google Tasks Sync] Failed to delete old task row on list move:", delErr);
              }
            }
            taskId = `google-task-${googleTask.id}`;
          } else {
            // 通常の更新
            await updateGoogleTask(googleListId, googleTaskId, {
              title: title,
              notes: notes,
              due: due,
              status: existing ? existing.status : 'needsAction'
            });
          }
        }
      }

      // 連携タスクの場合、notesにアソシエーションの情報をプレフィックスとして追加
      let updatedNotes = notes;
      if (taskId.startsWith('asana-') && workspaceName) {
        const belongStr = `【Asana帰属: ${workspaceName}${projectName ? ` ＞ ${projectName}` : ''}${sectionName ? ` (${sectionName})` : ''}】`;
        const lines = notes.split('\n');
        const filteredLines = lines.filter(line => !line.startsWith('【Asana帰属:'));
        filteredLines.unshift(belongStr);
        updatedNotes = filteredLines.join('\n');
      } else if (taskId.startsWith('google-task-') && googleListName) {
        const belongStr = `【Google To-Do帰属: ${googleListName}】`;
        const lines = notes.split('\n');
        const filteredLines = lines.filter(line => !line.startsWith('【Google To-Do帰属:'));
        filteredLines.unshift(belongStr);
        updatedNotes = filteredLines.join('\n');
      }

      const taskData = {
        id: taskId,
        user_id: me,
        user_name: myName,
        title: title,
        due: due || null,
        notes: updatedNotes,
        status: isNew ? 'needsAction' : (todoTasks.find(t => t.id === taskId)?.status || 'needsAction'),
        show_on_calendar: showOnCalendar,
        shared: isShared,
        shared_with: sharedWith,
        created_at: isNew ? new Date().toISOString() : (todoTasks.find(t => t.id === taskId)?.created_at || new Date().toISOString())
      };

      if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
        try {
          const { error } = await partnerSupabaseClient
            .from('synapse_todo_tasks')
            .upsert(taskData);

          if (error) throw error;
        } catch (err) {
          console.warn("[ToDo DB] Save failed, saving to sync queue:", err);
          pushToSyncQueue('synapse_todo_tasks', taskData);
        }
      }

      // メモリ ＆ ローカルストレージ更新
      const idx = todoTasks.findIndex(t => t.id === taskId);
      if (idx !== -1) {
        todoTasks[idx] = taskData;
      } else {
        todoTasks.push(taskData);
      }
      localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));

      // ToDo連携がOFFかつ、カレンダー連携がONのとき、Googleカレンダーにタスク予定として同期する
      if (isGoogleLinked && state.googleLinkCalendar !== false && !state.googleLinkTasks) {
        if (showOnCalendar && due) {
          const taskEvent = {
            title: (taskData.status === 'completed' ? '✓ ' : '○ ') + taskData.title,
            start_time: due,
            end_time: due,
            description: updatedNotes + `\n\n__SYNAPSE_TODO_ID__:${taskData.id}`
          };

          const existingEventId = taskData.google_event_id || localStorage.getItem(`SYNAPSE_TODO_GOOGLE_EVENT_ID_${taskData.id}`);
          if (existingEventId) {
            updateTodoEventOnGoogleCalendar(existingEventId, taskEvent);
          } else {
            addTodoEventToGoogleCalendar(taskData.id, taskEvent);
          }
        } else {
          const existingEventId = taskData.google_event_id || localStorage.getItem(`SYNAPSE_TODO_GOOGLE_EVENT_ID_${taskData.id}`);
          if (existingEventId) {
            deleteTodoEventFromGoogleCalendar(existingEventId);
            taskData.google_event_id = null;
          }
        }
      }

      showToast(isNew ? "タスクを追加しました。" : "タスクを更新しました。", "success");
      renderTodoList();
      resetTodoForm();

      // カレンダーの再描画もトリガー
      if (state.mypageCalendarInitialized) {
        renderMypageCalendar();
      }
    } catch (globalErr) {
      console.error("[ToDo Save Error] Global error caught:", globalErr);
      
      let errorMsg = globalErr.message || '';
      if (errorMsg.includes('ACCESS_TOKEN_SCOPE_INSUFFICIENT') || 
          errorMsg.includes('insufficient authentication scopes') || 
          errorMsg.includes('403') || 
          errorMsg.includes('Insufficient Permission')) {
        
        // キャッシュされた Google トークンをクリア
        localStorage.removeItem(`SYNAPSE_GOOGLE_ACCESS_TOKEN_${me}`);
        localStorage.removeItem(`SYNAPSE_GOOGLE_TOKEN_EXPIRES_${me}`);
        googleAccessToken = null;
        
        errorMsg = "Googleのアクセス権限が不足しています。一度Google連携を解除し、再度連携する際、Google公式画面で『Google To-Doのすべてのタスクの表示・編集・作成・削除』という項目に必ずチェック（ON）を入れてください。";
      }
      
      showToast("タスクの保存に失敗しました: " + errorMsg, "error", 12000);
      if (saveTodoBtn) {
        saveTodoBtn.disabled = false;
        saveTodoBtn.textContent = (!editingTodoId) ? '保存する' : '変更を保存';
      }
    }
  }

  // ToDoタスクの削除
  async function deleteTodoItem() {
    if (!editingTodoId) return;
    if (!confirm("このタスクを削除しますか？")) return;

    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();

    // 他人の共有タスクは削除不可
    const existing = todoTasks.find(t => t.id === editingTodoId);
    if (existing && existing.user_id !== me) {
      showToast("他人のタスクは削除できません。", "error");
      return;
    }

    // Asana タスクであれば Asana 側も削除
    if (editingTodoId.startsWith('asana-')) {
      const asanaLinked = localStorage.getItem(`SYNAPSE_ASANA_LINK_TASKS_${me}`) === 'true';
      const asanaToken = localStorage.getItem(`SYNAPSE_ASANA_PAT_${me}`) || '';
      if (asanaLinked && asanaToken) {
        const taskGid = editingTodoId.replace('asana-', '');
        try {
          await fetch(`https://app.asana.com/api/1.0/tasks/${taskGid}`, {
            method: 'DELETE',
            headers: {
              'Authorization': `Bearer ${asanaToken}`,
              'Accept': 'application/json'
            }
          });
        } catch (err) {
          console.warn("[Asana API] Failed to delete task on Asana:", err);
        }
      }
    }

    // Google タスクであれば Google 側も削除
    if (editingTodoId.startsWith('google-task-')) {
      const googleLinked = isGoogleLinked && (localStorage.getItem(`SYNAPSE_GOOGLE_LINK_TASKS_${me}`) === 'true');
      if (googleLinked && googleAccessToken) {
        const googleTaskId = editingTodoId.replace('google-task-', '');
        let listName = '';
        if (existing && existing.notes) {
          const match = existing.notes.match(/^【Google To-Do帰属: ([^】]+)】/);
          if (match) {
            listName = match[1] ? match[1].trim() : '';
          }
        }
        if (listName) {
          const list = (state.googleTaskLists || []).find(l => l.title === listName);
          if (list) {
            try {
              await deleteGoogleTask(list.id, googleTaskId);
            } catch (err) {
              console.warn("[Google Tasks API] Failed to delete task on Google To-Do:", err);
            }
          }
        }
      }
    }

    if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
      try {
        const { error } = await partnerSupabaseClient
          .from('synapse_todo_tasks')
          .delete()
          .eq('id', editingTodoId);

        if (error) throw error;
      } catch (err) {
        console.warn("[ToDo DB] Delete failed:", err);
      }
    }

    // もし Google カレンダーにイベントとして同期されていれば削除する
    const existingEventId = existing.google_event_id || localStorage.getItem(`SYNAPSE_TODO_GOOGLE_EVENT_ID_${editingTodoId}`);
    if (existingEventId && isGoogleLinked && state.googleLinkCalendar !== false && !state.googleLinkTasks) {
      deleteTodoEventFromGoogleCalendar(existingEventId);
    }

    todoTasks = todoTasks.filter(t => t.id !== editingTodoId);
    localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));

    showToast("タスクを削除しました。", "success");
    renderTodoList();
    resetTodoForm();

    if (state.mypageCalendarInitialized) {
      renderMypageCalendar();
    }
  }

  // 完了トグル（チェックボックス一発完了）
  async function toggleTodoStatus(taskId, isCompleted) {
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();

    const task = todoTasks.find(t => t.id === taskId);
    if (!task) return;

    const nextStatus = isCompleted ? 'completed' : 'needsAction';
    task.status = nextStatus;

    if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
      try {
        const { error } = await partnerSupabaseClient
          .from('synapse_todo_tasks')
          .update({ status: nextStatus })
          .eq('id', taskId);

        if (error) throw error;
      } catch (err) {
        console.warn("[ToDo DB] Status update failed:", err);
      }
    }

    localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));

    // Asanaのタスク連携がONのとき、Asana側の完了状態も同期する
    if (taskId.startsWith('asana-')) {
      const asanaLinked = localStorage.getItem(`SYNAPSE_ASANA_LINK_TASKS_${me}`) === 'true';
      const asanaPat = localStorage.getItem(`SYNAPSE_ASANA_PAT_${me}`);
      if (asanaLinked && asanaPat) {
        const taskGid = taskId.replace('asana-', '');
        fetch(`https://app.asana.com/api/1.0/tasks/${taskGid}`, {
          method: 'PUT',
          headers: {
            'Authorization': `Bearer ${asanaPat}`,
            'Content-Type': 'application/json',
            'Accept': 'application/json'
          },
          body: JSON.stringify({
            data: { completed: !!isCompleted }
          })
        }).catch(err => console.warn("[Asana Sync] Task status update failed:", err));
      }
    }

    // Google のタスク連携がONのとき、Google側の完了状態も同期する
    if (taskId.startsWith('google-task-')) {
      const googleLinked = isGoogleLinked && (localStorage.getItem(`SYNAPSE_GOOGLE_LINK_TASKS_${me}`) === 'true');
      if (googleLinked && googleAccessToken) {
        const googleTaskId = taskId.replace('google-task-', '');
        let listName = '';
        if (task.notes) {
          const match = task.notes.match(/^【Google To-Do帰属: ([^】]+)】/);
          if (match) {
            listName = match[1] ? match[1].trim() : '';
          }
        }
        if (listName) {
          const list = (state.googleTaskLists || []).find(l => l.title === listName);
          if (list) {
            updateGoogleTask(list.id, googleTaskId, {
              title: task.title,
              notes: task.notes,
              due: task.due,
              status: isCompleted ? 'completed' : 'needsAction'
            }).catch(err => console.warn("[Google Tasks Sync] Task status update failed:", err));
          }
        }
      }
    }

    // ToDo連携がOFFかつ、カレンダー連携がONのとき、Googleカレンダーにタスク予定として同期する
    if (isGoogleLinked && state.googleLinkCalendar !== false && !state.googleLinkTasks) {
      if (task.show_on_calendar && task.due) {
        const taskEvent = {
          title: (task.status === 'completed' ? '✓ ' : '○ ') + task.title,
          start_time: task.due,
          end_time: task.due,
          description: (task.notes || '') + `\n\n__SYNAPSE_TODO_ID__:${task.id}`
        };

        const existingEventId = task.google_event_id || localStorage.getItem(`SYNAPSE_TODO_GOOGLE_EVENT_ID_${task.id}`);
        if (existingEventId) {
          updateTodoEventOnGoogleCalendar(existingEventId, taskEvent);
        } else {
          addTodoEventToGoogleCalendar(task.id, taskEvent);
        }
      }
    }

    renderTodoList();

    if (state.mypageCalendarInitialized) {
      renderMypageCalendar();
    }
  }

  // タスク詳細の読み込み（編集フォームへ反映）
  function loadTodoDetails(taskId) {
    const task = todoTasks.find(t => t.id === taskId);
    if (!task) return;

    editingTodoId = taskId;
    
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const isOwner = task.user_id === me;

    document.getElementById('todo-form-title-text').textContent = isOwner ? 'タスクの編集' : 'タスクの詳細 (共有)';
    
    const inputTitle = document.getElementById('todo-form-title');
    const inputDue = document.getElementById('todo-form-due');
    const inputNotes = document.getElementById('todo-form-notes');
    const chkShowOnCalendar = document.getElementById('todo-form-show-on-calendar');
    const chkShared = document.getElementById('todo-form-shared');
    const saveTodoBtn = document.getElementById('todo-form-save-btn');
    const deleteTodoBtn = document.getElementById('todo-form-delete-btn');
    const shareMembersContainer = document.getElementById('todo-form-share-members-container');

    // フォームへの値反映
    inputTitle.value = task.title;
    inputDue.value = task.due || '';
    inputNotes.value = task.notes || '';
    chkShowOnCalendar.checked = task.show_on_calendar !== false;
    chkShared.checked = !!task.shared;

    // 権限制御 (作成者以外は編集・削除不可の閲覧専用モード)
    inputTitle.disabled = !isOwner;
    inputDue.disabled = !isOwner;
    inputNotes.disabled = !isOwner;
    chkShowOnCalendar.disabled = !isOwner;
    chkShared.disabled = !isOwner;

    if (isOwner) {
      deleteTodoBtn.style.display = 'block';
      if (saveTodoBtn) {
        saveTodoBtn.disabled = false;
        saveTodoBtn.textContent = '変更を保存';
      }
    } else {
      deleteTodoBtn.style.display = 'none';
      if (saveTodoBtn) {
        saveTodoBtn.disabled = true;
        saveTodoBtn.textContent = '保存不可 (閲覧のみ)';
      }
    }

    // 共有メンバーの描画と選択状態の復元
    if (task.shared) {
      shareMembersContainer.style.display = 'flex';
      renderTodoShareMembersList();
      
      const boxes = document.querySelectorAll('.todo-share-member-checkbox');
      boxes.forEach(box => {
        box.checked = task.shared_with && task.shared_with.includes(box.value);
        box.disabled = !isOwner;
      });
    } else {
      shareMembersContainer.style.display = 'none';
    }

    // Asana / Google 連携情報の復元とロード
    const asanaSyncToggleContainer = document.getElementById('todo-form-asana-sync-toggle-container');
    const asanaSyncCheckbox = document.getElementById('todo-form-asana-sync');
    const asanaFieldsContainer = document.getElementById('todo-form-asana-fields');

    const selectAsanaWorkspace = document.getElementById('todo-form-asana-workspace');
    const selectAsanaProject = document.getElementById('todo-form-asana-project');
    const selectAsanaSection = document.getElementById('todo-form-asana-section');
    const selectAsanaAssignee = document.getElementById('todo-form-asana-assignee');

    const googleSyncToggleContainer = document.getElementById('todo-form-google-sync-toggle-container');
    const googleSyncCheckbox = document.getElementById('todo-form-google-sync');
    const googleFieldsContainer = document.getElementById('todo-form-google-fields');
    const selectGoogleList = document.getElementById('todo-form-google-list');

    const asanaLinked = localStorage.getItem(`SYNAPSE_ASANA_LINK_TASKS_${me}`) === 'true';
    const asanaToken = localStorage.getItem(`SYNAPSE_ASANA_PAT_${me}`) || '';
    const googleLinked = isGoogleLinked && (localStorage.getItem(`SYNAPSE_GOOGLE_LINK_TASKS_${me}`) === 'true');

    if (asanaSyncCheckbox) {
      asanaSyncCheckbox.checked = false;
      asanaSyncCheckbox.disabled = !isOwner;
    }
    if (asanaFieldsContainer) asanaFieldsContainer.style.display = 'none';

    if (googleSyncCheckbox) {
      googleSyncCheckbox.checked = false;
      googleSyncCheckbox.disabled = !isOwner;
    }
    if (googleFieldsContainer) googleFieldsContainer.style.display = 'none';
    if (selectGoogleList) selectGoogleList.disabled = !isOwner;

    if (task.id.startsWith('asana-')) {
      if (asanaSyncCheckbox) {
        asanaSyncCheckbox.checked = true;
        asanaSyncCheckbox.disabled = true;
      }
      if (asanaFieldsContainer) asanaFieldsContainer.style.display = 'flex';
      if (googleSyncToggleContainer) googleSyncToggleContainer.style.display = 'none';

      if (asanaLinked && asanaToken) {
        const taskGid = task.id.replace('asana-', '');
        if (selectAsanaWorkspace) selectAsanaWorkspace.innerHTML = '<option value="">読み込み中...</option>';
        if (selectAsanaProject) selectAsanaProject.innerHTML = '<option value="">読み込み中...</option>';
        if (selectAsanaSection) selectAsanaSection.innerHTML = '<option value="">読み込み中...</option>';
        if (selectAsanaAssignee) selectAsanaAssignee.innerHTML = '<option value="">読み込み中...</option>';

        fetch(`https://app.asana.com/api/1.0/tasks/${taskGid}?opt_fields=workspace.gid,projects.gid,memberships.project.gid,memberships.section.gid,assignee.gid`, {
          headers: { 'Authorization': `Bearer ${asanaToken}`, 'Accept': 'application/json' }
        })
        .then(res => res.json())
        .then(async (resJson) => {
          const detail = resJson.data;
          if (!detail) return;

          const wsGid = detail.workspace ? detail.workspace.gid : '';
          const prjGid = (detail.projects && detail.projects.length > 0) ? detail.projects[0].gid : '';
          const assigneeGid = detail.assignee ? detail.assignee.gid : '';
          let secGid = '';
          if (detail.memberships && detail.memberships.length > 0) {
            const firstM = detail.memberships.find(m => m.project && m.project.gid === prjGid);
            if (firstM && firstM.section) secGid = firstM.section.gid;
          }

          if (wsGid && typeof window.populateAsanaWorkspaces === 'function') {
            await window.populateAsanaWorkspaces(wsGid);
            if (prjGid && typeof window.populateAsanaProjects === 'function') {
              await window.populateAsanaProjects(wsGid, prjGid);
              if (secGid && typeof window.populateAsanaSections === 'function') {
                await window.populateAsanaSections(prjGid, secGid);
              }
            }
            if (assigneeGid && typeof window.populateAsanaAssignees === 'function') {
              await window.populateAsanaAssignees(wsGid, assigneeGid);
            }
          }
        })
        .catch(err => {
          console.warn("[Asana API] Failed to load task details for editing:", err);
          showToast("Asanaの所属先詳細の読み込みに失敗しました。", "error");
        });
      }
    } else if (task.id.startsWith('google-task-')) {
      if (googleSyncCheckbox) {
        googleSyncCheckbox.checked = true;
        googleSyncCheckbox.disabled = true;
      }
      if (googleFieldsContainer) googleFieldsContainer.style.display = 'flex';
      if (asanaSyncToggleContainer) asanaSyncToggleContainer.style.display = 'none';

      let listName = '';
      if (task.notes) {
        const match = task.notes.match(/^【Google To-Do帰属: ([^】]+)】/);
        if (match) {
          listName = match[1] ? match[1].trim() : '';
        }
      }

      updateGoogleTaskListDropdown().then(() => {
        if (listName && selectGoogleList) {
          const list = (state.googleTaskLists || []).find(l => l.title === listName);
          if (list) {
            selectGoogleList.value = list.id;
          }
        }
      });
    } else {
      // 通常のタスク
      if (asanaLinked && asanaToken) {
        if (asanaSyncToggleContainer) asanaSyncToggleContainer.style.display = 'flex';
      } else {
        if (asanaSyncToggleContainer) asanaSyncToggleContainer.style.display = 'none';
      }
      if (googleLinked) {
        if (googleSyncToggleContainer) googleSyncToggleContainer.style.display = 'flex';
      } else {
        if (googleSyncToggleContainer) googleSyncToggleContainer.style.display = 'none';
      }
    }
  }



  // ToDo DOM要素生成のヘルパー
  function createTodoDomItem(task, todayStr, me) {
    const row = document.createElement('div');
    row.className = `todo-item ${task.status === 'completed' ? 'completed' : ''}`;
    
    // チェックボックス
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'todo-item-checkbox';
    checkbox.checked = task.status === 'completed';
    checkbox.onclick = (e) => {
      e.stopPropagation(); // 行全体のクリックと競合させない
      toggleTodoStatus(task.id, checkbox.checked);
    };

    // タイトル
    const title = document.createElement('span');
    title.className = 'todo-item-title';
    let prefix = '';
    if (task.id.startsWith('google-')) {
      prefix = '🔹 ';
    } else if (task.id.startsWith('asana-')) {
      prefix = '🔺 ';
    }
    title.textContent = prefix + task.title;

    row.appendChild(checkbox);
    row.appendChild(title);

    // メタ情報（バッジ類）を右側に寄せるためのコンテナ
    const metaContainer = document.createElement('div');
    metaContainer.className = 'todo-item-meta';
    metaContainer.style.marginLeft = 'auto';
    metaContainer.style.display = 'flex';
    metaContainer.style.alignItems = 'center';
    metaContainer.style.gap = '0.5rem';
    metaContainer.style.flexShrink = '0';
    metaContainer.style.minWidth = '0';

    // Asana の帰属先情報バッジの追加
    if (task.id.startsWith('asana-') && state.todoGroupMode !== 'project') {
      let wsName = task.workspace_name || '';
      let prjName = task.project_name || '';
      let secName = task.section_name || '';
      
      if (!wsName && !prjName && task.notes) {
        const match = task.notes.match(/^【Asana帰属: ([^＞】]+)(?: ＞ ([^】\()]+))?(?:\s*\(([^)]+)\))?】/);
        if (match) {
          wsName = match[1] ? match[1].trim() : '';
          prjName = match[2] ? match[2].trim() : '';
          secName = match[3] ? match[3].trim() : '';
        }
      }

      if (wsName || prjName) {
        const belongBadge = document.createElement('span');
        belongBadge.className = 'todo-asana-belong-badge';
        belongBadge.style.fontSize = '0.65rem';
        belongBadge.style.color = '#e04f5f'; // Asanaのブランドカラー風（レッドピンク）
        belongBadge.style.background = 'rgba(224, 79, 95, 0.08)';
        belongBadge.style.border = '1px solid rgba(224, 79, 95, 0.2)';
        belongBadge.style.padding = '1px 5px';
        belongBadge.style.borderRadius = '3px';
        belongBadge.style.fontWeight = '600';
        belongBadge.style.display = 'inline-flex';
        belongBadge.style.alignItems = 'center';
        belongBadge.style.gap = '2px';
        
        let badgeText = 'Asana: ';
        if (wsName) badgeText += wsName;
        if (prjName) badgeText += ` ＞ ${prjName}`;
        if (secName && secName !== 'Untitled section' && secName !== '無題のセクション') {
          badgeText += ` (${secName})`;
        }
        belongBadge.textContent = badgeText;
        metaContainer.appendChild(belongBadge);
      }
    }
    // Google の帰属先リスト情報バッジの追加
    if (task.id.startsWith('google-') && state.todoGroupMode !== 'project') {
      let listName = '';
      if (task.notes) {
        const match = task.notes.match(/^【Google To-Do帰属: ([^】]+)】/);
        if (match) {
          listName = match[1] ? match[1].trim() : '';
        }
      }

      if (listName) {
        const belongBadge = document.createElement('span');
        belongBadge.className = 'todo-google-belong-badge';
        belongBadge.style.fontSize = '0.65rem';
        belongBadge.style.color = '#3b82f6'; // Googleのブランドカラー（ブルー）
        belongBadge.style.background = 'rgba(59, 130, 246, 0.08)';
        belongBadge.style.border = '1px solid rgba(59, 130, 246, 0.2)';
        belongBadge.style.padding = '1px 5px';
        belongBadge.style.borderRadius = '3px';
        belongBadge.style.fontWeight = '600';
        belongBadge.style.display = 'inline-flex';
        belongBadge.style.alignItems = 'center';
        belongBadge.style.gap = '2px';
        belongBadge.textContent = `Google: ${listName}`;
        metaContainer.appendChild(belongBadge);
      }
    }

    // 共有バッジ
    if (task.user_id !== me) {
      const shareBadge = document.createElement('span');
      shareBadge.className = 'todo-shared-badge';
      shareBadge.textContent = `${task.user_name || task.user_id} から共有`;
      metaContainer.appendChild(shareBadge);
    } else if (task.shared) {
      const shareBadge = document.createElement('span');
      shareBadge.className = 'todo-shared-badge';
      shareBadge.textContent = `共有中`;
      metaContainer.appendChild(shareBadge);
    }

    // 期日バッジ
    if (task.due) {
      const dueBadge = document.createElement('span');
      dueBadge.className = `todo-due-badge ${task.status === 'completed' ? 'completed' : (task.due < todayStr ? 'overdue' : '')}`;
      dueBadge.textContent = task.due.replace(/-/g, '/');
      metaContainer.appendChild(dueBadge);
    }

    row.appendChild(metaContainer);

    // ツールチップ用テキストの組み立て
    let tooltip = `タスク名: ${task.title}`;
    if (task.user_id !== me) {
      tooltip += `\n共有元: ${task.user_name || task.user_id}`;
    } else if (task.shared) {
      tooltip += `\n状態: 共有中`;
    }
    if (task.due) {
      tooltip += `\n期日: ${task.due.replace(/-/g, '/')}`;
    }
    if (task.id.startsWith('asana-')) {
      let wsName = task.workspace_name || '';
      let prjName = task.project_name || '';
      let secName = task.section_name || '';
      if (!wsName && !prjName && task.notes) {
        const match = task.notes.match(/^【Asana帰属: ([^＞】]+)(?: ＞ ([^】\()]+))?(?:\s*\(([^)]+)\))?】/);
        if (match) {
          wsName = match[1] ? match[1].trim() : '';
          prjName = match[2] ? match[2].trim() : '';
          secName = match[3] ? match[3].trim() : '';
        }
      }
      if (wsName || prjName) {
        let belongText = 'Asana: ';
        if (wsName) belongText += wsName;
        if (prjName) belongText += ` ＞ ${prjName}`;
        if (secName && secName !== 'Untitled section' && secName !== '無題のセクション') {
          belongText += ` (${secName})`;
        }
        tooltip += `\n所属: ${belongText}`;
      }
    }
    row.title = tooltip;

    // クリックイベントで編集フォームへ詳細展開
    row.onclick = () => {
      loadTodoDetails(task.id);
    };

    return row;
  }

  // ToDoタスクをGoogleカレンダーのイベントに変換して同期するヘルパー
  async function addTodoEventToGoogleCalendar(todoId, event) {
    if (!isGoogleLinked || !googleAccessToken) return;
    const rawUserId = state.currentUser ? state.currentUser.id : 'guest';
    const me = rawUserId.toLowerCase();
    const apiKey = getLocalStorageGoogleItem('SYNAPSE_GOOGLE_API_KEY', rawUserId);
    const url = `https://www.googleapis.com/calendar/v3/calendars/primary/events?key=${apiKey}`;

    const body = {
      summary: event.title,
      description: event.description,
      start: { date: event.start_time }, // 終日予定
      end: { date: event.end_time }
    };

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${googleAccessToken}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
      });
      const data = await response.json();
      if (data && data.id) {
        localStorage.setItem(`SYNAPSE_TODO_GOOGLE_EVENT_ID_${todoId}`, data.id);
        const task = todoTasks.find(t => t.id === todoId);
        if (task) {
          task.google_event_id = data.id;
          localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));
          if (typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
            await partnerSupabaseClient
              .from('synapse_todo_tasks')
              .update({ google_event_id: data.id })
              .eq('id', todoId);
          }
        }
      }
    } catch (e) {
      console.warn("[Google Calendar Sync] Failed to add todo event:", e);
    }
  }

