  // 📋 Google Tasks マージ同期処理
  async function syncWithGoogleTasks(me) {
    if (state.googleLinkTasks === undefined) {
      state.googleLinkTasks = localStorage.getItem(`SYNAPSE_GOOGLE_LINK_TASKS_${me}`) === 'true';
    }
    if (!isGoogleLinked || !googleAccessToken || !state.googleLinkTasks) return;

    try {
      console.log("[Google Tasks Sync] Fetching tasks directly from Google Tasks API...");
      
      // 1. タスクリスト一覧を取得
      const listsRes = await fetchWithTimeout('https://tasks.googleapis.com/tasks/v1/users/@me/lists', {
        headers: {
          'Authorization': `Bearer ${googleAccessToken}`,
          'Accept': 'application/json'
        }
      });

      if (!listsRes.ok) {
        const errText = await listsRes.text();
        throw new Error(`Failed to fetch Google task lists: ${listsRes.status} - ${errText}`);
      }

      const listsData = await listsRes.json();
      const taskLists = listsData.items || [];
      state.googleTaskLists = taskLists; // メモリに保存
      let googleTasksList = [];

      // 2. 各タスクリストからタスクを取得
      for (const list of taskLists) {
        const tasksUrl = `https://tasks.googleapis.com/tasks/v1/lists/${list.id}/tasks?showCompleted=true&showHidden=true`;
        const tasksRes = await fetchWithTimeout(tasksUrl, {
          headers: {
            'Authorization': `Bearer ${googleAccessToken}`,
            'Accept': 'application/json'
          }
        });

        if (tasksRes.ok) {
          const tasksData = await tasksRes.json();
          if (tasksData.items) {
            const mapped = tasksData.items.map(t => ({
              ...t,
              listName: list.title
            }));
            googleTasksList = googleTasksList.concat(mapped);
          }
        }
      }

      // マージ用の既存IDマップ作成
      const currentGoogleTaskIds = new Set(googleTasksList.map(t => `google-task-${t.id}`));

      // 1. APIから消えた古いGoogleタスクを削除する
      const deletedIds = todoTasks.filter(t => t.id.startsWith('google-task-') && !currentGoogleTaskIds.has(t.id)).map(t => t.id);
      todoTasks = todoTasks.filter(t => !t.id.startsWith('google-task-') || currentGoogleTaskIds.has(t.id));

      if (deletedIds.length > 0 && typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
        try {
          await partnerSupabaseClient
            .from('synapse_todo_tasks')
            .delete()
            .in('id', deletedIds);
        } catch (delErr) {
          console.warn("[Google Tasks Sync] Failed to delete old tasks from DB:", delErr);
        }
      }

      // 2. APIから取得した最新のタスクをマージインポート
      const upsertTasks = [];
      googleTasksList.forEach(task => {
        const taskId = `google-task-${task.id}`;
        const isCompleted = task.status === 'completed';
        const nextStatus = isCompleted ? 'completed' : 'needsAction';
        const due = task.due ? task.due.substring(0, 10) : null; // YYYY-MM-DD

        let notesText = task.notes || '';
        // 既存の 【Google To-Do帰属】 ラベルがあれば取り除く
        notesText = notesText.replace(/^【Google To-Do帰属: [^】]+】\s*/, '');
        // リスト名を先頭に付与
        const listName = task.listName || 'My Tasks';
        notesText = `【Google To-Do帰属: ${listName}】\n${notesText}`.trim();

        const taskObj = {
          id: taskId,
          title: task.title || '無題のタスク',
          due: due,
          notes: notesText,
          status: nextStatus,
          show_on_calendar: true,
          user_id: me,
          user_name: googleLinkedEmail || 'Google Tasks Sync',
          google_event_id: null,
          shared: false,
          shared_with: []
        };

        upsertTasks.push(taskObj);

        const existing = todoTasks.find(t => t.id === taskId);
        if (existing) {
          Object.assign(existing, taskObj);
        } else {
          todoTasks.push(taskObj);
        }
      });

      if (upsertTasks.length > 0 && typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
        try {
          const { error: upsertErr } = await partnerSupabaseClient
            .from('synapse_todo_tasks')
            .upsert(upsertTasks);
          if (upsertErr) throw upsertErr;
        } catch (dbErr) {
          console.warn("[Google Tasks Sync] Failed to upsert tasks to DB:", dbErr);
        }
      }

      localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));
      console.log(`[Google Tasks Sync] Synced ${googleTasksList.length} tasks successfully.`);
    } catch (e) {
      console.warn("[Google Tasks Sync] Failed to sync tasks:", e);
      showToast(`Google To-Doの同期に失敗しました: ${e.message}`, 'error');
    }
  }

  // 📋 Asana Tasks マージ同期処理
  async function syncWithAsanaTasks(me) {
    if (state.asanaLinkTasks === undefined) {
      state.asanaLinkTasks = localStorage.getItem(`SYNAPSE_ASANA_LINK_TASKS_${me}`) === 'true';
    }
    const token = localStorage.getItem(`SYNAPSE_ASANA_PAT_${me}`);
    if (!token || !state.asanaLinkTasks) return;

    try {
      console.log("[Asana Tasks Sync] Fetching tasks directly from Asana API...");
      // 1. ユーザー情報から所属ワークスペースを取得
      const userRes = await fetch('https://app.asana.com/api/1.0/users/me', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Accept': 'application/json'
        }
      });

      if (!userRes.ok) {
        const errText = await userRes.text();
        throw new Error(`Failed to fetch Asana user info: ${userRes.status} - ${errText}`);
      }

      const userData = await userRes.json();
      const workspaces = userData.data ? userData.data.workspaces : [];
      let asanaTasksList = [];

      // 2. 各ワークスペースからタスクを取得
      if (workspaces && workspaces.length > 0) {
        for (const ws of workspaces) {
          const workspaceGid = ws.gid;
          const tasksUrl = `https://app.asana.com/api/1.0/tasks?assignee=me&workspace=${workspaceGid}&opt_fields=name,due_on,completed,notes,workspace.name,projects.name,memberships.project.name,memberships.section.name`;
          const tasksRes = await fetch(tasksUrl, {
            headers: {
              'Authorization': `Bearer ${token}`,
              'Accept': 'application/json'
            }
          });

          if (tasksRes.ok) {
            const tasksData = await tasksRes.json();
            const wsTasks = tasksData.data || [];
            asanaTasksList = asanaTasksList.concat(wsTasks);
          } else {
            const errText = await tasksRes.text();
            console.error(`Failed to fetch Asana tasks for workspace ${workspaceGid}:`, errText);
          }
        }
      } else {
        console.warn('No workspaces found for the user in Asana.');
      }

      // マージ用の既存IDマップ作成
      const currentAsanaTaskIds = new Set(asanaTasksList.map(t => `asana-${t.gid}`));

      // 1. APIから消えた古いAsanaタスクを削除する
      const deletedIds = todoTasks.filter(t => t.id.startsWith('asana-') && !currentAsanaTaskIds.has(t.id)).map(t => t.id);
      todoTasks = todoTasks.filter(t => !t.id.startsWith('asana-') || currentAsanaTaskIds.has(t.id));

      if (deletedIds.length > 0 && typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
        try {
          await partnerSupabaseClient
            .from('synapse_todo_tasks')
            .delete()
            .in('id', deletedIds);
        } catch (delErr) {
          console.warn("[Asana Tasks Sync] Failed to delete old tasks from DB:", delErr);
        }
      }

      // 2. APIから取得した最新のタスクをマージインポート
      const upsertTasks = [];
      asanaTasksList.forEach(task => {
        const taskId = `asana-${task.gid}`;
        const nextStatus = task.completed ? 'completed' : 'needsAction';
        const due = task.due_on || null; // YYYY-MM-DD

        // 帰属先情報の抽出
        let prjName = '';
        let secName = '';
        if (task.projects && task.projects.length > 0) {
          prjName = task.projects[0].name || '';
        }
        if (task.memberships && task.memberships.length > 0) {
          const firstM = task.memberships[0];
          if (firstM.project) prjName = prjName || firstM.project.name || '';
          if (firstM.section) secName = firstM.section.name || '';
        }
        const wsName = task.workspace ? task.workspace.name : '';

        // 帰属先ラベルを作成してメモ（notes）の先頭に埋め込む
        let belongInfo = '';
        if (wsName || prjName) {
          belongInfo = `【Asana帰属: ${wsName}`;
          if (prjName) belongInfo += ` ＞ ${prjName}`;
          if (secName && secName !== 'Untitled section' && secName !== '無題のセクション') {
            belongInfo += ` (${secName})`;
          }
          belongInfo += `】\n`;
        }

        let baseNotes = task.notes || '';
        // 過去の同期処理で埋め込んだ帰属先ラベルを一旦削除して重複を防ぐ
        baseNotes = baseNotes.replace(/^【Asana帰属: [^】]+】\n?/, '');
        const finalNotes = belongInfo + baseNotes;

        const taskObj = {
          id: taskId,
          title: task.name || '無題のタスク',
          due: due,
          notes: finalNotes,
          status: nextStatus,
          show_on_calendar: true,
          user_id: me,
          user_name: 'Asana Sync',
          google_event_id: null,
          shared: false,
          shared_with: [],
          // ローカルキャッシュでバッジとして描画するためにプロパティを保持
          workspace_name: wsName,
          project_name: prjName,
          section_name: secName
        };

        upsertTasks.push(taskObj);

        const existing = todoTasks.find(t => t.id === taskId);
        if (existing) {
          Object.assign(existing, taskObj);
        } else {
          todoTasks.push(taskObj);
        }
      });

      if (upsertTasks.length > 0 && typeof partnerSupabaseClient !== 'undefined' && partnerSupabaseClient) {
        try {
          // DB側のスキーマカラムに存在しないカスタムプロパティ（workspace_nameなど）を除外して送信
          const dbUpsertTasks = upsertTasks.map(t => ({
            id: t.id,
            user_id: t.user_id,
            user_name: t.user_name,
            title: t.title,
            due: t.due,
            notes: t.notes,
            status: t.status,
            show_on_calendar: t.show_on_calendar,
            shared_with: t.shared_with,
            google_event_id: t.google_event_id
          }));

          const { error: upsertErr } = await partnerSupabaseClient
            .from('synapse_todo_tasks')
            .upsert(dbUpsertTasks);
          if (upsertErr) throw upsertErr;
        } catch (dbErr) {
          console.warn("[Asana Tasks Sync] Failed to upsert tasks to DB:", dbErr);
        }
      }

      localStorage.setItem(`SYNAPSE_LOCAL_TODO_TASKS_${me}`, JSON.stringify(todoTasks));
      console.log(`[Asana Tasks Sync] Synced ${asanaTasksList.length} tasks successfully.`);
    } catch (e) {
      console.warn("[Asana Tasks Sync] Failed to sync tasks:", e);
      showToast(`Asanaの同期に失敗しました: ${e.message}`, 'error');
    }
  }

