// ============================================================
// 🌟 アポイント画面 連携フォーム管理 & 発行機能
// ============================================================

const APPOINT_DEFAULT_PRESET_FORMS = [
  {
    id: 'form_yosandas',
    name: 'ヨサンダス申込フォーム',
    desc: 'プラン選択、導入規模、契約希望時期など',
    appointIntegration: {
      enabled: true,
      fields: { customerName: true, appointDate: true, meetingType: true, sourceCategory: true, introducer: true }
    }
  },
  {
    id: 'form_agency',
    name: '代理店申込フォーム',
    desc: 'インボイス番号、手数料振込先口座、取扱商材など',
    appointIntegration: {
      enabled: true,
      fields: { customerName: true, appointDate: true, meetingType: true, sourceCategory: true, introducer: true }
    }
  }
];

// 📋 アポイント連携対象フォームを動的に取得（フォームエディタ側の「アポイント連携設定」と完全連動）
function getAppointAvailableForms() {
  const forms = [];
  try {
    // フォームエディタの保存先（form_customize_all_forms）およびフォールバック（synapse_custom_forms）から読み込み
    let allForms = [];
    try {
      allForms = JSON.parse(localStorage.getItem('form_customize_all_forms') || '[]');
    } catch(e) {}
    if (!Array.isArray(allForms) || allForms.length === 0) {
      try {
        allForms = JSON.parse(localStorage.getItem('synapse_custom_forms') || '[]');
      } catch(e) {}
    }

    if (Array.isArray(allForms)) {
      allForms.forEach(f => {
        if (!f) return;
        const fid = f.id || '';
        const ftitle = f.title || f.name || fid;
        const isPreset = fid === 'form_yosandas' || fid === 'form_agency' || ftitle.includes('ヨサンダス') || ftitle.includes('代理店');
        
        // appointIntegration が明示されている場合はその enabled 値を尊重。未定義かつプリセットなら true
        const isEnabled = f.appointIntegration ? (f.appointIntegration.enabled === true) : isPreset;

        if (isEnabled) {
          forms.push({
            id: fid,
            name: ftitle,
            desc: f.description || f.subtitle || '連携フォーム',
            appointIntegration: f.appointIntegration || {
              enabled: true,
              fields: { customerName: true, appointDate: true, meetingType: true, sourceCategory: true, introducer: true }
            }
          });
        }
      });
    }

    // まだ一度も保存されていない初期状態用のプリセットフォールバック
    // ※ allForms 内に同IDや同タイトルのフォームが既に存在し、それが OFF（isEnabled === false）の場合は絶対に復活させない！
    APPOINT_DEFAULT_PRESET_FORMS.forEach(preset => {
      const existsInAll = Array.isArray(allForms) && allForms.some(f => f && (f.id === preset.id || (f.title && f.title.includes(preset.name)) || (f.name && f.name.includes(preset.name))));
      if (!existsInAll && !forms.some(f => f.id === preset.id)) {
        forms.push(preset);
      }
    });
  } catch(e) {
    console.error('[getAppointAvailableForms] Error:', e);
  }

  return forms;
}
window.getAppointAvailableForms = getAppointAvailableForms;
const APPOINT_AVAILABLE_FORMS = APPOINT_DEFAULT_PRESET_FORMS;

function getCurrentAppointData() {
  if (state.tabs && state.activeTabId) {
    const currentTab = state.tabs.find(t => t.id === state.activeTabId);
    if (currentTab && currentTab.type === 'appointment-screen' && currentTab.appointData) {
      return currentTab.appointData;
    }
  }
  if (state.activeAppointData) {
    return state.activeAppointData;
  }
  // フォールバック: 画面上の表示IDから構築
  const displayIdEl = document.getElementById('display-appoint-id');
  const appointId = displayIdEl ? displayIdEl.textContent.trim() : '';
  if (appointId && appointId !== '-' && !appointId.includes('取得中')) {
    state.activeAppointData = { id: appointId, linkedForms: [] };
    return state.activeAppointData;
  }
  return null;
}

// 🌟 チェーン内（関連アポイント群）の有効なマスタIDと発行権限を解決するエンジン
function getEffectiveAppointMasterContext(appointData) {
  if (!appointData) return { masterId: '-', isOfficial: false, officialPartyId: null, authorityAppointId: null, canIssue: false };

  const allAppointIds = new Set();
  if (appointData.id) allAppointIds.add(appointData.id);

  // チェーン内の全アポイントIDを収集
  const queue = [appointData.id];
  const visited = new Set();
  while (queue.length > 0) {
    const curId = queue.shift();
    if (!curId || visited.has(curId)) continue;
    visited.add(curId);
    allAppointIds.add(curId);

    const ap = state.appointments?.find(a => a.id === curId);
    if (ap && ap.relatedAppointmentIds) {
      const rels = ap.relatedAppointmentIds.split(',').map(s => s.trim()).filter(Boolean);
      rels.forEach(r => {
        if (!visited.has(r)) queue.push(r);
      });
    }
  }

  const chainAppoints = [];
  allAppointIds.forEach(id => {
    const ap = (appointData.id === id) ? appointData : state.appointments?.find(a => a.id === id);
    if (ap) chainAppoints.push(ap);
  });

  // 1. 本登録Party ID（または本登録済みアポ）が存在するか探索
  let officialPartyId = null;
  let officialAppoint = null;

  if (appointData.customerId && appointData.customerId !== '本登録前') {
    officialPartyId = appointData.customerId;
    officialAppoint = appointData;
  }

  if (!officialPartyId) {
    for (const ap of chainAppoints) {
      if (ap.customerId && ap.customerId !== '本登録前') {
        officialPartyId = ap.customerId;
        officialAppoint = ap;
        break;
      }
      if (ap.status === 'official') {
        officialPartyId = ap.id;
        officialAppoint = ap;
        break;
      }
    }
  }

  if (officialPartyId) {
    // 既存顧客（本登録済み）が存在する場合:
    // 最新アポイント画面にも本登録IDが紐づいたフォームを表示・管理・発行可能とする
    return {
      masterId: officialPartyId,
      isOfficial: true,
      officialPartyId: officialPartyId,
      authorityAppointId: appointData.id,
      canIssue: true,
      chainAppoints: chainAppoints
    };
  }

  // 2. 本登録が存在しない場合（全員本登録前 / 見込み客）:
  // チェーン内で最も日時の新しい「最新アポイント」が仮IDとなり、唯一の発行権限を持つ
  let latestAppoint = appointData;
  let latestDate = appointData.date ? new Date(appointData.date).getTime() : 0;

  chainAppoints.forEach(ap => {
    const apTime = ap.date ? new Date(ap.date).getTime() : 0;
    const apReg = ap.registeredAt ? new Date(ap.registeredAt).getTime() : 0;
    const latestReg = latestAppoint.registeredAt ? new Date(latestAppoint.registeredAt).getTime() : 0;
    if (apTime > latestDate || (apTime === latestDate && (apReg > latestReg || ap.id > latestAppoint.id))) {
      latestDate = apTime;
      latestAppoint = ap;
    }
  });

  const isCurrentLatest = (latestAppoint.id === appointData.id);
  return {
    masterId: latestAppoint.id,
    isOfficial: false,
    officialPartyId: null,
    authorityAppointId: latestAppoint.id,
    canIssue: isCurrentLatest,
    isCurrentLatest: isCurrentLatest,
    chainAppoints: chainAppoints
  };
}

function renderAppointLinkedForms(appointData) {
  const data = appointData || getCurrentAppointData();
  if (data) {
    state.activeAppointData = data;
  }
  const dock = document.getElementById('appoint-linked-forms-dock');
  if (!dock) return;

  // 🌟 チェーン内の有効なマスタコンテキストを判定
  const ctx = getEffectiveAppointMasterContext(data);
  const masterId = ctx.masterId;
  const masterIdEl = document.getElementById('dock-master-id');
  if (masterIdEl) {
    masterIdEl.textContent = masterId;
    if (ctx.isOfficial) {
      masterIdEl.innerHTML = `${escapeHtml(masterId)} <span class="badge badge-success" style="font-size: 0.65rem; margin-left: 0.25rem; padding: 0.05rem 0.35rem;">本登録Party ID</span>`;
    }
  }

  // 発行ボタンの権限制御 & ガイダンス表示
  const openIssueBtn = document.getElementById('btn-open-appoint-form-modal');
  const lockedNoticeEl = document.getElementById('appoint-issue-locked-notice');
  if (openIssueBtn) {
    if (ctx.canIssue) {
      openIssueBtn.disabled = false;
      openIssueBtn.style.opacity = '1';
      openIssueBtn.style.cursor = 'pointer';
      openIssueBtn.title = '連携フォームを発行します';
    } else {
      openIssueBtn.disabled = true;
      openIssueBtn.style.opacity = '0.5';
      openIssueBtn.style.cursor = 'not-allowed';
      openIssueBtn.title = `最新アポイント（ID: ${ctx.authorityAppointId}）からのみ発行可能です`;
    }
  }
  if (lockedNoticeEl) {
    if (!ctx.canIssue) {
      lockedNoticeEl.style.display = 'block';
      lockedNoticeEl.innerHTML = `⚠️ ※本登録前のため、最新アポイント（ID: <strong>${escapeHtml(ctx.authorityAppointId)}</strong>）からのみフォームを発行できます。`;
    } else {
      lockedNoticeEl.style.display = 'none';
    }
  }

  const container = document.getElementById('appoint-issued-forms-list');
  if (!container) return;

  if (!data) {
    container.innerHTML = `<div id="appoint-no-forms-msg" style="font-size: 0.78rem; color: var(--text-muted); font-style: italic; padding: 0.25rem 0;">※ アポイント情報を読み込み中...</div>`;
    return;
  }

  if (!Array.isArray(data.linkedForms)) {
    data.linkedForms = [];
  }

  // synapse_form_links から最新状態を同期・復元（本登録Party IDまたは最新仮IDに紐づくリンクを網羅）
  try {
    const allStoredLinks = JSON.parse(localStorage.getItem('synapse_form_links') || '{}');
    
    // 対象とするマスタID一覧（有効マスターID、および自身のアポID）
    const targetMasterIds = new Set([masterId, data.id]);
    if (ctx.chainAppoints) {
      ctx.chainAppoints.forEach(a => { if (a.id) targetMasterIds.add(a.id); });
    }

    // storedLinksから該当するフォームを復元
    const resolvedFormsMap = new Map();
    data.linkedForms.forEach(f => {
      resolvedFormsMap.set(f.formId, { ...f });
    });

    Object.keys(allStoredLinks).forEach(key => {
      const item = allStoredLinks[key];
      if (item && targetMasterIds.has(item.masterId)) {
        if (!resolvedFormsMap.has(item.formId) || item.masterId === masterId) {
          resolvedFormsMap.set(item.formId, { ...item });
        }
      }
    });

    data.linkedForms = Array.from(resolvedFormsMap.values());
  } catch(e) {}

  // クラウド（Supabase synapse_storage）からの最新ステータス非同期同期
  if (masterId && masterId !== '-') {
    const now = Date.now();
    if (!data._lastCloudFetch || now - data._lastCloudFetch > 5000) {
      data._lastCloudFetch = now;
      fetchFormLinksFromCloud(masterId);
    }
  }

  if (data.linkedForms.length === 0) {
    container.innerHTML = `<div id="appoint-no-forms-msg" style="font-size: 0.78rem; color: var(--text-muted); font-style: italic; padding: 0.25rem 0;">※ 現在発行済みのフォームはありません。「フォームを発行」から選択してください。</div>`;
    return;
  }

  container.innerHTML = '';
  data.linkedForms.forEach(formItem => {
    const row = document.createElement('div');
    row.className = 'appoint-issued-form-row';

    // ステータス表示
    let statusBadgeHtml = '';
    if (formItem.status === 'submitted') {
      statusBadgeHtml = `<span class="appoint-form-status-tag status-submitted">回答済み</span>`;
    } else if (formItem.status === 'requesting') {
      statusBadgeHtml = `<span class="appoint-form-status-tag status-requesting">再有効化申請中</span>`;
    } else if (formItem.status === 'reopened') {
      statusBadgeHtml = `<span class="appoint-form-status-tag status-reopened">再有効化中</span>`;
    } else if (formItem.status === 'invalidated') {
      statusBadgeHtml = `<span class="appoint-form-status-tag status-invalidated" title="別アポイントとの連携により無効化されました">無効</span>`;
    } else {
      statusBadgeHtml = `<span class="appoint-form-status-tag status-pending">未回答</span>`;
    }

    // 🌟 アクションボタン（ユーザー指示: コピーはアイコンのみ、開くもスッキリしたUI）
    let actionButtonsHtml = '';
    if (formItem.status === 'invalidated') {
      actionButtonsHtml = `<span style="font-size: 0.7rem; color: var(--text-muted); font-style: italic;">※ 連結により無効化</span>`;
    } else {
      actionButtonsHtml = `
        <button type="button" class="btn-icon-custom" onclick="copyAppointFormLink(this, '${formItem.url}', '${escapeHtml(formItem.formName)}')" title="リンクをコピー">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>
        </button>
        <button type="button" class="btn-icon-custom" onclick="openAppointFormLink('${formItem.url}')" title="回答画面を開く">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg>
        </button>
      `;

      if (formItem.status === 'submitted') {
        actionButtonsHtml += `
          <button type="button" class="btn-outline-custom btn-action-request" onclick="requestAppointFormReopen('${formItem.formId}')" title="再有効化を申請">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"></polyline><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"></path></svg>
            <span>再申請</span>
          </button>
        `;
      } else if (formItem.status === 'requesting') {
        const isAdmin = (typeof isUserAdmin === 'function' && isUserAdmin()) || (state.currentUser && state.currentUser.role === 'admin');
        if (isAdmin) {
          actionButtonsHtml += `
            <button type="button" class="btn-outline-custom btn-action-approve" onclick="approveAppointFormReopen('${formItem.formId}')" title="管理者が承認してリンクを再有効化">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path><polyline points="22 4 12 14.01 9 11.01"></polyline></svg>
              <span>承認</span>
            </button>
          `;
        }
      }
    }

    row.innerHTML = `
      <div class="form-info-compact" style="display: flex; align-items: center; gap: 0.4rem; flex-wrap: wrap; flex: 1; min-width: 0;">
        <span class="appoint-form-name-badge" style="font-size: 0.8rem; font-weight: 600;">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg>
          <span>${escapeHtml(formItem.formName)}</span>
        </span>
        ${statusBadgeHtml}
        ${formItem.issuerName ? `<span style="font-size: 0.7rem; color: var(--text-muted); display: inline-flex; align-items: center; gap: 2px; background: rgba(0,0,0,0.03); padding: 1px 5px; border-radius: 4px;" title="発行者: ${escapeHtml(formItem.issuerName)}"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>${escapeHtml(formItem.issuerName)}</span>` : ''}
      </div>
      <div class="form-row-actions">
        ${actionButtonsHtml}
      </div>
    `;
    container.appendChild(row);
  });
}

function openAppointIssueModal() {
  const data = getCurrentAppointData();
  const ctx = getEffectiveAppointMasterContext(data);
  const masterId = ctx.masterId || '-';

  const modal = document.getElementById('modal-appoint-issue-form');
  const targetIdEl = document.getElementById('modal-appoint-master-id-text');
  if (targetIdEl) {
    targetIdEl.textContent = masterId;
    if (ctx.isOfficial) {
      targetIdEl.innerHTML = `${escapeHtml(masterId)} <span class="badge badge-success" style="font-size: 0.65rem; margin-left: 0.25rem;">本登録Party ID</span>`;
    }
  }

  if (!Array.isArray(data?.linkedForms)) {
    if (data) data.linkedForms = [];
  }

  // 📋 アポイント連携対象フォームを動的にレンダリング
  const listContainer = document.getElementById('appoint-available-forms-list');
  if (listContainer) {
    listContainer.innerHTML = '';
    const availableForms = getAppointAvailableForms();

    if (availableForms.length === 0) {
      listContainer.innerHTML = `
        <div style="padding: 1.5rem; text-align: center; color: var(--text-muted); font-size: 0.8rem; background: var(--bg-surface-elevated); border-radius: var(--radius-sm);">
          現在、アポイント連携可能なフォームがありません。<br>フォームエディタの「アポイント連携設定」で連携を有効にしてください。
        </div>
      `;
    } else {
      availableForms.forEach(formItem => {
        const isIssued = data?.linkedForms?.some(f => f.formId === formItem.id && f.status !== 'invalidated');

        // 引継ぎ設定バッジの生成
        const flds = formItem.appointIntegration?.fields || {};
        const badges = [];
        if (flds.customerName !== false) badges.push('🏢 顧客名');
        if (flds.appointDate !== false) badges.push('📅 日時');
        if (flds.meetingType !== false) badges.push('🌐 流入経路');
        if (flds.sourceCategory !== false) badges.push('🏷️ 流入詳細');
        if (flds.introducer !== false && flds.introducerName !== false) badges.push('👥 紹介者(ID)');
        const badgesHtml = badges.length > 0 
          ? `<div style="display: flex; gap: 4px; flex-wrap: wrap; margin-top: 0.35rem;">
               <span style="font-size: 0.68rem; color: var(--text-muted); line-height: 1.4;">引継ぎ項目:</span>
               ${badges.map(b => `<span style="font-size: 0.65rem; background: rgba(59, 130, 246, 0.08); color: var(--primary); padding: 1px 5px; border-radius: 3px;">${escapeHtml(b)}</span>`).join('')}
             </div>`
          : '';

        const itemEl = document.createElement('div');
        itemEl.className = 'appoint-form-select-item';
        itemEl.style.cssText = `border: 1px solid var(--border-color); border-radius: var(--radius-sm); padding: 0.75rem 1rem; display: flex; align-items: center; justify-content: space-between; cursor: ${isIssued ? 'default' : 'pointer'}; transition: all 0.15s; background: var(--bg-surface-elevated); ${isIssued ? 'opacity: 0.7;' : ''}`;

        itemEl.innerHTML = `
          <div style="flex: 1; min-width: 0; padding-right: 0.75rem;">
            <div style="font-weight: 600; font-size: 0.85rem; color: var(--text-primary); display: flex; align-items: center; gap: 0.4rem;">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line></svg>
              <span>${escapeHtml(formItem.name)}</span>
            </div>
            <div style="font-size: 0.72rem; color: var(--text-muted); margin-top: 0.2rem;">${escapeHtml(formItem.desc)}</div>
            ${badgesHtml}
          </div>
          <button type="button" class="btn btn-sm ${isIssued ? 'btn-secondary' : 'btn-primary'}" style="font-size: 0.75rem; padding: 0.3rem 0.75rem; flex-shrink: 0;" ${isIssued ? 'disabled' : ''}>
            ${isIssued ? '発行済み' : '選択する'}
          </button>
        `;

        if (!isIssued) {
          itemEl.addEventListener('click', () => issueAppointForm(formItem.id));
        }

        listContainer.appendChild(itemEl);
      });
    }
  }

  if (modal) {
    modal.style.display = 'flex';
    modal.classList.add('active');
  }
}

function closeAppointIssueModal() {
  const modal = document.getElementById('modal-appoint-issue-form');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
}

function getSynapseFormLinks() {
  try {
    return JSON.parse(localStorage.getItem('synapse_form_links') || '{}');
  } catch(e) {
    return {};
  }
}

function generateFormSecureToken(length = 20) {
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    const bytes = new Uint8Array(Math.ceil(length / 2));
    crypto.getRandomValues(bytes);
    return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('').substring(0, length);
  }
  let str = '';
  while (str.length < length) {
    str += Math.random().toString(36).substring(2);
  }
  return str.substring(0, length);
}

function saveSynapseFormLink(masterId, formId, linkData) {
  try {
    const links = getSynapseFormLinks();
    const key = `${masterId}_${formId}`;
    links[key] = {
      ...(links[key] || {}),
      ...linkData,
      masterId: masterId,
      formId: formId,
      updatedAt: new Date().toISOString()
    };
    localStorage.setItem('synapse_form_links', JSON.stringify(links));

    // トークン情報もトークンインデックス（synapse_form_tokens）へ保存
    if (links[key].token) {
      try {
        const tokens = JSON.parse(localStorage.getItem('synapse_form_tokens') || '{}');
        tokens[links[key].token] = links[key];
        localStorage.setItem('synapse_form_tokens', JSON.stringify(tokens));
      } catch(e) {}
    }

    if (typeof BroadcastChannel !== 'undefined') {
      const bc = new BroadcastChannel('synapse_form_channel');
      bc.postMessage({ type: 'FORM_LINK_UPDATED', masterId, formId, status: linkData.status });
      bc.close();
    }

    // クラウド（Supabase synapse_storage）へ非同期保存
    syncFormLinkToCloud(masterId, formId, links[key]);
  } catch(e) {
    console.warn('[SynapseForm] Failed to save form link:', e);
  }
}

async function syncFormLinkToCloud(masterId, formId, linkData) {
  try {
    const sbUrl = 'https://uefiuhywfsnrepiouofq.supabase.co';
    const sbKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InVlZml1aHl3ZnNucmVwaW91b2ZxIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODA5MDMxMTMsImV4cCI6MjA5NjQ3OTExM30.jRluR2-bcMnKf7CSMRM4CtaRlHT4FrBkQWV_lVuWZxQ';
    
    // 1. マスタIDキーでの保存
    const key = `synapse_form_link_${masterId}_${formId}`;
    await fetch(`${sbUrl}/rest/v1/synapse_storage`, {
      method: 'POST',
      headers: {
        'apikey': sbKey,
        'Authorization': `Bearer ${sbKey}`,
        'Content-Type': 'application/json',
        'Prefer': 'resolution=merge-duplicates'
      },
      body: JSON.stringify({
        key: key,
        value: linkData,
        updated_at: new Date().toISOString()
      })
    });

    // 2. セキュアトークンキーでの保存（顧客端末からトークンのみで情報照合用）
    if (linkData && linkData.token) {
      const tokenKey = `synapse_form_token_${linkData.token}`;
      await fetch(`${sbUrl}/rest/v1/synapse_storage`, {
        method: 'POST',
        headers: {
          'apikey': sbKey,
          'Authorization': `Bearer ${sbKey}`,
          'Content-Type': 'application/json',
          'Prefer': 'resolution=merge-duplicates'
        },
        body: JSON.stringify({
          key: tokenKey,
          value: linkData,
          updated_at: new Date().toISOString()
        })
      });
    }
  } catch(e) {
    console.warn('[CloudFormLink] Save error:', e);
  }
}

async function fetchFormLinksFromCloud(masterId) {
  if (!masterId || masterId === '-') return;
  try {
    const sbUrl = 'https://uefiuhywfsnrepiouofq.supabase.co';
    const sbKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InVlZml1aHl3ZnNucmVwaW91b2ZxIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODA5MDMxMTMsImV4cCI6MjA5NjQ3OTExM30.jRluR2-bcMnKf7CSMRM4CtaRlHT4FrBkQWV_lVuWZxQ';
    const res = await fetch(`${sbUrl}/rest/v1/synapse_storage?key=like.synapse_form_link_${encodeURIComponent(masterId)}_*&select=key,value`, {
      headers: { 'apikey': sbKey, 'Authorization': `Bearer ${sbKey}` }
    });
    if (res.ok) {
      const rows = await res.json();
      if (Array.isArray(rows) && rows.length > 0) {
        const stored = JSON.parse(localStorage.getItem('synapse_form_links') || '{}');
        const storedTokens = JSON.parse(localStorage.getItem('synapse_form_tokens') || '{}');
        let hasChanges = false;
        rows.forEach(r => {
          if (r.value && r.value.formId) {
            const k = `${masterId}_${r.value.formId}`;
            if (!stored[k] || stored[k].status !== r.value.status) {
              stored[k] = r.value;
              hasChanges = true;
            }
            if (r.value.token) {
              storedTokens[r.value.token] = r.value;
            }
          }
        });
        if (hasChanges) {
          localStorage.setItem('synapse_form_links', JSON.stringify(stored));
          localStorage.setItem('synapse_form_tokens', JSON.stringify(storedTokens));
          const curData = getCurrentAppointData();
          if (curData) {
            renderAppointLinkedForms(curData);
          }
        }
      }
    }
  } catch(e) {}
}

function issueAppointForm(formId) {
  const data = getCurrentAppointData();
  if (!data) {
    if (typeof showToast === 'function') showToast('アポイント情報が見つかりません', 'error');
    return;
  }
  if (!Array.isArray(data.linkedForms)) {
    data.linkedForms = [];
  }

  const existing = data.linkedForms.find(f => f.formId === formId && f.status !== 'invalidated');
  if (existing) {
    if (typeof showToast === 'function') showToast('このフォームは既に有効発行されています', 'warning');
    closeAppointIssueModal();
    return;
  }

  // 🌟 有効なマスターID（本登録Party ID、または最新仮ID）を解決
  const ctx = getEffectiveAppointMasterContext(data);
  const masterId = ctx.masterId || data.id;

  const availableForms = getAppointAvailableForms();
  const targetDef = availableForms.find(f => f.id === formId);
  const formName = targetDef ? targetDef.name : formId;

  // フォーム発行ユーザー（担当者）
  const issuerId = state.currentUser ? (state.currentUser.loginId || state.currentUser.id) : (localStorage.getItem('cos_logged_user') || localStorage.getItem('gf_current_user') || '');
  const issuerName = state.currentUser ? (state.currentUser.name || issuerId) : (issuerId || '');

  // 営業選択時の紹介者IDを取得
  const introducerId = document.getElementById('appoint-hidden-introducer-id')?.value || data.introducerId || '';
  const introducerName = document.getElementById('appoint-hidden-introducer-name')?.value || data.introducerName || '';
  const introducerType = document.getElementById('appoint-hidden-introducer-type')?.value || data.introducerType || '';

  // 📋 フォーム側で事前設定された「アポイント引継ぎ・回答記録項目」ルールを取得
  const flds = targetDef?.appointIntegration?.fields || {
    customerName: true,
    appointDate: true,
    meetingType: true,
    sourceCategory: true,
    introducer: true
  };

  // アポイント情報スナップショット（appointSnapshot）の自動構築
  const appointSnapshot = {};
  if (flds.customerName !== false && (data.customerName || data.name)) {
    appointSnapshot.customerName = data.customerName || data.name;
  }
  if (flds.appointDate !== false && (data.date || data.appointDate)) {
    appointSnapshot.appointDate = data.date || data.appointDate;
    appointSnapshot.date = data.date || data.appointDate;
  }

  // 1. 流入経路（大分類: オンライン / オフライン）
  if (flds.meetingType !== false) {
    const rawType = data.meetingType || data.sourceType || '';
    const normType = (rawType === 'online') ? 'オンライン' : (rawType === 'offline' ? 'オフライン' : rawType);
    if (normType) appointSnapshot.meetingType = normType;
  }

  // 2. 流入詳細（詳細分類: 広告、営業、追加された新選択肢等）
  if (flds.sourceCategory !== false) {
    const cat = data.onlineCategory || data.sourceCategory || '';
    if (cat) appointSnapshot.sourceCategory = cat;
  }

  // 3. 紹介者情報（本登録Party ID / 最新仮ID / 紹介者名）
  // オフライン→営業選択時に入力・紐付けされた紹介者IDおよび氏名を記録
  if (flds.introducer !== false && flds.introducerName !== false) {
    const effIntroId = introducerId || data.introducerId || '';
    const effIntroName = introducerName || data.introducerName || '';
    const effIntroType = introducerType || data.introducerType || '';
    if (effIntroId) appointSnapshot.introducerId = effIntroId;
    if (effIntroName) appointSnapshot.introducerName = effIntroName;
    if (effIntroType) appointSnapshot.introducerType = effIntroType;
  }

  if (data.id) {
    appointSnapshot.appointId = data.id;
  }

  // 🔑 推測不可能な英数字ハッシュ（セキュアトークン）を生成
  const token = generateFormSecureToken(20);
  const origin = window.location.origin || '';
  const pathname = window.location.pathname.substring(0, window.location.pathname.lastIndexOf('/') + 1);
  const formUrl = `${origin}${pathname}form-customize/view.html?k=${token}`;

  const newLink = {
    token: token,
    formId: formId,
    formName: formName,
    url: formUrl,
    masterId: masterId,
    appointId: data.id,
    issuerId: issuerId,
    issuerName: issuerName,
    introducerId: introducerId,
    introducerName: introducerName,
    introducerType: introducerType,
    appointSnapshot: appointSnapshot,
    status: 'pending',
    issuedAt: new Date().toISOString(),
    submittedAt: null,
    reopenedAt: null
  };

  data.linkedForms.push(newLink);
  saveSynapseFormLink(masterId, formId, newLink);

  renderAppointLinkedForms(data);
  closeAppointIssueModal();
  if (typeof showToast === 'function') {
    showToast(`「${formName}」を発行しました（マスタID: ${masterId}）。`, 'success');
  }
}

// 🌟 アイコンのみ＆コピー完了視覚フィードバック付きコピー関数
function copyAppointFormLink(targetEl, url, formName) {
  let btnEl = null;
  let actualUrl = url;
  let actualName = formName;

  if (typeof targetEl === 'string') {
    actualUrl = targetEl;
    actualName = url;
  } else if (targetEl && targetEl.nodeType) {
    btnEl = targetEl;
  }

  const onSuccess = () => {
    if (btnEl) {
      btnEl.classList.add('copied');
      const origHtml = btnEl.innerHTML;
      btnEl.innerHTML = `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>`;
      setTimeout(() => {
        btnEl.classList.remove('copied');
        btnEl.innerHTML = origHtml;
      }, 1800);
    }
    if (typeof showToast === 'function') {
      showToast(`「${actualName || 'フォーム'}」のリンクをコピーしました`, 'success');
    }
  };

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(actualUrl).then(onSuccess).catch(() => {
      prompt('リンクをコピーしてください:', actualUrl);
    });
  } else {
    prompt('リンクをコピーしてください:', actualUrl);
  }
}

function openAppointFormLink(url) {
  window.open(url, '_blank');
}

function requestAppointFormReopen(formId) {
  const data = getCurrentAppointData();
  if (!data || !Array.isArray(data.linkedForms)) return;
  const target = data.linkedForms.find(f => f.formId === formId);
  if (!target) return;

  if (confirm(`「${target.formName}」の再有効化を管理者に申請しますか？\n誤送信や内容修正のためにリンクを再回答可能にします。`)) {
    target.status = 'requesting';
    target.requestedAt = new Date().toISOString();
    saveSynapseFormLink(data.id, formId, target);
    renderAppointLinkedForms(data);
    if (typeof showToast === 'function') showToast(`「${target.formName}」の再有効化申請を送信しました（管理者承認待ち）`, 'info');
  }
}

function approveAppointFormReopen(formId) {
  const data = getCurrentAppointData();
  if (!data || !Array.isArray(data.linkedForms)) return;
  const target = data.linkedForms.find(f => f.formId === formId);
  if (!target) return;

  if (confirm(`「${target.formName}」の再有効化を承認しますか？\n回答者は同じURLから再度送信が可能になります。`)) {
    target.status = 'reopened';
    target.reopenedAt = new Date().toISOString();
    saveSynapseFormLink(data.id, formId, target);
    renderAppointLinkedForms(data);
    if (typeof showToast === 'function') showToast(`「${target.formName}」を再有効化しました`, 'success');
  }
}

function initAppointLinkedFormsEvents() {
  const openBtn = document.getElementById('btn-open-appoint-form-modal');
  if (openBtn) {
    openBtn.addEventListener('click', openAppointIssueModal);
  }

  const closeBtn = document.getElementById('btn-close-appoint-form-modal');
  if (closeBtn) {
    closeBtn.addEventListener('click', closeAppointIssueModal);
  }

  const modal = document.getElementById('modal-appoint-issue-form');
  if (modal) {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) closeAppointIssueModal();
    });
  }



  // リアルタイム同期リスナー（BroadcastChannel & storage イベント）
  if (typeof BroadcastChannel !== 'undefined') {
    try {
      const bc = new BroadcastChannel('synapse_form_channel');
      bc.onmessage = (e) => {
        if (e.data && (e.data.type === 'FORM_SUBMITTED' || e.data.type === 'FORM_LINK_UPDATED')) {
          const curData = getCurrentAppointData();
          if (curData && (!e.data.masterId || curData.id === e.data.masterId)) {
            renderAppointLinkedForms(curData);
          }
        }
      };
    } catch(e) {}
  }

  window.addEventListener('storage', (e) => {
    if (e.key === 'synapse_form_links') {
      const curData = getCurrentAppointData();
      if (curData) renderAppointLinkedForms(curData);
    }
  });
}

window.renderAppointLinkedForms = renderAppointLinkedForms;
window.openAppointIssueModal = openAppointIssueModal;
window.closeAppointIssueModal = closeAppointIssueModal;
window.issueAppointForm = issueAppointForm;
window.copyAppointFormLink = copyAppointFormLink;
window.openAppointFormLink = openAppointFormLink;
window.requestAppointFormReopen = requestAppointFormReopen;
window.approveAppointFormReopen = approveAppointFormReopen;

// 🌟 TimeCell Recovery & パートナーDB & フォーム連携グローバル参照
